const subject = { id: 'chemistry', name: 'Chemistry', board: 'AQA', spec: '8462', color: '#8b5cf6', icon: '⚗️', tiers: true };

const strands = [
  { id: 'chem-atomic', name: 'Atomic structure & the periodic table', color: '#8b5cf6', icon: '⚛️' },
  { id: 'chem-bonding', name: 'Bonding, structure & properties', color: '#6366f1', icon: '🔗' },
  { id: 'chem-quant', name: 'Quantitative chemistry', color: '#0ea5e9', icon: '⚖️' },
  { id: 'chem-changes', name: 'Chemical changes', color: '#ef4444', icon: '🧪' },
  { id: 'chem-energy', name: 'Energy changes', color: '#f97316', icon: '🔥' },
  { id: 'chem-rates', name: 'Rates & equilibrium', color: '#eab308', icon: '⏱️' },
  { id: 'chem-organic', name: 'Organic chemistry', color: '#22c55e', icon: '🛢️' },
  { id: 'chem-analysis', name: 'Chemical analysis', color: '#14b8a6', icon: '🔍' },
  { id: 'chem-atmos', name: 'Chemistry of the atmosphere', color: '#38bdf8', icon: '🌍' },
  { id: 'chem-resources', name: 'Using resources', color: '#a3a3a3', icon: '♻️' },
];

const topics = [];
const styles = {};
const learn = {};
module.exports = { subject, strands, topics, styles, learn };

// ---------- helpers ----------
function topic(t, styleDefs, L) {
  const ids = styleDefs.map((s, i) => {
    const id = `${t.id}-${i + 1}`;
    styles[id] = { id, topicId: t.id, ...s };
    return id;
  });
  topics.push({ ...t, styles: ids });
  learn[t.id] = { ...L, specRef: L.specRef || t.specRef };
}
const M = (q, options, correct, explain, hint) => ({ type: 'mcq', q, options, correct, explain, ...(hint ? { hint } : {}) });
const X = (q, options, correct, explain, hint) => ({ type: 'multi', q, options, correct, explain, ...(hint ? { hint } : {}) });
const T = (q, correct, explain, hint) => ({ type: 'tf', q, correct, explain, ...(hint ? { hint } : {}) });
const S = (q, answer, accept, explain, keywords, hint) => ({ type: 'short', q, answer, accept, ...(keywords ? { keywords } : {}), explain, ...(hint ? { hint } : {}) });
const O = (q, options, explain, hint) => ({ type: 'order', q, options, explain, ...(hint ? { hint } : {}) });
const N = (q, value, tol, unit, steps, explain, hint) => ({ type: 'number', q, value, tol, unit, answer: `${value} ${unit}`.trim(), steps, explain, ...(hint ? { hint } : {}) });

const pick = (rng, a) => a[Math.floor(rng() * a.length)];
const ri = (rng, lo, hi) => lo + Math.floor(rng() * (hi - lo + 1));
const rd = (x, dp) => Math.round(x * 10 ** dp) / 10 ** dp;

// Relative atomic masses (AQA data sheet values)
const AR = { H: 1, Li: 7, C: 12, N: 14, O: 16, F: 19, Na: 23, Mg: 24, Al: 27, S: 32, Cl: 35.5, K: 39, Ca: 40, Fe: 56, Cu: 63.5, Zn: 65, Br: 80, Ag: 108, I: 127, Ba: 137, Pb: 207 };
// [display formula, name, {element: count}]
const COMPOUNDS = [
  ['H<sub>2</sub>O', 'water', { H: 2, O: 1 }], ['CO<sub>2</sub>', 'carbon dioxide', { C: 1, O: 2 }],
  ['NaCl', 'sodium chloride', { Na: 1, Cl: 1 }], ['MgO', 'magnesium oxide', { Mg: 1, O: 1 }],
  ['CaCO<sub>3</sub>', 'calcium carbonate', { Ca: 1, C: 1, O: 3 }], ['H<sub>2</sub>SO<sub>4</sub>', 'sulfuric acid', { H: 2, S: 1, O: 4 }],
  ['NH<sub>3</sub>', 'ammonia', { N: 1, H: 3 }], ['CH<sub>4</sub>', 'methane', { C: 1, H: 4 }],
  ['C<sub>2</sub>H<sub>6</sub>', 'ethane', { C: 2, H: 6 }], ['C<sub>2</sub>H<sub>5</sub>OH', 'ethanol', { C: 2, H: 6, O: 1 }],
  ['Fe<sub>2</sub>O<sub>3</sub>', 'iron(III) oxide', { Fe: 2, O: 3 }], ['CuSO<sub>4</sub>', 'copper sulfate', { Cu: 1, S: 1, O: 4 }],
  ['Al<sub>2</sub>O<sub>3</sub>', 'aluminium oxide', { Al: 2, O: 3 }], ['MgCl<sub>2</sub>', 'magnesium chloride', { Mg: 1, Cl: 2 }],
  ['Ca(OH)<sub>2</sub>', 'calcium hydroxide', { Ca: 1, O: 2, H: 2 }], ['NaOH', 'sodium hydroxide', { Na: 1, O: 1, H: 1 }],
  ['HCl', 'hydrochloric acid', { H: 1, Cl: 1 }], ['HNO<sub>3</sub>', 'nitric acid', { H: 1, N: 1, O: 3 }],
  ['KCl', 'potassium chloride', { K: 1, Cl: 1 }], ['Na<sub>2</sub>CO<sub>3</sub>', 'sodium carbonate', { Na: 2, C: 1, O: 3 }],
  ['Mg(OH)<sub>2</sub>', 'magnesium hydroxide', { Mg: 1, O: 2, H: 2 }], ['(NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>', 'ammonium sulfate', { N: 2, H: 8, S: 1, O: 4 }],
  ['C<sub>3</sub>H<sub>8</sub>', 'propane', { C: 3, H: 8 }], ['C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>', 'glucose', { C: 6, H: 12, O: 6 }],
  ['ZnO', 'zinc oxide', { Zn: 1, O: 1 }], ['CuO', 'copper oxide', { Cu: 1, O: 1 }], ['SO<sub>2</sub>', 'sulfur dioxide', { S: 1, O: 2 }],
  ['Ca(NO<sub>3</sub>)<sub>2</sub>', 'calcium nitrate', { Ca: 1, N: 2, O: 6 }], ['K<sub>2</sub>SO<sub>4</sub>', 'potassium sulfate', { K: 2, S: 1, O: 4 }],
  ['LiF', 'lithium fluoride', { Li: 1, F: 1 }], ['AgBr', 'silver bromide', { Ag: 1, Br: 1 }], ['Na<sub>2</sub>SO<sub>4</sub>', 'sodium sulfate', { Na: 2, S: 1, O: 4 }],
];
const mrOf = (comp) => rd(Object.entries(comp).reduce((s, [el, n]) => s + AR[el] * n, 0), 1);
const mrSteps = (f, comp) => {
  const parts = Object.entries(comp).map(([el, n]) => `${n} × ${AR[el]} (${el})`);
  return [`Look up A<sub>r</sub> values: ${Object.keys(comp).map((el) => `${el} = ${AR[el]}`).join(', ')}.`,
    `Count the atoms of each element in ${f} (a number after a bracket multiplies everything inside it).`,
    `M<sub>r</sub> = ${parts.join(' + ')}`, `M<sub>r</sub> = ${mrOf(comp)} (relative formula mass has no units)`];
};

// =====================================================================
// YEAR 7 — Particles & states of matter
// =====================================================================
topic({ id: 'chem-y7-particles', strand: 'chem-bonding', year: 7, term: 1, tier: 'FH', name: 'Particles & States of Matter',
  summary: 'Use the particle model to explain solids, liquids, gases, changes of state, diffusion and gas pressure.', specRef: 'KS3 Chemistry: The particulate nature of matter' }, [
  { name: 'Solids, liquids & gases', intro: 'All matter is made of tiny particles. How the particles are arranged and how they move explains the properties of solids, liquids and gases.', items: [
    M('Which describes the particles in a <b>solid</b>?', ['Close together in a regular pattern, vibrating about fixed positions', 'Close together but moving around each other', 'Far apart and moving quickly in all directions', 'Close together and not moving at all'], 0, 'Solid particles are packed in a regular arrangement and vibrate on the spot. They are never completely still — even in a solid the particles vibrate. "Moving around each other" describes a liquid.'),
    M('Which state of matter has particles that are far apart and move quickly in random directions?', ['Solid', 'Liquid', 'Gas', 'All three'], 2, 'Gas particles are far apart with large spaces between them and move fast in random directions. Liquid particles touch each other; solid particles are fixed in place.'),
    M('Why can a liquid be poured but keep the same volume?', ['Its particles can slide past each other but stay close together', 'Its particles are far apart', 'Its particles are in a fixed regular pattern', 'Its particles get bigger when poured'], 0, 'Liquid particles touch but can move past one another, so a liquid flows and takes the shape of its container. They are still close together, so the volume stays the same. Particles never change size.'),
    M('Why are gases easy to compress (squash)?', ['There are large spaces between the particles', 'The particles are soft', 'The particles are very small', 'The particles are not moving'], 0, 'Gas particles have lots of empty space between them, so pushing them closer is easy. The particles themselves are not squashed — they are hard and do not change size.'),
    T('The particles in a solid are completely still.', false, 'False. Particles in a solid vibrate about fixed positions. Heating makes them vibrate more.'),
    T('A gas spreads out to fill whatever container it is in.', true, 'True. Gas particles move freely in all directions, so a gas has no fixed shape or volume and fills its container.'),
    T('When a substance is heated, its particles get bigger.', false, 'False — a very common misconception. Particles stay the same size. Heating gives them more energy, so they move or vibrate more and the spaces between them can get bigger (that is why things expand).'),
    S('What word describes a substance that flows and takes the shape of its container but cannot be compressed?', 'liquid', ['liquid', 'a liquid'], 'A liquid flows and takes the shape of the container, but its particles are touching so it cannot easily be compressed. A gas also flows but can be compressed.'),
    S('In the particle model, what is between gas particles?', 'nothing (empty space)', ['nothing', 'empty space', 'space', 'vacuum', 'a vacuum'], 'Between gas particles there is nothing — empty space. A common error is to say "air", but air is itself made of particles.', [['empty', 'nothing', 'vacuum', 'space']]),
    M('Which state has a fixed shape AND a fixed volume?', ['Solid', 'Liquid', 'Gas', 'Liquid and gas'], 0, 'Only solids keep a fixed shape and volume because the particles are held in fixed positions by strong forces. Liquids have a fixed volume but no fixed shape; gases have neither.'),
    X('Which TWO properties are true of gases?', ['They can be compressed', 'They have a fixed volume', 'They flow and fill their container', 'Their particles are in a regular pattern', 'Their particles vibrate in fixed positions'], [0, 2], 'Gases can be compressed (big spaces between particles) and flow to fill a container (particles move freely). Fixed volume, regular pattern and fixed positions belong to solids.'),
    M('A substance has a fixed volume but takes the shape of its container. What state is it?', ['Solid', 'Liquid', 'Gas', 'Plasma'], 1, 'Fixed volume + no fixed shape = liquid. A gas would not have a fixed volume; a solid would keep its own shape.'),
    M('Why do solids generally have a higher density than gases of the same substance?', ['More particles are packed into the same volume', 'The particles are heavier in a solid', 'Solid particles are larger', 'Gas particles have no mass'], 0, 'In a solid the particles are packed closely, so there is more mass in each cm³. Individual particles have the same mass in every state — only the spacing changes.'),
    O('Put the states in order of increasing distance between particles (closest first).', ['Solid', 'Liquid', 'Gas'], 'Solid particles are closest and regularly packed; liquid particles are close but random; gas particles are far apart. (Water is an unusual exception — ice is slightly less dense than liquid water.)'),
    M('Which statement best explains why a solid cannot flow?', ['Strong forces hold its particles in fixed positions', 'Its particles have no energy', 'Its particles are too large to move', 'There is no air between its particles'], 0, 'Strong forces of attraction keep solid particles in fixed positions, so they can only vibrate and the solid cannot flow. The particles do have energy (they vibrate).'),
    T('The particle model treats particles as small solid spheres, which is a simplification.', true, 'True. Real particles (atoms, molecules, ions) are not hard little balls and forces between them are not shown — the model is useful but has limitations.'),
    M('A metal spoon keeps its shape when you put it in a cup. Which particle idea explains this?', ['The particles are held in fixed positions by strong forces', 'The particles are not moving at all', 'There is air trapped between the particles', 'The particles are glued together by the cup'], 0, 'Solid particles are held in place by strong forces of attraction, so a solid keeps its own shape. They still vibrate — they are not motionless — and there is no air between particles.'),
    M('Which state of matter has the <b>weakest</b> forces of attraction between its particles?', ['Gas', 'Liquid', 'Solid', 'They are all the same'], 0, 'In a gas the particles are far apart and the forces between them are very weak, so they move freely. Forces are strongest in solids and intermediate in liquids.'),
    M('Honey and water are both liquids. Why can both be poured into any shaped jug?', ['Their particles can move past each other', 'Their particles are far apart', 'Their particles are in rows', 'Their particles are lighter than solid particles'], 0, 'Any liquid flows because its particles can slide past one another. Liquid particles are still close together (not far apart) and are not arranged in rows.'),
    M('A syringe full of water is sealed and the plunger is pushed. What happens?', ['The plunger hardly moves because liquid particles are already touching', 'The water is easily squashed into a smaller volume', 'The water turns into a gas', 'The water particles get smaller'], 0, 'Liquid particles are already touching, so there is almost no space to squash them into. A syringe of air, by contrast, is easy to compress. Particles never shrink.'),
    M('In which state do the particles have the <b>most</b> kinetic (movement) energy, for the same substance?', ['Gas', 'Liquid', 'Solid', 'All have the same energy'], 0, 'For a given substance, the gas particles have the most energy — they move fastest. Energy must be supplied to turn a solid into a liquid and a liquid into a gas.'),
    T('Particles of the same substance have the same mass whether it is a solid, liquid or gas.', true, 'True. Changing state only changes how particles are arranged and how they move; each particle keeps the same mass and size.'),
    T('A liquid has no fixed volume.', false, 'False. A liquid has a fixed volume because its particles stay close together; it has no fixed shape. A gas has neither a fixed shape nor a fixed volume.'),
    T('Gases can flow, just like liquids.', true, 'True. Both liquids and gases are fluids: their particles can move past each other, so they flow. Solids cannot flow.'),
    S('What general word describes the tiny pieces (atoms, molecules or ions) that all matter is made of?', 'particles', ['particle', 'particles'], 'All matter is made of particles. In chemistry these can be atoms, molecules or ions — the particle model treats them as tiny spheres.'),
    S('What state of matter is steam?', 'gas', ['gas', 'a gas', 'gaseous'], 'Steam is water in the gas state. (The white "cloud" you see above a kettle is actually tiny droplets of liquid water that have condensed.)'),
    X('Which TWO properties are true of solids?', ['They have a fixed shape', 'They are easily compressed', 'Their particles vibrate in fixed positions', 'They flow when poured', 'They fill any container they are put in'], [0, 2], 'Solids have a fixed shape because their particles vibrate about fixed positions. Being easily compressed and filling a container describe gases; flowing describes liquids and gases.'),
    M('Sand can be poured from a bucket. Does this mean sand is a liquid?', ['No — each grain is a solid; the tiny grains move past each other', 'Yes — anything that pours is a liquid', 'Yes — sand particles are far apart', 'No — sand is a gas'], 0, 'Each grain of sand is a solid with a fixed shape and volume. A pile of small grains can slide over one another, which looks like flowing, but zooming in shows that each grain keeps its shape.'),
    O('Put these states in order of how strongly the particles attract each other (strongest first).', ['Solid', 'Liquid', 'Gas'], 'Forces are strongest in solids (particles fixed), weaker in liquids (particles slide past each other) and weakest in gases (particles move freely and far apart).'),
    M('A gas is pumped from a small bottle into a much larger empty container. What happens to the gas?', ['It spreads out to fill the larger container', 'It stays in a small lump at the bottom', 'It turns into a liquid', 'Its particles get bigger to fill the space'], 0, 'Gas particles move randomly in all directions, so the gas spreads to fill any container. The particles do not change size — the spaces between them get bigger.'),
  ] },
  { name: 'Changes of state', intro: 'Heating or cooling can change a substance from one state to another. Changes of state are physical changes: no new substance is made and mass is conserved.', items: [
    M('What is the name for the change from liquid to gas at the boiling point?', ['Boiling', 'Melting', 'Condensing', 'Freezing'], 0, 'Liquid → gas throughout the liquid at the boiling point is boiling. Melting is solid → liquid; condensing is gas → liquid; freezing is liquid → solid.'),
    M('What is condensation?', ['Gas turning into a liquid', 'Liquid turning into a gas', 'Solid turning into a liquid', 'Solid turning straight into a gas'], 0, 'Condensing is gas → liquid, e.g. water vapour forming droplets on a cold window. Particles lose energy and come closer together.'),
    S('What is the name of the change when a solid turns directly into a gas?', 'sublimation', ['sublimation', 'subliming', 'sublime', 'sublimes'], 'Sublimation is solid → gas without becoming a liquid, e.g. dry ice (solid carbon dioxide). Do not confuse with evaporation (liquid → gas at the surface).'),
    M('How is evaporation different from boiling?', ['Evaporation happens only at the surface and at any temperature', 'Evaporation needs a higher temperature', 'Evaporation turns a gas into a liquid', 'Evaporation only happens in a closed container'], 0, 'Evaporation happens at the surface of a liquid at temperatures below the boiling point — puddles dry up without boiling. Boiling happens throughout the liquid at one fixed temperature.'),
    M('What happens to the particles when ice melts?', ['They gain energy, vibrate more and break free of fixed positions', 'They get bigger and push apart', 'They lose energy and slow down', 'They turn into different particles'], 0, 'Heating gives particles energy; at the melting point they vibrate enough to overcome some of the forces holding them in place and start to move past each other. They do not change size or identity.'),
    T('When water boils, the bubbles are made of air.', false, 'False. The bubbles in boiling water are water vapour (gaseous water). It is a change of state of the water itself.'),
    T('The mass of a substance stays the same when it melts.', true, 'True. Changes of state are physical changes; the same particles are present, just arranged differently, so mass is conserved.'),
    N('Pure water melts at 0 °C and boils at 100 °C. What is the temperature range over which water is a liquid (in °C)?', 100, 0, '°C', ['Range = boiling point − melting point', 'Range = 100 − 0', 'Range = 100 °C'], 'Water is liquid between its melting point (0 °C) and boiling point (100 °C), a range of 100 °C.'),
    M('A substance has melting point −39 °C and boiling point 357 °C. What state is it at 25 °C?', ['Liquid', 'Solid', 'Gas', 'It cannot be predicted'], 0, '25 °C is above the melting point (so it has melted) but below the boiling point (so it has not boiled). It is a liquid — this is mercury.'),
    M('A substance has melting point 801 °C. What state is it at room temperature (20 °C)?', ['Solid', 'Liquid', 'Gas', 'Liquid and gas'], 0, '20 °C is below the melting point, so it has not yet melted — it is solid (this is sodium chloride).'),
    M('Oxygen has melting point −218 °C and boiling point −183 °C. What state is it at −200 °C?', ['Liquid', 'Solid', 'Gas', 'Plasma'], 0, '−200 °C is warmer than −218 °C (melted) but colder than −183 °C (not boiled), so oxygen is liquid. Take care with negative numbers: −200 is above −218.'),
    O('Put these changes in the order water goes through when ice is heated until it is all steam.', ['Ice warms up', 'Ice melts at 0 °C', 'Liquid water warms up', 'Water boils at 100 °C'], 'Solid warms → melts (temperature stays at 0 °C) → liquid warms → boils (temperature stays at 100 °C).'),
    M('On a heating curve, why does the temperature stay constant while a solid melts?', ['The energy supplied is used to break forces between particles', 'The thermometer stops working', 'No energy is being supplied', 'The particles stop moving'], 0, 'During melting, energy goes into overcoming forces between particles rather than raising the temperature, so the graph is flat.'),
    S('What is the name for the change from liquid to solid?', 'freezing', ['freezing', 'freeze', 'solidifying', 'solidification'], 'Liquid → solid is freezing (or solidifying). It happens at the same temperature as melting for a pure substance.'),
    X('Which TWO are physical changes?', ['Ice melting', 'Wood burning', 'Water evaporating', 'Iron rusting', 'Bread toasting'], [0, 2], 'Melting and evaporating are changes of state — no new substance forms and they are easily reversed. Burning, rusting and toasting make new substances, so they are chemical changes.'),
    T('A pure substance melts at a single, sharp temperature.', true, 'True. Pure substances have fixed melting and boiling points; mixtures melt and boil over a range of temperatures — this is used to test purity.'),
    M('What happens to the particles when steam condenses on a cold mirror?', ['They lose energy, slow down and come closer together', 'They gain energy and spread out', 'They become smaller', 'They turn into air particles'], 0, 'The cold mirror takes energy from the water vapour particles, so they slow down and the attractions pull them together into liquid droplets. The particles stay the same size and are still water.'),
    M('Wet washing dries on a line even though the air is only 15 °C. Which process is this?', ['Evaporation', 'Boiling', 'Condensation', 'Sublimation'], 0, 'Evaporation happens at the surface of a liquid at any temperature, so washing dries well below 100 °C. Boiling needs the liquid to reach its boiling point.'),
    M('Which change of state needs energy to be <b>taken in</b> from the surroundings?', ['Melting', 'Freezing', 'Condensing', 'Deposition (gas to solid)'], 0, 'Melting needs energy to overcome the forces holding particles in place. Freezing, condensing and gas → solid all release energy to the surroundings.'),
    M('Which of these will make a puddle evaporate faster?', ['A warm, windy day', 'A cold, still day', 'Covering the puddle with a lid', 'Making the puddle deeper but narrower'], 0, 'Higher temperature gives particles more energy, and wind carries away vapour so more particles can escape. A lid traps vapour, and a smaller surface area slows evaporation.'),
    T('When a liquid evaporates, the particles with the most energy escape from the surface first.', true, 'True. Only the fastest-moving surface particles have enough energy to escape. That is why sweat evaporating cools you down — the higher-energy particles leave.'),
    T('Boiling and evaporation both turn a liquid into a gas.', true, 'True. Both change liquid to gas. Evaporation happens only at the surface and below the boiling point; boiling happens throughout the liquid at the boiling point.'),
    T('Salt dissolving in water is a change of state.', false, 'False. Dissolving is a physical change but not a change of state — the salt is mixing into the water to make a solution, not melting.'),
    S('What name is given to the temperature at which a liquid turns into a solid?', 'freezing point', ['freezing point', 'melting point', 'the freezing point'], 'This is the freezing point. For a pure substance it is the same temperature as the melting point.', [['freezing', 'melting'], ['point', 'temperature']]),
    S('Iodine crystals turn straight into a purple vapour when warmed. What is this change called?', 'sublimation', ['sublimation', 'subliming', 'sublimes'], 'Going straight from solid to gas without melting is sublimation. Iodine and solid carbon dioxide both sublime when heated gently.'),
    M('Ethanol melts at −114 °C and boils at 78 °C. What is its state at 90 °C?', ['Gas', 'Liquid', 'Solid', 'Solid and liquid'], 0, '90 °C is above the boiling point (78 °C), so ethanol has boiled and is a gas.'),
    M('Bromine melts at −7 °C and boils at 59 °C. What state is it at −20 °C?', ['Solid', 'Liquid', 'Gas', 'Plasma'], 0, '−20 °C is colder than its melting point of −7 °C, so bromine has not melted — it is a solid. Remember: −20 is lower than −7.'),
    N('A substance melts at −23 °C and boils at 77 °C. Over how many degrees Celsius is it a liquid?', 100, 0, '°C', ['Range = boiling point − melting point', 'Range = 77 − (−23) = 77 + 23', 'Range = 100 °C'], 'Subtracting a negative number is the same as adding: 77 − (−23) = 100 °C.'),
    X('Which TWO changes give out (release) energy to the surroundings?', ['Condensing', 'Freezing', 'Melting', 'Boiling', 'Evaporating'], [0, 1], 'Condensing and freezing release energy as particles are pulled closer together by attractive forces. Melting, boiling and evaporating all need energy to be taken in.'),
    M('A sample of wax melts gradually between 50 °C and 58 °C. What does this suggest?', ['It is a mixture, not a pure substance', 'It is a pure substance', 'The thermometer is broken', 'It is turning into a gas'], 0, 'Pure substances melt at one sharp temperature. Melting over a range of temperatures shows the wax is a mixture of different substances.'),
    O('Put these in order to describe what happens to steam as it is cooled until it is ice.', ['Steam cools down', 'Steam condenses to liquid water at 100 °C', 'Liquid water cools down', 'Water freezes to ice at 0 °C'], 'Cooling a gas lowers its temperature until it condenses; the liquid then cools until it freezes. The temperature stays constant during each change of state.'),
  ] },
  { name: 'Diffusion, pressure & density', intro: 'Particles move randomly. This explains diffusion (spreading out) and gas pressure (particles hitting surfaces). Density depends on how much mass is packed into a volume.', items: [
    M('What is diffusion?', ['The spreading of particles from high to low concentration', 'Particles joining together to make a compound', 'A liquid turning into a gas', 'Particles stopping when they meet a wall'], 0, 'Diffusion is the net movement of particles from an area of high concentration to an area of low concentration, caused by their random movement.'),
    M('Why does diffusion happen faster in a gas than in a liquid?', ['Gas particles move faster and have more space', 'Gas particles are bigger', 'Liquid particles do not move', 'Gases are heavier'], 0, 'Gas particles move quickly with large spaces between them, so they spread quickly. Liquid particles move more slowly and keep bumping into neighbours. Diffusion is extremely slow in solids.'),
    M('Why does perfume spread faster in a warm room?', ['The particles have more energy and move faster', 'Warm air pushes the particles', 'The perfume particles get bigger', 'The perfume turns into a liquid'], 0, 'Higher temperature means particles have more kinetic energy and move faster, so diffusion is quicker.'),
    M('What causes gas pressure in a container?', ['Gas particles colliding with the walls', 'Gas particles sticking to the walls', 'The weight of the container', 'Gas particles expanding'], 0, 'Gas particles move randomly and collide with the walls, exerting a force. Many collisions over the area cause pressure.'),
    M('A sealed balloon is heated. Why does the pressure inside increase?', ['Particles move faster and hit the walls more often and harder', 'The particles get bigger', 'More particles are made', 'The particles stop moving'], 0, 'Heating increases particle speed, so collisions with the walls are more frequent and more forceful, raising pressure. No new particles are created and their size does not change.'),
    T('Diffusion can happen in solids, but very slowly.', true, 'True. Solid particles only vibrate, so mixing between solids takes a very long time (years), but it can happen.'),
    T('If you squash a gas into a smaller volume at the same temperature, the pressure decreases.', false, 'False. A smaller volume means particles hit the walls more often, so pressure increases.'),
    S('What is the name of the process that lets you smell food cooking from another room?', 'diffusion', ['diffusion', 'diffusing', 'diffuse'], 'The smell particles move randomly through the air and spread from where they are concentrated (the kitchen) to where they are not — diffusion.'),
    N('A block has a mass of 54 g and a volume of 20 cm³. Calculate its density in g/cm³.', 2.7, 0.01, 'g/cm³', ['density = mass ÷ volume', 'density = 54 ÷ 20', 'density = 2.7 g/cm³'], 'Density = mass ÷ volume. This is the density of aluminium.'),
    N('A liquid has a density of 0.8 g/cm³. What is the mass of 50 cm³ of it?', 40, 0.01, 'g', ['mass = density × volume', 'mass = 0.8 × 50', 'mass = 40 g'], 'Rearrange density = mass ÷ volume to mass = density × volume.'),
    N('A gas sample has mass 0.6 g and volume 500 cm³. Calculate its density in g/cm³.', 0.0012, 0.00005, 'g/cm³', ['density = mass ÷ volume', 'density = 0.6 ÷ 500', 'density = 0.0012 g/cm³'], 'Gases have very low densities because their particles are far apart.'),
    M('A drop of purple potassium manganate(VII) is placed in still water. What will you see after an hour?', ['The purple colour spreads through the water', 'The purple sinks and stays as a drop', 'The water turns clear', 'The water freezes'], 0, 'The purple particles diffuse through the water as they and the water particles move randomly, so the colour slowly spreads out evenly.'),
    M('Why is the particle model unable to explain why some substances have different melting points?', ['It does not show the different strengths of forces between particles', 'It shows particles as too large', 'It shows particles moving', 'It only works for liquids'], 0, 'The simple model shows particles as identical spheres and does not show the forces between them. Melting point depends on how strong those forces are.'),
    X('Which TWO changes would increase the pressure of a gas in a sealed rigid container?', ['Heating the gas', 'Cooling the gas', 'Adding more gas particles', 'Removing some gas particles', 'Painting the container'], [0, 2], 'Heating makes particles hit the walls faster and more often; adding particles means more collisions. Cooling or removing particles lowers the pressure.'),
    M('Ammonia and hydrogen chloride gases are released from opposite ends of a tube. A white ring forms closer to the hydrogen chloride end. What does this show?', ['Ammonia particles diffuse faster', 'Hydrogen chloride particles diffuse faster', 'Both diffuse at the same speed', 'The gases do not diffuse'], 0, 'The ring forms where the gases meet. Ammonia travelled further in the same time, so it diffused faster — its particles are lighter (M<sub>r</sub> 17 vs 36.5).'),
    T('Gas particles slow down and stop when the gas has filled its container.', false, 'False. Gas particles keep moving randomly all the time; that constant motion keeps causing pressure.'),
    M('Which change makes diffusion happen more slowly?', ['Cooling the substances', 'Heating the substances', 'Using a gas instead of a liquid', 'Using lighter particles'], 0, 'Cooling lowers the particles\' energy so they move more slowly, and diffusion slows down. Heating, gases and lighter particles all speed diffusion up.'),
    M('A tea bag is placed in a cup of cold water and another in hot water. Which is correct?', ['The colour spreads faster in the hot water', 'The colour spreads faster in the cold water', 'The colour spreads at the same rate in both', 'The colour does not spread in cold water at all'], 0, 'In hot water the particles have more energy and move faster, so the coloured particles diffuse faster. Diffusion still happens in cold water, just more slowly.'),
    M('Why does a football feel harder after being pumped up?', ['More air particles hit the inside of the ball, increasing the pressure', 'The air particles become larger', 'The rubber particles stop moving', 'The air inside turns into a liquid'], 0, 'Pumping in air adds more particles, so there are more collisions with the inside surface each second — the pressure rises and the ball feels harder.'),
    M('A sealed plastic bottle is taken from a warm room into a freezer. It goes slightly squashed. Why?', ['The gas inside cools, particles slow down and the pressure inside drops', 'The air particles shrink', 'Air particles escape through the plastic', 'The plastic gets heavier'], 0, 'Cooling slows the gas particles, so they hit the walls less often and less hard. The pressure inside becomes less than outside, so the bottle is pushed in. Particles do not shrink.'),
    T('Diffusion happens because particles move in random directions.', true, 'True. Random movement means particles gradually spread from where there are many of them to where there are fewer — no push or wind is needed.'),
    T('Density is calculated by dividing volume by mass.', false, 'False. Density = mass ÷ volume. Dividing the other way round gives the wrong answer and wrong units.'),
    S('What is the name for the force per unit area caused by gas particles hitting a surface?', 'pressure', ['pressure', 'gas pressure', 'air pressure'], 'Gas pressure is caused by particles colliding with surfaces. More frequent or harder collisions mean higher pressure.'),
    N('A stone has a mass of 150 g and a volume of 60 cm³. Calculate its density in g/cm³.', 2.5, 0.01, 'g/cm³', ['density = mass ÷ volume', 'density = 150 ÷ 60', 'density = 2.5 g/cm³'], 'Divide mass by volume. A density of 2.5 g/cm³ is typical for rock.'),
    N('A piece of iron has a density of 7.9 g/cm³ and a volume of 10 cm³. What is its mass?', 79, 0.1, 'g', ['mass = density × volume', 'mass = 7.9 × 10', 'mass = 79 g'], 'Rearranging density = mass ÷ volume gives mass = density × volume.'),
    N('Cork has a density of 0.25 g/cm³. What volume is taken up by 5 g of cork?', 20, 0.01, 'cm³', ['volume = mass ÷ density', 'volume = 5 ÷ 0.25', 'volume = 20 cm³'], 'Rearranging density = mass ÷ volume gives volume = mass ÷ density.'),
    M('Oil (density 0.9 g/cm³) is poured onto water (density 1.0 g/cm³). What happens?', ['The oil floats on top of the water', 'The oil sinks below the water', 'The oil and water mix completely', 'The oil turns solid'], 0, 'A liquid with lower density floats on one with higher density. Oil and water do not mix, so the oil forms a layer on top.'),
    X('Which TWO observations are evidence that particles are moving?', ['The smell of cut onions spreads across a kitchen', 'A dye spreads through still water', 'Ice keeps its shape in a freezer', 'A stone sinks in water', 'Metal is shiny'], [0, 1], 'Smells spreading and dyes spreading in still water are both diffusion, which only happens because particles move randomly. The other observations do not show particle movement.'),
    M('Why does a gas in a closed syringe push back harder when the plunger is pushed in?', ['The same number of particles in a smaller space hit the walls more often', 'The particles get bigger', 'The particles move more slowly', 'New particles are made'], 0, 'Squashing the gas into a smaller volume means the particles collide with the walls more frequently, so the pressure rises.'),
    O('Put these in order of how quickly diffusion happens (fastest first).', ['A gas at 50 °C', 'A gas at 20 °C', 'A liquid at 20 °C', 'A solid at 20 °C'], 'Diffusion is fastest in hot gases (particles fast and far apart), slower in cooler gases, slower again in liquids and extremely slow in solids.'),
  ] },
], {
  overview: 'Everything around you is made of particles too small to see. The <b>particle model</b> explains why solids, liquids and gases behave so differently, what happens during changes of state, and why smells spread and gases exert pressure.',
  objectives: ['I can describe the arrangement and movement of particles in solids, liquids and gases', 'I can name and explain the changes of state', 'I can use melting and boiling points to predict the state of a substance', 'I can explain diffusion and gas pressure using particles', 'I can calculate density = mass ÷ volume'],
  keyWords: [{ term: 'Particle', def: 'A tiny piece of matter — an atom, molecule or ion.' }, { term: 'Melting point', def: 'The temperature at which a solid turns into a liquid.' }, { term: 'Boiling point', def: 'The temperature at which a liquid boils into a gas throughout.' }, { term: 'Evaporation', def: 'Liquid turning to gas at the surface, below the boiling point.' }, { term: 'Sublimation', def: 'A solid turning directly into a gas.' }, { term: 'Diffusion', def: 'Net movement of particles from high to low concentration due to random motion.' }, { term: 'Gas pressure', def: 'The force per area caused by gas particles colliding with surfaces.' }, { term: 'Density', def: 'Mass per unit volume; density = mass ÷ volume.' }],
  sections: [
    { title: 'Three states of matter', html: `<p>The particle model treats particles as tiny hard spheres.</p><table class="qt"><tr><th>State</th><th>Arrangement</th><th>Movement</th><th>Properties</th></tr><tr><td>Solid</td><td>Close, regular pattern</td><td>Vibrate about fixed positions</td><td>Fixed shape and volume; cannot be compressed</td></tr><tr><td>Liquid</td><td>Close, random</td><td>Move around each other</td><td>Flows; fixed volume; takes shape of container</td></tr><tr><td>Gas</td><td>Far apart, random</td><td>Fast, in all directions</td><td>Flows; fills container; easily compressed</td></tr></table><svg viewBox="0 0 300 90" width="100%" style="max-width:340px"><rect x="5" y="5" width="90" height="70" fill="none" stroke="currentColor"/><rect x="105" y="5" width="90" height="70" fill="none" stroke="currentColor"/><rect x="205" y="5" width="90" height="70" fill="none" stroke="currentColor"/><g fill="#3b6cf6"><circle cx="25" cy="25" r="8"/><circle cx="42" cy="25" r="8"/><circle cx="59" cy="25" r="8"/><circle cx="76" cy="25" r="8"/><circle cx="25" cy="42" r="8"/><circle cx="42" cy="42" r="8"/><circle cx="59" cy="42" r="8"/><circle cx="76" cy="42" r="8"/><circle cx="25" cy="59" r="8"/><circle cx="42" cy="59" r="8"/><circle cx="59" cy="59" r="8"/><circle cx="76" cy="59" r="8"/><circle cx="120" cy="66" r="8"/><circle cx="137" cy="64" r="8"/><circle cx="154" cy="66" r="8"/><circle cx="171" cy="62" r="8"/><circle cx="128" cy="50" r="8"/><circle cx="146" cy="48" r="8"/><circle cx="163" cy="47" r="8"/><circle cx="182" cy="56" r="8"/><circle cx="225" cy="22" r="8"/><circle cx="270" cy="30" r="8"/><circle cx="240" cy="60" r="8"/><circle cx="280" cy="64" r="8"/></g><text x="50" y="88" font-size="10" text-anchor="middle" fill="currentColor">solid</text><text x="150" y="88" font-size="10" text-anchor="middle" fill="currentColor">liquid</text><text x="250" y="88" font-size="10" text-anchor="middle" fill="currentColor">gas</text></svg>` },
    { title: 'Changes of state', html: `<p>Heating gives particles more energy; cooling removes it.</p><ul><li><b>Melting</b>: solid → liquid; <b>freezing</b>: liquid → solid (same temperature for a pure substance).</li><li><b>Boiling</b>: liquid → gas throughout the liquid at the boiling point; <b>evaporation</b>: at the surface, below the boiling point.</li><li><b>Condensing</b>: gas → liquid; <b>sublimation</b>: solid → gas directly.</li></ul><div class="rule">Changes of state are physical changes: no new substance is made, they are reversible, and mass is conserved.</div><p>While a substance melts or boils, its temperature stays constant — the energy is used to overcome the forces between particles.</p>` },
    { title: 'Predicting state from melting and boiling points', html: `<ul><li>Below the melting point → <b>solid</b></li><li>Between melting and boiling points → <b>liquid</b></li><li>Above the boiling point → <b>gas</b></li></ul><div class="worked"><div class="wq">Chlorine melts at −101 °C and boils at −34 °C. What is its state at −50 °C?</div><ol><li>−50 °C is warmer than −101 °C, so it has melted.</li><li>−50 °C is colder than −34 °C, so it has not boiled.</li></ol><div class="wa">Answer: liquid</div></div><div class="note">With negative temperatures, a number further from zero is colder: −101 °C is colder than −50 °C.</div>` },
    { title: 'Diffusion and gas pressure', html: `<p><b>Diffusion</b> is the spreading of particles from high to low concentration caused by their random movement. It is fastest in gases, slower in liquids and extremely slow in solids, and faster at higher temperatures.</p><p><b>Gas pressure</b> is caused by particles colliding with the walls of the container. Pressure increases if the gas is heated (faster particles, harder and more frequent collisions), squashed into a smaller volume, or if more gas is added.</p>` },
    { title: 'Density', html: `<div class="rule">density = mass ÷ volume (g/cm³)</div><div class="worked"><div class="wq">A stone has mass 39 g and volume 15 cm³. Find its density.</div><ol><li>density = mass ÷ volume</li><li>= 39 ÷ 15</li></ol><div class="wa">Answer: 2.6 g/cm³</div></div><p>Solids are usually densest because their particles are packed most closely; gases have very low densities.</p>` },
  ],
  mistakes: ['Saying particles expand or melt — the particles stay the same; only their movement and spacing change.', 'Saying solid particles do not move — they vibrate.', 'Saying the space between gas particles is "air" — it is empty space.', 'Mixing up evaporation (surface, any temperature) and boiling (throughout, at the boiling point).'],
  examTips: ['For "describe" questions about states, mention BOTH arrangement and movement of particles.', 'For "explain" questions about pressure, link faster particles to more frequent AND harder collisions with the walls.', 'Always give units with density answers (g/cm³).'],
  realLife: 'Gas pressure is why car tyres are checked when cold — after a long drive the warm air inside gives a higher, misleading reading.',
});

// =====================================================================
// YEAR 7 — Pure substances, mixtures & separation
// =====================================================================
topic({ id: 'chem-y7-mixtures', strand: 'chem-atomic', year: 7, term: 2, tier: 'FH', name: 'Elements, Compounds, Mixtures & Separation',
  summary: 'Tell elements, compounds and mixtures apart and choose the right technique to separate a mixture.', specRef: 'KS3 Chemistry: Pure and impure substances' }, [
  { name: 'Elements, compounds & mixtures', intro: 'An element contains only one type of atom. A compound has two or more elements chemically joined in fixed proportions. A mixture has substances that are not chemically joined.', items: [
    M('What is an <b>element</b>?', ['A substance made of only one type of atom', 'Two or more atoms chemically joined', 'A mixture of different atoms', 'Any substance that is a solid'], 0, 'An element contains only one type of atom (all with the same number of protons). Molecules such as O<sub>2</sub> can still be an element because both atoms are oxygen.'),
    M('Which of these is a <b>compound</b>?', ['Carbon dioxide, CO<sub>2</sub>', 'Oxygen, O<sub>2</sub>', 'Iron, Fe', 'Air'], 0, 'CO<sub>2</sub> contains two different elements (carbon and oxygen) chemically bonded. O<sub>2</sub> is an element (only oxygen atoms); air is a mixture.'),
    M('Which of these is a <b>mixture</b>?', ['Sea water', 'Water', 'Sodium chloride', 'Copper'], 0, 'Sea water is water with dissolved salts — not chemically joined and separable by physical means. Water and sodium chloride are compounds; copper is an element.'),
    T('The properties of a compound are usually very different from those of the elements it is made from.', true, 'True. Sodium (a reactive metal) and chlorine (a toxic gas) make sodium chloride — table salt. A new substance with new properties forms.'),
    T('A mixture always contains substances in fixed proportions.', false, 'False. Mixtures can have any proportions (you can add more sugar to tea). Compounds have fixed proportions — water is always H<sub>2</sub>O.'),
    M('Iron filings and sulfur powder are stirred together. Which is true?', ['It is a mixture; a magnet can remove the iron', 'It is a compound called iron sulfide', 'The iron and sulfur have reacted', 'It cannot be separated'], 0, 'Simply stirring makes a mixture; the iron keeps its magnetic property so a magnet separates it. Only heating them makes the compound iron sulfide, which is not magnetic.'),
    S('What name is given to a substance made of two or more different elements chemically combined?', 'compound', ['compound', 'a compound'], 'A compound has two or more elements chemically bonded in fixed proportions. It can only be separated by a chemical reaction.'),
    X('Which TWO are elements?', ['Nitrogen, N<sub>2</sub>', 'Water, H<sub>2</sub>O', 'Gold, Au', 'Air', 'Salt, NaCl'], [0, 2], 'N<sub>2</sub> and Au contain only one type of atom. Water and salt are compounds; air is a mixture of gases.'),
    M('How many different elements are in calcium carbonate, CaCO<sub>3</sub>?', ['3', '5', '1', '2'], 0, 'Ca, C and O — three elements. Five is the number of atoms (1 Ca + 1 C + 3 O), not the number of elements.'),
    M('How many atoms are in one molecule of glucose, C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>?', ['24', '3', '18', '12'], 0, '6 + 12 + 6 = 24 atoms. There are 3 different elements; do not confuse number of elements with number of atoms.'),
    M('Which diagram description shows a mixture of an element and a compound?', ['Single circles of one colour plus pairs of joined circles of two colours', 'Only pairs of joined circles of the same colour', 'Only single circles of one colour', 'Only pairs of joined circles of two colours'], 0, 'Single identical atoms = an element; joined atoms of different colours = a compound. Having both types of particle present = a mixture.'),
    T('Air is a compound of nitrogen and oxygen.', false, 'False. Air is a mixture — the nitrogen, oxygen, argon and carbon dioxide are not chemically joined, and the proportions can vary.'),
    S('What is the chemical symbol for sodium?', 'Na', ['na'], 'Sodium is Na (from its Latin name natrium). S is sulfur, So is not an element symbol.'),
    M('In chemistry, what does "pure" mean?', ['A single element or compound, not mixed with anything else', 'Natural with nothing added', 'Safe to drink', 'Clean and colourless'], 0, 'In everyday language "pure" orange juice means nothing added, but chemically it is a mixture. A chemically pure substance is one element or one compound only.'),
    O('Put these in order from simplest to most complex.', ['Atom', 'Molecule of an element (e.g. O<sub>2</sub>)', 'Molecule of a compound (e.g. CO<sub>2</sub>)', 'Mixture of compounds (e.g. air)'], 'Atoms join to make molecules; molecules of different elements make compounds; compounds and elements mixed together make mixtures.'),
    M('Which formula represents an element?', ['Cl<sub>2</sub>', 'HCl', 'NaCl', 'CCl<sub>4</sub>'], 0, 'Cl<sub>2</sub> contains only chlorine atoms. All the others contain more than one element.'),
    M('Which of these is a <b>molecule of a compound</b>?', ['H<sub>2</sub>O', 'O<sub>2</sub>', 'N<sub>2</sub>', 'He'], 0, 'H<sub>2</sub>O contains two different elements (hydrogen and oxygen) chemically joined, so it is a compound. O<sub>2</sub> and N<sub>2</sub> are molecules of elements (only one type of atom); He exists as single atoms of an element.'),
    M('Sodium is a reactive metal and chlorine is a poisonous green gas. They react to make sodium chloride. What does this show?', ['A compound can have very different properties from its elements', 'Sodium chloride must be poisonous', 'Sodium chloride is a mixture of sodium and chlorine', 'The elements keep their own properties'], 0, 'Sodium chloride (table salt) is safe to eat even though sodium and chlorine are dangerous. When elements chemically combine, a new substance with new properties forms. In a mixture, the substances would keep their properties.'),
    M('Why is it hard to separate the elements in a compound?', ['They are chemically joined, so a chemical reaction is needed', 'They are too small to see', 'They are always gases', 'They are mixed in random amounts'], 0, 'The atoms in a compound are held together by chemical bonds, so physical methods like filtering or distilling cannot separate them — a chemical reaction (or electrolysis) is needed.'),
    M('Which statement about a mixture of iron and sulfur is correct?', ['A magnet can pull out the iron', 'It has a fixed formula, FeS', 'It must be heated to separate it', 'It is a new substance with new properties'], 0, 'In a mixture, iron keeps its magnetic property, so a magnet separates it. Only after heating do iron and sulfur react to form the compound iron sulfide (FeS), which is not magnetic.'),
    T('An element can be broken down into simpler substances by a chemical reaction.', false, 'False. An element contains only one type of atom, so it cannot be broken down into anything simpler by chemical means.'),
    T('There are around 118 known elements.', true, 'True. About 118 elements are known; they are all listed in the periodic table. Every other substance is made from these elements.'),
    T('Oxygen gas, O<sub>2</sub>, is a compound because it has two atoms joined together.', false, 'False. O<sub>2</sub> has two atoms but they are both oxygen — the same element. A compound needs two or more <i>different</i> elements chemically joined.'),
    S('What is the smallest particle of an element that can exist?', 'atom', ['atom', 'an atom', 'atoms'], 'An atom is the smallest part of an element that can exist. Atoms can join to make molecules.'),
    S('What name is given to two or more atoms chemically bonded together?', 'molecule', ['molecule', 'a molecule', 'molecules'], 'A molecule is two or more atoms chemically bonded. The atoms can be the same element (O<sub>2</sub>) or different elements (CO<sub>2</sub>).'),
    X('Which TWO are mixtures?', ['Sea water', 'Air', 'Carbon dioxide', 'Copper', 'Water'], [0, 1], 'Sea water (water + dissolved salts) and air (nitrogen, oxygen, argon, CO<sub>2</sub> …) are mixtures. Carbon dioxide and water are compounds; copper is an element.'),
    M('How many atoms are there in one molecule of ammonia, NH<sub>3</sub>?', ['4', '3', '2', '1'], 0, 'NH<sub>3</sub> has 1 nitrogen atom and 3 hydrogen atoms = 4 atoms. The small number only applies to the symbol just before it.'),
    M('How many different elements are in sulfuric acid, H<sub>2</sub>SO<sub>4</sub>?', ['3', '7', '4', '2'], 0, 'H<sub>2</sub>SO<sub>4</sub> contains hydrogen, sulfur and oxygen — 3 different elements. The total number of atoms is 7, which is a different question.'),
    M('A substance cannot be split up by physical methods but can be broken down by electrolysis. What is it?', ['A compound', 'An element', 'A mixture', 'A pure element mixed with water'], 0, 'Mixtures can be separated physically. Elements cannot be broken down at all. A substance broken down only by a chemical process (like electrolysis) is a compound.'),
    O('Put these in order of size, smallest first.', ['Atom', 'Molecule of water', 'Grain of salt', 'Drop of sea water'], 'An atom is smallest; a water molecule contains three atoms; a grain of salt contains billions of particles; a drop of sea water is a mixture containing huge numbers of particles.'),
  ] },
  { name: 'Separating mixtures', intro: 'Because the substances in a mixture are not chemically joined, physical methods can separate them: filtration, evaporation, crystallisation, simple and fractional distillation, and chromatography.', items: [
    M('Which method separates sand from water?', ['Filtration', 'Distillation', 'Chromatography', 'Crystallisation'], 0, 'Sand is insoluble, so its grains are trapped by filter paper while water passes through. Distillation would work but is unnecessary; chromatography separates dissolved substances.'),
    M('Which method gets salt crystals from salty water?', ['Crystallisation (or evaporation)', 'Filtration', 'Using a magnet', 'Fractional distillation'], 0, 'The salt is dissolved, so it passes through filter paper. Heating to evaporate water leaves the salt; crystallisation (heating gently, then leaving to cool) gives good crystals.'),
    M('Which method obtains pure water from sea water?', ['Simple distillation', 'Filtration', 'Chromatography', 'Evaporation'], 0, 'Distillation boils the water, then condenses the vapour back to liquid, leaving the salt behind. Evaporation alone loses the water to the air.'),
    M('Which method separates a mixture of liquids with different boiling points, such as ethanol and water?', ['Fractional distillation', 'Filtration', 'Crystallisation', 'Using a separating funnel and a magnet'], 0, 'Fractional distillation uses a fractionating column so liquids condense and are collected at different temperatures. Ethanol (bp 78 °C) distils off before water (100 °C).'),
    M('Which method shows how many dyes are in a felt-tip ink?', ['Paper chromatography', 'Filtration', 'Distillation', 'Evaporation'], 0, 'In chromatography each dye travels a different distance up the paper with the solvent, so separate spots show the different dyes.'),
    S('In filtration, what name is given to the liquid that passes through the filter paper?', 'filtrate', ['filtrate', 'the filtrate'], 'The liquid that passes through is the filtrate; the solid left on the paper is the residue.'),
    S('In filtration, what is the solid left on the filter paper called?', 'residue', ['residue', 'the residue'], 'The trapped insoluble solid is the residue; the liquid passing through is the filtrate.'),
    O('Put the steps for getting pure salt from rock salt (salt + sand) in order.', ['Grind the rock salt and add water', 'Stir and warm to dissolve the salt', 'Filter to remove the sand', 'Heat the filtrate to evaporate some water, then leave to crystallise'], 'Dissolve the salt, filter out the insoluble sand, then crystallise the salt from the filtrate.'),
    M('In simple distillation, what is the job of the condenser?', ['To cool the vapour so it turns back into a liquid', 'To heat the mixture', 'To filter out solids', 'To measure the boiling point'], 0, 'Cold water flowing around the condenser cools the vapour, which condenses into a liquid (the distillate). The thermometer measures temperature, not the condenser.'),
    T('Filtration can remove salt from salty water.', false, 'False. Dissolved salt particles are tiny and pass through filter paper with the water. Filtration only removes insoluble solids.'),
    T('Crystallisation gives larger crystals if the solution is cooled slowly.', true, 'True. Slow cooling allows particles time to arrange into large regular crystals.'),
    M('Why is crystallisation sometimes chosen instead of evaporating to dryness?', ['Some solids decompose or spit when heated strongly', 'It is faster', 'It removes insoluble impurities', 'It produces more water'], 0, 'Heating to dryness can break down some salts (e.g. hydrated copper sulfate loses water) and is hazardous; gentle evaporation then cooling forms crystals safely.'),
    X('Which TWO mixtures could be separated using a separating funnel?', ['Oil and water', 'Salt and water', 'Petrol and water', 'Ethanol and water', 'Sand and water'], [0, 2], 'A separating funnel separates immiscible liquids (that do not mix) — oil/water, petrol/water. Ethanol mixes with water; salt dissolves; sand needs filtering.'),
    M('Iron filings are mixed with sand. Best way to separate them?', ['Use a magnet', 'Filtration', 'Distillation', 'Chromatography'], 0, 'Iron is magnetic and sand is not. Neither dissolves in water, so filtering would not separate them.'),
    O('Put the steps of simple distillation in order.', ['Heat the mixture in a flask', 'The liquid with the lowest boiling point evaporates', 'The vapour is cooled in the condenser', 'Pure liquid (distillate) is collected'], 'Heat → evaporate → condense → collect.'),
    M('Which property allows fractional distillation to separate liquids?', ['Different boiling points', 'Different colours', 'Different solubility in water', 'Different magnetism'], 0, 'Each liquid boils and condenses at a different temperature, so the fractions can be collected separately.'),
    M('Which method would separate a mixture of salt and sugar dissolved together in water?', ['None of these simple methods separates them easily', 'Filtration', 'Using a magnet', 'Sieving'], 0, 'Both salt and sugar are dissolved, so filtration, sieving and magnets cannot separate them. This is why choosing the right method depends on the properties of each part of the mixture.'),
    M('Why does filtration separate sand from water?', ['Sand grains are too big to pass through the tiny holes in the filter paper', 'Sand dissolves in water', 'Water evaporates through the paper', 'Sand is attracted to the paper'], 0, 'Filter paper has tiny holes: water molecules and dissolved particles pass through, but insoluble sand grains are too large and are trapped as residue.'),
    M('In chromatography, why must the start line be drawn in pencil, not pen?', ['Pencil does not dissolve in the solvent and run up the paper', 'Pencil is easier to see', 'Pen would make the paper too heavy', 'Pencil makes the dyes move faster'], 0, 'Graphite in pencil is insoluble in the solvent, so it stays put. Ink from a pen would dissolve and separate, confusing the results.'),
    M('In chromatography, why must the ink spots be placed above the level of the solvent?', ['Otherwise the dyes would dissolve into the solvent in the beaker', 'So the spots dry faster', 'So the solvent evaporates', 'So the paper does not tear'], 0, 'If the spots are below the solvent, the dyes wash out into the solvent in the beaker instead of travelling up the paper.'),
    M('Which part of the distillation apparatus has cold water flowing through it?', ['The condenser', 'The flask', 'The thermometer', 'The beaker collecting the distillate'], 0, 'Cold water flows around the condenser to cool the hot vapour so it condenses back into a liquid.'),
    T('In chromatography, a dye that is more soluble in the solvent travels further up the paper.', true, 'True. More soluble dyes spend more time dissolved in the moving solvent, so they travel further before the solvent stops.'),
    T('Evaporation can separate two liquids that are mixed together.', false, 'False. Evaporating would just remove both liquids into the air. Mixed liquids that dissolve in each other are separated by distillation (or fractional distillation).'),
    S('What name is given to the liquid collected at the end of distillation?', 'distillate', ['distillate', 'the distillate'], 'The distillate is the condensed liquid collected after distillation — for example pure water from salty water.'),
    S('What separation method uses a sieve to separate particles of different sizes, such as gravel and sand?', 'sieving', ['sieving', 'sieve', 'sifting'], 'Sieving separates solids with different particle sizes — the small pieces fall through the holes while the large pieces stay behind.'),
    M('Black ink from a pen gives three coloured spots on a chromatogram. What does this show?', ['The ink is a mixture of at least three dyes', 'The ink is a pure substance', 'The ink is an element', 'The solvent has three colours'], 0, 'Each separate spot is a different dye, so the ink is a mixture of at least three. A pure substance would give just one spot.'),
    X('Which TWO methods could be used to get pure water from muddy, salty water?', ['Filter, then distil the filtrate', 'Distil the muddy, salty water directly', 'Filter only', 'Evaporate to dryness', 'Use a magnet'], [0, 1], 'Distillation leaves both mud and salt behind, so it works directly (filtering first keeps the flask cleaner). Filtering alone leaves the salt dissolved; evaporating to dryness throws the water away.'),
    M('Crude oil is separated into petrol, diesel and other parts. Which method is used?', ['Fractional distillation', 'Filtration', 'Chromatography', 'Crystallisation'], 0, 'Crude oil is a mixture of many liquids with different boiling points, so it is separated by fractional distillation.'),
    M('Why is a thermometer placed at the top of the flask in distillation?', ['To measure the boiling point of the vapour going into the condenser', 'To stir the mixture', 'To measure the temperature of the cold water', 'To stop the liquid boiling'], 0, 'The thermometer bulb sits by the side arm so it reads the temperature of the vapour leaving the flask — which tells you which substance is being collected.'),
    O('Put the steps of making a paper chromatogram in order.', ['Draw a pencil line near the bottom of the paper', 'Put small spots of ink on the line', 'Stand the paper in solvent below the line', 'Remove the paper when the solvent nears the top and let it dry'], 'Pencil line first, then spots on it, then stand in solvent below the line. Remove when the solvent front is near the top and mark how far it reached.'),
  ] },
  { name: 'Solutions & solubility', intro: 'A solution forms when a solute dissolves in a solvent. Solubility is how much solute dissolves in a fixed amount of solvent at a given temperature.', items: [
    M('In salty water, what is the <b>solute</b>?', ['Salt', 'Water', 'Salty water', 'Air'], 0, 'The solute is the substance that dissolves (salt). The solvent is the liquid it dissolves in (water). The mixture formed is the solution.'),
    M('In salty water, what is the <b>solvent</b>?', ['Water', 'Salt', 'Salty water', 'Sodium'], 0, 'The solvent is the liquid that does the dissolving — water. Salt is the solute.'),
    S('What word describes a substance that will NOT dissolve in a solvent?', 'insoluble', ['insoluble'], 'Insoluble substances (e.g. sand in water) do not dissolve. Soluble substances do.'),
    M('10 g of sugar dissolves in 100 g of water. What is the mass of the solution?', ['110 g', '100 g', '90 g', '10 g'], 0, 'Mass is conserved when dissolving: 100 + 10 = 110 g. The sugar has not disappeared — its particles are spread between water particles.'),
    T('When sugar dissolves, it disappears and its mass is lost.', false, 'False. Dissolving is a physical change; the sugar particles spread out between the water particles. You can taste it and get it back by evaporation, and mass is conserved.'),
    S('What name is given to a solution in which no more solute can dissolve at that temperature?', 'saturated', ['saturated', 'saturated solution', 'a saturated solution'], 'A saturated solution holds the maximum amount of solute at that temperature. Extra solid stays undissolved.'),
    M('For most solids, what happens to solubility as temperature increases?', ['It increases', 'It decreases', 'It stays the same', 'It becomes zero'], 0, 'Most solids dissolve better in hotter water — that is why crystals form as a hot saturated solution cools. (Gases do the opposite: they are less soluble in warm water.)'),
    N('A solubility of 36 g per 100 g of water means how many grams dissolve in 50 g of water?', 18, 0.01, 'g', ['Solubility per 100 g = 36 g', '50 g is half of 100 g', 'Mass = 36 × 50 ÷ 100 = 18 g'], 'Halve the water, halve the amount that can dissolve.'),
    N('A student dissolves 25 g of salt in 200 g of water. What is the mass of the solution?', 225, 0, 'g', ['mass of solution = mass of solute + mass of solvent', '= 25 + 200', '= 225 g'], 'Mass is conserved in dissolving.'),
    M('Which would make sugar dissolve faster?', ['Stirring and using warmer water', 'Using bigger sugar lumps', 'Using colder water', 'Leaving it still'], 0, 'Stirring and heating make particles move and mix faster; smaller pieces have more surface area. Bigger lumps and cold water slow dissolving.'),
    T('A solution is a mixture.', true, 'True. A solution is a mixture of solute and solvent that are not chemically joined; they can be separated by evaporation or distillation.'),
    M('Nail varnish does not dissolve in water but does dissolve in propanone. What does this show?', ['Solubility depends on the solvent', 'Nail varnish is an element', 'Propanone is water', 'Nail varnish is a liquid'], 0, 'A substance can be insoluble in one solvent but soluble in another. That is why we use different solvents in chromatography and cleaning.'),
    X('Which TWO are true of a solution such as copper sulfate solution?', ['It is transparent (see-through)', 'It can be coloured', 'The solute settles at the bottom', 'It can be separated by filtering', 'It is a pure compound'], [0, 1], 'Solutions are transparent but may be coloured (blue copper sulfate). Dissolved solute does not settle and passes through filter paper. A solution is a mixture, not a pure compound.'),
    M('What is the word for a liquid that does not mix with water and forms a separate layer?', ['Immiscible', 'Soluble', 'Saturated', 'Miscible'], 0, 'Immiscible liquids (oil and water) form layers. Miscible liquids (ethanol and water) mix completely.'),
    S('A hot saturated solution of copper sulfate is cooled. What forms?', 'crystals', ['crystals', 'crystal', 'copper sulfate crystals'], 'Solubility falls as it cools, so solid copper sulfate comes out of solution as crystals.', [['crystal']]),
    M('Which of these is a solution?', ['Sugar dissolved in tea', 'Sand stirred into water', 'Oil floating on water', 'Chalk powder in water'], 0, 'In a solution the solute is dissolved and spread evenly so you cannot see separate particles. Sand and chalk do not dissolve (they are insoluble); oil and water do not mix.'),
    M('What word describes a substance that dissolves in a solvent?', ['Soluble', 'Insoluble', 'Saturated', 'Immiscible'], 0, 'Soluble means able to dissolve. Insoluble means it will not dissolve; saturated means no more can dissolve; immiscible describes liquids that do not mix.'),
    M('Why does a solution look clear even though it contains a dissolved solid?', ['The solute particles have spread out between the solvent particles', 'The solute has disappeared', 'The solute has turned into a gas', 'The solute has sunk to the bottom'], 0, 'When a solid dissolves, its particles separate and spread out between the solvent particles — they are too small to see, but they are still there and still have mass.'),
    M('Why does powdered sugar dissolve faster than a sugar cube?', ['It has a larger surface area exposed to the water', 'It is a different chemical', 'It is lighter', 'It has a higher solubility'], 0, 'Powder exposes more surface to the water, so more particles can be surrounded by water at once. The solubility (how much can dissolve) is the same; only the rate changes.'),
    T('Stirring increases how much solute can dissolve in total.', false, 'False. Stirring makes a solute dissolve faster, but does not change its solubility — the maximum that can dissolve at that temperature.'),
    T('Water is sometimes called a universal solvent because it dissolves many different substances.', true, 'True. Water dissolves a wide range of substances, which is why most solutions we meet are aqueous. It does not dissolve everything, though — oils and fats do not dissolve in water.'),
    T('Two liquids that mix completely, like ethanol and water, are described as miscible.', true, 'True. Miscible liquids mix together completely; immiscible liquids such as oil and water form separate layers.'),
    S('What name is given to the liquid that dissolves the solute?', 'solvent', ['solvent', 'the solvent'], 'The solvent does the dissolving. Solute + solvent → solution.'),
    S('What name is given to a solution where water is the solvent?', 'aqueous', ['aqueous', 'aqueous solution', 'an aqueous solution'], 'An aqueous solution is one in water. It is shown by the state symbol (aq) in equations.'),
    N('The solubility of potassium nitrate at 40 °C is 64 g per 100 g of water. What mass will dissolve in 250 g of water at 40 °C?', 160, 0.5, 'g', ['Solubility is per 100 g of water', '250 g is 2.5 × 100 g', '2.5 × 64 = 160 g'], 'Scale up the solubility: 250 g of water is 2.5 times 100 g, so 2.5 × 64 = 160 g dissolves.'),
    N('A solution is made by dissolving salt in 80 g of water. The solution has mass 92 g. What mass of salt was used?', 12, 0.01, 'g', ['mass of solution = mass of solute + mass of solvent', 'mass of salt = 92 − 80', 'mass of salt = 12 g'], 'Mass is conserved when dissolving, so the solute mass is the difference between the solution mass and the water mass.'),
    M('A student adds salt to water until no more dissolves. She then heats the water. What will happen?', ['More salt will dissolve', 'The salt will come out of solution', 'Nothing can dissolve after saturation', 'The water will become a solid'], 0, 'For most solids, solubility increases with temperature, so heating a saturated solution allows more solute to dissolve.'),
    M('Fizzy drinks go flat faster when warm. What does this suggest about gases dissolved in water?', ['Gases are less soluble in warmer water', 'Gases are more soluble in warmer water', 'Temperature has no effect', 'Gases turn into liquids when warm'], 0, 'Unlike most solids, gases become LESS soluble as temperature rises, so carbon dioxide escapes faster from a warm drink.'),
    X('Which TWO will make salt dissolve faster in water?', ['Stirring', 'Using warmer water', 'Using bigger crystals', 'Using colder water', 'Adding less water'], [0, 1], 'Stirring and heating help water particles reach and pull away the salt particles more quickly. Bigger crystals and colder water slow dissolving.'),
    O('Put these in order to make a saturated solution of copper sulfate and then grow crystals.', ['Add copper sulfate to warm water and stir', 'Keep adding until no more dissolves', 'Filter off the undissolved solid', 'Leave the solution to cool slowly'], 'Dissolve, continue until saturated, filter out the excess solid, then cool slowly — solubility falls as it cools, so crystals form.'),
  ] },
], {
  overview: 'Chemists classify substances as <b>elements</b>, <b>compounds</b> or <b>mixtures</b>. Because the parts of a mixture are not chemically joined, physical methods such as filtration, crystallisation, distillation and chromatography can separate them.',
  objectives: ['I can define element, compound and mixture and identify them from formulae or particle diagrams', 'I can explain what pure means in chemistry', 'I can choose and describe a separation technique', 'I can use the words solute, solvent, solution, soluble and saturated', 'I can explain why mass is conserved when dissolving'],
  keyWords: [{ term: 'Element', def: 'A substance made of only one type of atom.' }, { term: 'Compound', def: 'Two or more elements chemically combined in fixed proportions.' }, { term: 'Mixture', def: 'Two or more substances not chemically combined.' }, { term: 'Pure substance', def: 'A single element or compound.' }, { term: 'Filtration', def: 'Separates an insoluble solid from a liquid.' }, { term: 'Crystallisation', def: 'Obtains a soluble solid from a solution by evaporating some solvent then cooling.' }, { term: 'Distillation', def: 'Separates a liquid from a solution (simple) or liquids with different boiling points (fractional).' }, { term: 'Solubility', def: 'Mass of solute that dissolves in a fixed mass of solvent at a set temperature.' }],
  sections: [
    { title: 'Elements, compounds and mixtures', html: `<ul><li><b>Element</b>: one type of atom, e.g. Fe, O<sub>2</sub>.</li><li><b>Compound</b>: different elements chemically bonded in a fixed ratio, e.g. H<sub>2</sub>O, CO<sub>2</sub>. Has different properties from its elements. Separated only by chemical reactions.</li><li><b>Mixture</b>: substances not chemically joined, any proportions, each keeps its own properties. Separated by physical methods.</li></ul><div class="note">Count elements and atoms separately: H<sub>2</sub>SO<sub>4</sub> has 3 elements but 7 atoms.</div>` },
    { title: 'Choosing a separation technique', html: `<table class="qt"><tr><th>Mixture</th><th>Method</th></tr><tr><td>Insoluble solid + liquid (sand + water)</td><td>Filtration</td></tr><tr><td>Soluble solid from solution (salt from salt water)</td><td>Evaporation or crystallisation</td></tr><tr><td>Liquid from a solution (water from sea water)</td><td>Simple distillation</td></tr><tr><td>Liquids with different boiling points (ethanol + water)</td><td>Fractional distillation</td></tr><tr><td>Dissolved coloured substances (inks, dyes)</td><td>Chromatography</td></tr></table>` },
    { title: 'Distillation', html: `<p>In <b>simple distillation</b> the solution is heated; the solvent boils, the vapour travels into a water-cooled <b>condenser</b>, condenses and drips into a beaker as the pure <b>distillate</b>. The solute stays in the flask.</p><p><b>Fractional distillation</b> adds a fractionating column. It is hotter at the bottom and cooler at the top, so liquids with different boiling points can be collected one at a time.</p>` },
    { title: 'Solutions and solubility', html: `<div class="rule">solute + solvent → solution; mass of solution = mass of solute + mass of solvent</div><p>A <b>saturated</b> solution cannot dissolve any more solute at that temperature. Most solids are more soluble in hot water, so a hot saturated solution forms crystals as it cools.</p><div class="worked"><div class="wq">Solubility of potassium nitrate at 20 °C is 32 g per 100 g water. How much dissolves in 250 g of water?</div><ol><li>32 g per 100 g → 0.32 g per gram of water</li><li>0.32 × 250 = 80</li></ol><div class="wa">Answer: 80 g</div></div>` },
  ],
  mistakes: ['Thinking that "pure" orange juice is chemically pure — it is a mixture.', 'Trying to filter out a dissolved solid — filtration only removes insoluble solids.', 'Saying a dissolved substance disappears — it is still there and mass is conserved.', 'Confusing number of elements with number of atoms in a formula.'],
  examTips: ['When asked to describe a separation, give equipment AND what happens to each substance (e.g. "sand stays on the filter paper as residue").', 'Name the correct technique precisely: "crystallisation", not just "heating".', 'In particle-diagram questions, look for joined atoms of different types (compound) and more than one type of particle (mixture).'],
  realLife: 'Desalination plants in dry countries use distillation or reverse osmosis to turn sea water into drinking water.',
});

// =====================================================================
// YEAR 8 — Atoms, elements & the periodic table
// =====================================================================
topic({ id: 'chem-y8-atoms-periodic', strand: 'chem-atomic', year: 8, term: 1, tier: 'FH', name: 'Atoms & the Periodic Table',
  summary: 'Describe atoms, use chemical symbols and the periodic table, and compare metals with non-metals.', specRef: 'KS3 Chemistry: Atoms, elements and compounds; The periodic table' }, [
  { name: 'Atoms, symbols & formulae', intro: 'Atoms are the smallest part of an element that can exist. Each element has a one- or two-letter symbol, and formulae show which atoms are in a substance.', items: [
    M('What is the symbol for potassium?', ['K', 'P', 'Po', 'Pt'], 0, 'Potassium is K (from Latin kalium). P is phosphorus, Po is polonium, Pt is platinum.'),
    M('What is the symbol for iron?', ['Fe', 'I', 'Ir', 'In'], 0, 'Iron is Fe (Latin ferrum). I is iodine, Ir iridium, In indium.'),
    M('Which is written correctly?', ['Mg', 'MG', 'mg', 'mG'], 0, 'Symbols start with a capital letter; any second letter is lower case. MG would wrongly suggest two elements.'),
    S('Which element has the symbol Cu?', 'copper', ['copper'], 'Cu comes from the Latin cuprum, meaning copper.'),
    S('Which element has the symbol Pb?', 'lead', ['lead'], 'Pb is from plumbum (Latin for lead) — the same root as "plumber", as old water pipes were lead.'),
    M('How many atoms are in one formula unit of Ca(OH)<sub>2</sub>?', ['5', '4', '3', '6'], 0, 'The 2 multiplies everything in the bracket: 1 Ca + 2 O + 2 H = 5 atoms. Forgetting to multiply the bracket gives 3.'),
    M('What does the formula H<sub>2</sub>O tell you?', ['Each molecule has 2 hydrogen atoms and 1 oxygen atom', 'Each molecule has 2 oxygen atoms and 1 hydrogen atom', 'It is a mixture of hydrogen and oxygen gases', 'It contains 2 molecules of hydrogen'], 0, 'The small number after a symbol applies only to that symbol. H<sub>2</sub>O: 2 H, 1 O, chemically bonded — not a mixture.'),
    T('An atom is the smallest part of an element that can exist.', true, 'True. Atoms are made of smaller subatomic particles, but an atom is the smallest piece that still counts as that element.'),
    T('All atoms of the same element are identical in the number of protons.', true, 'True. The number of protons (atomic number) defines the element. (Isotopes differ only in neutrons — you will meet these at GCSE.)'),
    M('Roughly how many elements are known?', ['About 118', 'About 20', 'About 1000', 'Exactly 50'], 0, 'There are 118 known elements, about 94 occurring naturally. Millions of compounds are made from them.'),
    M('What is a molecule?', ['Two or more atoms chemically joined', 'A single atom', 'A mixture of elements', 'A charged atom'], 0, 'A molecule is atoms bonded together; they can be the same (O<sub>2</sub>) or different (CO<sub>2</sub>). A charged atom is an ion.'),
    S('Name the compound with formula NaCl.', 'sodium chloride', ['sodium chloride'], 'Metal first, then the non-metal with the ending changed to "-ide": chlorine → chloride.', [['sodium'], ['chloride']]),
    M('What is the name of MgO?', ['Magnesium oxide', 'Magnesium oxygen', 'Manganese oxide', 'Magnesium oxidate'], 0, 'Two elements: metal + non-metal-ide. Oxygen becomes oxide. Mg is magnesium (Mn is manganese).'),
    M('What do compounds ending in "-ate", like copper sulfate, contain?', ['Oxygen as well as the other elements', 'Only two elements', 'No metal', 'Hydrogen'], 0, '"-ate" means oxygen is present: sulfate = SO<sub>4</sub>, carbonate = CO<sub>3</sub>, nitrate = NO<sub>3</sub>. "-ide" usually means just two elements.'),
    M('How many different elements are in CuSO<sub>4</sub>?', ['3', '6', '4', '2'], 0, 'Cu, S and O = 3 elements (6 atoms).'),
    X('Which TWO statements about Dalton\'s ideas are still accepted?', ['Elements are made of atoms', 'Atoms of an element are alike in the way they react', 'Atoms cannot be divided into anything smaller', 'Atoms are solid all the way through', 'All atoms are the same size'], [0, 1], 'Dalton said matter is made of atoms and each element\'s atoms are alike — still useful. We now know atoms contain smaller particles and are mostly empty space.'),
    M('What is the symbol for sodium?', ['Na', 'So', 'S', 'Sd'], 0, 'Sodium is Na, from its Latin name <i>natrium</i>. S is sulfur; So and Sd are not symbols of any element.'),
    M('What is the symbol for chlorine?', ['Cl', 'CL', 'C', 'Ch'], 0, 'Chlorine is Cl — a capital C then a lower-case l. CL is wrong because only the first letter is a capital; C on its own is carbon.'),
    M('The formula of carbon dioxide is CO<sub>2</sub>. What does the small 2 tell you?', ['There are two oxygen atoms in each molecule', 'There are two carbon atoms', 'There are two molecules', 'The molecule has a charge of 2'], 0, 'A subscript number applies only to the symbol immediately before it, so CO<sub>2</sub> has 1 carbon and 2 oxygen atoms. A big number in front (2CO<sub>2</sub>) would show two molecules.'),
    M('Why is "Co" not the same as "CO"?', ['Co is the element cobalt; CO is a compound of carbon and oxygen', 'They are the same thing written differently', 'CO is an element and Co is a compound', 'Co is a mistake and does not exist'], 0, 'A capital letter always starts a new symbol. Co (one symbol) is cobalt; CO (two symbols) is carbon monoxide, a compound of carbon and oxygen.'),
    M('How many atoms are in one molecule of ethanol, C<sub>2</sub>H<sub>5</sub>OH?', ['9', '8', '4', '3'], 0, 'C<sub>2</sub> = 2, H<sub>5</sub> = 5, O = 1, H = 1, so 2 + 5 + 1 + 1 = 9 atoms. There are 3 different elements, which is a different question.'),
    M('What is the name of the compound K<sub>2</sub>O?', ['Potassium oxide', 'Potassium dioxide', 'Krypton oxide', 'Potassium oxygenate'], 0, 'A metal + oxygen compound is named "metal oxide". K is potassium (not krypton, which is Kr). The "di-" prefix is not used in naming simple ionic compounds like this.'),
    M('What is the name of the compound FeS?', ['Iron sulfide', 'Iron sulfate', 'Iron sulfur', 'Fluorine sulfide'], 0, 'A compound of two elements usually ends in "-ide", so iron + sulfur → iron sulfide. "-ate" (sulfate) means oxygen is also present. Fe is iron, not fluorine (F).'),
    T('In the formula Mg(OH)<sub>2</sub>, the 2 doubles both the oxygen and the hydrogen.', true, 'True. A number after a bracket multiplies everything inside it: Mg(OH)<sub>2</sub> has 1 Mg, 2 O and 2 H atoms.'),
    T('Every element symbol starts with a capital letter.', true, 'True. Symbols are one capital letter, or a capital followed by a lower-case letter (e.g. Mg, Zn). This lets you see where each new symbol starts in a formula.'),
    S('Which element has the symbol Ag?', 'silver', ['silver'], 'Ag is silver, from the Latin <i>argentum</i>. Several symbols come from Latin names: Fe (iron), Pb (lead), Cu (copper), Na (sodium), K (potassium).'),
    S('What is the chemical symbol for magnesium?', 'Mg', ['mg'], 'Magnesium is Mg. Note that M on its own is not a symbol and Mn is manganese.'),
    X('Which TWO formulae contain exactly three atoms?', ['H<sub>2</sub>O', 'CO<sub>2</sub>', 'NH<sub>3</sub>', 'CH<sub>4</sub>', 'NaCl'], [0, 1], 'H<sub>2</sub>O = 2 + 1 = 3 and CO<sub>2</sub> = 1 + 2 = 3 atoms. NH<sub>3</sub> has 4, CH<sub>4</sub> has 5 and NaCl has 2.'),
    M('A compound is named calcium carbonate. Which elements does it contain?', ['Calcium, carbon and oxygen', 'Calcium and carbon only', 'Calcium, carbon and nitrogen', 'Calcium and oxygen only'], 0, 'The ending "-ate" tells you oxygen is present as well. Carbonate = carbon + oxygen, so calcium carbonate (CaCO<sub>3</sub>) contains Ca, C and O.'),
    M('What does the chemical symbol "O" stand for?', ['Oxygen', 'Osmium', 'Oxide', 'Gold'], 0, 'O is oxygen. Osmium is Os, gold is Au, and "oxide" is not an element — it is part of a compound name.'),
  ] },
  { name: 'The periodic table', intro: 'The periodic table arranges elements by atomic number. Columns are groups (similar properties); rows are periods. Metals are on the left, non-metals on the right.', items: [
    M('What is a vertical column of the periodic table called?', ['A group', 'A period', 'A series', 'A block'], 0, 'Columns are groups; elements in a group have similar chemical properties. Rows are periods.'),
    M('What is a horizontal row of the periodic table called?', ['A period', 'A group', 'A family', 'A column'], 0, 'Rows are periods. Moving across a period, properties change gradually from metal to non-metal.'),
    M('Where are the metals found on the periodic table?', ['On the left and in the centre', 'On the right', 'Only at the top', 'Only in Group 0'], 0, 'About three-quarters of elements are metals, found on the left and middle. Non-metals are top right; a staircase line separates them.'),
    M('Why do elements in the same group react in similar ways?', ['They have the same number of electrons in their outer shell', 'They have the same mass', 'They have the same number of neutrons', 'They were discovered at the same time'], 0, 'Chemical reactions involve outer electrons. Same group = same number of outer electrons = similar reactions.'),
    M('Which group contains the noble gases?', ['Group 0', 'Group 1', 'Group 7', 'Group 2'], 0, 'The noble gases (helium, neon, argon…) are in Group 0 (sometimes called Group 8). They are very unreactive.'),
    M('Which group contains the alkali metals?', ['Group 1', 'Group 2', 'Group 7', 'Group 0'], 0, 'Group 1: lithium, sodium, potassium… They react with water to form alkaline solutions.'),
    S('What name is given to the Group 7 elements?', 'halogens', ['halogens', 'halogen', 'the halogens'], 'Group 7 elements (fluorine, chlorine, bromine, iodine) are the halogens — "salt makers".'),
    T('Dmitri Mendeleev left gaps in his periodic table for elements not yet discovered.', true, 'True. He predicted properties of missing elements (such as germanium); when they were found and matched his predictions, his table was accepted.'),
    T('The modern periodic table is arranged in order of atomic mass.', false, 'False. It is arranged by atomic number (number of protons). Mendeleev used atomic mass but swapped some pairs (e.g. tellurium and iodine) to keep groups consistent.'),
    M('Which element is in Group 1, Period 3?', ['Sodium', 'Lithium', 'Magnesium', 'Potassium'], 0, 'Period 3 starts with sodium (Na). Lithium is Period 2; potassium Period 4; magnesium is Group 2.'),
    O('Put these Group 1 metals in order of increasing reactivity.', ['Lithium', 'Sodium', 'Potassium'], 'Group 1 metals get more reactive down the group: lithium fizzes steadily, sodium melts into a ball and whizzes, potassium burns with a lilac flame.'),
    O('Put these halogens in order of decreasing reactivity (most reactive first).', ['Fluorine', 'Chlorine', 'Bromine', 'Iodine'], 'Halogens get LESS reactive down the group — the opposite of Group 1.'),
    M('Why are the noble gases so unreactive?', ['They have a full outer shell of electrons', 'They are gases', 'They are very heavy', 'They have no electrons'], 0, 'A full outer shell is stable, so noble gases do not need to gain, lose or share electrons. Being a gas has nothing to do with it.'),
    M('Chlorine is a pale green gas at room temperature. What is the state of iodine, further down Group 7?', ['Solid', 'Gas', 'Liquid', 'Plasma'], 0, 'Melting and boiling points increase down Group 7: fluorine and chlorine are gases, bromine is a liquid, iodine a grey-black solid.'),
    X('Which TWO are properties of noble gases?', ['Unreactive', 'Colourless gases', 'React violently with water', 'Good conductors of heat', 'Form coloured compounds'], [0, 1], 'Noble gases are colourless, unreactive gases. Violent reaction with water describes Group 1; coloured compounds are typical of transition metals.'),
    M('An unknown element is a dull solid that does not conduct electricity. Where would you expect it on the periodic table?', ['On the right, as a non-metal', 'In Group 1', 'In the centre with the transition metals', 'In Group 2'], 0, 'Dull and non-conducting = non-metal, found on the right side (e.g. sulfur). Groups 1, 2 and the transition metals are all metals.'),
    M('Which element is in Group 7, Period 2?', ['Fluorine', 'Chlorine', 'Oxygen', 'Neon'], 0, 'Period 2 is the second row; Group 7 is the halogens. The element in both is fluorine. Chlorine is Group 7 Period 3; oxygen is Group 6; neon is Group 0.'),
    M('Lithium, sodium and potassium are all in Group 1. Which property do they share?', ['They react with water to make an alkaline solution', 'They are all gases', 'They are all unreactive', 'They are all very hard and dense'], 0, 'Group 1 (alkali) metals react with water to give hydrogen and an alkaline hydroxide solution. They are soft, low-density solids and are very reactive.'),
    M('Approximately what fraction of the elements are metals?', ['About three-quarters', 'About a quarter', 'About half', 'Almost none'], 0, 'Most elements (roughly three-quarters) are metals, found on the left and centre of the table. Non-metals are on the right.'),
    M('What is the trend in melting point going down Group 1?', ['Melting point decreases', 'Melting point increases', 'Melting point stays the same', 'There is no pattern at all'], 0, 'Group 1 melting points decrease going down: lithium melts at about 181 °C, sodium at about 98 °C and potassium at about 63 °C.'),
    M('What is the trend in boiling point going down Group 7?', ['Boiling point increases', 'Boiling point decreases', 'Boiling point stays the same', 'All halogens are gases'], 0, 'Boiling points increase down Group 7: fluorine and chlorine are gases, bromine is a liquid and iodine is a solid at room temperature.'),
    T('Elements in the same period have similar chemical properties.', false, 'False. Elements in the same <b>group</b> (column) have similar properties. Across a period (row) properties change from metal to non-metal.'),
    T('Hydrogen is a non-metal.', true, 'True. Hydrogen is a non-metal gas, even though it is often placed above Group 1. It does not have metallic properties.'),
    S('What name is given to the Group 1 elements?', 'alkali metals', ['alkali metals', 'alkali metal', 'the alkali metals'], 'Group 1 elements are the alkali metals because they react with water to form alkaline solutions.'),
    S('Which scientist arranged the first widely accepted periodic table in 1869?', 'Mendeleev', ['mendeleev', 'dmitri mendeleev', 'mendeleyev'], 'Dmitri Mendeleev arranged the elements and left gaps for undiscovered ones. His predictions of their properties were later shown to be accurate.'),
    M('Mendeleev predicted an element he called "eka-silicon". It was later discovered as germanium. Why was this important?', ['It showed his table could correctly predict new elements', 'It proved atoms contain electrons', 'It showed the table was wrong', 'It meant no more elements could be found'], 0, 'When germanium was found with properties close to his predictions, scientists accepted that his periodic table reflected real patterns.'),
    M('Which group contains elements that are all gases with full outer shells?', ['Group 0', 'Group 1', 'Group 7', 'Group 2'], 0, 'Group 0 (the noble gases: helium, neon, argon …) are all unreactive gases. Group 7 contains gases, a liquid and a solid; Groups 1 and 2 are metals.'),
    X('Which TWO statements are true about the halogens?', ['They are non-metals', 'They become more reactive going down the group', 'They exist as molecules of two atoms, like Cl<sub>2</sub>', 'They are all solids at room temperature', 'They are in Group 1'], [0, 2], 'Halogens are non-metals and form diatomic molecules (F<sub>2</sub>, Cl<sub>2</sub>, Br<sub>2</sub>, I<sub>2</sub>). They become LESS reactive down the group, are not all solids, and are in Group 7.'),
    O('Put these Group 7 elements in order of increasing boiling point.', ['Fluorine', 'Chlorine', 'Bromine', 'Iodine'], 'Boiling points rise going down Group 7: fluorine (lowest) → chlorine → bromine → iodine (highest).'),
    M('Potassium is below sodium in Group 1. How would you expect potassium to react with water compared with sodium?', ['More vigorously', 'Less vigorously', 'In exactly the same way', 'Not at all'], 0, 'Group 1 metals get more reactive going down the group, so potassium reacts more vigorously than sodium (it even catches fire with a lilac flame).'),
  ] },
  { name: 'Metals & non-metals', intro: 'Metals and non-metals have typical physical and chemical properties. Metal oxides are usually basic; non-metal oxides are usually acidic.', items: [
    X('Which TWO are typical properties of metals?', ['Good conductors of electricity', 'Malleable (can be hammered into shape)', 'Brittle when solid', 'Low melting points', 'Poor conductors of heat'], [0, 1], 'Metals conduct heat and electricity and are malleable and ductile, usually with high melting points. Brittle and poor conductors describe non-metals.'),
    M('Which non-metal conducts electricity?', ['Graphite (a form of carbon)', 'Sulfur', 'Oxygen', 'Iodine'], 0, 'Graphite is the famous exception — it conducts because it has free (delocalised) electrons. Other non-metals are insulators.'),
    M('Which metal is liquid at room temperature?', ['Mercury', 'Iron', 'Sodium', 'Aluminium'], 0, 'Mercury melts at −39 °C, so it is liquid at room temperature — an exception to "metals have high melting points".'),
    S('What word means a metal can be drawn into wires?', 'ductile', ['ductile'], 'Ductile = can be stretched into wires (copper wiring). Malleable = can be hammered into sheets.'),
    S('What word means a metal can be hammered into shape without breaking?', 'malleable', ['malleable'], 'Malleable materials can be bent or hammered into shape; brittle ones shatter.'),
    M('What type of oxide do most metals form?', ['Basic oxides', 'Acidic oxides', 'Neutral oxides only', 'They do not form oxides'], 0, 'Metal oxides are bases; soluble ones (like sodium oxide) dissolve to form alkalis. Non-metal oxides (like CO<sub>2</sub>, SO<sub>2</sub>) are acidic.'),
    M('Sulfur burns in oxygen and the product is dissolved in water with universal indicator. What colour would you expect?', ['Red or orange (acidic)', 'Purple (alkaline)', 'Green (neutral)', 'Blue (alkaline)'], 0, 'Sulfur is a non-metal; sulfur dioxide dissolves to give an acidic solution, so the indicator turns red/orange.'),
    M('Magnesium burns in oxygen and the product is shaken with water and universal indicator. What colour would you expect?', ['Blue or purple (alkaline)', 'Red (acidic)', 'Green (neutral)', 'Yellow (weakly acidic)'], 0, 'Magnesium oxide is a metal oxide — basic — and makes a weakly alkaline solution, so the indicator turns blue/purple.'),
    T('All metals are magnetic.', false, 'False. Only iron, nickel and cobalt (and some alloys like steel) are magnetic. Copper, aluminium and gold are not.'),
    T('Non-metals usually have lower melting points than metals.', true, 'True, in general — many non-metals are gases at room temperature. Exceptions include carbon (diamond/graphite), which has a very high melting point.'),
    M('Why is copper used for electrical wiring?', ['It is a good conductor and ductile', 'It is magnetic', 'It is cheap and brittle', 'It is a non-metal'], 0, 'Copper conducts electricity very well and can be drawn into wires. It is not magnetic and is not brittle.'),
    M('Why are saucepans made of metal but handles often made of plastic?', ['Metal conducts heat well; plastic is a poor conductor (insulator)', 'Plastic is stronger', 'Metal is a poor conductor', 'Plastic conducts heat'], 0, 'Metals are good thermal conductors so they heat food; plastics are insulators so the handle stays cool.'),
    M('Which property describes most non-metals in the solid state?', ['Brittle and dull', 'Shiny and malleable', 'Good conductors', 'Sonorous (ring when hit)'], 0, 'Solid non-metals like sulfur are dull and brittle (crumble). Shiny, malleable, conducting and sonorous are metallic properties.'),
    S('A shiny, malleable element conducts electricity. Is it a metal or non-metal?', 'metal', ['metal', 'a metal'], 'Shiny + malleable + conducts electricity are all metallic properties.'),
    M('What does "sonorous" mean?', ['Makes a ringing sound when struck', 'Dissolves in water', 'Is magnetic', 'Has a high density'], 0, 'Sonorous materials ring when hit — why bells are metal.'),
    M('Which element is a non-metal?', ['Sulfur', 'Sodium', 'Zinc', 'Calcium'], 0, 'Sulfur is a yellow, brittle non-metal. Sodium, zinc and calcium are all metals.'),
    M('Which property is typical of non-metals?', ['They are poor conductors of heat', 'They are shiny', 'They are malleable', 'They are sonorous'], 0, 'Non-metals are usually poor conductors (insulators) of heat and electricity. Shiny, malleable and sonorous are all typical metal properties.'),
    M('Which metal is attracted to a magnet?', ['Iron', 'Copper', 'Aluminium', 'Gold'], 0, 'Only a few metals are magnetic — iron, nickel and cobalt (and steel, which is mainly iron). Copper, aluminium and gold are not magnetic.'),
    M('Which of these is a liquid non-metal at room temperature?', ['Bromine', 'Mercury', 'Chlorine', 'Iodine'], 0, 'Bromine is the only non-metal element that is liquid at room temperature. Mercury is a liquid but it is a metal; chlorine is a gas and iodine is a solid.'),
    M('Why is aluminium used to make aeroplane bodies?', ['It is strong but has a low density', 'It is magnetic', 'It is very dense', 'It is a good insulator'], 0, 'Aluminium is light (low density) yet strong, and it resists corrosion — ideal for aircraft. It is not magnetic and is a good conductor.'),
    M('Carbon dioxide dissolves in water to form a weakly acidic solution. What does this show?', ['Non-metal oxides tend to be acidic', 'Metal oxides tend to be acidic', 'All oxides are neutral', 'Carbon is a metal'], 0, 'Non-metal oxides such as CO<sub>2</sub> and SO<sub>2</sub> form acidic solutions. Metal oxides tend to be basic.'),
    T('Diamond is a form of carbon and is a non-metal.', true, 'True. Diamond and graphite are both forms of the non-metal carbon. Diamond does not conduct electricity; graphite is the unusual non-metal that does.'),
    T('Solid non-metals are usually brittle.', true, 'True. Solid non-metals such as sulfur and iodine shatter or crumble when hit, unlike metals which bend or flatten.'),
    T('All metals have very high melting points.', false, 'False. Most metals do have high melting points, but some are exceptions: mercury is liquid at room temperature and sodium melts below 100 °C.'),
    S('What word describes a material that makes a ringing sound when hit?', 'sonorous', ['sonorous'], 'Sonorous means it rings when struck — a typical metal property, which is why bells are made of metal.'),
    S('What is the word for a material that does not conduct electricity or heat well?', 'insulator', ['insulator', 'an insulator', 'insulating'], 'An insulator is a poor conductor. Most non-metals are insulators.'),
    X('Which TWO elements are metals?', ['Copper', 'Potassium', 'Silicon', 'Oxygen', 'Phosphorus'], [0, 1], 'Copper and potassium are metals. Silicon is a semi-metal (metalloid), while oxygen and phosphorus are non-metals.'),
    M('Gold is used in jewellery. Which property is the main reason?', ['It is shiny and very unreactive, so it does not tarnish', 'It is magnetic', 'It is a good insulator', 'It has a low density'], 0, 'Gold stays shiny because it does not react with air or water. It is not magnetic, it conducts well, and it is very dense.'),
    M('An element forms an oxide that turns universal indicator blue-purple. What is the element most likely to be?', ['A metal', 'A non-metal', 'A noble gas', 'Impossible to say'], 0, 'Blue-purple shows an alkaline solution. Metal oxides are basic and those that dissolve form alkalis, so the element is most likely a metal.'),
    O('Put these in order of electrical conductivity, best conductor first.', ['Copper', 'Graphite', 'Sulfur'], 'Copper is an excellent metallic conductor. Graphite (a non-metal) conducts, but less well than copper. Sulfur is an insulator.'),
  ] },
], {
  overview: 'Atoms are the building blocks of all substances. The <b>periodic table</b> organises the 118 elements by atomic number so that elements with similar properties line up in <b>groups</b>. Most elements are <b>metals</b>; the non-metals sit on the right.',
  objectives: ['I can write chemical symbols correctly and interpret simple formulae', 'I can name simple compounds (-ide and -ate)', 'I can describe the layout of the periodic table: groups, periods, metals and non-metals', 'I can describe trends in Groups 1, 7 and 0', 'I can compare the properties of metals and non-metals and their oxides'],
  keyWords: [{ term: 'Atom', def: 'The smallest part of an element that can exist.' }, { term: 'Molecule', def: 'Two or more atoms chemically bonded.' }, { term: 'Group', def: 'A vertical column of the periodic table; elements with similar properties.' }, { term: 'Period', def: 'A horizontal row of the periodic table.' }, { term: 'Alkali metals', def: 'Group 1 elements.' }, { term: 'Halogens', def: 'Group 7 elements.' }, { term: 'Noble gases', def: 'Group 0 elements; very unreactive.' }, { term: 'Malleable', def: 'Can be hammered into shape.' }],
  sections: [
    { title: 'Symbols and formulae', html: `<p>Every element has a symbol: one capital letter, or a capital plus a lower-case letter (Na, Cl, Fe). Some come from Latin: Na (sodium), K (potassium), Fe (iron), Cu (copper), Pb (lead), Ag (silver), Au (gold).</p><p>A formula shows the atoms in a substance. A small subscript number applies to the symbol before it; a number after a bracket multiplies everything inside.</p><div class="worked"><div class="wq">How many atoms of each element in Mg(NO<sub>3</sub>)<sub>2</sub>?</div><ol><li>Mg: 1</li><li>N: 1 × 2 = 2</li><li>O: 3 × 2 = 6</li></ol><div class="wa">Answer: 1 Mg, 2 N, 6 O (9 atoms)</div></div><div class="rule">Naming: metal first; non-metal ending "-ide" (chloride, oxide, sulfide). "-ate" means oxygen is also present (sulfate, nitrate, carbonate).</div>` },
    { title: 'Layout of the periodic table', html: `<ul><li>Elements are in order of <b>atomic number</b>.</li><li><b>Groups</b> (columns) contain elements with the same number of outer electrons, so similar reactions.</li><li><b>Periods</b> (rows) show a gradual change from metals to non-metals.</li><li>Metals: left and centre. Non-metals: top right.</li></ul><p>Mendeleev (1869) arranged elements by atomic mass but left gaps for undiscovered elements and predicted their properties.</p>` },
    { title: 'Group trends', html: `<table class="qt"><tr><th>Group</th><th>Name</th><th>Reactivity trend</th></tr><tr><td>1</td><td>Alkali metals</td><td>More reactive down the group</td></tr><tr><td>7</td><td>Halogens</td><td>Less reactive down; melting/boiling points increase</td></tr><tr><td>0</td><td>Noble gases</td><td>Unreactive (full outer shell); boiling points increase down</td></tr></table>` },
    { title: 'Metals vs non-metals', html: `<table class="qt"><tr><th>Metals</th><th>Non-metals</th></tr><tr><td>Shiny, malleable, ductile, sonorous</td><td>Dull, brittle when solid</td></tr><tr><td>Good conductors of heat and electricity</td><td>Poor conductors (except graphite)</td></tr><tr><td>Usually high melting points (not mercury)</td><td>Often low melting points; many are gases</td></tr><tr><td>Oxides are <b>basic</b></td><td>Oxides are <b>acidic</b></td></tr></table>` },
  ],
  mistakes: ['Writing symbols with two capitals (CO means carbon monoxide, Co is cobalt!).', 'Forgetting that a number after a bracket multiplies everything inside it.', 'Saying Group 7 gets more reactive down the group — it is the opposite of Group 1.', 'Thinking all metals are magnetic.'],
  examTips: ['When comparing metals and non-metals, use paired properties ("metals are good conductors; non-metals are poor conductors").', 'If asked to predict a property of an element, use the trend in its group and quote a neighbour as evidence.', 'Check symbols carefully — examiners will not accept the wrong case.'],
  realLife: 'Neon and argon are used in lights and window glazing precisely because, as noble gases, they will not react.',
});

// =====================================================================
// YEAR 8 — Chemical reactions
// =====================================================================
function genConservation(rng) {
  const v = ri(rng, 0, 3);
  if (v === 0) {
    const a = ri(rng, 20, 120) / 10, b = ri(rng, 10, 90) / 10, p = rd(a + b, 1);
    return { type: 'number', q: `In a sealed flask, ${a} g of reactant A reacts completely with ${b} g of reactant B to form a single product. What mass of product is made?`, value: p, tol: 0.05, unit: 'g', answer: `${p} g`,
      steps: ['Law of conservation of mass: total mass of reactants = total mass of products.', `mass of product = ${a} + ${b}`, `mass of product = ${p} g`], explain: 'Atoms are rearranged, not created or destroyed, so in a closed system the mass does not change.', hint: 'Mass of reactants = mass of products.' };
  }
  if (v === 1) {
    const start = ri(rng, 50, 200) / 10, frac = 0.44, lost = rd(start * frac, 2), end = rd(start - lost, 2);
    return { type: 'number', q: `${start} g of calcium carbonate is heated strongly in an open tube until it fully decomposes: calcium carbonate → calcium oxide + carbon dioxide. ${end} g of solid remains. What mass of carbon dioxide escaped?`, value: lost, tol: 0.02, unit: 'g', answer: `${lost} g`,
      steps: ['Total mass of products = mass of reactant (conservation of mass).', 'Mass of CO<sub>2</sub> = mass at start − mass of solid left', `= ${start} − ${end}`, `= ${lost} g`], explain: 'The mass of solid seems to fall because the carbon dioxide gas escapes from the open tube — mass is not destroyed.', hint: 'The missing mass left as a gas.' };
  }
  if (v === 2) {
    const mg = ri(rng, 12, 60) / 10, mgo = rd(mg * 40 / 24, 2), ox = rd(mgo - mg, 2);
    return { type: 'number', q: `${mg} g of magnesium ribbon is burned in a crucible and forms ${mgo} g of magnesium oxide. What mass of oxygen reacted with the magnesium?`, value: ox, tol: 0.02, unit: 'g', answer: `${ox} g`,
      steps: ['magnesium + oxygen → magnesium oxide', 'mass of oxygen = mass of magnesium oxide − mass of magnesium', `= ${mgo} − ${mg}`, `= ${ox} g`], explain: 'The mass increases because oxygen atoms from the air have joined the magnesium. Mass is still conserved: Mg + O<sub>2</sub> = MgO.', hint: 'Where did the extra mass come from?' };
  }
  const sol1 = ri(rng, 200, 600) / 10, sol2 = ri(rng, 200, 600) / 10, tot = rd(sol1 + sol2, 1);
  return { type: 'number', q: `A student mixes ${sol1} g of sodium sulfate solution with ${sol2} g of barium chloride solution in a beaker. A white precipitate forms. What is the total mass of the beaker contents after the reaction?`, value: tot, tol: 0.05, unit: 'g', answer: `${tot} g`,
    steps: ['No gas is made, so nothing escapes — the system behaves as closed.', `total mass = ${sol1} + ${sol2}`, `= ${tot} g`], explain: 'A precipitate is a solid product, but it stays in the beaker, so the total mass is unchanged.', hint: 'Does anything leave the beaker?' };
}

topic({ id: 'chem-y8-reactions', strand: 'chem-quant', year: 8, term: 2, tier: 'FH', name: 'Chemical Reactions & Equations',
  summary: 'Recognise chemical changes, write word and balanced symbol equations, and use conservation of mass.', specRef: 'KS3 Chemistry: Chemical reactions; AQA 8462 4.3.1.1' }, [
  { name: 'Chemical vs physical change', intro: 'In a chemical reaction atoms are rearranged to make new substances. Physical changes (such as melting and dissolving) make no new substance and are easily reversed.', items: [
    X('Which TWO are signs that a chemical reaction may have happened?', ['Fizzing (a gas given off)', 'A permanent colour change', 'A solid melting', 'Sugar dissolving', 'Water evaporating'], [0, 1], 'Fizzing and permanent colour changes suggest new substances. Melting, dissolving and evaporating are physical changes.'),
    M('Which is a chemical change?', ['Cooking an egg', 'Ice melting', 'Salt dissolving', 'Cutting paper'], 0, 'Cooking an egg makes new substances (proteins change permanently) and cannot be reversed. The others make no new substance.'),
    M('Which is a physical change?', ['Water boiling', 'Wood burning', 'Iron rusting', 'Milk going sour'], 0, 'Boiling is a change of state — still water. Burning, rusting and souring all make new substances.'),
    T('In a chemical reaction, atoms are created and destroyed.', false, 'False. Atoms are only rearranged into new substances; the same atoms are present before and after. This is why mass is conserved.'),
    T('Physical changes are usually easy to reverse.', true, 'True. Melted chocolate can be re-solidified; dissolved salt can be recovered by evaporation. Chemical changes are usually hard to reverse.'),
    S('What name is given to the substances at the start of a chemical reaction?', 'reactants', ['reactants', 'reactant', 'the reactants'], 'Reactants are written on the left of the arrow; products on the right.'),
    S('What name is given to the new substances made in a chemical reaction?', 'products', ['products', 'product', 'the products'], 'Products are made in the reaction and appear on the right-hand side of the equation.'),
    M('What is a precipitate?', ['An insoluble solid formed when two solutions react', 'A gas given off in a reaction', 'A liquid that boils off', 'A solution with a colour'], 0, 'When two solutions react to form an insoluble product, the solid appears as a cloudy precipitate (e.g. lead iodide is yellow).'),
    M('A test tube gets hot when two chemicals are mixed. What does this show?', ['Energy is given out — the reaction is exothermic', 'Energy is taken in — endothermic', 'No reaction has occurred', 'The chemicals are melting'], 0, 'Getting hotter means energy is transferred to the surroundings: exothermic. Endothermic reactions make things colder.'),
    M('Which word equation shows a chemical reaction?', ['magnesium + oxygen → magnesium oxide', 'ice → water', 'salt + water → salt solution', 'water → steam'], 0, 'Magnesium oxide is a new substance. The other three are changes of state or dissolving — physical changes.'),
    M('What does the arrow in a chemical equation mean?', ['"reacts to form"', '"equals"', '"is mixed with"', '"is heated"'], 0, 'The arrow means reactants react to form products. Do not use = in chemical equations.'),
    T('Rusting is a chemical change.', true, 'True. Iron reacts with oxygen and water to make hydrated iron(III) oxide — a new substance.'),
    X('Which TWO are chemical changes?', ['Toast burning', 'Fireworks exploding', 'Chocolate melting', 'Water freezing', 'Sugar dissolving'], [0, 1], 'Burning toast and exploding fireworks make new substances. The others are physical changes.'),
    M('Sodium hydrogencarbonate is added to vinegar and it fizzes. Why does the mass of the open beaker go down?', ['A gas (carbon dioxide) escapes into the air', 'Atoms are destroyed', 'The liquid gets lighter when it fizzes', 'The products have no mass'], 0, 'Carbon dioxide gas leaves the open beaker. If the beaker were sealed, the mass would stay the same.'),
    M('Which observation would NOT tell you a chemical reaction has happened?', ['The mixture changes shape', 'A gas is given off', 'A precipitate forms', 'The temperature changes'], 0, 'A change of shape is a physical change. Gas, precipitate or temperature change can all indicate a reaction.'),
    M('Which of these is NOT a chemical change?', ['Chocolate melting', 'Toast burning', 'An egg being fried', 'Fireworks exploding'], 0, 'Melting chocolate is a change of state — no new substance is made and it can be reversed by cooling. Burning, frying and exploding all produce new substances.'),
    M('Which statement about chemical reactions is correct?', ['New substances are made', 'They are always easy to reverse', 'Mass is always lost', 'They never involve energy changes'], 0, 'A chemical reaction always produces new substances. Most are hard to reverse, mass is conserved overall, and energy is always given out or taken in.'),
    M('When a candle burns, the wax gets smaller. What happened to it?', ['It reacted with oxygen to form carbon dioxide and water vapour, which escaped', 'It disappeared completely', 'It melted and soaked into the table', 'It turned into heat energy'], 0, 'Burning wax reacts with oxygen; the products are gases that go into the air. The atoms still exist — they are just in new substances. Mass is not turned into energy in chemical reactions.'),
    M('Silver nitrate solution is added to sodium chloride solution and a white solid appears. What is the solid called?', ['A precipitate', 'A solvent', 'A filtrate', 'A catalyst'], 0, 'An insoluble solid formed when two solutions react is a precipitate — a sign of a chemical change.'),
    M('Which observation best shows that a new gas has been produced?', ['Bubbles form in a liquid that was not being heated', 'The liquid gets slightly warmer', 'A solid dissolves', 'The volume of liquid stays the same'], 0, 'Bubbles (effervescence) in a cold liquid mean a gas is being made by a reaction. Bubbles in a boiling liquid are just the liquid turning to vapour.'),
    T('Dissolving sugar in water is a chemical change because the sugar seems to disappear.', false, 'False. Dissolving is a physical change. The sugar is still there (you can taste it and get it back by evaporating the water).'),
    T('In a chemical reaction the atoms are rearranged to make new substances.', true, 'True. The same atoms are present before and after; they are just joined together differently.'),
    T('A colour change always means a chemical reaction has happened.', false, 'False. A colour change is a sign that a reaction <i>may</i> have happened, but it can also be physical — for example, diluting a coloured solution makes it paler.'),
    S('What word describes a physical change such as melting, which can easily be undone?', 'reversible', ['reversible'], 'Physical changes are usually reversible: melting can be undone by freezing, dissolving by evaporating.'),
    S('What is the general name for the fizzing seen when a gas is given off in a reaction?', 'effervescence', ['effervescence', 'fizzing', 'bubbling', 'bubbles'], 'Effervescence (fizzing) is the formation of gas bubbles, one of the signs of a chemical change.'),
    X('Which TWO are physical changes?', ['Boiling water', 'Dissolving salt', 'Burning paper', 'Cooking an egg', 'Rusting nails'], [0, 1], 'Boiling and dissolving make no new substance and can be reversed. Burning, cooking and rusting all make new substances.'),
    M('Magnesium ribbon is heated and becomes a white powder. The powder has a greater mass than the ribbon. Why?', ['Oxygen from the air has combined with the magnesium', 'The magnesium has absorbed heat, which has mass', 'The magnesium has expanded', 'Some magnesium was lost'], 0, 'Magnesium reacts with oxygen to form magnesium oxide. The extra mass is the oxygen atoms that joined on. Heat energy has no mass.'),
    M('Which pair of word equations shows reactions that make the same product?', ['carbon + oxygen → carbon dioxide; methane + oxygen → carbon dioxide + water', 'iron + sulfur → iron sulfide; iron + oxygen → iron oxide', 'water → steam; ice → water', 'salt + water → salt solution; sugar + water → sugar solution'], 0, 'Both reactions produce carbon dioxide. The second pair make different products; the third and fourth pairs are physical changes rather than reactions.'),
    M('Why is cooking a cake an example of a chemical change?', ['New substances form and it cannot be turned back into the raw ingredients', 'The cake changes shape', 'The cake gets hot', 'The mixture is stirred'], 0, 'Baking creates new substances (for example carbon dioxide gas makes it rise) and cannot be reversed. A shape or temperature change alone does not prove a chemical change.'),
    O('Put these in order to test whether a reaction gives off energy as heat.', ['Measure the starting temperature of one solution', 'Add the second solution', 'Stir the mixture', 'Record the highest temperature reached'], 'Measure the start temperature, add the other reactant, stir, then record the maximum. A rise in temperature shows the reaction released energy (exothermic).'),
  ] },
  { name: 'Word & symbol equations', intro: 'Equations show reactants and products. Balanced symbol equations have the same number of each type of atom on both sides — you balance by changing the big numbers in front, never the small ones.', items: [
    M('Which is the balanced equation for magnesium burning?', ['2Mg + O<sub>2</sub> → 2MgO', 'Mg + O<sub>2</sub> → MgO', 'Mg + O → MgO<sub>2</sub>', 'Mg<sub>2</sub> + O<sub>2</sub> → 2MgO'], 0, '2 Mg and 2 O on each side. Mg + O<sub>2</sub> → MgO has 2 O on the left but 1 on the right. Changing formulae (MgO<sub>2</sub>, Mg<sub>2</sub>) changes the substance — not allowed.'),
    M('How do you balance a symbol equation?', ['Change the numbers in front of formulae', 'Change the small numbers in formulae', 'Add extra substances', 'Remove atoms from one side'], 0, 'Only the large numbers (coefficients) in front can be changed. Changing subscripts changes what the substance is: H<sub>2</sub>O would become H<sub>2</sub>O<sub>2</sub>, hydrogen peroxide.'),
    M('Balance: __H<sub>2</sub> + O<sub>2</sub> → __H<sub>2</sub>O', ['2 and 2', '1 and 1', '2 and 1', '1 and 2'], 0, '2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O: 4 H and 2 O on each side.'),
    M('Balance: N<sub>2</sub> + __H<sub>2</sub> → __NH<sub>3</sub>', ['3 and 2', '1 and 1', '2 and 3', '3 and 1'], 0, 'N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>: 2 N and 6 H each side. This is the Haber process.'),
    M('Balance: CH<sub>4</sub> + __O<sub>2</sub> → CO<sub>2</sub> + __H<sub>2</sub>O', ['2 and 2', '1 and 2', '2 and 1', '3 and 2'], 0, 'CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O: C 1=1, H 4=4, O 4=4.'),
    M('Balance: __Na + Cl<sub>2</sub> → __NaCl', ['2 and 2', '1 and 1', '1 and 2', '2 and 1'], 0, '2Na + Cl<sub>2</sub> → 2NaCl: 2 Na, 2 Cl each side.'),
    N('In the balanced equation 2Fe<sub>2</sub>O<sub>3</sub> + 3C → 4Fe + 3CO<sub>2</sub>, how many oxygen atoms are on each side?', 6, 0, '', ['Left: 2 × 3 = 6 O', 'Right: 3 × 2 = 6 O', 'Both sides have 6'], 'Multiply the coefficient by the subscript to count atoms.'),
    S('Complete the word equation: zinc + hydrochloric acid → zinc chloride + ______', 'hydrogen', ['hydrogen', 'hydrogen gas'], 'Metal + acid → salt + hydrogen. Hydrochloric acid makes chloride salts.'),
    S('Complete: copper carbonate → copper oxide + ______ (on heating)', 'carbon dioxide', ['carbon dioxide', 'co2'], 'Metal carbonates decompose on heating to the metal oxide and carbon dioxide — thermal decomposition.', [['carbon'], ['dioxide']]),
    M('What does the state symbol (aq) mean?', ['Dissolved in water (aqueous)', 'A liquid', 'A gas', 'A solid'], 0, '(aq) = aqueous solution. (l) = liquid, (g) = gas, (s) = solid. Salt water is NaCl(aq), not NaCl(l).'),
    T('2H<sub>2</sub>O means two molecules of water, containing 4 hydrogen atoms and 2 oxygen atoms in total.', true, 'True. The 2 in front multiplies the whole formula: 2 × H<sub>2</sub> = 4 H, 2 × O = 2 O.'),
    M('Balance: __Al + __O<sub>2</sub> → 2Al<sub>2</sub>O<sub>3</sub>', ['4 and 3', '2 and 3', '4 and 6', '2 and 2'], 0, '2Al<sub>2</sub>O<sub>3</sub> has 4 Al and 6 O, so 4Al and 3O<sub>2</sub>.'),
    M('Balance: CaCO<sub>3</sub> + __HCl → CaCl<sub>2</sub> + H<sub>2</sub>O + CO<sub>2</sub>', ['2', '1', '3', '4'], 0, 'CaCl<sub>2</sub> has 2 Cl and H<sub>2</sub>O has 2 H, so 2HCl.'),
    T('C + O<sub>2</sub> → CO<sub>2</sub> is already balanced.', true, 'True. 1 C and 2 O on each side.'),
    M('What is the word equation for iron reacting with sulfur?', ['iron + sulfur → iron sulfide', 'iron + sulfur → iron sulfate', 'iron + sulfur → iron oxide', 'iron sulfide → iron + sulfur'], 0, 'Only two elements are present, so the product is a sulfide. Sulfate would need oxygen.'),
    M('Balance: __K + __H<sub>2</sub>O → __KOH + H<sub>2</sub>', ['2, 2, 2', '1, 1, 1', '2, 1, 2', '1, 2, 1'], 0, '2K + 2H<sub>2</sub>O → 2KOH + H<sub>2</sub>: K 2=2, H 4=2+2, O 2=2.'),
    M('Balance: __Mg + O<sub>2</sub> → __MgO', ['2, 2', '1, 1', '1, 2', '2, 1'], 0, 'There are 2 O atoms on the left, so make 2MgO. That needs 2 Mg atoms on the left: 2Mg + O<sub>2</sub> → 2MgO.'),
    M('Balance: __Fe + __Cl<sub>2</sub> → 2FeCl<sub>3</sub>', ['2, 3', '1, 3', '2, 2', '3, 2'], 0, '2FeCl<sub>3</sub> contains 2 Fe and 6 Cl. So 2Fe on the left and 3Cl<sub>2</sub> (6 Cl): 2Fe + 3Cl<sub>2</sub> → 2FeCl<sub>3</sub>.'),
    M('Balance: Zn + __HCl → ZnCl<sub>2</sub> + H<sub>2</sub>', ['2', '1', '3', '4'], 0, 'ZnCl<sub>2</sub> has 2 Cl and H<sub>2</sub> has 2 H, so you need 2HCl.'),
    M('Balance: C<sub>3</sub>H<sub>8</sub> + __O<sub>2</sub> → 3CO<sub>2</sub> + 4H<sub>2</sub>O', ['5', '3', '4', '10'], 0, 'Right side oxygen: 3 × 2 + 4 × 1 = 10 O atoms. That needs 5O<sub>2</sub>. 10 is the number of oxygen atoms, not molecules.'),
    M('What does the state symbol (g) mean?', ['Gas', 'Grams', 'Glass', 'Gel'], 0, 'State symbols: (s) solid, (l) liquid, (g) gas, (aq) aqueous — dissolved in water.'),
    M('Which is the correct word equation for calcium carbonate reacting with hydrochloric acid?', ['calcium carbonate + hydrochloric acid → calcium chloride + water + carbon dioxide', 'calcium carbonate + hydrochloric acid → calcium chloride + hydrogen', 'calcium carbonate + hydrochloric acid → calcium oxide + water', 'calcium carbonate + hydrochloric acid → calcium carbonate chloride'], 0, 'Acid + carbonate → salt + water + carbon dioxide. Hydrogen is made when an acid reacts with a metal, not a carbonate.'),
    T('To balance an equation you can change H<sub>2</sub>O to H<sub>2</sub>O<sub>2</sub>.', false, 'False. Changing the small numbers changes the substance — H<sub>2</sub>O<sub>2</sub> is hydrogen peroxide, not water. Only the big numbers in front can be changed.'),
    T('In a balanced equation, the total number of atoms of each element is the same on both sides.', true, 'True. Atoms are not created or destroyed in a reaction, so each element must appear in equal numbers on both sides.'),
    S('Complete the word equation: magnesium + oxygen → ______', 'magnesium oxide', ['magnesium oxide'], 'A metal burning in oxygen forms the metal oxide: magnesium + oxygen → magnesium oxide.'),
    S('Complete the word equation: sodium hydroxide + hydrochloric acid → sodium chloride + ______', 'water', ['water'], 'Acid + alkali → salt + water. This is a neutralisation reaction.'),
    N('How many hydrogen atoms are shown in 3H<sub>2</sub>O?', 6, 0, 'atoms', ['The big number multiplies the whole formula', 'Each H<sub>2</sub>O has 2 H atoms', '3 × 2 = 6 hydrogen atoms'], 'The 3 in front means three water molecules, each with 2 H atoms: 3 × 2 = 6.'),
    N('How many oxygen atoms are shown in 2Ca(NO<sub>3</sub>)<sub>2</sub>?', 12, 0, 'atoms', ['Inside the bracket: NO<sub>3</sub> has 3 O', 'The bracket subscript 2 gives 3 × 2 = 6 O per formula unit', 'The big 2 in front doubles it: 6 × 2 = 12 O atoms'], 'Work from the inside out: 3 O per nitrate × 2 nitrates = 6, then × 2 formula units = 12.'),
    M('Which equation is correctly balanced?', ['2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>', 'H<sub>2</sub>O<sub>2</sub> → H<sub>2</sub>O + O<sub>2</sub>', '2H<sub>2</sub>O<sub>2</sub> → H<sub>2</sub>O + O<sub>2</sub>', 'H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>'], 0, 'Check 2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>: left 4 H and 4 O; right 4 H and 2 + 2 = 4 O. Balanced. The others have unequal oxygen or hydrogen.'),
    O('Put these steps for writing a balanced symbol equation in order.', ['Write the word equation', 'Write the correct formula for each substance', 'Count the atoms of each element on both sides', 'Add big numbers in front to balance, then recount'], 'Start with words, convert to correct formulae (never change these), count atoms, then balance using numbers in front and check again.'),
  ] },
  { name: 'Conservation of mass calculations', intro: 'Mass is conserved in every reaction because atoms are only rearranged. If a gas escapes (or joins from the air) the measured mass appears to change.', gen: genConservation },
  { name: 'Types of reaction', intro: 'Common reaction types are combustion (burning in oxygen), oxidation (gaining oxygen), thermal decomposition (breaking down by heating), and neutralisation. Reactions can be exothermic or endothermic.', items: [
    M('What are the products when methane burns completely?', ['Carbon dioxide and water', 'Carbon monoxide and water', 'Carbon and hydrogen', 'Methane oxide'], 0, 'Complete combustion of a hydrocarbon in plenty of oxygen gives CO<sub>2</sub> and H<sub>2</sub>O. Carbon monoxide and soot form in incomplete combustion (limited oxygen).'),
    S('What name is given to a reaction where a substance is broken down by heating?', 'thermal decomposition', ['thermal decomposition'], '"Thermal" = heat, "decomposition" = breaking down. E.g. calcium carbonate → calcium oxide + carbon dioxide.', [['thermal'], ['decomposition', 'decompose']]),
    M('What is oxidation (at KS3 level)?', ['A substance gaining oxygen', 'A substance losing oxygen', 'A substance dissolving', 'A substance melting'], 0, 'Oxidation is gaining oxygen (e.g. Mg → MgO). Losing oxygen is reduction.'),
    M('Which three things make up the fire triangle?', ['Fuel, heat and oxygen', 'Fuel, water and oxygen', 'Heat, water and carbon dioxide', 'Fuel, nitrogen and heat'], 0, 'A fire needs fuel, heat and oxygen. Removing any one puts the fire out — e.g. a fire blanket removes oxygen.'),
    T('Combustion reactions are exothermic.', true, 'True. Burning releases energy to the surroundings as heat and light.'),
    M('What is an endothermic reaction?', ['One that takes in energy from the surroundings', 'One that gives out energy', 'One that produces a gas', 'One that needs a catalyst'], 0, 'Endothermic reactions take in energy, so the surroundings get colder (e.g. thermal decomposition, sports cold packs).'),
    M('What test shows carbon dioxide is produced when a carbonate is heated?', ['It turns limewater milky/cloudy', 'It relights a glowing splint', 'It gives a squeaky pop', 'It bleaches damp litmus paper'], 0, 'CO<sub>2</sub> turns limewater milky. Glowing splint = oxygen; squeaky pop = hydrogen; bleaching = chlorine.'),
    M('Why is incomplete combustion dangerous?', ['It produces toxic carbon monoxide', 'It produces too much oxygen', 'It produces water', 'It uses up nitrogen'], 0, 'With limited oxygen, carbon monoxide (colourless, odourless, toxic) and soot form. CO stops blood carrying oxygen.'),
    X('Which TWO are thermal decomposition reactions?', ['Copper carbonate → copper oxide + carbon dioxide', 'Calcium carbonate → calcium oxide + carbon dioxide', 'Magnesium + oxygen → magnesium oxide', 'Sodium + water → sodium hydroxide + hydrogen', 'Methane + oxygen → carbon dioxide + water'], [0, 1], 'One reactant splitting into two products on heating = thermal decomposition. The others are oxidation/combustion or a displacement-type reaction with water.'),
    O('Put the steps in order for showing that heating copper carbonate gives off carbon dioxide.', ['Put copper carbonate in a boiling tube fitted with a bung and delivery tube', 'Place the end of the delivery tube in limewater', 'Heat the copper carbonate strongly', 'Lift the delivery tube out of the limewater before you stop heating'], 'The gas bubbles through limewater, which turns milky. Removing the tube before stopping heating prevents cold limewater being sucked back into the hot tube (suck-back), which could crack it.'),
    T('Thermal decomposition reactions are usually endothermic.', true, 'True. Energy must be supplied continuously to break the substance down.'),
    M('Which gas is needed for combustion?', ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Hydrogen'], 0, 'Combustion is reaction with oxygen. Carbon dioxide is used in fire extinguishers because it does not support burning.'),
    S('What word describes a reaction that gives out heat to the surroundings?', 'exothermic', ['exothermic'], 'Exo = out. Exothermic reactions raise the temperature of the surroundings.'),
    M('A hand warmer gets hot when activated. What type of reaction is this?', ['Exothermic', 'Endothermic', 'Thermal decomposition', 'Physical change'], 0, 'Hand warmers use exothermic oxidation of iron powder to release heat.'),
    M('What is formed when iron rusts?', ['Hydrated iron(III) oxide', 'Iron sulfide', 'Iron carbonate', 'Iron chloride'], 0, 'Rusting: iron + oxygen + water → hydrated iron(III) oxide. Both water and oxygen are needed — it is an oxidation reaction.'),
    M('Which is the word equation for the complete combustion of methane?', ['methane + oxygen → carbon dioxide + water', 'methane + oxygen → carbon monoxide + water', 'methane → carbon + hydrogen', 'methane + water → carbon dioxide + oxygen'], 0, 'Complete combustion of a hydrocarbon fuel in plenty of oxygen gives carbon dioxide and water. Carbon monoxide forms in incomplete combustion.'),
    M('What are the products of the thermal decomposition of calcium carbonate?', ['Calcium oxide and carbon dioxide', 'Calcium and carbon dioxide', 'Calcium oxide and oxygen', 'Calcium hydroxide and water'], 0, 'Heating calcium carbonate (limestone) breaks it down: CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. This makes quicklime.'),
    M('Iron wool is heated in air and its mass increases. What type of reaction is this?', ['Oxidation', 'Thermal decomposition', 'Neutralisation', 'Distillation'], 0, 'The iron gains oxygen to form iron oxide, so it is oxidation. Decomposition would break a substance down and usually lose mass as gas escapes.'),
    M('Which method of putting out a fire works by removing the oxygen?', ['Covering a pan fire with a fire blanket', 'Turning off the gas supply', 'Cutting a firebreak in a forest', 'Taking away the fuel'], 0, 'A fire blanket stops air reaching the fuel. Turning off the gas and firebreaks remove the fuel instead.'),
    M('Why should water NOT be used on a burning oil pan?', ['The water boils instantly and spreads burning oil', 'Water makes oil stop burning too slowly', 'Water reacts to make oxygen', 'Water is a fuel'], 0, 'Water sinks under the hot oil, turns instantly to steam and throws burning oil out of the pan, spreading the fire. Use a fire blanket or turn off the heat instead.'),
    T('Combustion is a type of oxidation reaction.', true, 'True. In combustion, a fuel reacts with oxygen — it gains oxygen, which is oxidation. It also releases energy.'),
    T('When copper carbonate is heated, the green powder turns black.', true, 'True. Green copper carbonate decomposes to black copper oxide and carbon dioxide gas.'),
    T('Neutralisation is the reaction between an acid and a base.', true, 'True. Acid + base → salt + water. The pH moves towards 7.'),
    S('What toxic gas can be formed by the incomplete combustion of a fuel?', 'carbon monoxide', ['carbon monoxide', 'co'], 'With too little oxygen, carbon monoxide (CO) forms. It is colourless and odourless and stops the blood carrying oxygen.'),
    S('What word describes a reaction that takes in energy from the surroundings?', 'endothermic', ['endothermic'], 'Endothermic reactions take in energy, so the surroundings get colder. Thermal decomposition and dissolving some salts are examples.'),
    X('Which TWO are examples of oxidation?', ['Magnesium burning to form magnesium oxide', 'Iron rusting', 'Ice melting', 'Calcium carbonate decomposing', 'Salt dissolving'], [0, 1], 'Burning magnesium and rusting iron both involve gaining oxygen. Melting and dissolving are physical changes; decomposition breaks a compound down.'),
    M('Which of these is an endothermic process?', ['A sports cold pack getting cold when squeezed', 'A candle burning', 'A firework exploding', 'Magnesium burning'], 0, 'A cold pack takes in energy from the surroundings so it feels cold — endothermic. Burning and explosions release energy (exothermic).'),
    M('A blue flame on a Bunsen burner is hotter than a yellow flame. Why?', ['The blue flame has more oxygen, so combustion is complete', 'The blue flame uses a different fuel', 'The yellow flame has more oxygen', 'The blue flame contains soot'], 0, 'Opening the air hole lets in more oxygen, giving complete combustion and more energy released. The yellow flame has incomplete combustion; glowing soot particles make it yellow.'),
    O('Put these in order to show what happens when limestone (calcium carbonate) is heated strongly then has water added.', ['Calcium carbonate is heated', 'It decomposes to calcium oxide and carbon dioxide', 'Water is added to the calcium oxide', 'Calcium hydroxide is formed, releasing heat'], 'Thermal decomposition gives calcium oxide (quicklime). Adding water to quicklime is exothermic and forms calcium hydroxide (slaked lime).'),
    N('A student heats 10.0 g of copper carbonate. 6.4 g of copper oxide remains. What mass of carbon dioxide was given off?', 3.6, 0.01, 'g', ['Mass is conserved: mass of reactant = total mass of products', 'mass of CO<sub>2</sub> = 10.0 − 6.4', 'mass of CO<sub>2</sub> = 3.6 g'], 'The mass seems to fall because the carbon dioxide gas escapes into the air, but no mass is destroyed.'),
  ] },
], {
  overview: 'In a <b>chemical reaction</b> the atoms in the reactants are rearranged to make new substances. Equations summarise reactions; balanced symbol equations show that no atoms are created or destroyed, which is why mass is conserved.',
  objectives: ['I can distinguish chemical and physical changes', 'I can write word equations for common reactions', 'I can balance symbol equations by changing coefficients', 'I can use conservation of mass to calculate masses', 'I can describe combustion, oxidation and thermal decomposition'],
  keyWords: [{ term: 'Reactant', def: 'A substance that reacts at the start of a reaction.' }, { term: 'Product', def: 'A new substance made in a reaction.' }, { term: 'Conservation of mass', def: 'No atoms are lost or made, so total mass stays the same.' }, { term: 'Combustion', def: 'Burning a fuel in oxygen, releasing energy.' }, { term: 'Oxidation', def: 'Gain of oxygen (GCSE: loss of electrons).' }, { term: 'Thermal decomposition', def: 'Breaking down a substance using heat.' }, { term: 'Exothermic', def: 'Gives out energy to the surroundings.' }, { term: 'Endothermic', def: 'Takes in energy from the surroundings.' }],
  sections: [
    { title: 'Chemical and physical changes', html: `<p><b>Chemical change</b>: a new substance forms; usually hard to reverse. Signs: gas given off, colour change, precipitate, temperature change, light.</p><p><b>Physical change</b>: no new substance (melting, dissolving, boiling); easily reversed.</p>` },
    { title: 'Writing and balancing equations', html: `<div class="rule">Balance by changing the big numbers in front of formulae — never the small subscripts.</div><div class="worked"><div class="wq">Balance: Mg + HCl → MgCl<sub>2</sub> + H<sub>2</sub></div><ol><li>Count: left 1 Mg, 1 H, 1 Cl; right 1 Mg, 2 H, 2 Cl.</li><li>Put 2 in front of HCl: left now 2 H, 2 Cl.</li><li>Check all atoms match.</li></ol><div class="wa">Answer: Mg + 2HCl → MgCl<sub>2</sub> + H<sub>2</sub></div></div><p>State symbols: (s) solid, (l) liquid, (g) gas, (aq) dissolved in water.</p>` },
    { title: 'Conservation of mass', html: `<div class="rule">total mass of reactants = total mass of products</div><p>In an <b>open</b> container the mass may seem to change:</p><ul><li><b>Decrease</b> — a gas product escapes (e.g. CO<sub>2</sub> from a carbonate).</li><li><b>Increase</b> — a gas from the air reacts (e.g. oxygen when magnesium burns).</li></ul><div class="worked"><div class="wq">2.4 g of magnesium forms 4.0 g of magnesium oxide. What mass of oxygen reacted?</div><ol><li>mass oxygen = mass product − mass magnesium</li><li>= 4.0 − 2.4</li></ol><div class="wa">Answer: 1.6 g</div></div>` },
    { title: 'Types of reaction', html: `<ul><li><b>Combustion</b>: fuel + oxygen → oxides + energy. Complete combustion of hydrocarbons → CO<sub>2</sub> + H<sub>2</sub>O.</li><li><b>Oxidation</b>: gaining oxygen (rusting, burning metals).</li><li><b>Thermal decomposition</b>: e.g. copper carbonate → copper oxide + carbon dioxide.</li><li><b>Exothermic</b> (heat out) vs <b>endothermic</b> (heat in).</li></ul><p>The fire triangle: fuel, heat, oxygen. Remove one to put out a fire.</p>` },
  ],
  mistakes: ['Changing subscripts to balance an equation.', 'Saying mass is lost when a gas is given off — it has just escaped.', 'Using = instead of → in equations.', 'Mixing up exothermic (temperature rises) and endothermic (temperature falls).'],
  examTips: ['After balancing, re-count every element on both sides — this takes ten seconds and catches most errors.', 'When explaining a mass change in an open container, name the gas and say whether it left or joined.', 'Include units (g) in every mass answer.'],
  realLife: 'Bakers rely on thermal decomposition: baking soda breaks down in the oven to release carbon dioxide that makes cakes rise.',
});

// =====================================================================
// YEAR 9 — Acids, alkalis & reactivity
// =====================================================================
topic({ id: 'chem-y9-acids', strand: 'chem-changes', year: 9, term: 1, tier: 'FH', name: 'Acids, Alkalis & Reactivity',
  summary: 'Use the pH scale and indicators, predict the salts made in neutralisation, and use the reactivity series.', specRef: 'KS3 Chemistry: Chemical reactions — acids and alkalis; reactivity series' }, [
  { name: 'pH & indicators', intro: 'The pH scale runs from 0 to 14. Below 7 is acidic, 7 is neutral and above 7 is alkaline. Indicators change colour to show pH.', items: [
    M('What is the pH of a neutral solution such as pure water?', ['7', '0', '1', '14'], 0, 'Neutral solutions have pH 7. Acids are below 7; alkalis are above 7.'),
    M('Which pH is the strongest acid?', ['1', '5', '7', '13'], 0, 'The lower the pH, the more acidic. pH 1 is very acidic; pH 13 is strongly alkaline.'),
    M('What colour is universal indicator in a strong alkali (pH 13)?', ['Purple', 'Red', 'Green', 'Yellow'], 0, 'Universal indicator: red (strong acid) → orange/yellow (weak acid) → green (neutral) → blue (weak alkali) → purple (strong alkali).'),
    M('What colour does universal indicator turn in pure water?', ['Green', 'Red', 'Purple', 'Colourless'], 0, 'Pure water is neutral (pH 7), so universal indicator is green.'),
    M('What colour does litmus paper turn in acid?', ['Red', 'Blue', 'Green', 'Purple'], 0, 'Acids turn blue litmus red. Alkalis turn red litmus blue. Litmus only shows acid or alkali, not the pH number.'),
    S('What is the name for a soluble base?', 'alkali', ['alkali', 'an alkali', 'alkalis'], 'A base reacts with an acid to neutralise it; an alkali is a base that dissolves in water (e.g. sodium hydroxide).'),
    T('Universal indicator can show how strongly acidic or alkaline a solution is, but litmus cannot.', true, 'True. Universal indicator is a mixture of indicators with many colours across the pH range; litmus has only two colours.'),
    T('All acids are dangerous and corrosive.', false, 'False. Many acids are weak or dilute and safe — citric acid in lemons, ethanoic acid in vinegar. Concentrated strong acids are corrosive.'),
    O('Put these in order of increasing pH (most acidic first).', ['Stomach acid', 'Vinegar', 'Pure water', 'Soap', 'Oven cleaner'], 'Stomach acid ≈ pH 1–2, vinegar ≈ 3, water 7, soap ≈ 9–10, oven cleaner ≈ 13–14.'),
    M('Which household substance is an alkali?', ['Bleach / oven cleaner', 'Lemon juice', 'Vinegar', 'Cola'], 0, 'Oven cleaner and bleach contain alkalis (sodium hydroxide, sodium hypochlorite). Lemon juice, vinegar and cola are acidic.'),
    M('What ion do all acids produce when dissolved in water?', ['H<sup>+</sup>', 'OH<sup>−</sup>', 'Na<sup>+</sup>', 'Cl<sup>−</sup>'], 0, 'Acids release hydrogen ions, H<sup>+</sup>(aq). Alkalis release hydroxide ions, OH<sup>−</sup>(aq).'),
    M('What ion do alkalis produce in water?', ['OH<sup>−</sup>', 'H<sup>+</sup>', 'O<sup>2−</sup>', 'Cl<sup>−</sup>'], 0, 'Alkalis produce hydroxide ions, OH<sup>−</sup>.'),
    M('What does "dilute" mean for an acid?', ['There is a small amount of acid dissolved in a lot of water', 'The acid is weak', 'The acid has a pH of 7', 'The acid has been neutralised'], 0, 'Dilute/concentrated describes how much acid is in a given volume. Weak/strong (GCSE) describes how much the acid ionises — a different idea.'),
    S('Which hazard symbol word is used for acids that destroy skin and metals?', 'corrosive', ['corrosive'], 'Corrosive substances destroy living tissue and many materials. Wear goggles and wash spills with plenty of water.'),
    X('Which TWO are acids?', ['Hydrochloric acid', 'Citric acid', 'Sodium hydroxide', 'Calcium hydroxide', 'Ammonia solution'], [0, 1], 'Hydrochloric and citric are acids. Sodium hydroxide, calcium hydroxide (limewater) and ammonia solution are alkalis.'),
    M('Red cabbage juice is purple in water, red in acid and green in alkali. A solution turns it green. What is the solution?', ['Alkaline', 'Acidic', 'Neutral', 'It cannot be known'], 0, 'Use the colour key given: green = alkali for this indicator. Different indicators have different colour keys.'),
    M('What colour is universal indicator in a weak acid such as vinegar (about pH 4)?', ['Orange', 'Red', 'Green', 'Blue'], 0, 'Universal indicator is red for strong acids (pH 0–2), orange/yellow for weak acids (pH 3–6), green at pH 7 and blue/purple for alkalis. Vinegar is weakly acidic, so orange.'),
    M('A solution turns universal indicator purple. What is its approximate pH?', ['13', '7', '4', '1'], 0, 'Purple shows a strong alkali, around pH 12–14. Green would be 7 and red would be around 1.'),
    M('What colour does red litmus paper turn in an alkali?', ['Blue', 'Red (no change)', 'Green', 'Purple'], 0, 'Litmus is red in acid and blue in alkali, so red litmus turns blue in an alkali. Litmus never turns green.'),
    M('Which of these is the best way to measure an exact pH value such as 6.8?', ['A pH probe (pH meter)', 'Red litmus paper', 'Blue litmus paper', 'Smelling the solution'], 0, 'A pH probe gives a precise numerical reading. Litmus only shows acid or alkali, and you should never smell or taste chemicals to test them.'),
    M('Which of these is most likely to have a pH of about 2?', ['Lemon juice', 'Pure water', 'Soap', 'Oven cleaner'], 0, 'Lemon juice contains citric acid and is quite acidic (about pH 2). Pure water is pH 7; soap and oven cleaner are alkaline.'),
    T('An alkali has a pH greater than 7.', true, 'True. pH 7 is neutral; any pH above 7 is alkaline, and the higher it is the more strongly alkaline.'),
    T('Litmus is an example of an indicator.', true, 'True. An indicator is a substance that changes colour depending on whether it is in an acid or an alkali. Litmus and universal indicator are both indicators.'),
    T('A pH of 1 means a solution is only very slightly acidic.', false, 'False. pH 1 is a strongly acidic solution. The lower the pH below 7, the more acidic.'),
    S('What is the name of the scale used to measure how acidic or alkaline a solution is?', 'pH scale', ['ph', 'ph scale', 'the ph scale'], 'The pH scale runs from 0 (most acidic) through 7 (neutral) to 14 (most alkaline).'),
    S('Name the acid found in your stomach.', 'hydrochloric acid', ['hydrochloric acid', 'hydrochloric', 'hcl'], 'The stomach contains dilute hydrochloric acid, which helps digestion and kills bacteria.'),
    X('Which TWO safety precautions are sensible when using dilute acids and alkalis?', ['Wear eye protection', 'Wash any spills off skin with plenty of water', 'Taste a drop to identify it', 'Heat it in a sealed container', 'Use your fingers to stir'], [0, 1], 'Goggles protect your eyes and washing with lots of water dilutes and removes spills. Never taste chemicals, heat sealed containers or touch chemicals with bare hands.'),
    M('An acid is diluted by adding lots of water. What happens to its pH?', ['It rises towards 7', 'It falls towards 0', 'It goes above 7', 'It stays exactly the same'], 0, 'Diluting an acid spreads out the H<sup>+</sup> ions, so it becomes less acidic and the pH rises towards 7 — but it never becomes alkaline just by adding water.'),
    O('Put these in order of increasing pH.', ['Battery acid', 'Orange juice', 'Pure water', 'Toothpaste', 'Drain cleaner'], 'Battery acid (≈ 1) < orange juice (≈ 3–4) < water (7) < toothpaste (≈ 8–9) < drain cleaner (≈ 13–14).'),
    M('A solution has pH 9. Which statement is correct?', ['It is weakly alkaline', 'It is strongly acidic', 'It is neutral', 'It is strongly alkaline'], 0, 'pH 9 is a little above 7, so it is weakly alkaline (indicator blue-green). Strong alkalis have pH around 12–14.'),
  ] },
  { name: 'Neutralisation & naming salts', intro: 'Acid + base → salt + water. The salt name comes from the metal in the base and the acid used: hydrochloric → chloride, sulfuric → sulfate, nitric → nitrate.', items: [
    M('What is made when an acid reacts with an alkali?', ['A salt and water', 'A salt and hydrogen', 'Only water', 'Carbon dioxide and water'], 0, 'Acid + alkali → salt + water. Hydrogen comes from acid + metal; CO<sub>2</sub> from acid + carbonate.'),
    M('Which salt forms from sodium hydroxide and hydrochloric acid?', ['Sodium chloride', 'Sodium sulfate', 'Sodium nitrate', 'Sodium hydride'], 0, 'Hydrochloric acid → chloride salts. Sodium comes from the alkali.'),
    M('Which salt forms from copper oxide and sulfuric acid?', ['Copper sulfate', 'Copper chloride', 'Copper sulfide', 'Copper nitrate'], 0, 'Sulfuric acid → sulfate. Sulfide (no oxygen) would come from sulfur alone, not the acid.'),
    M('Which salt forms from potassium hydroxide and nitric acid?', ['Potassium nitrate', 'Potassium chloride', 'Potassium nitride', 'Potassium sulfate'], 0, 'Nitric acid → nitrates.'),
    S('Complete: magnesium oxide + hydrochloric acid → ______ + water', 'magnesium chloride', ['magnesium chloride'], 'Metal from the base (magnesium) + chloride from hydrochloric acid.', [['magnesium'], ['chloride']]),
    S('Complete: calcium carbonate + nitric acid → calcium nitrate + water + ______', 'carbon dioxide', ['carbon dioxide', 'co2'], 'Acid + carbonate → salt + water + carbon dioxide (fizzing).', [['carbon'], ['dioxide']]),
    T('In neutralisation, H<sup>+</sup> ions from the acid react with OH<sup>−</sup> ions from the alkali to make water.', true, 'True. H<sup>+</sup>(aq) + OH<sup>−</sup>(aq) → H<sub>2</sub>O(l). This is the same for every acid–alkali neutralisation.'),
    M('Why might a farmer spread lime (calcium hydroxide) on a field?', ['To neutralise acidic soil', 'To make the soil more acidic', 'To kill weeds', 'To add nitrogen'], 0, 'Lime is a base; it raises the pH of acidic soil so crops grow well.'),
    M('Why does indigestion medicine contain a base such as magnesium hydroxide?', ['To neutralise excess stomach acid', 'To make the stomach more acidic', 'To add hydrogen to the stomach', 'To kill bacteria'], 0, 'Excess hydrochloric acid in the stomach causes indigestion; a base neutralises it.'),
    M('A bee sting is acidic. What would you use to treat it?', ['A weak alkali such as baking soda', 'Vinegar', 'Lemon juice', 'Strong acid'], 0, 'A weak alkali neutralises the acid. A strong alkali would damage skin; vinegar and lemon would make it worse (and are used for alkaline wasp stings).'),
    O('Put in order how to make copper sulfate crystals from copper oxide.', ['Warm dilute sulfuric acid', 'Add copper oxide until no more dissolves (in excess)', 'Filter off the excess copper oxide', 'Heat the solution to evaporate some water, then leave to crystallise'], 'Excess base makes sure all the acid reacts; filtering removes unreacted solid; crystallisation gives the salt.'),
    M('Why is copper oxide added in excess when making copper sulfate?', ['To make sure all the acid is used up', 'To make the reaction faster', 'To colour the solution', 'To produce more water'], 0, 'Adding excess guarantees no acid is left. The excess solid is easy to filter off.'),
    X('Which TWO are bases?', ['Copper oxide', 'Sodium hydroxide', 'Sulfuric acid', 'Sodium chloride', 'Water'], [0, 1], 'Metal oxides and hydroxides are bases. Sodium hydroxide is also an alkali (soluble). Sodium chloride is a salt; water is neutral.'),
    M('A student adds acid to an alkali with universal indicator. What colour shows it is exactly neutralised?', ['Green', 'Red', 'Purple', 'Blue'], 0, 'At pH 7 universal indicator is green. Adding more acid would turn it orange/red.'),
    M('What is the pH change as acid is slowly added to an alkali?', ['It falls from above 7 to 7 and then below 7', 'It rises from 7 to 14', 'It stays at 7', 'It rises from below 7 to above 7'], 0, 'The alkali starts above 7; as acid neutralises it the pH falls to 7, and extra acid makes it fall below 7.'),
    M('Which salt is made when zinc oxide reacts with sulfuric acid?', ['Zinc sulfate', 'Zinc sulfide', 'Zinc chloride', 'Zinc sulfite'], 0, 'Sulfuric acid makes sulfates. Zinc oxide + sulfuric acid → zinc sulfate + water. "Sulfide" would contain no oxygen.'),
    M('Which acid would you use to make calcium chloride from calcium carbonate?', ['Hydrochloric acid', 'Sulfuric acid', 'Nitric acid', 'Citric acid'], 0, 'Chloride salts come from hydrochloric acid. Sulfuric acid gives sulfates and nitric acid gives nitrates.'),
    M('Which base would you use with nitric acid to make sodium nitrate?', ['Sodium hydroxide', 'Potassium hydroxide', 'Copper oxide', 'Calcium carbonate'], 0, 'The metal in the salt comes from the base, so you need a sodium compound — sodium hydroxide. The other bases would give potassium, copper or calcium nitrate.'),
    M('What is the general word equation for an acid reacting with a metal carbonate?', ['acid + metal carbonate → salt + water + carbon dioxide', 'acid + metal carbonate → salt + hydrogen', 'acid + metal carbonate → salt + water', 'acid + metal carbonate → metal + carbon dioxide'], 0, 'Carbonates give salt, water AND carbon dioxide (fizzing). Hydrogen is produced only when an acid reacts with a metal.'),
    M('What is a base?', ['A substance that neutralises an acid to form a salt and water', 'Any substance with a pH below 7', 'A substance that only dissolves in acid', 'An acid that has been diluted'], 0, 'Bases (metal oxides, hydroxides and carbonates) neutralise acids. A soluble base is called an alkali. A pH below 7 means acidic.'),
    T('All bases are alkalis.', false, 'False. Alkalis are bases that dissolve in water. Many bases, such as copper oxide, are insoluble, so they are bases but not alkalis.'),
    T('A neutralisation reaction always forms a salt.', true, 'True. Whenever an acid is neutralised by a base, a salt is formed (plus water, and CO<sub>2</sub> for carbonates).'),
    T('Toothpaste is slightly alkaline to help neutralise acids made by bacteria in the mouth.', true, 'True. Bacteria produce acids that attack tooth enamel; mildly alkaline toothpaste helps neutralise them.'),
    S('Complete: sodium hydroxide + sulfuric acid → ______ + water', 'sodium sulfate', ['sodium sulfate', 'sodium sulphate'], 'Sulfuric acid forms sulfates, and the metal comes from the alkali: sodium sulfate.'),
    S('What is the general name for the compound formed when the hydrogen in an acid is replaced by a metal?', 'salt', ['salt', 'a salt', 'salts'], 'A salt forms when the hydrogen of an acid is replaced by a metal (or ammonium). Sodium chloride is just one of many salts.'),
    X('Which TWO reactions produce a salt and water ONLY?', ['Hydrochloric acid + sodium hydroxide', 'Sulfuric acid + copper oxide', 'Hydrochloric acid + calcium carbonate', 'Sulfuric acid + magnesium', 'Nitric acid + zinc'], [0, 1], 'Acid + hydroxide and acid + metal oxide both give salt + water only. Carbonates also give CO<sub>2</sub>, and metals give hydrogen instead of water.'),
    N('A student needs 25 cm³ of acid to neutralise 25 cm³ of an alkali. How much acid would neutralise 75 cm³ of the same alkali?', 75, 0.1, 'cm³', ['The ratio is 25 cm³ acid : 25 cm³ alkali, i.e. 1 : 1', '75 cm³ alkali is 3 times as much', '3 × 25 = 75 cm³ of acid'], 'Using three times as much alkali needs three times as much of the same acid.'),
    M('Why is an indicator used when neutralising an alkali with an acid?', ['To show when the alkali has been exactly neutralised', 'To speed up the reaction', 'To make the salt coloured', 'To stop the solution getting hot'], 0, 'Both the acid and the alkali solutions are colourless, so an indicator shows the colour change at the point of neutralisation.'),
    M('Some farmers add powdered limestone to fields after acid rain. Which salt-forming reaction takes place?', ['Acid + carbonate → salt + water + carbon dioxide', 'Acid + metal → salt + hydrogen', 'Acid + alkali → salt + water only', 'No reaction happens'], 0, 'Limestone is calcium carbonate, so it neutralises acid in the soil producing a calcium salt, water and carbon dioxide.'),
    O('Put these steps in order to make a neutral solution of sodium chloride using an indicator.', ['Measure sodium hydroxide into a flask', 'Add a few drops of indicator', 'Add hydrochloric acid a little at a time, swirling', 'Stop when the indicator shows neutral'], 'Measure the alkali, add indicator, add acid slowly while swirling, and stop at the colour change. (To get pure salt you would repeat without indicator, then evaporate.)'),
  ] },
  { name: 'Metals, acids & the reactivity series', intro: 'Metals can be placed in a reactivity series by how vigorously they react with water, acids and oxygen. A more reactive metal displaces a less reactive one from its compounds.', items: [
    M('What gas is produced when magnesium reacts with dilute hydrochloric acid?', ['Hydrogen', 'Oxygen', 'Carbon dioxide', 'Chlorine'], 0, 'Metal + acid → salt + hydrogen. Test: lighted splint gives a squeaky pop.'),
    M('Which test identifies hydrogen?', ['A lighted splint gives a squeaky pop', 'Limewater turns milky', 'A glowing splint relights', 'Damp litmus is bleached'], 0, 'Hydrogen burns with a squeaky pop. Limewater = CO<sub>2</sub>; glowing splint = O<sub>2</sub>; bleached litmus = Cl<sub>2</sub>.'),
    O('Put these metals in order of reactivity (most reactive first).', ['Potassium', 'Magnesium', 'Zinc', 'Copper'], 'K is extremely reactive; Mg reacts readily with acid; Zn more slowly; Cu does not react with dilute acids.'),
    M('Which metal does NOT react with dilute hydrochloric acid?', ['Copper', 'Magnesium', 'Zinc', 'Iron'], 0, 'Copper is below hydrogen in the reactivity series, so it cannot displace hydrogen from acids.'),
    M('Iron is placed in copper sulfate solution. What happens?', ['Iron displaces copper; pink copper forms and the solution turns from blue to pale green', 'Nothing happens', 'Copper displaces iron', 'Hydrogen is given off'], 0, 'Iron is more reactive than copper, so it displaces copper: iron + copper sulfate → iron sulfate + copper.'),
    M('Copper is placed in magnesium sulfate solution. What happens?', ['No reaction', 'Copper displaces magnesium', 'Magnesium is deposited on the copper', 'The solution turns blue'], 0, 'Copper is less reactive than magnesium, so it cannot displace it.'),
    T('A more reactive metal can displace a less reactive metal from a solution of its salt.', true, 'True. This is a displacement reaction, used to compare reactivity.'),
    S('Which non-metal is included in the reactivity series between aluminium and zinc and is used to extract metals?', 'carbon', ['carbon', 'c'], 'Carbon is placed between aluminium and zinc. Metals below carbon (zinc, iron, copper…) can be extracted by heating their oxides with carbon.'),
    M('Why is gold found as the pure metal in the ground?', ['It is very unreactive', 'It is very reactive', 'It is magnetic', 'It is a non-metal'], 0, 'Unreactive metals do not form compounds easily, so gold is found native (uncombined).'),
    M('Which metal is extracted by heating its oxide with carbon?', ['Iron', 'Sodium', 'Potassium', 'Aluminium'], 0, 'Iron is below carbon, so carbon can remove the oxygen. Sodium, potassium and aluminium are above carbon and need electrolysis.'),
    S('Complete: zinc + sulfuric acid → ______ + hydrogen', 'zinc sulfate', ['zinc sulfate'], 'Sulfuric acid makes sulfate salts.', [['zinc'], ['sulfate', 'sulphate']]),
    M('Sodium reacts with cold water. What are the products?', ['Sodium hydroxide and hydrogen', 'Sodium oxide and oxygen', 'Sodium chloride and water', 'Sodium hydroxide and oxygen'], 0, 'Reactive metals + water → metal hydroxide + hydrogen. The solution is alkaline.'),
    X('Which TWO observations would show magnesium is more reactive than zinc with acid?', ['Magnesium fizzes faster', 'The temperature rises more with magnesium', 'Zinc gives off more bubbles per second', 'Both look identical', 'Zinc dissolves faster'], [0, 1], 'A more reactive metal reacts more vigorously: more bubbles per second and a bigger temperature rise (more energy released per second).'),
    M('In a displacement reaction, magnesium + copper oxide → magnesium oxide + copper. Which substance is oxidised?', ['Magnesium', 'Copper oxide', 'Copper', 'Magnesium oxide'], 0, 'Magnesium gains oxygen, so it is oxidised. Copper oxide loses oxygen — it is reduced.'),
    T('Aluminium is extracted using carbon because it is less reactive than carbon.', false, 'False. Aluminium is MORE reactive than carbon, so carbon cannot reduce aluminium oxide — electrolysis is used.'),
    M('Which metal reacts most vigorously with dilute hydrochloric acid?', ['Magnesium', 'Zinc', 'Iron', 'Copper'], 0, 'Of these, magnesium is highest in the reactivity series, so it fizzes most rapidly. Copper does not react with dilute hydrochloric acid at all.'),
    M('Which metal is stored under oil because it reacts with air and water?', ['Potassium', 'Copper', 'Iron', 'Zinc'], 0, 'Potassium (like sodium and lithium) reacts quickly with oxygen and water, so it is stored under oil. Copper, iron and zinc react slowly or not at all.'),
    M('Magnesium is put in zinc sulfate solution. What happens?', ['Magnesium displaces zinc, forming magnesium sulfate and zinc', 'Nothing happens', 'Zinc displaces magnesium', 'Hydrogen is given off'], 0, 'Magnesium is more reactive than zinc, so it pushes zinc out of its compound: magnesium + zinc sulfate → magnesium sulfate + zinc.'),
    M('Why is iron extracted from its ore by heating with carbon?', ['Carbon is more reactive than iron, so it removes the oxygen', 'Iron is more reactive than carbon', 'Carbon is a metal', 'Iron is found as the pure metal'], 0, 'Carbon is above iron in the reactivity series, so it can take oxygen from iron oxide (reduction), leaving iron.'),
    M('A metal reacts slowly with dilute acid, but not with cold water. Which metal is it most likely to be?', ['Iron', 'Sodium', 'Gold', 'Calcium'], 0, 'Iron reacts slowly with dilute acid and hardly at all with cold water. Sodium and calcium react with cold water; gold reacts with neither.'),
    T('Copper reacts with dilute sulfuric acid to make hydrogen.', false, 'False. Copper is below hydrogen in the reactivity series, so it does not react with dilute acids to give hydrogen.'),
    T('The more reactive a metal, the harder it usually is to extract from its ore.', true, 'True. Reactive metals form very stable compounds. Metals more reactive than carbon (like aluminium) need electrolysis, which uses a lot of energy.'),
    T('In a displacement reaction, the less reactive metal ends up in the compound.', false, 'False. The MORE reactive metal ends up in the compound; the less reactive metal is pushed out as the free element.'),
    S('Complete: calcium + water → calcium hydroxide + ______', 'hydrogen', ['hydrogen', 'hydrogen gas', 'h2'], 'Reactive metals react with water to form a metal hydroxide and hydrogen gas.'),
    S('What is the name of the rock that a metal is extracted from?', 'ore', ['ore', 'an ore', 'metal ore'], 'An ore is a rock containing enough of a metal compound for extraction to be worth doing.'),
    X('Which TWO pairs would react (show a displacement)?', ['Zinc + copper sulfate solution', 'Magnesium + iron sulfate solution', 'Copper + zinc sulfate solution', 'Silver + copper sulfate solution', 'Iron + magnesium sulfate solution'], [0, 1], 'Displacement only happens when the free metal is more reactive than the metal in the compound. Zinc > copper and magnesium > iron. Copper < zinc, silver < copper and iron < magnesium, so those do not react.'),
    O('Put these in the order of how they react with cold water (most vigorous first).', ['Potassium', 'Sodium', 'Calcium', 'Magnesium'], 'Potassium bursts into flame; sodium whizzes and melts; calcium fizzes steadily; magnesium reacts very slowly with cold water.'),
    M('Iron nails are put in blue copper sulfate solution. Which observation is expected after a while?', ['A brown coating forms on the nails and the blue colour fades', 'The nails turn blue', 'Bubbles of oxygen form', 'Nothing happens'], 0, 'Iron displaces copper, which coats the nails as a brown/pink layer. Blue copper ions are used up, so the solution fades (pale green iron sulfate forms).'),
    M('A student adds metal X to acid; bubbles form quickly. Metal Y gives a few slow bubbles. Metal Z gives none. Which order of reactivity is correct?', ['X > Y > Z', 'Z > Y > X', 'Y > X > Z', 'X > Z > Y'], 0, 'The faster the bubbles of hydrogen, the more reactive the metal. X reacted fastest and Z not at all.'),
    M('Why is a fair test important when comparing metals with acid?', ['Only the metal should change; acid concentration, volume and temperature must be kept the same', 'So that all metals react at the same speed', 'So that the acid does not get used up', 'Fair tests are only needed with alkalis'], 0, 'If concentration, volume, temperature or the size of the metal pieces differed, you could not tell whether the metal caused the difference in rate.'),
  ] },
], {
  overview: 'Acids and alkalis are everywhere — from lemon juice to oven cleaner. The <b>pH scale</b> measures acidity, and <b>neutralisation</b> reactions make salts. The <b>reactivity series</b> ranks metals and explains displacement and how metals are extracted.',
  objectives: ['I can use the pH scale and indicators', 'I can describe neutralisation and name the salt made', 'I can write word equations for acids with metals, bases and carbonates', 'I can place metals in a reactivity series and predict displacement', 'I can explain how the reactivity series links to extraction'],
  keyWords: [{ term: 'pH', def: 'A scale from 0 to 14 measuring acidity or alkalinity.' }, { term: 'Indicator', def: 'A substance that changes colour with pH.' }, { term: 'Base', def: 'A substance that neutralises an acid, e.g. metal oxides and hydroxides.' }, { term: 'Alkali', def: 'A soluble base; produces OH⁻ ions in water.' }, { term: 'Neutralisation', def: 'Acid + base → salt + water.' }, { term: 'Salt', def: 'Compound formed when the hydrogen of an acid is replaced by a metal.' }, { term: 'Displacement', def: 'A more reactive element takes the place of a less reactive one in a compound.' }, { term: 'Reactivity series', def: 'A list of metals in order of reactivity.' }],
  sections: [
    { title: 'The pH scale', html: `<table class="qt"><tr><th>pH</th><th>0–2</th><th>3–6</th><th>7</th><th>8–11</th><th>12–14</th></tr><tr><td>Type</td><td>Strong acid</td><td>Weak acid</td><td>Neutral</td><td>Weak alkali</td><td>Strong alkali</td></tr><tr><td>Universal indicator</td><td>Red</td><td>Orange/yellow</td><td>Green</td><td>Blue</td><td>Purple</td></tr></table><p>Acids produce H<sup>+</sup> ions in water; alkalis produce OH<sup>−</sup> ions.</p>` },
    { title: 'Reactions of acids', html: `<div class="rule">acid + metal → salt + hydrogen<br>acid + base (metal oxide/hydroxide) → salt + water<br>acid + metal carbonate → salt + water + carbon dioxide</div><p>Naming the salt: hydrochloric → <b>chloride</b>; sulfuric → <b>sulfate</b>; nitric → <b>nitrate</b>. The first part comes from the metal.</p><div class="worked"><div class="wq">Name the salt from zinc oxide + nitric acid.</div><ol><li>Metal: zinc</li><li>Nitric acid → nitrate</li></ol><div class="wa">Answer: zinc nitrate (+ water)</div></div>` },
    { title: 'Reactivity series', html: `<p>Most → least reactive: <b>potassium, sodium, calcium, magnesium, aluminium, (carbon), zinc, iron, (hydrogen), copper, silver, gold</b>.</p><ul><li>Metals above hydrogen react with dilute acids to give hydrogen.</li><li>A more reactive metal displaces a less reactive one: Mg + CuSO<sub>4</sub> → MgSO<sub>4</sub> + Cu.</li><li>Metals below carbon are extracted by heating with carbon; those above by electrolysis.</li></ul>` },
    { title: 'Everyday neutralisation', html: `<ul><li>Indigestion tablets neutralise excess stomach acid.</li><li>Farmers add lime to acidic soils.</li><li>Toothpaste is slightly alkaline to neutralise acids made by mouth bacteria.</li></ul>` },
  ],
  mistakes: ['Saying hydrochloric acid makes "chlorine salts" — they are chlorides.', 'Thinking dilute means weak — dilute is about amount of water.', 'Thinking a less reactive metal can displace a more reactive one.', 'Forgetting carbon dioxide as a product when acids react with carbonates.'],
  examTips: ['Learn the three general acid equations — they turn up in many questions.', 'For displacement questions, state the observation (colour change, metal coating) and explain using reactivity.', 'Give indicator colours precisely (e.g. "purple" not "dark").'],
  realLife: 'Swimming-pool staff check pH several times a day so the water is neither irritating to eyes nor a breeding ground for microbes.',
});

// =====================================================================
// YEAR 9 — Earth & atmosphere
// =====================================================================
topic({ id: 'chem-y9-earth', strand: 'chem-atmos', year: 9, term: 2, tier: 'FH', name: 'The Earth & Atmosphere',
  summary: 'Describe the structure of the Earth, the rock cycle, the composition of air, the carbon cycle and human impacts.', specRef: 'KS3 Chemistry: Earth and atmosphere' }, [
  { name: 'Earth structure & the rock cycle', intro: 'The Earth has a crust, mantle and core. Igneous, sedimentary and metamorphic rocks form in different ways and are linked by the rock cycle.', items: [
    O('Put the layers of the Earth in order from the surface inwards.', ['Crust', 'Mantle', 'Outer core', 'Inner core'], 'The thin rocky crust sits on the mantle; the outer core is liquid iron/nickel; the inner core is solid.'),
    M('Which layer of the Earth is liquid?', ['Outer core', 'Inner core', 'Crust', 'Lithosphere'], 0, 'The outer core is liquid iron and nickel. The inner core is solid because of the enormous pressure despite its high temperature.'),
    M('How do igneous rocks form?', ['Molten rock (magma/lava) cools and solidifies', 'Layers of sediment are compacted', 'Existing rock is changed by heat and pressure', 'Shells collect on the sea floor'], 0, 'Igneous rocks crystallise from molten rock. Compaction = sedimentary; heat and pressure = metamorphic.'),
    M('Why does granite have larger crystals than basalt?', ['Granite cooled slowly underground', 'Granite cooled quickly at the surface', 'Granite is sedimentary', 'Granite contains fossils'], 0, 'Slow cooling (intrusive, underground) gives time for large crystals. Basalt cooled quickly from lava at the surface, so its crystals are small.'),
    M('Which type of rock may contain fossils?', ['Sedimentary', 'Igneous', 'Metamorphic', 'None'], 0, 'Sedimentary rocks form gently from layers of sediment, so remains of organisms can be preserved. Melting (igneous) or heat/pressure (metamorphic) usually destroys fossils.'),
    S('What type of rock forms when existing rock is changed by heat and pressure without melting?', 'metamorphic', ['metamorphic'], 'Metamorphic rocks (marble, slate) form from existing rocks under heat and pressure. If the rock melted, it would become igneous when it cooled.'),
    M('Limestone is changed by heat and pressure. Which rock forms?', ['Marble', 'Slate', 'Granite', 'Sandstone'], 0, 'Limestone → marble. Mudstone/shale → slate.'),
    O('Put the formation of sedimentary rock in order.', ['Weathering breaks rock into pieces', 'Erosion and transport carry the pieces away', 'Deposition of sediment in layers', 'Compaction and cementation form rock'], 'Weathering → erosion/transport → deposition → compaction and cementation.'),
    T('Weathering can be caused by water freezing in cracks in rocks.', true, 'True. Water expands when it freezes, widening cracks (freeze–thaw weathering).'),
    T('Sedimentary rocks are usually harder than igneous rocks.', false, 'False. Sedimentary rocks are usually softer and more porous because they are grains cemented together. Igneous rocks have interlocking crystals and are hard.'),
    M('What is the main compound in limestone?', ['Calcium carbonate', 'Sodium chloride', 'Silicon dioxide', 'Iron oxide'], 0, 'Limestone is mostly calcium carbonate, CaCO<sub>3</sub>, often formed from shells. Sandstone is mostly silicon dioxide.'),
    X('Which TWO are igneous rocks?', ['Granite', 'Basalt', 'Limestone', 'Marble', 'Sandstone'], [0, 1], 'Granite and basalt formed from cooling magma/lava. Limestone and sandstone are sedimentary; marble is metamorphic.'),
    M('Acid rain reacts with limestone buildings. What type of weathering is this?', ['Chemical weathering', 'Physical weathering', 'Biological weathering', 'Metamorphism'], 0, 'Acid reacting with calcium carbonate is chemical weathering — new substances form (a salt, water and CO<sub>2</sub>).'),
    M('Why is the crust described as a "thin" layer?', ['It is very thin compared with the radius of the Earth', 'It is only a few metres thick', 'It is thinner than paper', 'It is the thinnest rock on Earth'], 0, 'The crust is about 5–70 km thick, tiny compared with Earth\'s ~6400 km radius.'),
    S('What name is given to molten rock that reaches the Earth\'s surface?', 'lava', ['lava'], 'Molten rock underground is magma; when it erupts at the surface it is lava.'),
    M('What is the inner core of the Earth mainly made of?', ['Iron and nickel', 'Granite', 'Liquid water', 'Limestone'], 0, 'The core is mainly iron and nickel. The inner core is solid because of the huge pressure; the outer core is liquid.'),
    M('Which layer of the Earth lies directly beneath the crust?', ['Mantle', 'Outer core', 'Inner core', 'Atmosphere'], 0, 'Going inwards: crust → mantle → outer core → inner core. The mantle is mostly solid rock that can flow very slowly.'),
    M('Basalt has tiny crystals. Where did it form?', ['From lava cooling quickly at the surface', 'From magma cooling slowly underground', 'From layers of sediment', 'From heat and pressure on limestone'], 0, 'Fast cooling at the surface gives crystals little time to grow, so they are small. Slow cooling underground (e.g. granite) gives large crystals.'),
    M('How are sediments turned into sedimentary rock?', ['They are compacted by the weight of layers above and cemented together', 'They are melted and then cooled', 'They are heated without melting', 'They react with oxygen'], 0, 'Layers build up, the weight squeezes out water (compaction) and dissolved minerals glue the grains together (cementation). Melting would make igneous rock.'),
    M('Marble is a metamorphic rock. Which rock is it made from?', ['Limestone', 'Granite', 'Sandstone', 'Basalt'], 0, 'Heat and pressure turn limestone into marble. Both are mainly calcium carbonate, but marble has interlocking crystals and is harder.'),
    T('Metamorphic rocks are formed when rock melts completely and then cools.', false, 'False. Rock that melts and cools forms igneous rock. Metamorphic rocks are changed by heat and pressure WITHOUT melting.'),
    T('Igneous rocks are made of interlocking crystals.', true, 'True. As molten rock cools, crystals grow and lock together, so igneous rocks are usually hard and not porous.'),
    T('The rock cycle takes millions of years.', true, 'True. Most rock cycle processes — erosion, burial, metamorphism, uplift — happen extremely slowly, over millions of years.'),
    S('What name is given to the movement of weathered rock pieces by wind, water or ice?', 'transport', ['transport', 'transportation', 'erosion'], 'Transport moves rock fragments away; erosion is the wearing away and removal of rock. Eventually the pieces are deposited as sediment.'),
    S('What name is given to molten rock found underground?', 'magma', ['magma'], 'Molten rock below the surface is magma; when it reaches the surface it is called lava.'),
    X('Which TWO are sedimentary rocks?', ['Sandstone', 'Limestone', 'Granite', 'Marble', 'Basalt'], [0, 1], 'Sandstone and limestone form from compacted and cemented sediments. Granite and basalt are igneous; marble is metamorphic.'),
    M('Why are sedimentary rocks often porous (able to soak up water)?', ['There are gaps between the cemented grains', 'They are made of interlocking crystals', 'They are formed from lava', 'They contain metals'], 0, 'Sedimentary rocks are made of grains cemented together with small spaces between them, so water can soak in. Interlocking crystals (igneous and metamorphic rocks) leave few gaps.'),
    M('Rocks in a desert crack because they heat up in the day and cool at night. What type of weathering is this?', ['Physical weathering', 'Chemical weathering', 'Biological weathering', 'Metamorphism'], 0, 'Repeated expansion and contraction breaks rocks without changing their chemistry — physical weathering. Chemical weathering involves reactions, e.g. acid rain dissolving limestone.'),
    O('Put these rock cycle stages in order, starting with an existing rock at the surface.', ['Weathering breaks up the rock', 'Fragments are transported and deposited', 'Layers are compacted and cemented', 'Sedimentary rock forms'], 'Weathering → transport → deposition → compaction and cementation → sedimentary rock.'),
    M('Why do fossils not usually survive in metamorphic rocks?', ['The heat and pressure destroy or distort them', 'Animals never lived where metamorphic rocks form', 'Metamorphic rocks form from lava', 'Fossils dissolve in water'], 0, 'Metamorphic rocks form under great heat and pressure, which usually destroys fossils in the original sedimentary rock. Igneous rocks form from molten rock, so they contain no fossils at all.'),
  ] },
  { name: 'The air & the carbon cycle', intro: 'Dry air is about 78% nitrogen, 21% oxygen, 0.9% argon and 0.04% carbon dioxide. The carbon cycle moves carbon between the atmosphere, living things, oceans and rocks.', items: [
    M('Approximately what percentage of dry air is nitrogen?', ['78%', '21%', '1%', '50%'], 0, 'About 78% (roughly four-fifths) nitrogen; about 21% (one-fifth) oxygen.'),
    M('Approximately what percentage of dry air is oxygen?', ['21%', '78%', '0.04%', '50%'], 0, 'About one-fifth of air is oxygen.'),
    M('Approximately what percentage of air is carbon dioxide?', ['0.04%', '4%', '21%', '0.9%'], 0, 'Carbon dioxide is only about 0.04% of air, but it is an important greenhouse gas. 0.9% is argon.'),
    S('Which noble gas makes up nearly 1% of the air?', 'argon', ['argon', 'ar'], 'Argon is about 0.9% of dry air — more than carbon dioxide.'),
    M('Which process removes carbon dioxide from the atmosphere?', ['Photosynthesis', 'Respiration', 'Combustion', 'Decay'], 0, 'Plants and algae take in CO<sub>2</sub> for photosynthesis. Respiration, combustion and decay all release CO<sub>2</sub>.'),
    X('Which TWO processes release carbon dioxide into the atmosphere?', ['Burning fossil fuels', 'Respiration', 'Photosynthesis', 'Formation of limestone', 'Dissolving in oceans'], [0, 1], 'Combustion and respiration release CO<sub>2</sub>. Photosynthesis, dissolving in oceans and formation of carbonate rocks remove it.'),
    T('The oceans absorb carbon dioxide from the atmosphere.', true, 'True. CO<sub>2</sub> dissolves in sea water; some ends up in shells and carbonate sediments. Extra CO<sub>2</sub> makes oceans more acidic.'),
    T('Fossil fuels contain carbon that was originally taken from the atmosphere millions of years ago.', true, 'True. Coal, oil and gas formed from ancient organisms that absorbed carbon. Burning them returns that locked-up carbon to the air quickly.'),
    M('What is the word equation for photosynthesis?', ['carbon dioxide + water → glucose + oxygen', 'glucose + oxygen → carbon dioxide + water', 'carbon + oxygen → carbon dioxide', 'water → hydrogen + oxygen'], 0, 'Photosynthesis uses CO<sub>2</sub> and water with light energy to make glucose and oxygen. The reverse is respiration.'),
    M('How do decomposers return carbon to the atmosphere?', ['By respiring as they break down dead material', 'By photosynthesising', 'By forming fossil fuels', 'By absorbing oxygen only'], 0, 'Bacteria and fungi feed on dead organisms and respire, releasing CO<sub>2</sub>.'),
    O('Put these steps in order for one carbon atom moving through the carbon cycle.', ['CO<sub>2</sub> in the air is absorbed by a plant', 'Carbon becomes part of glucose in the plant', 'An animal eats the plant', 'The animal respires and releases CO<sub>2</sub>'], 'Photosynthesis → carbon in plant compounds → feeding → respiration returns CO<sub>2</sub>.'),
    M('Which test identifies oxygen?', ['It relights a glowing splint', 'It turns limewater milky', 'It gives a squeaky pop', 'It bleaches damp litmus'], 0, 'Oxygen relights a glowing splint. Limewater = CO<sub>2</sub>, squeaky pop = H<sub>2</sub>, bleaching = Cl<sub>2</sub>.'),
    M('Why has the percentage of carbon dioxide in the air increased over the last 200 years?', ['Increased burning of fossil fuels and deforestation', 'More photosynthesis', 'Volcanoes have stopped erupting', 'More limestone forming'], 0, 'Burning fuels adds CO<sub>2</sub>; cutting down forests reduces photosynthesis (and burning trees adds more).'),
    S('Name the gas that makes up most of the air.', 'nitrogen', ['nitrogen', 'n2'], 'Nitrogen is about 78% of the air. It is fairly unreactive.'),
    M('Air is a mixture. Which evidence supports this?', ['Its composition can vary slightly and its gases can be separated by fractional distillation', 'It has a fixed formula', 'It cannot be separated', 'It is colourless'], 0, 'Mixtures have variable composition and can be separated physically — liquid air is fractionally distilled to give nitrogen, oxygen and argon.'),
    M('Which gas makes up about 0.9% of dry air?', ['Argon', 'Carbon dioxide', 'Helium', 'Hydrogen'], 0, 'Argon is about 0.9% of dry air. Carbon dioxide is only about 0.04%.'),
    M('In photosynthesis, which substance is produced along with glucose?', ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Methane'], 0, 'Photosynthesis: carbon dioxide + water → glucose + oxygen. Plants release oxygen and take in carbon dioxide.'),
    M('What is the word equation for respiration in living things?', ['glucose + oxygen → carbon dioxide + water', 'carbon dioxide + water → glucose + oxygen', 'glucose → oxygen + water', 'oxygen + water → carbon dioxide'], 0, 'Respiration releases energy from glucose using oxygen, giving out carbon dioxide and water. It is the reverse of photosynthesis.'),
    M('How is carbon stored for millions of years in the carbon cycle?', ['In fossil fuels and carbonate rocks such as limestone', 'In the air only', 'In clouds', 'In the Sun'], 0, 'Fossil fuels (coal, oil, gas) and limestone hold carbon for millions of years. Burning fuels or weathering rocks releases it again.'),
    M('Which test identifies carbon dioxide?', ['It turns limewater milky (cloudy)', 'It relights a glowing splint', 'It gives a squeaky pop with a lit splint', 'It bleaches damp litmus paper'], 0, 'CO<sub>2</sub> turns limewater cloudy. A glowing splint relighting shows oxygen; a squeaky pop shows hydrogen; bleaching litmus shows chlorine.'),
    T('Animals take in carbon by eating plants or other animals.', true, 'True. Carbon passes along food chains as animals eat plants (or other animals) and use the carbon compounds in their bodies.'),
    T('The amount of oxygen in the air is about 50%.', false, 'False. Oxygen is about 21% of dry air. Nitrogen makes up about 78%.'),
    T('Burning (combustion) of wood releases carbon dioxide into the atmosphere.', true, 'True. Wood contains carbon compounds; when it burns they react with oxygen to form carbon dioxide.'),
    S('Name the process by which green plants use light to make glucose from carbon dioxide and water.', 'photosynthesis', ['photosynthesis'], 'Photosynthesis uses light energy absorbed by chlorophyll to make glucose and oxygen.'),
    S('Which gas in the air is needed for things to burn?', 'oxygen', ['oxygen', 'o2'], 'Oxygen is needed for combustion. Nitrogen (the main gas in air) does not support burning.'),
    X('Which TWO processes take carbon dioxide OUT of the atmosphere?', ['Photosynthesis', 'Dissolving in oceans', 'Respiration', 'Burning fossil fuels', 'Decomposition'], [0, 1], 'Plants use CO<sub>2</sub> in photosynthesis and the oceans dissolve it. Respiration, combustion and decomposition all release CO<sub>2</sub>.'),
    N('Dry air is 78% nitrogen and 21% oxygen. What percentage is made up of all the other gases together?', 1, 0, '%', ['Total = 100%', 'Other gases = 100 − 78 − 21', 'Other gases = 1%'], 'About 1% of dry air is everything else — mainly argon (0.9%) plus carbon dioxide (0.04%) and traces of other gases.'),
    M('Why is the amount of oxygen in the air roughly constant today?', ['Photosynthesis replaces the oxygen used in respiration and combustion', 'Nothing uses up oxygen', 'Oxygen is made by volcanoes', 'Oxygen cannot react'], 0, 'Oxygen is used up by respiration and burning, but photosynthesis by plants and algae puts oxygen back, keeping the level fairly steady.'),
    M('Cutting down large areas of forest increases atmospheric CO<sub>2</sub>. Which explanation is best?', ['Less photosynthesis, and the wood is often burned or decays', 'More photosynthesis and less respiration', 'Trees produce carbon dioxide only when alive', 'Soil absorbs more CO<sub>2</sub>'], 0, 'Fewer trees means less CO<sub>2</sub> removed by photosynthesis, and burning or rotting wood releases the stored carbon as CO<sub>2</sub>.'),
    O('Put these gases in order of their percentage in dry air, highest first.', ['Nitrogen', 'Oxygen', 'Argon', 'Carbon dioxide'], 'Nitrogen ≈ 78%, oxygen ≈ 21%, argon ≈ 0.9%, carbon dioxide ≈ 0.04%.'),
  ] },
  { name: 'Climate & Earth\'s resources', intro: 'Greenhouse gases keep Earth warm, but extra carbon dioxide from human activity is causing climate change. Earth\'s resources are limited, so recycling matters.', items: [
    M('What is the greenhouse effect?', ['Gases in the atmosphere trap heat, keeping Earth warm', 'A hole in the ozone layer', 'Plants growing in greenhouses', 'Acid rain damaging buildings'], 0, 'Greenhouse gases absorb infrared radiation emitted by the warm Earth and re-emit it, warming the lower atmosphere. The ozone hole is a separate issue.'),
    X('Which TWO are greenhouse gases?', ['Carbon dioxide', 'Methane', 'Nitrogen', 'Oxygen', 'Argon'], [0, 1], 'Carbon dioxide, methane and water vapour are greenhouse gases. Nitrogen, oxygen and argon are not.'),
    T('Without any greenhouse effect, Earth would be too cold for most life.', true, 'True. The natural greenhouse effect keeps Earth\'s average temperature around 15 °C rather than about −18 °C. The problem is the enhanced effect from extra gases.'),
    M('Which is a likely effect of global climate change?', ['Rising sea levels', 'More oxygen in the air', 'Thicker ozone layer', 'Fewer storms everywhere'], 0, 'Warming melts ice and expands sea water, raising sea levels; also more extreme weather and changes to habitats.'),
    M('Which action would reduce carbon dioxide emissions?', ['Using renewable energy instead of fossil fuels', 'Burning more coal', 'Cutting down forests', 'Driving more'], 0, 'Renewables such as wind and solar release no CO<sub>2</sub> when generating electricity.'),
    S('What word describes a resource that will run out because it is not being replaced, such as crude oil?', 'finite', ['finite', 'non-renewable', 'nonrenewable', 'non renewable'], 'Finite / non-renewable resources form far more slowly than we use them.'),
    M('Why is recycling aluminium cans better than extracting new aluminium?', ['It uses much less energy and saves the ore', 'Recycled aluminium is stronger', 'It produces more waste', 'Aluminium ore is unlimited'], 0, 'Recycling aluminium uses about 5% of the energy needed for extraction by electrolysis and conserves ore and landfill space.'),
    X('Which TWO are benefits of recycling metals?', ['Saves energy', 'Reduces waste in landfill', 'Uses more ore', 'Increases mining', 'Produces more carbon dioxide'], [0, 1], 'Recycling saves energy and finite ores and reduces landfill and mining damage.'),
    T('Methane is released by cattle and rice paddy fields.', true, 'True. Methane comes from livestock digestion, rice paddies and landfill sites; it is a powerful greenhouse gas.'),
    M('What is a "carbon footprint"?', ['The total greenhouse gases released over the life of a product or activity', 'Soot left by a fire', 'Carbon found in soil', 'The mass of carbon in a fuel'], 0, 'A carbon footprint measures total greenhouse gas emissions, usually as CO<sub>2</sub> equivalent.'),
    M('Why is it hard to make exact predictions about climate change?', ['The climate system is complex with many interacting factors', 'Scientists do not measure temperature', 'Carbon dioxide does not affect temperature', 'The Sun never changes'], 0, 'Many factors (clouds, oceans, ice, human choices) interact, so models give ranges. Scientists agree human activity is causing warming.'),
    M('Which material is NOT a finite resource?', ['Wood from managed forests', 'Coal', 'Natural gas', 'Iron ore'], 0, 'Wood can be regrown, so it is renewable if forests are replanted. Coal, gas and ores are finite.'),
    T('Planting trees helps to remove carbon dioxide from the atmosphere.', true, 'True. Trees absorb CO<sub>2</sub> by photosynthesis and store carbon in their wood.'),
    O('Put in order of the "waste hierarchy" from most to least preferred.', ['Reduce', 'Reuse', 'Recycle', 'Dispose in landfill'], 'Using less is best; reusing avoids processing; recycling still uses some energy; landfill is the last resort.'),
    M('Why does burning fossil fuels increase global temperatures?', ['It releases carbon dioxide, which increases the greenhouse effect', 'It releases oxygen, which traps heat', 'It makes the Sun hotter', 'It removes nitrogen'], 0, 'Extra CO<sub>2</sub> absorbs more infrared radiation, enhancing the greenhouse effect.'),
    M('Which human activity releases large amounts of methane?', ['Cattle farming', 'Planting trees', 'Using solar panels', 'Recycling glass'], 0, 'Cattle produce methane during digestion. Rice paddies and landfill sites are other important human sources.'),
    M('How do greenhouse gases warm the Earth?', ['They absorb heat (infrared) given off by the Earth and re-emit some back towards it', 'They make the Sun hotter', 'They create holes for more sunlight to enter', 'They reflect all sunlight away'], 0, 'The Earth gives off infrared radiation; greenhouse gases absorb it and send some back, keeping the lower atmosphere warmer. They do not change the Sun.'),
    M('What is the difference between weather and climate?', ['Weather is day-to-day conditions; climate is the average pattern over many years', 'They mean exactly the same thing', 'Climate is day-to-day; weather is long-term', 'Weather only refers to temperature'], 0, 'Weather is short-term (today\'s rain). Climate is the long-term average over 30 years or more. One cold winter does not disprove climate change.'),
    M('Why does melting land ice cause sea levels to rise?', ['Water from ice on land flows into the oceans, adding to their volume', 'Ice is denser than water', 'Melting ice makes the sea evaporate', 'Sea ice on land sinks'], 0, 'Glaciers and ice sheets on land add extra water to the sea when they melt. Warmer water also expands, adding to the rise.'),
    M('Which of these is a renewable energy resource?', ['Wind', 'Coal', 'Natural gas', 'Crude oil'], 0, 'Wind is renewable — it will not run out. Coal, natural gas and crude oil are finite fossil fuels.'),
    T('Climate change could cause more frequent and severe extreme weather events, such as floods and heatwaves.', true, 'True. A warmer atmosphere holds more energy and moisture, which is linked to more extreme weather.'),
    T('Recycling metals uses more energy than extracting them from ores.', false, 'False. Recycling usually uses much less energy than mining and extracting new metal, and it saves ores and reduces waste.'),
    T('Glass bottles can be reused or crushed and melted to make new glass.', true, 'True. Reusing glass saves the most energy; recycling by melting cullet (crushed glass) still saves energy and raw materials.'),
    S('Name the greenhouse gas with the formula CH<sub>4</sub>.', 'methane', ['methane'], 'CH<sub>4</sub> is methane. Molecule for molecule it is a stronger greenhouse gas than carbon dioxide.'),
    S('What word describes a resource, like wood from managed forests, that can be replaced as fast as it is used?', 'renewable', ['renewable', 'renewable resource'], 'A renewable resource is replaced naturally within a human lifetime. Finite resources, like metal ores and fossil fuels, are not.'),
    X('Which TWO actions reduce the amount of new metal ore that must be mined?', ['Recycling metal cans', 'Repairing and reusing old items', 'Throwing metal in landfill', 'Using more single-use products', 'Burying scrap cars'], [0, 1], 'Recycling and reusing keep metal in use, reducing demand for newly mined ore. Landfill and single-use items increase the need for new metal.'),
    M('Which is a problem caused by mining metal ores?', ['Scarring of the landscape and loss of habitats', 'It increases the amount of ore left', 'It reduces energy use', 'It removes carbon dioxide from the air'], 0, 'Mining creates large quarries and waste heaps, destroys habitats, and uses energy (often releasing CO<sub>2</sub>). It reduces the ore that remains.'),
    M('A graph shows CO<sub>2</sub> levels and global temperature both rising since 1900. What can scientists conclude from this alone?', ['There is a correlation; other evidence is needed to show one causes the other', 'CO<sub>2</sub> definitely does not affect temperature', 'Temperature rise causes all CO<sub>2</sub> emissions', 'The data must be wrong'], 0, 'Two things rising together shows a correlation. Scientists use further evidence (e.g. how CO<sub>2</sub> absorbs infrared, and climate models) to show that rising CO<sub>2</sub> is a cause of warming.'),
    O('Put these steps in order to show how burning fossil fuels leads to global warming.', ['Fossil fuels are burned', 'Carbon dioxide is released into the air', 'More infrared radiation is trapped in the atmosphere', 'Average global temperature rises'], 'Burning releases CO<sub>2</sub>, which increases the greenhouse effect, trapping more heat and raising average temperatures.'),
    M('Which method of reducing climate change captures carbon dioxide and stores it underground?', ['Carbon capture and storage', 'Recycling', 'Composting', 'Fractional distillation'], 0, 'Carbon capture and storage (CCS) traps CO<sub>2</sub> from power stations and stores it in rocks underground so it does not reach the atmosphere.'),
  ] },
], {
  overview: 'The Earth is a layered planet whose rocks are constantly recycled. The thin layer of <b>air</b> around it is a mixture of gases kept in balance by the <b>carbon cycle</b>. Human activities are changing that balance, which links chemistry to climate change and to how we use limited resources.',
  objectives: ['I can describe the structure of the Earth', 'I can explain how igneous, sedimentary and metamorphic rocks form', 'I can state the composition of the air', 'I can describe the carbon cycle', 'I can explain the greenhouse effect and why recycling is important'],
  keyWords: [{ term: 'Crust', def: 'The thin, rocky outer layer of the Earth.' }, { term: 'Igneous rock', def: 'Rock formed when molten rock cools and solidifies.' }, { term: 'Sedimentary rock', def: 'Rock formed from compacted and cemented layers of sediment.' }, { term: 'Metamorphic rock', def: 'Rock changed by heat and pressure without melting.' }, { term: 'Carbon cycle', def: 'The movement of carbon between air, living things, oceans and rocks.' }, { term: 'Greenhouse gas', def: 'A gas that absorbs and re-emits infrared radiation, e.g. CO₂, CH₄, H₂O.' }, { term: 'Finite resource', def: 'A resource that will run out.' }, { term: 'Recycling', def: 'Processing used materials to make new products.' }],
  sections: [
    { title: 'Structure of the Earth', html: `<ul><li><b>Crust</b>: thin solid rock.</li><li><b>Mantle</b>: hot rock that flows very slowly.</li><li><b>Outer core</b>: liquid iron and nickel.</li><li><b>Inner core</b>: solid iron and nickel.</li></ul>` },
    { title: 'The rock cycle', html: `<table class="qt"><tr><th>Rock type</th><th>How it forms</th><th>Examples</th></tr><tr><td>Igneous</td><td>Molten rock cools; slow cooling → big crystals</td><td>Granite, basalt</td></tr><tr><td>Sedimentary</td><td>Weathering → erosion → deposition → compaction/cementation</td><td>Limestone, sandstone</td></tr><tr><td>Metamorphic</td><td>Heat and pressure change existing rock</td><td>Marble, slate</td></tr></table>` },
    { title: 'The air and the carbon cycle', html: `<div class="rule">Dry air ≈ 78% nitrogen, 21% oxygen, 0.9% argon, 0.04% carbon dioxide</div><p>Carbon moves into the air by <b>respiration</b>, <b>combustion</b> and <b>decay</b>, and out by <b>photosynthesis</b> and dissolving in <b>oceans</b>. Carbon is also locked in fossil fuels and limestone.</p>` },
    { title: 'Climate change', html: `<p>Greenhouse gases (CO<sub>2</sub>, methane, water vapour) trap heat. Burning fossil fuels and deforestation increase CO<sub>2</sub>; farming and landfill increase methane. Effects include rising sea levels, extreme weather and changes to habitats.</p>` },
    { title: 'Using resources wisely', html: `<p>Ores and fossil fuels are <b>finite</b>. Recycling saves energy, conserves resources and reduces landfill. The waste hierarchy: reduce → reuse → recycle → dispose.</p>` },
  ],
  mistakes: ['Saying the outer core is solid — it is liquid.', 'Confusing the greenhouse effect with the ozone hole.', 'Thinking oxygen is the main gas in the air — nitrogen is.', 'Saying metamorphic rock forms by melting — melting then cooling makes igneous rock.'],
  examTips: ['When explaining crystal size, link cooling rate to time for crystals to grow.', 'In carbon cycle questions, name the process (respiration, photosynthesis) rather than just "plants" or "animals".', 'Quote approximate percentages of the air — examiners accept ~78% and ~21%.'],
  realLife: 'Many cathedrals are built from limestone, and you can see the effects of chemical weathering by acid rain on their carved stonework.',
});

// =====================================================================
// YEAR 10 — Atomic structure & the periodic table (AQA 4.1)
// =====================================================================
function genRAM(rng) {
  const ISO = [['chlorine', 'Cl', 35, 37], ['copper', 'Cu', 63, 65], ['boron', 'B', 10, 11], ['lithium', 'Li', 6, 7], ['bromine', 'Br', 79, 81], ['gallium', 'Ga', 69, 71], ['silver', 'Ag', 107, 109], ['rubidium', 'Rb', 85, 87]];
  const [name, sym, m1, m2] = pick(rng, ISO);
  const a = ri(rng, 5, 95), b = 100 - a;
  const val = rd((m1 * a + m2 * b) / 100, 2);
  return { type: 'number', q: `A sample of ${name} contains ${a}% <sup>${m1}</sup>${sym} and ${b}% <sup>${m2}</sup>${sym}. Calculate the relative atomic mass of ${name} in this sample. Give your answer to 1 decimal place.`,
    value: val, tol: 0.051, unit: '', answer: `${rd(val, 1)}`,
    steps: ['A<sub>r</sub> = (mass₁ × abundance₁ + mass₂ × abundance₂) ÷ 100', `A<sub>r</sub> = (${m1} × ${a} + ${m2} × ${b}) ÷ 100`, `A<sub>r</sub> = (${m1 * a} + ${m2 * b}) ÷ 100 = ${val}`, `A<sub>r</sub> = ${rd(val, 1)} (1 d.p.)`],
    explain: 'Relative atomic mass is a weighted mean of the isotope masses. The answer must lie between the two isotope masses, closer to the more abundant one.', hint: 'Multiply each mass by its percentage, add, divide by 100.' };
}

topic({ id: 'chem-y10-atomic-structure', strand: 'chem-atomic', year: 10, term: 1, tier: 'FH', name: 'Atomic Structure & the Periodic Table',
  summary: 'Subatomic particles, isotopes, the development of the atomic model, electronic structure and group trends.', specRef: 'AQA 8462 4.1.1–4.1.3' }, [
  { name: 'Protons, neutrons, electrons & isotopes', intro: 'Atoms have a tiny nucleus of protons and neutrons surrounded by electrons. Atomic number = protons; mass number = protons + neutrons. Isotopes have the same protons but different neutrons.', items: [
    M('What is the relative charge of a neutron?', ['0', '+1', '−1', '+2'], 0, 'Proton +1, neutron 0, electron −1.'),
    M('What is the relative mass of an electron?', ['Very small (about 1/2000)', '1', '0 exactly', '2'], 0, 'Protons and neutrons have relative mass 1; electrons are about 1/1840 — usually described as "very small". It is not exactly zero.'),
    M('An atom of sodium is <sup>23</sup><sub>11</sub>Na. How many neutrons does it have?', ['12', '11', '23', '34'], 0, 'Neutrons = mass number − atomic number = 23 − 11 = 12.'),
    N('An atom of aluminium has atomic number 13 and mass number 27. How many neutrons does it have?', 14, 0, '', ['neutrons = mass number − atomic number', '= 27 − 13', '= 14'], 'Atomic number gives protons; the rest of the mass number is neutrons.'),
    M('Why do atoms have no overall charge?', ['They have equal numbers of protons and electrons', 'Neutrons cancel the charges', 'They have equal protons and neutrons', 'Electrons have no charge'], 0, 'Each proton (+1) is balanced by an electron (−1). Neutrons are neutral and do not cancel anything.'),
    S('What name is given to atoms of the same element with different numbers of neutrons?', 'isotopes', ['isotopes', 'isotope'], 'Isotopes have the same atomic number (protons) but different mass numbers.'),
    T('Isotopes of the same element have the same chemical properties.', true, 'True. Chemical properties depend on electrons, and isotopes have the same electron arrangement.'),
    M('What is the approximate radius of an atom?', ['0.1 nm (1 × 10<sup>−10</sup> m)', '1 mm', '1 × 10<sup>−3</sup> m', '100 nm'], 0, 'Atoms are about 0.1 nm across. The nucleus is about 1/10 000 of that radius.'),
    M('How does the radius of the nucleus compare with the radius of the atom?', ['About 1/10 000 of the atom\'s radius', 'About half', 'About the same', 'About 1/10'], 0, 'The nucleus is tiny — about 1 × 10<sup>−14</sup> m — yet contains almost all of the mass.'),
    M('How many electrons are in a <sup>35</sup><sub>17</sub>Cl atom?', ['17', '18', '35', '52'], 0, 'In a neutral atom electrons = protons = atomic number = 17. 18 is the number of neutrons.'),
    X('Which TWO are in the nucleus?', ['Protons', 'Neutrons', 'Electrons', 'Ions', 'Shells'], [0, 1], 'The nucleus contains protons and neutrons. Electrons occupy shells (energy levels) around it.'),
    M('<sup>12</sup>C and <sup>14</sup>C are isotopes. What is different about them?', ['Number of neutrons', 'Number of protons', 'Number of electrons', 'Chemical reactions'], 0, 'Both have 6 protons and 6 electrons; <sup>12</sup>C has 6 neutrons, <sup>14</sup>C has 8.'),
    S('What is the term for the number of protons in an atom?', 'atomic number', ['atomic number', 'proton number'], 'Atomic (proton) number identifies the element and its position in the periodic table.', [['atomic', 'proton'], ['number']]),
    M('A Mg<sup>2+</sup> ion (atomic number 12) has how many electrons?', ['10', '12', '14', '2'], 0, 'Mg loses 2 electrons to form Mg<sup>2+</sup>: 12 − 2 = 10.'),
    M('Which particle has a relative mass of 1 and a charge of +1?', ['Proton', 'Neutron', 'Electron', 'Nucleus'], 0, 'The proton. A neutron also has mass 1 but no charge.'),
    T('The mass number is the number of protons plus electrons.', false, 'False. Mass number = protons + neutrons. Electrons have negligible mass.'),
    M('What is the relative charge of an electron?', ['−1', '+1', '0', '−2'], 0, 'Electrons have a relative charge of −1. Protons are +1 and neutrons are 0 (neutral).'),
    M('How many protons, neutrons and electrons are in an atom of <sup>39</sup><sub>19</sub>K?', ['19 protons, 20 neutrons, 19 electrons', '19 protons, 39 neutrons, 19 electrons', '20 protons, 19 neutrons, 20 electrons', '39 protons, 19 neutrons, 39 electrons'], 0, 'The bottom number (atomic number, 19) gives protons and, in a neutral atom, electrons. Neutrons = mass number − atomic number = 39 − 19 = 20.'),
    N('An atom has 26 protons and 30 neutrons. What is its mass number?', 56, 0, '', ['mass number = protons + neutrons', 'mass number = 26 + 30', 'mass number = 56'], 'Mass number counts the particles in the nucleus. This is iron-56.'),
    M('How many electrons are in an oxide ion, O<sup>2−</sup>? (oxygen atomic number 8)', ['10', '8', '6', '16'], 0, 'An oxygen atom has 8 electrons. A 2− charge means it has gained 2 electrons: 8 + 2 = 10.'),
    M('How many electrons are in an aluminium ion, Al<sup>3+</sup>? (aluminium atomic number 13)', ['10', '13', '16', '3'], 0, 'Al has 13 electrons. A 3+ ion has lost 3 electrons: 13 − 3 = 10. The number of protons (13) does not change.'),
    M('Approximately what is the radius of a nucleus compared with the radius of an atom (about 1 × 10<sup>−10</sup> m)?', ['About 1/10 000 of it', 'About half of it', 'About the same', 'About 10 times larger'], 0, 'The nucleus has a radius of about 1 × 10<sup>−14</sup> m, around 1/10 000 of the atomic radius, so most of an atom is empty space.'),
    M('Where is almost all of the mass of an atom concentrated?', ['In the nucleus', 'In the electron shells', 'Evenly spread through the atom', 'In the space between shells'], 0, 'Protons and neutrons (each relative mass 1) are in the nucleus. Electrons are very light (about 1/2000), so they add almost no mass.'),
    T('All atoms of an element have the same number of protons.', true, 'True. The number of protons (atomic number) defines the element. Change the proton number and you have a different element.'),
    T('Isotopes of an element have different atomic numbers.', false, 'False. Isotopes have the SAME atomic number (same protons) but different mass numbers because they have different numbers of neutrons.'),
    S('What name is given to the total number of protons and neutrons in an atom?', 'mass number', ['mass number', 'nucleon number'], 'Mass number = protons + neutrons. It is the top (larger) number in nuclear notation.'),
    S('What name is given to an atom or group of atoms with an electric charge?', 'ion', ['ion', 'an ion', 'ions'], 'An ion is a charged particle formed when an atom gains or loses electrons.'),
    X('Which TWO statements about <sup>35</sup>Cl and <sup>37</sup>Cl are correct?', ['They both have 17 protons', '<sup>37</sup>Cl has two more neutrons than <sup>35</sup>Cl', '<sup>37</sup>Cl has two more electrons', 'They react differently with sodium', 'They have different atomic numbers'], [0, 1], 'Both are chlorine (17 protons, 17 electrons as atoms). They differ only in neutrons (18 vs 20). Same electrons means same chemical reactions.'),
    M('An atom has 15 protons, 16 neutrons and 15 electrons. Which element is it? (P = 15, S = 16)', ['Phosphorus', 'Sulfur', 'Gallium', 'It cannot be identified'], 0, 'The element is identified by its proton number only. 15 protons = phosphorus. The neutron number (16) is a distractor.'),
    M('Which particle has a relative mass of 1 and no charge?', ['Neutron', 'Proton', 'Electron', 'Ion'], 0, 'The neutron has relative mass 1 and charge 0. The proton has mass 1 but charge +1; the electron has tiny mass and charge −1.'),
    O('Put these in order of size, smallest first.', ['Electron', 'Nucleus', 'Atom', 'Small molecule'], 'An electron is far smaller than a nucleus; the nucleus is about 1/10 000 the radius of the atom; a molecule contains several atoms.'),
  ] },
  { name: 'Development of the atomic model', intro: 'Models of the atom changed as new evidence appeared: Dalton\'s solid spheres, Thomson\'s plum pudding, Rutherford\'s nuclear model, Bohr\'s electron shells and Chadwick\'s neutron.', items: [
    O('Put the models of the atom in the order they were proposed.', ['Solid sphere (Dalton)', 'Plum pudding (Thomson)', 'Nuclear model (Rutherford)', 'Electron shells (Bohr)'], 'Each model replaced the last when new evidence appeared. Chadwick found the neutron later (1932).'),
    M('What did J.J. Thomson discover that led to the plum pudding model?', ['The electron', 'The neutron', 'The nucleus', 'The proton'], 0, 'Discovering the electron showed atoms contained smaller charged particles, so they could not be indivisible spheres.'),
    M('What is the plum pudding model?', ['A ball of positive charge with negative electrons embedded in it', 'A tiny nucleus with orbiting electrons', 'A solid indivisible sphere', 'Electrons in fixed shells'], 0, 'Thomson pictured a sphere of positive charge with electrons scattered through it, like plums in a pudding.'),
    M('In the alpha scattering experiment, most alpha particles passed straight through the gold foil. What did this show?', ['Most of the atom is empty space', 'The atom is solid', 'Atoms have no mass', 'Electrons are positive'], 0, 'If most particles pass straight through, most of the atom must be empty space.'),
    M('A few alpha particles bounced back. What did this show?', ['Mass and positive charge are concentrated in a tiny nucleus', 'Electrons are very heavy', 'The atom is a uniform ball of charge', 'Gold is magnetic'], 0, 'Only a small, dense, positively charged nucleus could repel alpha particles back. This disproved the plum pudding model.'),
    S('Which scientist proposed that electrons orbit the nucleus at specific distances (shells)?', 'Bohr', ['bohr', 'niels bohr'], 'Niels Bohr\'s calculations agreed with experimental observations of light emitted by atoms.'),
    S('Which scientist provided evidence for the neutron?', 'Chadwick', ['chadwick', 'james chadwick'], 'James Chadwick (1932) showed the existence of neutrons, explaining why atomic masses were bigger than the proton count alone.'),
    M('Who carried out the alpha scattering experiment interpretation that led to the nuclear model?', ['Rutherford (with Geiger and Marsden)', 'Dalton', 'Mendeleev', 'Bohr'], 0, 'Geiger and Marsden did the experiment under Rutherford, who interpreted the results as evidence of a nucleus.'),
    T('Scientific models are changed when new experimental evidence does not fit the existing model.', true, 'True. The plum pudding model was replaced because it could not explain alpha particles bouncing back.'),
    T('Dalton\'s model included electrons.', false, 'False. Dalton (early 1800s) thought atoms were tiny solid spheres that could not be divided. Electrons were discovered later by Thomson.'),
    M('Later experiments showed the positive charge of the nucleus is made of smaller particles. What are they?', ['Protons', 'Electrons', 'Neutrons', 'Alpha particles'], 0, 'Each proton carries the same amount of positive charge; this followed Rutherford\'s work.'),
    M('Why was the neutron discovered later than the proton and electron?', ['It has no charge so it is harder to detect', 'It is much smaller', 'It is outside the atom', 'It only exists in gold'], 0, 'Charged particles can be deflected and detected easily; neutral neutrons are not affected by electric fields.'),
    X('Which TWO observations from alpha scattering disproved the plum pudding model?', ['Some alpha particles were deflected by large angles', 'A very few bounced straight back', 'Most went straight through', 'The foil glowed', 'The foil melted'], [0, 1], 'Large deflections and rebounds needed a concentrated positive nucleus. "Most went straight through" was evidence for empty space but did not by itself disprove the plum pudding.'),
    M('What part of the nuclear model did Bohr add?', ['Electrons orbit in fixed energy levels (shells)', 'Neutrons in the nucleus', 'A positive nucleus', 'Atoms are indivisible'], 0, 'Bohr adapted Rutherford\'s model by placing electrons in specific shells.'),
    M('Why was the plum pudding model accepted at first?', ['It explained the evidence available at the time (electrons exist)', 'It was proved by alpha scattering', 'It included the nucleus', 'Rutherford suggested it'], 0, 'A model is accepted while it fits the evidence. Once alpha scattering gave new evidence, it was replaced.'),
    M('What was Dalton\'s model of the atom?', ['Atoms are tiny solid spheres that cannot be divided', 'A ball of positive charge with electrons embedded', 'A tiny nucleus with electrons in shells', 'A cloud of protons only'], 0, 'In the early 1800s Dalton described atoms as tiny, indivisible solid spheres, with each element having its own type of atom.'),
    M('What particles were fired at gold foil in the scattering experiment?', ['Alpha particles', 'Electrons', 'Neutrons', 'Light rays'], 0, 'Geiger and Marsden, working with Rutherford, fired positively charged alpha particles at very thin gold foil.'),
    M('Some alpha particles were deflected by small angles. What did this suggest?', ['The centre of the atom is positively charged and repels alpha particles passing close to it', 'Electrons attract alpha particles strongly', 'The gold foil had holes in it', 'Alpha particles are negative'], 0, 'Alpha particles are positive, so they are repelled when they pass near the concentrated positive charge of the nucleus, changing direction.'),
    M('Why did Thomson\'s discovery of the electron show that Dalton\'s model needed changing?', ['It showed atoms contain smaller particles, so they are not indivisible', 'It showed atoms are positive', 'It proved atoms have a nucleus', 'It showed electrons are in shells'], 0, 'If electrons can be removed from atoms, atoms must have internal structure — they are not indivisible solid spheres.'),
    M('What evidence led Bohr to suggest electrons orbit in fixed shells?', ['His calculations agreed with experimental observations (e.g. light given out by atoms)', 'He saw electrons under a microscope', 'Alpha particles bounced off electrons', 'Dalton had already proved it'], 0, 'Bohr\'s theoretical calculations matched experimental observations, supporting the idea that electrons are at specific distances (energy levels) from the nucleus.'),
    M('Approximately when did Chadwick provide evidence for the neutron?', ['About 20 years after the nuclear model', 'Before Dalton\'s model', 'At the same time as Thomson\'s work', 'In the 21st century'], 0, 'Rutherford\'s nuclear model was proposed in 1911; Chadwick\'s evidence for neutrons came in 1932, about 20 years later.'),
    T('In the nuclear model, most of the atom is empty space.', true, 'True. Most alpha particles passed straight through the foil, showing most of the atom is empty space.'),
    T('The plum pudding model has a dense nucleus at its centre.', false, 'False. The plum pudding model has a ball of spread-out positive charge with electrons embedded in it — there is no nucleus.'),
    T('Rutherford\'s nuclear model was developed because the results of the alpha scattering experiment did not fit the plum pudding model.', true, 'True. The plum pudding model predicted that alpha particles would all pass through with little deflection, but some were deflected strongly — new evidence led to a new model.'),
    S('Which scientist discovered the electron?', 'J.J. Thomson', ['thomson', 'jj thomson', 'j.j. thomson', 'j j thomson', 'joseph thomson', 'joseph john thomson'], 'J.J. Thomson discovered the electron (1897) and suggested the plum pudding model.'),
    S('In the plum pudding model, what was the "pudding" thought to be made of?', 'positive charge', ['positive charge', 'positive', 'a ball of positive charge'], 'The plum pudding model has a ball of positive charge (the pudding) with negative electrons (the plums) scattered through it.', [['positive']]),
    X('Which TWO features does the modern model of the atom include?', ['A tiny, dense, positive nucleus', 'Electrons in shells (energy levels)', 'Atoms as indivisible solid spheres', 'Positive charge spread evenly throughout', 'No neutrons'], [0, 1], 'The modern model combines Rutherford\'s nucleus, Bohr\'s electron shells and Chadwick\'s neutrons. Indivisible spheres (Dalton) and spread-out charge (Thomson) were replaced.'),
    M('Which observation shows that the nucleus contains most of the mass of the atom?', ['A very small number of alpha particles bounced straight back', 'Most alpha particles went straight through', 'Electrons can be removed', 'Gold is a shiny metal'], 0, 'To make a fast, heavy alpha particle bounce back, it must hit something very massive and positive — the nucleus.'),
    M('Why is it important that scientists publish their results so others can repeat them?', ['Others can check the results are reproducible before a new model is accepted', 'So they can be paid', 'So no one else needs to do experiments', 'So the old model is kept'], 0, 'Models are accepted when evidence is repeatable and reproducible by other scientists. Geiger and Marsden\'s results were checked and supported Rutherford\'s model.'),
    O('Put these discoveries in order.', ['Electron discovered', 'Nucleus proposed from alpha scattering', 'Electron shells proposed', 'Neutron evidence found'], 'Thomson (electron, 1897) → Rutherford (nucleus, 1911) → Bohr (shells, 1913) → Chadwick (neutron, 1932).'),
  ] },
  { name: 'Electronic structure & group trends', intro: 'Electrons fill shells in order: 2, 8, 8, … The number of outer electrons gives the group; the number of shells gives the period. This explains the trends in Groups 1, 7 and 0.', items: [
    M('What is the electronic structure of sodium (atomic number 11)?', ['2,8,1', '2,9', '2,8,8,1', '8,2,1'], 0, 'First shell holds 2, second 8; the 11th electron goes into the third shell: 2,8,1.'),
    M('What is the electronic structure of chlorine (atomic number 17)?', ['2,8,7', '2,7,8', '2,8,8,1', '2,15'], 0, '2 + 8 + 7 = 17. Seven outer electrons → Group 7.'),
    S('Write the electronic structure of calcium (atomic number 20).', '2,8,8,2', ['2,8,8,2', '2 8 8 2', '2.8.8.2'], 'For the first 20 elements, shells fill 2, 8, 8 then the next 2: 2,8,8,2. Calcium is in Group 2, Period 4.', null),
    M('An element has electronic structure 2,8,3. Which group and period is it in?', ['Group 3, Period 3', 'Group 2, Period 3', 'Group 3, Period 8', 'Group 13, Period 2'], 0, 'Outer electrons = group (3); number of shells = period (3). This is aluminium.'),
    M('Why does reactivity increase down Group 1?', ['The outer electron is further from the nucleus and more easily lost', 'The atoms gain electrons more easily', 'There are fewer shells', 'The nucleus has fewer protons'], 0, 'More shells → outer electron further away and more shielded → weaker attraction → lost more easily.'),
    M('Why does reactivity decrease down Group 7?', ['It is harder to gain an electron because the outer shell is further from the nucleus', 'It is easier to lose electrons', 'Atoms get smaller', 'They have more outer electrons'], 0, 'Halogens react by gaining one electron. Further down, the outer shell is further from the nucleus, so the attraction for an extra electron is weaker.'),
    M('What are the products when potassium reacts with water?', ['Potassium hydroxide and hydrogen', 'Potassium oxide and hydrogen', 'Potassium hydroxide and oxygen', 'Potassium and water vapour'], 0, '2K + 2H<sub>2</sub>O → 2KOH + H<sub>2</sub>. The hydroxide makes the solution alkaline.'),
    M('Chlorine water is added to potassium bromide solution. What happens?', ['The solution turns orange as bromine is displaced', 'No reaction', 'Bromine displaces chlorine', 'A white precipitate forms'], 0, 'Chlorine is more reactive than bromine, so it displaces it: Cl<sub>2</sub> + 2KBr → 2KCl + Br<sub>2</sub>. Bromine solution is orange.'),
    M('Iodine solution is added to potassium chloride solution. What happens?', ['No reaction', 'Chlorine is displaced', 'The solution turns orange', 'Iodine gas forms'], 0, 'Iodine is less reactive than chlorine, so it cannot displace chloride.'),
    T('Noble gas boiling points increase down Group 0.', true, 'True. Larger atoms have stronger forces between them, so boiling point increases (helium is lowest).'),
    T('Halogens exist as single atoms.', false, 'False. Halogens are diatomic molecules: F<sub>2</sub>, Cl<sub>2</sub>, Br<sub>2</sub>, I<sub>2</sub>.'),
    X('Which TWO are typical properties of transition metals compared with Group 1 metals? (Chemistry only)', ['Higher melting points and densities', 'Form coloured compounds', 'Softer and more reactive with water', 'Form only +1 ions', 'Low densities'], [0, 1], 'Transition metals (Cr, Mn, Fe, Co, Ni, Cu) are harder, denser, have higher melting points, form ions with different charges, coloured compounds and are useful catalysts.'),
    M('Why do Group 1 metals have to be stored under oil?', ['They react quickly with oxygen and water in the air', 'They are very dense', 'They are toxic gases', 'They melt at room temperature'], 0, 'Oil keeps air and moisture away from these very reactive metals.'),
    M('Why are noble gases unreactive?', ['They have stable arrangements of electrons (full outer shells)', 'They are monatomic', 'They are gases', 'They have no neutrons'], 0, 'Full outer shells (helium has 2, others 8) mean they do not easily gain, lose or share electrons.'),
    M('Which property of Group 1 metals increases down the group?', ['Reactivity', 'Melting point', 'Hardness', 'Number of outer electrons'], 0, 'Reactivity increases; melting point decreases; all have one outer electron.'),
    M('Which word equation shows sodium reacting with chlorine?', ['sodium + chlorine → sodium chloride', 'sodium + chlorine → sodium chlorate', 'sodium chloride → sodium + chlorine', 'sodium + chloride → sodium chlorine'], 0, 'Group 1 metals react with halogens to form metal halides (ionic salts) such as sodium chloride.'),
    M('What is the electronic structure of magnesium (atomic number 12)?', ['2,8,2', '2,10', '2,2,8', '8,2,2'], 0, 'Fill shells in order: 2 in the first, 8 in the second, then the remaining 2 in the third: 2,8,2. Magnesium is in Group 2 (2 outer electrons), Period 3 (3 shells).'),
    M('What is the electronic structure of argon (atomic number 18)?', ['2,8,8', '2,8,6,2', '2,16', '8,8,2'], 0, '2 + 8 + 8 = 18. A full outer shell of 8 is why argon is an unreactive noble gas.'),
    M('Element X has electronic structure 2,8,7. Which statement about X is correct?', ['It is in Group 7 and Period 3', 'It is in Group 3 and Period 7', 'It is a noble gas', 'It is a Group 1 metal'], 0, 'The number of outer electrons (7) gives the group; the number of shells (3) gives the period. 2,8,7 is chlorine.'),
    M('Why do elements in the same group have similar chemical properties?', ['They have the same number of electrons in their outer shell', 'They have the same number of shells', 'They have the same mass number', 'They have the same number of neutrons'], 0, 'Chemical reactions involve the outer electrons. Elements in the same group have the same number of outer electrons, so they react similarly.'),
    M('What is the trend in melting point going down Group 1?', ['It decreases', 'It increases', 'It stays the same', 'It increases then decreases'], 0, 'Group 1 metals have lower melting points going down the group (Li ≈ 181 °C, Na ≈ 98 °C, K ≈ 63 °C).'),
    M('What colour is bromine at room temperature?', ['Red-brown liquid', 'Pale green gas', 'Grey-black solid', 'Colourless gas'], 0, 'Bromine is a red-brown liquid (it gives an orange solution). Chlorine is a pale green gas; iodine is a grey-black solid.'),
    M('When sodium reacts with chlorine, what type of compound is formed?', ['An ionic compound, sodium chloride', 'A covalent compound, sodium chlorine', 'An alloy', 'A mixture'], 0, 'Metal + non-metal gives an ionic compound. Sodium loses one electron and chlorine gains one, forming Na<sup>+</sup> and Cl<sup>−</sup> ions in sodium chloride.'),
    T('Group 1 metals react with water to produce a metal hydroxide and hydrogen.', true, 'True. For example: 2Na + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub>. The hydroxide makes the solution alkaline.'),
    T('The halogens become more reactive going down Group 7.', false, 'False. Halogen reactivity DECREASES down the group, because the outer shell is further from the nucleus and it is harder to gain an electron.'),
    T('Helium has only 2 electrons, but it is still unreactive because its outer shell is full.', true, 'True. Helium\'s only shell can hold a maximum of 2 electrons, so it is full and stable, like the other noble gases.'),
    S('Write the electronic structure of nitrogen (atomic number 7).', '2,5', ['2,5', '2 5', '2.5'], 'Nitrogen has 7 electrons: 2 in the first shell and 5 in the second, so 2,5. It is in Group 5, Period 2.'),
    X('Which TWO observations are seen when lithium is added to water?', ['It floats', 'It fizzes steadily', 'It bursts into a lilac flame', 'It sinks and does not react', 'It explodes violently'], [0, 1], 'Lithium is less dense than water so it floats, and it fizzes steadily as hydrogen is produced. A lilac flame is seen with potassium. Lithium reacts least vigorously in Group 1.'),
    M('Bromine water is added to potassium iodide solution. What happens?', ['Bromine displaces iodine; the solution turns brown', 'No reaction', 'Iodine displaces bromine', 'Potassium bromide gas forms'], 0, 'Bromine is more reactive than iodine, so it displaces it: Br<sub>2</sub> + 2KI → 2KBr + I<sub>2</sub>. The iodine formed gives a brown colour.'),
    M('Why does reactivity increase going down Group 1?', ['The outer electron is further from the nucleus, so it is lost more easily', 'The atoms have more outer electrons', 'The nucleus has a smaller charge', 'The atoms are smaller'], 0, 'Going down, there are more shells, so the single outer electron is further from the nucleus and more shielded — it is attracted less strongly and lost more easily.'),
    O('Put these elements in order of the number of electron shells their atoms have, fewest first.', ['Hydrogen', 'Lithium', 'Sodium', 'Potassium'], 'H has 1 shell (period 1), Li 2 shells (period 2), Na 3 shells (period 3), K 4 shells (period 4).'),
  ] },
  { name: 'Relative atomic mass from isotopes', intro: 'The relative atomic mass (A<sub>r</sub>) of an element is the weighted mean mass of its isotopes, taking into account their percentage abundance.', gen: genRAM },
], {
  overview: 'Atoms are made of protons, neutrons and electrons. The model of the atom developed over 100 years as scientists gathered new evidence. The arrangement of electrons explains the layout of the periodic table and the trends in reactivity of Groups 1, 7 and 0.',
  objectives: ['I can give the relative mass and charge of subatomic particles', 'I can work out protons, neutrons and electrons from atomic and mass numbers', 'I can describe how the atomic model changed and why', 'I can write electronic structures for the first 20 elements', 'I can explain trends in Groups 1, 7 and 0', 'I can calculate relative atomic mass from isotope abundances'],
  keyWords: [{ term: 'Atomic number', def: 'Number of protons in an atom.' }, { term: 'Mass number', def: 'Number of protons + neutrons.' }, { term: 'Isotope', def: 'Atoms of the same element with different numbers of neutrons.' }, { term: 'Relative atomic mass (Ar)', def: 'Weighted mean mass of an element\'s isotopes compared with carbon-12.' }, { term: 'Electronic structure', def: 'The arrangement of electrons in shells, e.g. 2,8,1.' }, { term: 'Nuclear model', def: 'A tiny, dense, positive nucleus surrounded by electrons.' }, { term: 'Alkali metals', def: 'Group 1; more reactive down the group.' }, { term: 'Halogens', def: 'Group 7; less reactive down the group; diatomic.' }],
  sections: [
    { title: 'Inside the atom', html: `<table class="qt"><tr><th>Particle</th><th>Relative mass</th><th>Relative charge</th><th>Location</th></tr><tr><td>Proton</td><td>1</td><td>+1</td><td>Nucleus</td></tr><tr><td>Neutron</td><td>1</td><td>0</td><td>Nucleus</td></tr><tr><td>Electron</td><td>Very small</td><td>−1</td><td>Shells</td></tr></table><div class="rule">neutrons = mass number − atomic number</div><p>Atoms are about 0.1 nm in radius; the nucleus is about 1/10 000 of that but holds almost all the mass.</p>` },
    { title: 'Isotopes and relative atomic mass', html: `<p>Isotopes have the same number of protons but different numbers of neutrons, e.g. <sup>35</sup>Cl and <sup>37</sup>Cl.</p><div class="worked"><div class="wq">Chlorine is 75% <sup>35</sup>Cl and 25% <sup>37</sup>Cl. Calculate A<sub>r</sub>.</div><ol><li>A<sub>r</sub> = (35 × 75 + 37 × 25) ÷ 100</li><li>= (2625 + 925) ÷ 100</li><li>= 3550 ÷ 100</li></ol><div class="wa">Answer: 35.5</div></div>` },
    { title: 'How the model of the atom developed', html: `<ol><li><b>Dalton</b>: tiny solid spheres that cannot be divided.</li><li><b>Thomson</b> discovered electrons → <b>plum pudding</b>: ball of positive charge with electrons embedded.</li><li><b>Rutherford</b> (alpha scattering): most alpha particles passed through (mostly empty space); a few bounced back (tiny, dense, positive nucleus) → <b>nuclear model</b>.</li><li><b>Bohr</b>: electrons in fixed shells.</li><li>Protons identified; <b>Chadwick</b> (1932) discovered the neutron.</li></ol>` },
    { title: 'Electronic structure and the periodic table', html: `<p>Shells fill 2, 8, 8 (for the first 20 elements). Group = number of outer electrons; period = number of shells.</p><svg viewBox="0 0 120 120" width="100%" style="max-width:160px"><circle cx="60" cy="60" r="8" fill="#3b6cf6"/><circle cx="60" cy="60" r="22" fill="none" stroke="currentColor"/><circle cx="60" cy="60" r="38" fill="none" stroke="currentColor"/><circle cx="60" cy="60" r="54" fill="none" stroke="currentColor"/><g fill="currentColor"><circle cx="60" cy="38" r="3"/><circle cx="60" cy="82" r="3"/><circle cx="60" cy="22" r="3"/><circle cx="60" cy="98" r="3"/><circle cx="22" cy="60" r="3"/><circle cx="98" cy="60" r="3"/><circle cx="33" cy="33" r="3"/><circle cx="87" cy="33" r="3"/><circle cx="33" cy="87" r="3"/><circle cx="87" cy="87" r="3"/><circle cx="114" cy="60" r="3"/></g><text x="60" y="63" font-size="8" text-anchor="middle" fill="#fff">Na</text></svg><p>Sodium: 2,8,1 → Group 1, Period 3.</p>` },
    { title: 'Group trends', html: `<ul><li><b>Group 1</b>: react with water → metal hydroxide + hydrogen. Reactivity increases down the group because the outer electron is further from the nucleus and more easily lost.</li><li><b>Group 7</b>: diatomic molecules; reactivity decreases down the group because it is harder to gain an electron. A more reactive halogen displaces a less reactive one from a solution of its salt.</li><li><b>Group 0</b>: unreactive, full outer shells; boiling point increases down the group.</li><li><b>Transition metals</b> (chemistry only): high density and melting point, ions with different charges, coloured compounds, catalysts.</li></ul>` },
  ],
  mistakes: ['Saying the mass number counts electrons.', 'Thinking isotopes have different chemical properties.', 'Saying alpha particles bounced back off electrons — they were repelled by the positive nucleus.', 'Explaining Group 7 trend by "losing" electrons — halogens gain electrons.'],
  examTips: ['For "explain the trend" questions use the chain: more shells → outer shell further from nucleus → weaker attraction → electron lost (Group 1) or gained (Group 7) less/more easily.', 'Relative atomic mass answers must lie between the isotope masses — check this.', 'In the alpha scattering question, link each observation to its conclusion.'],
  realLife: 'Carbon-14, a radioactive isotope, is used to date ancient bones and wood up to about 50 000 years old.',
});

// =====================================================================
// YEAR 10 — Bonding, structure & properties (AQA 4.2)
// =====================================================================
topic({ id: 'chem-y10-bonding', strand: 'chem-bonding', year: 10, term: 1, tier: 'FH', name: 'Bonding, Structure & Properties',
  summary: 'Ionic, covalent and metallic bonding and how structure explains melting point, conductivity and uses.', specRef: 'AQA 8462 4.2.1–4.2.4' }, [
  { name: 'Ionic bonding', intro: 'Ionic bonding happens between metals and non-metals. Metal atoms transfer electrons to non-metal atoms, forming oppositely charged ions held in a giant lattice by strong electrostatic forces.', items: [
    M('What happens to electrons when sodium reacts with chlorine?', ['Sodium transfers one electron to chlorine', 'They share a pair of electrons', 'Chlorine transfers an electron to sodium', 'Electrons become delocalised'], 0, 'The metal loses its outer electron; the non-metal gains it. Sharing is covalent bonding; delocalised electrons are metallic bonding.'),
    M('What is the charge on a magnesium ion?', ['2+', '2−', '1+', '6−'], 0, 'Mg (Group 2) loses 2 outer electrons → Mg<sup>2+</sup>.'),
    M('What is the charge on an oxide ion?', ['2−', '2+', '6−', '1−'], 0, 'Oxygen (Group 6) gains 2 electrons to complete its outer shell → O<sup>2−</sup>.'),
    M('What is the formula of magnesium chloride?', ['MgCl<sub>2</sub>', 'MgCl', 'Mg<sub>2</sub>Cl', 'MgCl<sub>3</sub>'], 0, 'Mg<sup>2+</sup> needs two Cl<sup>−</sup> ions to balance its charge.'),
    M('What is the formula of aluminium oxide?', ['Al<sub>2</sub>O<sub>3</sub>', 'AlO', 'Al<sub>3</sub>O<sub>2</sub>', 'AlO<sub>3</sub>'], 0, 'Al<sup>3+</sup> and O<sup>2−</sup>: 2 × (+3) = +6 balances 3 × (−2) = −6.'),
    M('Why does sodium chloride have a high melting point?', ['Lots of energy is needed to overcome strong electrostatic forces between oppositely charged ions', 'Its covalent bonds are strong', 'Its intermolecular forces are strong', 'It contains delocalised electrons'], 0, 'Ionic compounds are giant lattices; every ion is strongly attracted to many oppositely charged neighbours.'),
    M('When does an ionic compound conduct electricity?', ['When molten or dissolved in water', 'When solid', 'Never', 'Only when cold'], 0, 'Ions must be free to move to carry charge. In the solid, ions are fixed in the lattice.'),
    T('Solid sodium chloride conducts electricity because it contains ions.', false, 'False. The ions are present but cannot move in the solid lattice, so it does not conduct. Molten or dissolved, the ions move and carry current.'),
    T('Ions formed by Group 1 and Group 7 elements have the same electronic structure as a noble gas.', true, 'True. Na<sup>+</sup> is 2,8 (like neon); Cl<sup>−</sup> is 2,8,8 (like argon).'),
    S('What name is given to the regular 3D arrangement of ions in an ionic compound?', 'giant ionic lattice', ['giant ionic lattice', 'ionic lattice', 'lattice', 'giant lattice'], 'Ionic compounds form giant lattices with strong electrostatic forces acting in all directions.', [['lattice']]),
    M('What is the electronic structure of a Na<sup>+</sup> ion?', ['2,8', '2,8,1', '2,8,8', '2,7'], 0, 'Sodium 2,8,1 loses its single outer electron → 2,8.'),
    M('What is the formula of potassium sulfide? (K<sup>+</sup>, S<sup>2−</sup>)', ['K<sub>2</sub>S', 'KS', 'KS<sub>2</sub>', 'K<sub>2</sub>S<sub>2</sub>'], 0, 'Two K<sup>+</sup> ions balance one S<sup>2−</sup>.'),
    M('What is a limitation of a dot-and-cross diagram for an ionic compound?', ['It does not show the 3D arrangement of the lattice', 'It does not show electron transfer', 'It shows charges', 'It shows which atom electrons came from'], 0, 'Dot-and-cross diagrams show electron transfer well but not the structure or the relative sizes of ions.'),
    X('Which TWO compounds are ionic?', ['Calcium oxide', 'Potassium bromide', 'Methane', 'Water', 'Carbon dioxide'], [0, 1], 'Metal + non-metal → ionic. Methane, water and CO<sub>2</sub> are non-metal compounds — covalent.'),
    M('What is the formula of calcium hydroxide? (OH<sup>−</sup> ion)', ['Ca(OH)<sub>2</sub>', 'CaOH', 'CaOH<sub>2</sub>', 'Ca<sub>2</sub>OH'], 0, 'Ca<sup>2+</sup> needs two OH<sup>−</sup>. Brackets show two whole hydroxide ions; CaOH<sub>2</sub> would mean one O and two H.'),
    M('Why does a solution of sodium chloride conduct electricity?', ['Its ions are free to move and carry charge', 'Its electrons are delocalised', 'Water molecules carry charge', 'It contains free protons'], 0, 'Dissolving separates the ions so they can move. It is moving ions (not electrons) that carry current in solutions.'),
    M('What is the charge on an ion formed by a Group 2 element?', ['2+', '2−', '6−', '1+'], 0, 'Group 2 atoms have 2 outer electrons, which they lose to form 2+ ions (e.g. Mg<sup>2+</sup>, Ca<sup>2+</sup>).'),
    M('What is the charge on an ion formed by a Group 7 element?', ['1−', '7+', '1+', '7−'], 0, 'Group 7 atoms have 7 outer electrons and gain 1 more to fill the shell, forming 1− ions (e.g. Cl<sup>−</sup>, Br<sup>−</sup>).'),
    M('What is the formula of calcium oxide? (Ca<sup>2+</sup>, O<sup>2−</sup>)', ['CaO', 'Ca<sub>2</sub>O', 'CaO<sub>2</sub>', 'Ca<sub>2</sub>O<sub>2</sub>'], 0, 'The charges +2 and −2 balance in a 1:1 ratio, so the formula is CaO. Formulas are written in the simplest whole-number ratio.'),
    M('What is the formula of sodium oxide? (Na<sup>+</sup>, O<sup>2−</sup>)', ['Na<sub>2</sub>O', 'NaO', 'NaO<sub>2</sub>', 'Na<sub>2</sub>O<sub>2</sub>'], 0, 'Two Na<sup>+</sup> ions (+2 total) balance one O<sup>2−</sup> ion (−2), giving Na<sub>2</sub>O.'),
    M('What holds the ions together in an ionic lattice?', ['Strong electrostatic forces between oppositely charged ions, acting in all directions', 'Shared pairs of electrons', 'Weak intermolecular forces', 'Delocalised electrons'], 0, 'Ionic bonding is the electrostatic attraction between positive and negative ions, acting in all directions in the lattice. Shared pairs are covalent; delocalised electrons are metallic.'),
    M('What is the empirical formula of an ionic compound in which there are 2 aluminium ions for every 3 sulfide ions?', ['Al<sub>2</sub>S<sub>3</sub>', 'Al<sub>3</sub>S<sub>2</sub>', 'AlS', 'Al<sub>2</sub>S'], 0, 'The ratio of ions gives the formula: 2 Al : 3 S → Al<sub>2</sub>S<sub>3</sub>. Check charges: 2 × (+3) = +6 and 3 × (−2) = −6.'),
    T('Ionic compounds have high melting points because a lot of energy is needed to overcome the strong forces between ions.', true, 'True. Many strong electrostatic attractions in the lattice must be overcome, so ionic compounds melt at high temperatures.'),
    T('A chlorine atom becomes a positive ion by losing an electron.', false, 'False. Chlorine (a non-metal) GAINS an electron to become Cl<sup>−</sup>, a negative ion. Metals lose electrons to form positive ions.'),
    T('When molten, an ionic compound conducts electricity because its ions are free to move.', true, 'True. In the solid the ions are fixed. When melted (or dissolved), the ions can move and carry charge.'),
    S('What name is given to a positively charged ion?', 'cation', ['cation', 'cations', 'positive ion'], 'A positive ion is a cation (e.g. Na<sup>+</sup>). A negative ion is an anion (e.g. Cl<sup>−</sup>).'),
    S('What is the formula of the sulfate ion (including its charge)?', 'SO4 2-', ['so4 2-', 'so42-', 'so4-2', 'so4 2', 'so4'], 'The sulfate ion is SO<sub>4</sub><sup>2−</sup>, a group of atoms carrying an overall 2− charge.', [['so4']]),
    X('Which TWO statements describe what happens when magnesium reacts with oxygen?', ['Each magnesium atom loses 2 electrons', 'Each oxygen atom gains 2 electrons', 'Magnesium and oxygen share electrons', 'Oxygen atoms lose electrons', 'Magnesium atoms gain electrons'], [0, 1], 'Magnesium (Group 2) transfers its 2 outer electrons to oxygen (Group 6), forming Mg<sup>2+</sup> and O<sup>2−</sup> ions. Sharing electrons would be covalent bonding.'),
    M('What is the formula of magnesium nitrate? (Mg<sup>2+</sup>, NO<sub>3</sub><sup>−</sup>)', ['Mg(NO<sub>3</sub>)<sub>2</sub>', 'MgNO<sub>3</sub>', 'Mg<sub>2</sub>NO<sub>3</sub>', 'MgNO<sub>6</sub>'], 0, 'Two NO<sub>3</sub><sup>−</sup> ions balance one Mg<sup>2+</sup>. Brackets show the whole nitrate ion is doubled: Mg(NO<sub>3</sub>)<sub>2</sub>.'),
    M('Which is a limitation of a 3D ball-and-stick model of sodium chloride?', ['It shows gaps between ions and the sticks suggest bonds in fixed directions, which is misleading', 'It shows the ions in 3D', 'It shows the ratio of ions', 'It shows the regular pattern'], 0, 'Real ions touch each other and the electrostatic forces act in all directions; sticks wrongly suggest individual bonds. Showing the 3D pattern and ratio are strengths, not limitations.'),
    O('Put these steps in order to describe the formation of lithium fluoride.', ['A lithium atom loses its one outer electron', 'A fluorine atom gains that electron', 'Li<sup>+</sup> and F<sup>−</sup> ions are formed', 'The oppositely charged ions attract to form a giant lattice'], 'Electron transfer from metal to non-metal forms ions, which then attract each other in all directions to form an ionic lattice.'),
  ] },
  { name: 'Covalent bonding & simple molecules', intro: 'Covalent bonds are shared pairs of electrons between non-metal atoms. Simple molecular substances have strong bonds within molecules but weak intermolecular forces between them, so they have low melting and boiling points.', items: [
    M('What is a covalent bond?', ['A shared pair of electrons between two atoms', 'Transfer of electrons from metal to non-metal', 'Attraction between ions', 'Delocalised electrons around positive ions'], 0, 'Covalent bonds form between non-metals sharing electron pairs.'),
    M('How many covalent bonds does carbon form in methane, CH<sub>4</sub>?', ['4', '1', '2', '3'], 0, 'Carbon has 4 outer electrons and shares each with a hydrogen atom → 4 single bonds.'),
    M('How many shared pairs of electrons are in an O<sub>2</sub> molecule?', ['2 (a double bond)', '1', '3', '4'], 0, 'Each oxygen needs 2 more electrons, so they share two pairs: O=O.'),
    M('How many covalent bonds are in a nitrogen molecule, N<sub>2</sub>?', ['A triple bond (3 shared pairs)', 'A single bond', 'A double bond', 'No bonds'], 0, 'Nitrogen needs 3 more electrons, so N≡N has three shared pairs — very strong, making N<sub>2</sub> unreactive.'),
    M('Why does water have a low boiling point compared with sodium chloride?', ['Only weak intermolecular forces must be overcome', 'Its covalent bonds are weak', 'It has no bonds', 'It is a liquid'], 0, 'Boiling water separates molecules (weak intermolecular forces); the strong O–H covalent bonds do not break.'),
    T('When a simple molecular substance boils, its covalent bonds break.', false, 'False — a major misconception. Only the weak forces between molecules are overcome. The molecules stay intact.'),
    T('Simple molecular substances do not conduct electricity.', true, 'True. Molecules have no overall charge and there are no free electrons or ions.'),
    M('Why does the boiling point of alkanes increase as the molecules get bigger?', ['Intermolecular forces are stronger between larger molecules', 'They have more covalent bonds to break', 'They become ionic', 'They have more delocalised electrons'], 0, 'Bigger molecules → stronger intermolecular forces → more energy to separate them.'),
    S('What type of bonding is found between non-metal atoms?', 'covalent', ['covalent', 'covalent bonding', 'covalent bond'], 'Non-metals share electrons to complete their outer shells.'),
    M('How many bonds does a hydrogen atom form?', ['1', '2', '3', '4'], 0, 'Hydrogen has one electron and needs one more to fill its first shell (2), so it forms one bond.'),
    M('Ammonia is NH<sub>3</sub>. How many non-bonding (lone) pairs does nitrogen have?', ['1', '0', '2', '3'], 0, 'N has 5 outer electrons: 3 used in bonds to H, leaving 2 = one lone pair.'),
    X('Which TWO substances are simple molecular?', ['Carbon dioxide', 'Chlorine', 'Diamond', 'Sodium chloride', 'Copper'], [0, 1], 'CO<sub>2</sub> and Cl<sub>2</sub> are small molecules. Diamond is giant covalent; NaCl ionic; Cu metallic.'),
    M('What is a polymer?', ['A very large molecule made of many repeating units joined by covalent bonds', 'A giant ionic lattice', 'A mixture of small molecules', 'A metal alloy'], 0, 'Polymers (like poly(ethene)) are long chains of covalently bonded repeating units. Intermolecular forces between chains are stronger than in small molecules, so they are solid at room temperature.'),
    M('A substance melts at −182 °C and does not conduct electricity. What is its likely structure?', ['Simple molecular', 'Giant ionic', 'Giant covalent', 'Metallic'], 0, 'A very low melting point and no conduction point to small molecules with weak intermolecular forces (this is methane).'),
    M('Which is the strongest: covalent bonds in a chlorine molecule or the forces between chlorine molecules?', ['The covalent bond within the molecule', 'The forces between molecules', 'They are equal', 'Neither exists'], 0, 'Covalent bonds are strong; intermolecular forces are weak. That is why chlorine is a gas but Cl<sub>2</sub> molecules stay intact.'),
    M('How many covalent bonds are in a water molecule, H<sub>2</sub>O?', ['2', '1', '3', '4'], 0, 'Oxygen shares one electron pair with each of the two hydrogen atoms, so there are 2 single covalent bonds.'),
    M('Which molecule contains a double covalent bond?', ['O<sub>2</sub>', 'H<sub>2</sub>', 'Cl<sub>2</sub>', 'HCl'], 0, 'Each oxygen atom needs 2 more electrons, so two oxygen atoms share two pairs — a double bond (O=O). H<sub>2</sub>, Cl<sub>2</sub> and HCl have single bonds.'),
    M('In a carbon dioxide molecule, how is each oxygen joined to the carbon?', ['By a double covalent bond', 'By a single covalent bond', 'By an ionic bond', 'By a triple covalent bond'], 0, 'CO<sub>2</sub> is O=C=O: carbon forms two double bonds, sharing 4 pairs of electrons in total, so all atoms have full outer shells.'),
    M('Why do simple molecular substances not conduct electricity?', ['Their molecules have no overall charge and there are no free electrons or ions', 'Their covalent bonds are weak', 'They are always gases', 'Their electrons are free to move'], 0, 'Molecules are neutral and all electrons are held in bonds or atoms, so nothing charged can move to carry a current.'),
    M('Chlorine (Cl<sub>2</sub>) boils at −34 °C. What is overcome when chlorine boils?', ['The weak intermolecular forces between Cl<sub>2</sub> molecules', 'The covalent bond between the Cl atoms', 'Ionic bonds', 'Metallic bonds'], 0, 'Only the weak forces between molecules are overcome. The Cl–Cl covalent bonds inside each molecule stay intact, so boiled chlorine is still Cl<sub>2</sub>.'),
    M('How many electrons are shared in a single covalent bond?', ['2', '1', '4', '8'], 0, 'A single covalent bond is one shared pair = 2 electrons, one from each atom (in the simple model). A double bond shares 4 electrons.'),
    T('Covalent bonds within molecules are strong.', true, 'True. Covalent bonds are strong; it is the forces BETWEEN simple molecules (intermolecular forces) that are weak.'),
    T('Hydrogen chloride (HCl) is held together by ionic bonding because it contains a halogen.', false, 'False. Hydrogen and chlorine are both non-metals, so they share a pair of electrons — HCl is covalent.'),
    T('Polymer molecules are very large, so the intermolecular forces between them are relatively strong; most polymers are solids at room temperature.', true, 'True. Large molecules have stronger intermolecular forces than small ones, so polymers are usually solids.'),
    S('What is the name for the forces between separate simple molecules?', 'intermolecular forces', ['intermolecular forces', 'intermolecular force', 'intermolecular'], 'Intermolecular forces act between molecules. They are much weaker than the covalent bonds inside molecules.', [['intermolecular']]),
    S('How many covalent bonds does a carbon atom usually form?', '4', ['4', 'four'], 'Carbon has 4 outer electrons and forms 4 covalent bonds to complete its outer shell (e.g. CH<sub>4</sub>).'),
    X('Which TWO properties are typical of simple molecular substances?', ['Low melting and boiling points', 'Do not conduct electricity', 'Conduct electricity when solid', 'Very high melting points', 'Malleable'], [0, 1], 'Weak intermolecular forces give low melting/boiling points, and neutral molecules cannot conduct. High melting points and conductivity suggest giant structures.'),
    M('Which of these is a limitation of a dot-and-cross diagram of a molecule?', ['It does not show the 3D shape of the molecule', 'It shows which atom each electron came from', 'It shows the shared pairs', 'It shows the outer shell electrons'], 0, 'Dot-and-cross diagrams are flat (2D) and do not show the real shape or bond angles. Showing shared pairs and electron origin are strengths.'),
    M('Why is iodine (I<sub>2</sub>) a solid at room temperature but fluorine (F<sub>2</sub>) a gas?', ['I<sub>2</sub> molecules are larger, so the intermolecular forces are stronger', 'I<sub>2</sub> has stronger covalent bonds', 'Iodine is ionic', 'Fluorine has no intermolecular forces'], 0, 'Larger molecules have stronger intermolecular forces, which need more energy to overcome, so melting and boiling points rise down Group 7.'),
    O('Put these substances in order of increasing boiling point.', ['Hydrogen (H<sub>2</sub>)', 'Methane (CH<sub>4</sub>)', 'Water (H<sub>2</sub>O)', 'Sodium chloride (NaCl)'], 'H<sub>2</sub> (−253 °C) and CH<sub>4</sub> (−162 °C) have very weak intermolecular forces; water (100 °C) has stronger ones; NaCl (≈1413 °C) is a giant ionic lattice.'),
  ] },
  { name: 'Giant structures & metals', intro: 'Giant covalent structures (diamond, graphite, silicon dioxide) have very high melting points. Graphene and fullerenes are other forms of carbon. Metals have giant structures of positive ions in a sea of delocalised electrons.', items: [
    M('Why is diamond very hard?', ['Each carbon forms four strong covalent bonds in a rigid giant structure', 'It has delocalised electrons', 'It has weak intermolecular forces', 'It is ionic'], 0, 'Every atom is bonded to four others in a 3D network; breaking it means breaking many strong covalent bonds.'),
    M('Why does graphite conduct electricity?', ['Each carbon forms three bonds, leaving one delocalised electron per atom', 'It contains ions', 'Its layers are held strongly', 'It is a metal'], 0, 'The fourth outer electron of each carbon is delocalised and can move through the layers, carrying charge.'),
    M('Why is graphite soft and slippery?', ['Its layers have no covalent bonds between them and can slide over each other', 'It has weak covalent bonds', 'It is a liquid', 'It is made of small molecules'], 0, 'Within layers bonds are strong; between layers there are only weak forces, so layers slide. Used in pencils and as a lubricant.'),
    S('What name is given to a single layer of graphite?', 'graphene', ['graphene'], 'Graphene is one atom thick, very strong and conducts electricity — useful in electronics and composites.'),
    M('What is the formula of buckminsterfullerene?', ['C<sub>60</sub>', 'C<sub>6</sub>', 'C<sub>12</sub>', 'C<sub>100</sub>'], 0, 'The first fullerene discovered was C<sub>60</sub>, a hollow sphere of carbon atoms in hexagons and pentagons.'),
    M('What is metallic bonding?', ['Attraction between positive metal ions and a sea of delocalised electrons', 'Sharing of electron pairs', 'Transfer of electrons', 'Weak forces between molecules'], 0, 'Metal atoms lose outer electrons, which become delocalised throughout the structure; the electrostatic attraction holds it together.'),
    M('Why do metals conduct electricity?', ['Delocalised electrons can move through the structure', 'Their ions move', 'They have free protons', 'They are shiny'], 0, 'Moving delocalised electrons carry charge (and energy — so metals also conduct heat well).'),
    M('Why are pure metals malleable?', ['Layers of atoms can slide over each other', 'They have weak bonds', 'They contain covalent bonds', 'Their electrons are fixed'], 0, 'In a pure metal, atoms are the same size and in regular layers that slide when a force is applied.'),
    M('Why are alloys harder than pure metals?', ['Different-sized atoms distort the layers so they cannot slide easily', 'Alloys have no delocalised electrons', 'Alloys are ionic', 'Alloys are pure elements'], 0, 'Atoms of a different size disrupt the regular layers, making sliding harder.'),
    T('Silicon dioxide (silica) has a giant covalent structure.', true, 'True. Sand (SiO<sub>2</sub>) is giant covalent, so it has a very high melting point.'),
    T('Diamond conducts electricity because it is a form of carbon.', false, 'False. In diamond all four outer electrons are used in bonds, so there are no delocalised electrons. Graphite conducts; diamond does not.'),
    X('Which TWO are uses of carbon nanotubes?', ['Reinforcing materials such as tennis rackets', 'Electronics', 'Table salt', 'Fertiliser', 'Fuel for cars'], [0, 1], 'Nanotubes are cylindrical fullerenes with high length-to-diameter ratios; they are strong and conduct, so are used in nanotechnology, electronics and composites.'),
    M('Which state symbol describes pure liquid water?', ['(l)', '(aq)', '(g)', '(s)'], 0, '(l) liquid; (aq) is dissolved in water — water cannot be dissolved in itself.'),
    M('What size range do nanoparticles have? (Chemistry only)', ['1–100 nm', '0.1–1 nm', '100–2500 nm', '1–100 μm'], 0, 'Nanoparticles are 1–100 nm (a few hundred atoms). Fine particles (PM2.5) are 100–2500 nm.'),
    M('Why do nanoparticles have different properties from the same material in bulk? (Chemistry only)', ['They have a very high surface area to volume ratio', 'They are made of different atoms', 'They have no mass', 'They are always charged'], 0, 'As side length decreases by 10, surface area to volume ratio increases by 10, so a larger fraction of atoms are on the surface — useful in catalysts and sun creams.'),
    M('A substance has a very high melting point, conducts when solid and is malleable. What is its structure?', ['Metallic', 'Giant ionic', 'Giant covalent', 'Simple molecular'], 0, 'Conducting as a solid + malleable = metal. Ionic compounds do not conduct when solid; giant covalent are hard and brittle (except graphite).'),
    M('How many covalent bonds does each carbon atom form in diamond?', ['4', '3', '2', '1'], 0, 'In diamond every carbon forms 4 strong covalent bonds in a rigid 3D lattice, making it very hard with a very high melting point.'),
    M('How many covalent bonds does each carbon atom form in graphite?', ['3', '4', '2', '1'], 0, 'In graphite each carbon bonds to 3 others in hexagonal layers. The fourth electron is delocalised, which is why graphite conducts.'),
    M('Why does graphite have a very high melting point even though it is soft?', ['Many strong covalent bonds within the layers must be broken to melt it', 'Its layers are held by strong ionic bonds', 'It has strong intermolecular forces', 'Its delocalised electrons are hard to move'], 0, 'Melting graphite means breaking the strong covalent bonds in the layers. Softness comes from the weak forces between layers, which let them slide.'),
    M('Which property makes graphene useful in electronics?', ['It conducts electricity very well', 'It is a good insulator', 'It is soft and slippery', 'It dissolves in water'], 0, 'Graphene is a single layer of graphite: it is very strong and an excellent conductor because of its delocalised electrons.'),
    M('Why are fullerenes such as C<sub>60</sub> described as molecules rather than giant structures?', ['They contain a fixed number of carbon atoms', 'They contain ions', 'They have metallic bonding', 'They are infinite lattices'], 0, 'Fullerenes have a definite number of atoms (e.g. 60) forming hollow cages or tubes, so they are molecules — unlike diamond and graphite, which are giant lattices.'),
    M('Why do metals have high melting points?', ['There are strong electrostatic attractions between positive metal ions and delocalised electrons', 'Metal atoms share pairs of electrons', 'There are weak forces between metal molecules', 'Metals are made of negative ions'], 0, 'Metallic bonding — the attraction between positive ions and the sea of delocalised electrons — is strong, so a lot of energy is needed to melt metals.'),
    T('In an alloy, atoms of different sizes distort the layers so they cannot slide over each other as easily.', true, 'True. The different-sized atoms disrupt the regular layers, which is why alloys are harder than pure metals.'),
    T('Graphite and diamond are made of different elements.', false, 'False. Both are pure carbon. They have different properties because their atoms are arranged and bonded differently.'),
    T('Metals are good conductors of thermal energy because their delocalised electrons can move and carry energy.', true, 'True. Delocalised electrons transfer thermal energy (and electric charge) through the metal.'),
    S('What is the name for the electrons in a metal that are free to move throughout the structure?', 'delocalised electrons', ['delocalised electrons', 'delocalized electrons', 'delocalised', 'delocalized', 'sea of electrons'], 'Delocalised electrons are not attached to any one atom. They explain metal conductivity.', [['delocalised', 'delocalized', 'sea']]),
    S('What name is given to a mixture of a metal with other elements, such as steel?', 'alloy', ['alloy', 'an alloy', 'alloys'], 'An alloy is a mixture of a metal with other elements (usually metals). Alloys are often harder and more useful than pure metals.'),
    X('Which TWO are properties of diamond?', ['Very hard', 'Does not conduct electricity', 'Soft and slippery', 'Conducts electricity', 'Low melting point'], [0, 1], 'Diamond is very hard (rigid 3D covalent lattice) and does not conduct (no delocalised electrons). Softness and conductivity describe graphite.'),
    M('Carbon nanotubes have very high length-to-diameter ratios. Which use does this make them good for?', ['Reinforcing materials such as tennis rackets', 'Making them into soft lubricants', 'Insulating electric cables', 'Making them dissolve quickly'], 0, 'Nanotubes are cylindrical fullerenes with high tensile strength, so they reinforce composite materials. They also conduct electricity.'),
    M('Which substance is a giant covalent structure?', ['Silicon dioxide', 'Sodium chloride', 'Carbon dioxide', 'Copper'], 0, 'Silicon dioxide (sand) is a giant covalent lattice. Sodium chloride is ionic, carbon dioxide is simple molecular, and copper is metallic.'),
    O('Put these in order of the number of carbon atoms in one particle, fewest first.', ['Methane molecule', 'Buckminsterfullerene molecule', 'A piece of graphite'], 'Methane has 1 carbon atom; C<sub>60</sub> has 60; graphite is a giant structure with millions of carbon atoms.'),
  ] },
], {
  overview: 'How atoms are held together decides how a substance behaves. <b>Ionic</b> bonds (metal + non-metal), <b>covalent</b> bonds (non-metals) and <b>metallic</b> bonds give different structures, which explain melting points, electrical conductivity and uses.',
  objectives: ['I can describe ionic bonding and work out ionic formulae', 'I can draw dot-and-cross diagrams for simple molecules', 'I can explain the properties of simple molecular and giant covalent substances', 'I can explain the properties of diamond, graphite, graphene and fullerenes', 'I can describe metallic bonding and explain why alloys are harder', 'I can link structure to properties and state symbols'],
  keyWords: [{ term: 'Ion', def: 'A charged atom or group of atoms formed by losing or gaining electrons.' }, { term: 'Ionic bond', def: 'Electrostatic attraction between oppositely charged ions.' }, { term: 'Covalent bond', def: 'A shared pair of electrons between two atoms.' }, { term: 'Intermolecular forces', def: 'Weak forces between molecules.' }, { term: 'Giant covalent structure', def: 'A huge network of atoms joined by covalent bonds, e.g. diamond.' }, { term: 'Delocalised electrons', def: 'Electrons free to move through a structure.' }, { term: 'Alloy', def: 'A mixture of a metal with other elements.' }, { term: 'Fullerene', def: 'A molecule of carbon atoms in a hollow shape, e.g. C₆₀.' }],
  sections: [
    { title: 'Ionic bonding', html: `<p>Metal atoms lose electrons to become positive ions; non-metal atoms gain electrons to become negative ions. Ions have noble-gas electron structures.</p><div class="rule">Group 1 → +1, Group 2 → +2, Group 6 → −2, Group 7 → −1</div><p>Ionic formulae balance charges: Al<sup>3+</sup> + O<sup>2−</sup> → Al<sub>2</sub>O<sub>3</sub>.</p><p>Ionic compounds: giant lattices, high melting points, conduct only when molten or dissolved.</p>` },
    { title: 'Covalent bonding', html: `<p>Non-metal atoms share pairs of electrons. Single (H–H), double (O=O) and triple (N≡N) bonds.</p><p><b>Simple molecules</b> (H<sub>2</sub>O, CO<sub>2</sub>, CH<sub>4</sub>, NH<sub>3</sub>): strong bonds inside molecules, weak intermolecular forces between them → low melting/boiling points, do not conduct. Bigger molecules → stronger intermolecular forces.</p><div class="note">When water boils, the O–H bonds do NOT break — only the forces between molecules are overcome.</div>` },
    { title: 'Giant covalent structures and carbon', html: `<table class="qt"><tr><th>Form</th><th>Structure</th><th>Properties</th></tr><tr><td>Diamond</td><td>Each C bonded to 4 others</td><td>Very hard, very high mp, does not conduct</td></tr><tr><td>Graphite</td><td>Layers of hexagons; each C bonded to 3; one delocalised electron per C</td><td>Soft, slippery, high mp, conducts</td></tr><tr><td>Graphene</td><td>Single layer of graphite</td><td>Very strong, conducts</td></tr><tr><td>Fullerenes</td><td>Hollow cages/tubes (C<sub>60</sub>, nanotubes)</td><td>Lubricants, drug delivery, catalysts, reinforcement</td></tr></table><p>Silicon dioxide is also giant covalent.</p>` },
    { title: 'Metals and alloys', html: `<p>Metallic bonding: positive ions in a sea of delocalised electrons. Metals have high melting points, conduct heat and electricity, and are malleable (layers slide).</p><p><b>Alloys</b> contain atoms of different sizes, which distort the layers so they cannot slide easily — so alloys are harder.</p>` },
    { title: 'States and nanoparticles', html: `<p>State symbols: (s), (l), (g), (aq). Use melting and boiling points to predict state.</p><p><b>Nanoparticles</b> (chemistry only) are 1–100 nm with huge surface area to volume ratios; used in sun creams, catalysts, medicine. Possible risks to health are not yet fully understood.</p>` },
  ],
  mistakes: ['Saying covalent bonds break when simple molecules melt or boil.', 'Saying ionic solids conduct.', 'Saying graphite conducts because of "free ions" — it is delocalised electrons.', 'Writing CaOH₂ instead of Ca(OH)₂.'],
  examTips: ['For property questions use "structure → bonding → energy needed" logic, e.g. "giant lattice, strong electrostatic forces, lots of energy needed to overcome".', 'Always say WHAT is overcome: intermolecular forces (simple molecules) or bonds (giant structures).', 'In "compare" questions, write a sentence about each substance.'],
  realLife: 'Smartphone screens and next-generation batteries are being developed using graphene because it is strong, flexible and an excellent conductor.',
});

// =====================================================================
// YEAR 10 — Quantitative chemistry (AQA 4.3)
// =====================================================================
const arList = (comp) => Object.keys(comp).map((el) => `${el} = ${AR[el]}`).join(', ');
function genMr(rng) {
  const [f, name, comp] = pick(rng, COMPOUNDS);
  const mr = mrOf(comp);
  return { type: 'number', q: `Calculate the relative formula mass (M<sub>r</sub>) of ${name}, ${f}.<br>Relative atomic masses (A<sub>r</sub>): ${arList(comp)}.`, value: mr, tol: 0.05, unit: '', answer: `${mr}`,
    steps: mrSteps(f, comp), explain: 'M<sub>r</sub> is the sum of the relative atomic masses of all the atoms in the formula. Common errors: forgetting to multiply everything inside a bracket, or adding each element only once.', hint: 'Count every atom, then add up their A<sub>r</sub> values.' };
}
function genConcMass(rng) {
  const v = ri(rng, 0, 2);
  const vol = pick(rng, [25, 50, 100, 200, 250, 400, 500, 750]);
  const solute = pick(rng, ['sodium chloride', 'copper sulfate', 'glucose', 'potassium nitrate', 'sodium hydroxide', 'sugar']);
  if (v === 0) {
    const m = ri(rng, 5, 100) / 10, c = rd(m / (vol / 1000), 2);
    return { type: 'number', q: `${m} g of ${solute} is dissolved in water to make ${vol} cm³ of solution. Calculate the concentration in g/dm³.`, value: c, tol: Math.max(0.01, c * 0.005), unit: 'g/dm³', answer: `${c} g/dm³`,
      steps: ['Convert volume to dm³: divide cm³ by 1000.', `${vol} cm³ = ${vol / 1000} dm³`, 'concentration = mass ÷ volume', `concentration = ${m} ÷ ${vol / 1000} = ${c} g/dm³`], explain: 'Concentration (g/dm³) = mass of solute (g) ÷ volume of solution (dm³). Forgetting to convert cm³ to dm³ gives an answer 1000 times too small.', hint: '1 dm³ = 1000 cm³.' };
  }
  if (v === 1) {
    const c = ri(rng, 4, 120), m = rd(c * vol / 1000, 3);
    return { type: 'number', q: `What mass of ${solute} is needed to make ${vol} cm³ of a ${c} g/dm³ solution?`, value: m, tol: Math.max(0.01, m * 0.005), unit: 'g', answer: `${m} g`,
      steps: [`Volume = ${vol} ÷ 1000 = ${vol / 1000} dm³`, 'mass = concentration × volume', `mass = ${c} × ${vol / 1000} = ${m} g`], explain: 'Rearrange concentration = mass ÷ volume to mass = concentration × volume, with volume in dm³.', hint: 'Rearrange the concentration equation.' };
  }
  const c = ri(rng, 5, 80), m = ri(rng, 1, 40) / 2, volDm = rd(m / c, 4), volCm = rd(volDm * 1000, 1);
  return { type: 'number', q: `A student needs ${m} g of ${solute} and has a solution of concentration ${c} g/dm³. What volume of solution, in cm³, contains this mass?`, value: volCm, tol: Math.max(0.1, volCm * 0.005), unit: 'cm³', answer: `${volCm} cm³`,
    steps: ['volume = mass ÷ concentration', `volume = ${m} ÷ ${c} = ${volDm} dm³`, `Convert to cm³: × 1000 = ${volCm} cm³`], explain: 'volume (dm³) = mass ÷ concentration, then multiply by 1000 for cm³.', hint: 'Find the volume in dm³ first.' };
}
function genMoles(rng) {
  const [f, name, comp] = pick(rng, COMPOUNDS);
  const mr = mrOf(comp);
  const v = ri(rng, 0, 3);
  if (v === 0) {
    const n = ri(rng, 1, 60) / 20, m = rd(n * mr, 2);
    return { type: 'number', q: `How many moles are in ${m} g of ${name}, ${f}? (M<sub>r</sub> = ${mr})`, value: rd(n, 3), tol: 0.005, unit: 'mol', answer: `${rd(n, 3)} mol`,
      steps: ['moles = mass ÷ M<sub>r</sub>', `moles = ${m} ÷ ${mr}`, `moles = ${rd(n, 3)} mol`], explain: 'The number of moles equals the mass in grams divided by the relative formula mass.', hint: 'n = m ÷ M<sub>r</sub>' };
  }
  if (v === 1) {
    const n = ri(rng, 1, 60) / 20, m = rd(n * mr, 2);
    return { type: 'number', q: `What is the mass of ${n} mol of ${name}, ${f}? (A<sub>r</sub>: ${arList(comp)})`, value: m, tol: Math.max(0.01, m * 0.002), unit: 'g', answer: `${m} g`,
      steps: [`M<sub>r</sub> of ${f} = ${mr}`, 'mass = moles × M<sub>r</sub>', `mass = ${n} × ${mr} = ${m} g`], explain: 'Work out M<sub>r</sub> first, then rearrange n = m ÷ M<sub>r</sub> to m = n × M<sub>r</sub>.', hint: 'Find M<sub>r</sub>, then multiply.' };
  }
  if (v === 2) {
    const n = ri(rng, 1, 40) / 20, m = rd(n * mr, 2);
    return { type: 'number', q: `${n} mol of a compound has a mass of ${m} g. Calculate its relative formula mass.`, value: mr, tol: 0.06, unit: '', answer: `${mr}`,
      steps: ['M<sub>r</sub> = mass ÷ moles', `M<sub>r</sub> = ${m} ÷ ${n}`, `M<sub>r</sub> = ${mr}`], explain: `Rearranging n = m ÷ M<sub>r</sub> gives M<sub>r</sub> = m ÷ n. (This compound could be ${name}.)`, hint: 'Rearrange n = m ÷ M<sub>r</sub>.' };
  }
  const vol = pick(rng, [20, 25, 50, 100, 200, 250, 500]), c = ri(rng, 1, 40) / 20, n = rd(c * vol / 1000, 5);
  return { type: 'number', q: `How many moles of ${name} are in ${vol} cm³ of a ${c} mol/dm³ solution?`, value: n, tol: Math.max(0.00005, n * 0.005), unit: 'mol', answer: `${n} mol`,
    steps: [`volume = ${vol} ÷ 1000 = ${vol / 1000} dm³`, 'moles = concentration × volume', `moles = ${c} × ${vol / 1000} = ${n} mol`], explain: 'For solutions: moles = concentration (mol/dm³) × volume (dm³). Always convert cm³ to dm³ first.', hint: 'Convert cm³ to dm³.' };
}
const REACTIONS = [
  ['2Mg + O<sub>2</sub> → 2MgO', 'magnesium', 24, 2, 'magnesium oxide', 40, 2],
  ['CaCO<sub>3</sub> → CaO + CO<sub>2</sub>', 'calcium carbonate', 100, 1, 'calcium oxide', 56, 1],
  ['Fe<sub>2</sub>O<sub>3</sub> + 3CO → 2Fe + 3CO<sub>2</sub>', 'iron(III) oxide', 160, 1, 'iron', 56, 2],
  ['2Na + Cl<sub>2</sub> → 2NaCl', 'sodium', 23, 2, 'sodium chloride', 58.5, 2],
  ['CuO + H<sub>2</sub> → Cu + H<sub>2</sub>O', 'copper oxide', 79.5, 1, 'copper', 63.5, 1],
  ['2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O', 'hydrogen', 2, 2, 'water', 18, 2],
  ['C + O<sub>2</sub> → CO<sub>2</sub>', 'carbon', 12, 1, 'carbon dioxide', 44, 1],
  ['4Al + 3O<sub>2</sub> → 2Al<sub>2</sub>O<sub>3</sub>', 'aluminium', 27, 4, 'aluminium oxide', 102, 2],
  ['N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>', 'nitrogen', 28, 1, 'ammonia', 17, 2],
  ['CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O', 'methane', 16, 1, 'water', 18, 2],
  ['2NaOH + H<sub>2</sub>SO<sub>4</sub> → Na<sub>2</sub>SO<sub>4</sub> + 2H<sub>2</sub>O', 'sodium hydroxide', 40, 2, 'sodium sulfate', 142, 1],
  ['Zn + 2HCl → ZnCl<sub>2</sub> + H<sub>2</sub>', 'zinc', 65, 1, 'zinc chloride', 136, 1],
];
function genReactingMass(rng) {
  const [eq, rName, rMr, rCo, pName, pMr, pCo] = pick(rng, REACTIONS);
  const nR = ri(rng, 1, 40) / 10, mR = rd(nR * rMr, 2), nP = rd(nR * pCo / rCo, 4), mP = rd(nP * pMr, 2);
  return { type: 'number', q: `${eq}<br>Calculate the maximum mass of ${pName} that can be made from ${mR} g of ${rName}. (M<sub>r</sub>: ${rName} = ${rMr}, ${pName} = ${pMr})`, value: mP, tol: Math.max(0.05, mP * 0.005), unit: 'g', answer: `${mP} g`,
    steps: [`moles of ${rName} = ${mR} ÷ ${rMr} = ${nR} mol`, `Mole ratio ${rName} : ${pName} = ${rCo} : ${pCo}`, `moles of ${pName} = ${nR} × ${pCo} ÷ ${rCo} = ${nP} mol`, `mass of ${pName} = ${nP} × ${pMr} = ${mP} g`],
    explain: 'Mass → moles (÷ M<sub>r</sub>), use the balanced equation ratio, then moles → mass (× M<sub>r</sub>). A common mistake is to ignore the numbers in front of the formulae.', hint: 'Use the balancing numbers for the mole ratio.' };
}

topic({ id: 'chem-y10-quantitative', strand: 'chem-quant', year: 10, term: 2, tier: 'FH', name: 'Quantitative Chemistry: Mass, Moles & Concentration',
  summary: 'Calculate relative formula mass, concentration in g/dm³ and, at Higher tier, moles and reacting masses.', specRef: 'AQA 8462 4.3.1–4.3.2, 4.3.4' }, [
  { name: 'Relative formula mass (M<sub>r</sub>)', intro: 'The relative formula mass of a compound is the sum of the relative atomic masses of the atoms in its formula.', gen: genMr },
  { name: 'Concentration in g/dm³', intro: 'Concentration = mass of solute (g) ÷ volume of solution (dm³). Remember 1 dm³ = 1000 cm³.', gen: genConcMass },
  { name: 'Moles (Higher)', intro: 'HT only. One mole of a substance has a mass in grams equal to its M<sub>r</sub> and contains 6.02 × 10<sup>23</sup> particles. moles = mass ÷ M<sub>r</sub>; for solutions moles = concentration (mol/dm³) × volume (dm³).', gen: genMoles },
  { name: 'Reacting masses (Higher)', intro: 'HT only. Use moles and the balanced equation to calculate the mass of product formed or reactant needed.', gen: genReactingMass },
  { name: 'Mole concepts, limiting reactants & mass changes', intro: 'Conservation of mass, apparent mass changes, the Avogadro constant, limiting reactants and uncertainty in measurements.', items: [
    M('What is the value of the Avogadro constant?', ['6.02 × 10<sup>23</sup> per mole', '6.02 × 10<sup>−23</sup> per mole', '1.66 × 10<sup>23</sup> per mole', '12 per mole'], 0, 'One mole of any substance contains 6.02 × 10<sup>23</sup> particles (atoms, molecules or ions).'),
    M('Which contains the most atoms?', ['1 mol of CH<sub>4</sub>', '1 mol of He', '1 mol of O<sub>2</sub>', '1 mol of Ne'], 0, 'Each mole has 6.02 × 10<sup>23</sup> molecules. CH<sub>4</sub> has 5 atoms per molecule, so it has the most atoms (5 × 6.02 × 10<sup>23</sup>).'),
    M('What is a limiting reactant?', ['The reactant that is completely used up and limits the amount of product', 'The reactant in excess', 'A catalyst', 'The product with the smallest mass'], 0, 'Once the limiting reactant runs out, the reaction stops. The other reactant is in excess.'),
    M('2 mol of H<sub>2</sub> reacts with 2 mol of O<sub>2</sub> (2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O). Which is limiting?', ['Hydrogen', 'Oxygen', 'Neither', 'Water'], 0, '2 mol H<sub>2</sub> needs only 1 mol O<sub>2</sub>. Hydrogen runs out first, leaving 1 mol O<sub>2</sub> in excess.'),
    N('How many moles of water form when 2 mol of H<sub>2</sub> react completely with excess oxygen? (2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O)', 2, 0, 'mol', ['Ratio H<sub>2</sub> : H<sub>2</sub>O = 2 : 2 = 1 : 1', 'moles of water = 2 mol'], 'Use the balancing numbers for the mole ratio.'),
    T('One mole of carbon atoms has a mass of 12 g.', true, 'True. The mass of one mole in grams equals the relative atomic (or formula) mass.'),
    T('When a metal carbonate is heated in an open tube, the mass of solid decreases because atoms are destroyed.', false, 'False. Carbon dioxide gas escapes; total mass of all products equals the mass of reactant.'),
    M('Magnesium is heated in a crucible and its mass increases. Why?', ['Oxygen from the air has combined with it', 'Magnesium atoms got heavier', 'The crucible gained mass', 'Heat has mass'], 0, 'The product magnesium oxide includes oxygen atoms from the air that were not weighed at the start.'),
    M('A balance reads to ±0.01 g. Five readings of a mass are 2.35, 2.37, 2.36, 2.34, 2.38 g. What is the mean?', ['2.36 g', '2.37 g', '2.35 g', '11.80 g'], 0, 'Mean = (2.35 + 2.37 + 2.36 + 2.34 + 2.38) ÷ 5 = 11.80 ÷ 5 = 2.36 g.'),
    M('For the readings 2.35, 2.37, 2.36, 2.34, 2.38 g, what is the uncertainty in the mean (half the range)?', ['± 0.02 g', '± 0.04 g', '± 0.01 g', '± 0.36 g'], 0, 'Range = 2.38 − 2.34 = 0.04 g; uncertainty ≈ half the range = ±0.02 g.'),
    M('Which unit is used for concentration measured in moles? (HT)', ['mol/dm³', 'g/cm³', 'g/mol', 'dm³/mol'], 0, 'Concentration in moles is mol/dm³; mass concentration is g/dm³.'),
    S('What word describes the reactant that is NOT completely used up?', 'in excess', ['excess', 'in excess'], 'A reactant in excess is left over when the limiting reactant has run out.', [['excess']]),
    M('A solution of 0.1 mol/dm³ NaOH has what mass concentration? (M<sub>r</sub> NaOH = 40) (HT)', ['4 g/dm³', '0.4 g/dm³', '40 g/dm³', '400 g/dm³'], 0, 'g/dm³ = mol/dm³ × M<sub>r</sub> = 0.1 × 40 = 4 g/dm³.'),
    M('What volume does one mole of any gas occupy at room temperature and pressure? (Chemistry only, HT)', ['24 dm³', '22.4 cm³', '1 dm³', '6.02 dm³'], 0, 'At RTP one mole of any gas occupies 24 dm³ (24 000 cm³).'),
    N('What volume of gas (in dm³) is 0.5 mol of CO<sub>2</sub> at room temperature and pressure? (Chemistry only, HT)', 12, 0.01, 'dm³', ['volume = moles × 24', '= 0.5 × 24', '= 12 dm³'], 'Volume at RTP = moles × 24 dm³.'),
    M('Why does increasing the amount of the limiting reactant increase the amount of product?', ['More of it can react before it runs out', 'It speeds up the reaction only', 'It makes the excess reactant limiting immediately', 'It does not change the product'], 0, 'The amount of product is proportional to the amount of limiting reactant (until the other reactant becomes limiting).'),
    M('What does the law of conservation of mass state?', ['No atoms are lost or made in a reaction, so the mass of products equals the mass of reactants', 'Mass always increases in a reaction', 'Mass is converted into energy in reactions', 'Only gases conserve mass'], 0, 'In a chemical reaction atoms are only rearranged, so total mass stays the same. If mass seems to change, a gas has usually entered or left an open container.'),
    M('Hydrochloric acid reacts with marble chips in an open flask on a balance. Why does the reading go down?', ['Carbon dioxide gas escapes from the flask', 'The marble chips are destroyed', 'The acid evaporates completely', 'Mass is turned into heat'], 0, 'CaCO<sub>3</sub> + 2HCl → CaCl<sub>2</sub> + H<sub>2</sub>O + CO<sub>2</sub>. The CO<sub>2</sub> leaves the open flask, so the measured mass falls, but no atoms are destroyed.'),
    M('HT: How many moles are in 22 g of carbon dioxide? (M<sub>r</sub> CO<sub>2</sub> = 44)', ['0.5 mol', '2 mol', '968 mol', '22 mol'], 0, 'moles = mass ÷ M<sub>r</sub> = 22 ÷ 44 = 0.5 mol. Multiplying (22 × 44) is a common error.'),
    N('HT: What is the mass of 3 mol of water? (M<sub>r</sub> H<sub>2</sub>O = 18)', 54, 0.01, 'g', ['mass = moles × M<sub>r</sub>', 'mass = 3 × 18', 'mass = 54 g'], 'Rearrange moles = mass ÷ M<sub>r</sub> to mass = moles × M<sub>r</sub>.'),
    M('HT: How many molecules are in 2 mol of oxygen gas, O<sub>2</sub>?', ['1.204 × 10<sup>24</sup>', '6.02 × 10<sup>23</sup>', '3.01 × 10<sup>23</sup>', '2.408 × 10<sup>24</sup>'], 0, 'Number of molecules = moles × Avogadro constant = 2 × 6.02 × 10<sup>23</sup> = 1.204 × 10<sup>24</sup>. (2.408 × 10<sup>24</sup> would be the number of oxygen ATOMS.)'),
    M('HT: In Mg + 2HCl → MgCl<sub>2</sub> + H<sub>2</sub>, 0.1 mol of Mg is added to 0.1 mol of HCl. Which is the limiting reactant?', ['HCl', 'Mg', 'Neither — they are in the correct ratio', 'H<sub>2</sub>'], 0, '0.1 mol Mg needs 2 × 0.1 = 0.2 mol HCl. Only 0.1 mol HCl is present, so HCl runs out first and is limiting; some magnesium is left over.'),
    N('HT: Calcium carbonate decomposes: CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. How many moles of CaO form from 0.25 mol of CaCO<sub>3</sub>?', 0.25, 0.001, 'mol', ['Use the ratio from the balanced equation', 'CaCO<sub>3</sub> : CaO = 1 : 1', 'moles of CaO = 0.25 mol'], 'The equation shows 1 mol of CaCO<sub>3</sub> makes 1 mol of CaO, so the moles are the same.'),
    N('HT: Calculate the concentration in mol/dm³ when 0.2 mol of NaCl is dissolved to make 500 cm³ of solution.', 0.4, 0.001, 'mol/dm³', ['Convert volume: 500 cm³ = 0.5 dm³', 'concentration = moles ÷ volume', '0.2 ÷ 0.5 = 0.4 mol/dm³'], 'Always convert cm³ to dm³ (divide by 1000) before calculating concentration in mol/dm³.'),
    T('HT: The mass of one mole of a substance in grams equals its relative formula mass.', true, 'True. For example, M<sub>r</sub> of NaCl is 58.5, so one mole of NaCl has a mass of 58.5 g.'),
    T('A reaction in a sealed container shows no change in mass, even if a gas is produced.', true, 'True. In a closed system nothing can enter or leave, so the total mass stays constant.'),
    S('What is the name for the amount of a substance containing 6.02 × 10<sup>23</sup> particles?', 'mole', ['mole', 'a mole', 'one mole', 'mol'], 'One mole contains the Avogadro constant number of particles, 6.02 × 10<sup>23</sup>.'),
    X('HT: Which TWO samples contain one mole of particles?', ['12 g of carbon atoms', '18 g of water molecules', '1 g of oxygen molecules', '35.5 g of chlorine molecules (Cl<sub>2</sub>)', '44 g of sodium atoms'], [0, 1], 'One mole has a mass equal to A<sub>r</sub> or M<sub>r</sub> in grams: C = 12 g, H<sub>2</sub>O = 18 g. O<sub>2</sub> is 32 g, Cl<sub>2</sub> is 71 g and Na is 23 g per mole.'),
    M('A student repeats a measurement and the results are very close together. Which word describes the results?', ['Precise', 'Accurate', 'Anomalous', 'Valid'], 0, 'Precise means repeat readings are close to each other (small spread). Accurate means close to the true value — results can be precise but still inaccurate.'),
    M('HT: 4.8 g of magnesium (A<sub>r</sub> 24) reacts with excess oxygen: 2Mg + O<sub>2</sub> → 2MgO. What mass of MgO forms? (M<sub>r</sub> MgO = 40)', ['8.0 g', '4.8 g', '16.0 g', '4.0 g'], 0, 'Moles Mg = 4.8 ÷ 24 = 0.2 mol. Ratio Mg : MgO = 2 : 2 = 1 : 1, so 0.2 mol MgO. Mass = 0.2 × 40 = 8.0 g.'),
  ] },
], {
  overview: 'Chemists need to know how much of each substance reacts and how much product forms. This topic covers <b>relative formula mass</b>, <b>conservation of mass</b>, <b>concentration</b> and — at Higher tier — the <b>mole</b> and reacting-mass calculations.',
  objectives: ['I can calculate M<sub>r</sub> from a formula', 'I can explain apparent mass changes using conservation of mass', 'I can calculate concentration in g/dm³', 'HT: I can convert between mass, moles and M<sub>r</sub>', 'HT: I can calculate reacting masses and identify limiting reactants', 'I can estimate uncertainty from a range of results'],
  keyWords: [{ term: 'Relative formula mass (Mr)', def: 'Sum of the relative atomic masses of all atoms in a formula.' }, { term: 'Mole', def: 'Amount of substance containing 6.02 × 10²³ particles; mass in g = Mr.' }, { term: 'Avogadro constant', def: '6.02 × 10²³ per mole.' }, { term: 'Concentration', def: 'Amount of solute per volume of solution (g/dm³ or mol/dm³).' }, { term: 'Limiting reactant', def: 'The reactant that is used up first.' }, { term: 'Excess', def: 'More of a reactant than is needed.' }, { term: 'Uncertainty', def: 'The range within which the true value is likely to lie.' }],
  sections: [
    { title: 'Relative formula mass', html: `<div class="worked"><div class="wq">Calculate M<sub>r</sub> of Ca(OH)<sub>2</sub>. (Ca = 40, O = 16, H = 1)</div><ol><li>Atoms: 1 Ca, 2 O, 2 H</li><li>40 + (2 × 16) + (2 × 1)</li></ol><div class="wa">Answer: 74</div></div><p>In a balanced equation, the sum of M<sub>r</sub> of reactants = sum of M<sub>r</sub> of products (using the balancing numbers).</p>` },
    { title: 'Concentration', html: `<div class="rule">concentration (g/dm³) = mass (g) ÷ volume (dm³)<br>1 dm³ = 1000 cm³</div><div class="worked"><div class="wq">5 g of salt in 250 cm³ of solution. Concentration?</div><ol><li>250 cm³ = 0.25 dm³</li><li>5 ÷ 0.25</li></ol><div class="wa">Answer: 20 g/dm³</div></div>` },
    { title: 'Moles (Higher)', html: `<div class="rule">moles = mass ÷ M<sub>r</sub><br>moles = concentration (mol/dm³) × volume (dm³)</div><p>1 mol contains 6.02 × 10<sup>23</sup> particles. Chemistry only: 1 mol of any gas occupies 24 dm³ at RTP.</p><div class="worked"><div class="wq">How many moles in 22 g of CO<sub>2</sub>? (M<sub>r</sub> = 44)</div><ol><li>n = 22 ÷ 44</li></ol><div class="wa">Answer: 0.5 mol</div></div>` },
    { title: 'Reacting masses (Higher)', html: `<div class="worked"><div class="wq">2Mg + O<sub>2</sub> → 2MgO. What mass of MgO forms from 6 g of Mg? (Mg = 24, MgO = 40)</div><ol><li>moles Mg = 6 ÷ 24 = 0.25 mol</li><li>Ratio Mg : MgO = 2 : 2, so 0.25 mol MgO</li><li>mass = 0.25 × 40</li></ol><div class="wa">Answer: 10 g</div></div><p>The <b>limiting reactant</b> is used up first; the other is in <b>excess</b>. Product depends on the limiting reactant.</p>` },
    { title: 'Mass changes and uncertainty', html: `<p>In open systems mass can seem to change: it <b>decreases</b> if a gas product escapes and <b>increases</b> if a gas from the air (usually oxygen) reacts.</p><p>Uncertainty ≈ ± half the range of repeat results.</p>` },
  ],
  mistakes: ['Forgetting to multiply atoms inside brackets when calculating Mr.', 'Using cm³ instead of dm³ in concentration calculations.', 'Ignoring the balancing numbers when using mole ratios.', 'Giving Mr a unit — it has none (molar mass has g/mol).'],
  examTips: ['Show every step: marks are given for the method even if the final answer is wrong.', 'Check that the answer is sensible (e.g. a product mass of 0.002 g from 20 g of reactant suggests an error).', 'Give answers to the number of significant figures asked for.'],
  realLife: 'Pharmacists use concentration calculations every day to make sure each dose of a liquid medicine contains exactly the right mass of drug.',
});

