// =====================================================================
// YEAR 10 — Energy changes (AQA 4.5)
// =====================================================================
const BOND = { 'H–H': 436, 'Cl–Cl': 242, 'H–Cl': 431, 'Br–Br': 193, 'H–Br': 366, 'O=O': 498, 'O–H': 464, 'C–H': 413, 'C=O': 805, 'N≡N': 945, 'N–H': 391, 'C=C': 612, 'C–C': 347, 'I–I': 151, 'H–I': 299 };
const BOND_RX = [
  ['H<sub>2</sub> + Cl<sub>2</sub> → 2HCl', { 'H–H': 1, 'Cl–Cl': 1 }, { 'H–Cl': 2 }],
  ['H<sub>2</sub> + Br<sub>2</sub> → 2HBr', { 'H–H': 1, 'Br–Br': 1 }, { 'H–Br': 2 }],
  ['H<sub>2</sub> + I<sub>2</sub> → 2HI', { 'H–H': 1, 'I–I': 1 }, { 'H–I': 2 }],
  ['2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O', { 'H–H': 2, 'O=O': 1 }, { 'O–H': 4 }],
  ['CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O', { 'C–H': 4, 'O=O': 2 }, { 'C=O': 2, 'O–H': 4 }],
  ['N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>', { 'N≡N': 1, 'H–H': 3 }, { 'N–H': 6 }],
  ['C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub>', { 'C=C': 1, 'C–H': 4, 'H–H': 1 }, { 'C–C': 1, 'C–H': 6 }],
  ['2HCl → H<sub>2</sub> + Cl<sub>2</sub>', { 'H–Cl': 2 }, { 'H–H': 1, 'Cl–Cl': 1 }],
  ['2NH<sub>3</sub> → N<sub>2</sub> + 3H<sub>2</sub>', { 'N–H': 6 }, { 'N≡N': 1, 'H–H': 3 }],
];
function genBondEnergy(rng) {
  const [eq, broken, made] = pick(rng, BOND_RX);
  const e = {};
  for (const b of new Set([...Object.keys(broken), ...Object.keys(made)])) e[b] = BOND[b] + ri(rng, -6, 6);
  const sum = (o) => Object.entries(o).reduce((s, [b, n]) => s + e[b] * n, 0);
  const inE = sum(broken), outE = sum(made), dH = inE - outE;
  const rows = Object.keys(e).map((b) => `<tr><td>${b}</td><td>${e[b]}</td></tr>`).join('');
  const terms = (o) => Object.entries(o).map(([b, n]) => `${n} × ${b} (${n} × ${e[b]})`).join(' + ');
  return { type: 'number', q: `Use the bond energies to calculate the overall energy change for:<br>${eq}<br><table class="qt"><tr><th>Bond</th><th>Bond energy (kJ/mol)</th></tr>${rows}</table>Give your answer in kJ/mol, with a sign.`,
    value: dH, tol: 0.5, unit: 'kJ/mol', answer: `${dH} kJ/mol`,
    steps: [`Energy to break bonds (reactants) = ${terms(broken)} = ${inE} kJ/mol`, `Energy released making bonds (products) = ${terms(made)} = ${outE} kJ/mol`, 'Energy change = energy in (breaking) − energy out (making)', `= ${inE} − ${outE} = ${dH} kJ/mol`, dH < 0 ? 'Negative, so the reaction is exothermic.' : 'Positive, so the reaction is endothermic.'],
    explain: 'Breaking bonds takes in energy; making bonds releases energy. If more energy is released making bonds than is used breaking them, the overall change is negative (exothermic). Draw the displayed formulae to count every bond — including bonds that appear on both sides.', hint: 'Break − make.' };
}

topic({ id: 'chem-y10-energy', strand: 'chem-energy', year: 10, term: 3, tier: 'FH', name: 'Energy Changes',
  summary: 'Exothermic and endothermic reactions, reaction profiles, the temperature-change practical, bond energies (HT) and chemical cells.', specRef: 'AQA 8462 4.5.1–4.5.2' }, [
  { name: 'Exothermic, endothermic & reaction profiles', intro: 'Exothermic reactions transfer energy to the surroundings (temperature rises); endothermic reactions take energy in (temperature falls). Reaction profiles show the energy of reactants and products and the activation energy.', items: [
    M('In an exothermic reaction, what happens to the temperature of the surroundings?', ['It increases', 'It decreases', 'It stays the same', 'It drops then rises'], 0, 'Energy is transferred from the reacting chemicals to the surroundings, so they warm up.'),
    X('Which TWO are exothermic?', ['Combustion', 'Neutralisation', 'Thermal decomposition', 'Citric acid + sodium hydrogencarbonate', 'Photosynthesis'], [0, 1], 'Combustion, neutralisation and most oxidation reactions are exothermic. Thermal decomposition, citric acid + sodium hydrogencarbonate and photosynthesis are endothermic.'),
    M('Which is a use of an endothermic reaction?', ['Sports injury cold packs', 'Hand warmers', 'Self-heating cans', 'Fireworks'], 0, 'Cold packs take in energy from the surroundings so they feel cold. The others use exothermic reactions.'),
    M('What is activation energy?', ['The minimum energy particles need to react when they collide', 'The energy given out by a reaction', 'The energy stored in products', 'The total energy of reactants'], 0, 'Activation energy is the energy barrier on the reaction profile; collisions with less energy than this do not lead to a reaction.'),
    M('On a reaction profile for an exothermic reaction, where are the products?', ['Lower in energy than the reactants', 'Higher than the reactants', 'At the same level', 'At the top of the curve'], 0, 'Energy has been released, so products have less energy than reactants.'),
    M('On a reaction profile for an endothermic reaction, the overall energy change is…', ['Positive — products are higher than reactants', 'Negative — products are lower', 'Zero', 'Equal to the activation energy'], 0, 'Endothermic: energy taken in, so the products are higher and ΔH is positive.'),
    T('Energy is conserved in chemical reactions.', true, 'True. Energy is transferred between the chemicals and surroundings, never created or destroyed.'),
    T('Breaking chemical bonds releases energy.', false, 'False — a common misconception. Breaking bonds REQUIRES energy (endothermic process). Making bonds releases energy.'),
    S('What word describes a reaction that takes in energy from the surroundings?', 'endothermic', ['endothermic'], 'Endo = in. The temperature of the surroundings decreases.'),
    M('HT: A reaction is exothermic because…', ['More energy is released making new bonds than is needed to break existing bonds', 'More energy is needed to break bonds than is released making them', 'No bonds are broken', 'Only bonds are broken'], 0, 'Overall change = bonds broken − bonds made; negative when making bonds releases more.'),
    M('What is the sign of ΔH for an exothermic reaction?', ['Negative', 'Positive', 'Zero', 'It can be either'], 0, 'Exothermic reactions lose energy to the surroundings, so ΔH is negative.'),
    M('Which feature on a reaction profile shows the activation energy?', ['The difference from the reactants\' energy up to the peak', 'The difference between reactants and products', 'The energy of the products', 'The horizontal axis'], 0, 'Activation energy is measured from the reactant level up to the top of the hump.'),
    M('A catalyst affects a reaction profile by…', ['Lowering the activation energy', 'Raising the products\' energy', 'Changing the overall energy change', 'Making it endothermic'], 0, 'A catalyst provides an alternative pathway with lower activation energy; the energies of reactants and products are unchanged.'),
    M('Dissolving ammonium nitrate in water makes the beaker feel cold. This is…', ['Endothermic', 'Exothermic', 'Neither', 'Combustion'], 0, 'The temperature fell, so energy was taken in from the surroundings.'),
    O('Put the parts of an exothermic reaction profile in order from left to right.', ['Reactants energy level', 'Rise to the peak (activation energy)', 'Fall from the peak', 'Products at a lower energy level'], 'Reactants must overcome the activation energy before products form at a lower energy.'),
    M('Which of these is an endothermic reaction?', ['Thermal decomposition of calcium carbonate', 'Combustion of methane', 'Neutralisation of HCl by NaOH', 'Magnesium reacting with acid'], 0, 'Thermal decomposition needs a continuous supply of energy, so it is endothermic. Combustion, neutralisation and most metal–acid reactions are exothermic.'),
    M('Which everyday product uses an exothermic reaction?', ['Self-heating cans of food', 'Instant cold packs', 'A fridge', 'Ice cubes'], 0, 'Self-heating cans and hand warmers use exothermic reactions. Instant cold packs use endothermic processes.'),
    M('Photosynthesis takes in energy from sunlight. What type of reaction is it?', ['Endothermic', 'Exothermic', 'Neutralisation', 'Combustion'], 0, 'Photosynthesis absorbs light energy to build glucose, so it is endothermic. Respiration, the reverse process, is exothermic.'),
    M('On a reaction profile for an endothermic reaction, where are the products compared with the reactants?', ['Higher in energy', 'Lower in energy', 'At the same energy', 'Below zero'], 0, 'In an endothermic reaction energy is taken in from the surroundings, so the products have more energy than the reactants.'),
    M('What happens to the temperature of the reaction mixture in an endothermic reaction?', ['It decreases', 'It increases', 'It stays the same', 'It first rises then becomes very high'], 0, 'Energy is taken in from the surroundings (including the solution and the thermometer), so the temperature reading falls.'),
    M('HT: Overall, in an endothermic reaction…', ['More energy is needed to break bonds than is released when new bonds form', 'More energy is released making bonds than is used breaking them', 'No bonds are broken', 'Bond breaking releases energy'], 0, 'If bond breaking (endothermic) takes in more energy than bond making (exothermic) gives out, the overall change is endothermic.'),
    T('Making chemical bonds releases energy.', true, 'True. Bond making is exothermic; bond breaking is endothermic.'),
    T('Activation energy is the overall energy change of a reaction.', false, 'False. Activation energy is the minimum energy needed for particles to react (the hump on the profile). The overall energy change is the difference between reactants and products.'),
    T('A reaction with a high activation energy may need heating to start, even if it is exothermic overall.', true, 'True. Methane burning is exothermic but needs a spark or flame to supply the activation energy before it starts.'),
    S('What word describes a reaction that transfers energy to the surroundings?', 'exothermic', ['exothermic'], 'Exothermic reactions give out energy, so the surroundings warm up. Combustion and neutralisation are examples.'),
    X('Which TWO are endothermic processes?', ['Dissolving ammonium nitrate in water', 'The reaction of citric acid with sodium hydrogencarbonate', 'Burning wood', 'Respiration', 'Neutralising an acid with an alkali'], [0, 1], 'Dissolving ammonium nitrate and the citric acid / sodium hydrogencarbonate reaction both cause a temperature drop. Burning, respiration and neutralisation are exothermic.'),
    M('On a reaction profile, the activation energy is measured from…', ['The energy of the reactants to the top of the curve', 'The energy of the products to the top of the curve', 'The reactants to the products', 'Zero to the top of the curve'], 0, 'Activation energy is the energy difference between the reactants and the highest point (peak) of the profile.'),
    M('A reaction has ΔH = +50 kJ/mol. What does this tell you?', ['It is endothermic; 50 kJ is taken in per mole', 'It is exothermic; 50 kJ is given out per mole', 'The activation energy is 50 kJ/mol', 'It cannot happen'], 0, 'A positive ΔH means the products have more energy than the reactants — energy is taken in, so the reaction is endothermic.'),
    N('A reaction profile shows reactants at 120 kJ, the peak at 200 kJ and products at 40 kJ. What is the activation energy in kJ?', 80, 0, 'kJ', ['Activation energy = peak − reactants', '= 200 − 120', '= 80 kJ'], 'Activation energy is measured from the reactants to the peak, not from zero or from the products.'),
    N('Using the same profile (reactants 120 kJ, products 40 kJ), what is the size of the overall energy released in kJ?', 80, 0, 'kJ', ['Energy change = reactants − products', '= 120 − 40', '= 80 kJ released (exothermic, ΔH = −80 kJ)'], 'Products are lower than reactants, so 80 kJ is released to the surroundings.'),
  ] },
  { name: 'Temperature change practical', intro: 'Required practical: investigate how variables (e.g. volume of acid or type of metal) affect the temperature change of reacting solutions, using a polystyrene cup and thermometer.', items: [
    M('Why is a polystyrene cup used in the temperature change practical?', ['It is a good insulator, reducing energy transfer to the surroundings', 'It is cheap', 'It reacts with the acid', 'It conducts heat well'], 0, 'Polystyrene is a poor conductor, so less heat is lost and the measured temperature change is more accurate.'),
    M('Why is a lid placed on the cup?', ['To reduce energy loss by evaporation and convection', 'To stop the reaction', 'To make it endothermic', 'To keep the thermometer upright only'], 0, 'A lid reduces heat lost to the air, improving accuracy.'),
    M('A student adds 5 cm³ portions of HCl to 25 cm³ of NaOH and records the highest temperature each time. What is the independent variable?', ['Volume of hydrochloric acid', 'Temperature', 'Volume of sodium hydroxide', 'Type of cup'], 0, 'The independent variable is what you change — volume of acid. Temperature is the dependent variable.'),
    N('Start temperature 19.5 °C, highest temperature 27.0 °C. What is the temperature change?', 7.5, 0.01, '°C', ['change = final − initial', '= 27.0 − 19.5', '= 7.5 °C'], 'A positive change shows an exothermic reaction.'),
    M('The temperature rises then falls as more acid is added beyond neutralisation. Why does it fall?', ['Extra cold acid is added but no more reaction occurs to release heat', 'The reaction becomes endothermic', 'The thermometer breaks', 'The cup absorbs heat'], 0, 'After all the alkali is neutralised, adding more acid just dilutes and cools the mixture.'),
    X('Which TWO variables should be controlled?', ['Concentration of the acid', 'Starting temperature of solutions', 'Volume of acid added (the independent variable)', 'Maximum temperature', 'The temperature change'], [0, 1], 'Concentration and starting temperature must be kept the same. Volume of acid is the independent variable; temperature change is dependent.'),
    T('Stirring the mixture helps to give a more accurate temperature reading.', true, 'True. Stirring makes sure the temperature is the same throughout the mixture.'),
    M('How could the accuracy of temperature readings be improved?', ['Use a digital thermometer with higher resolution', 'Use a larger beaker made of glass', 'Remove the lid', 'Take only one reading'], 0, 'A higher resolution thermometer and good insulation (lid, polystyrene) improve accuracy.'),
    M('Which graph should be drawn from these results?', ['Maximum temperature (y) against volume of acid (x) with two best-fit lines', 'A bar chart of temperature', 'A pie chart', 'Volume against time'], 0, 'Both are continuous variables: plot a line graph. Two straight best-fit lines meet at the point of neutralisation.'),
    M('A reaction gives a temperature change of −4 °C. What type of reaction is it?', ['Endothermic', 'Exothermic', 'Neutralisation only', 'Combustion'], 0, 'A drop in temperature means energy was taken in from the solution: endothermic.'),
    M('Why might the measured temperature rise be smaller than the true value?', ['Some energy is lost to the surroundings', 'The thermometer adds energy', 'Polystyrene releases energy', 'The reaction is too slow'], 0, 'Heat loss to the air and equipment is the main source of error.'),
    N('Mean of three temperature rises: 6.2, 6.6, 6.4 °C. Calculate the mean.', 6.4, 0.01, '°C', ['mean = (6.2 + 6.6 + 6.4) ÷ 3', '= 19.2 ÷ 3', '= 6.4 °C'], 'Repeat readings reduce the effect of random errors.'),
    M('Metal powders of Mg, Zn and Cu are added to copper sulfate solution. Which gives the biggest temperature rise?', ['Magnesium', 'Zinc', 'Copper', 'All the same'], 0, 'The more reactive the metal compared with copper, the more energy is released in the displacement. Copper does not react with copper sulfate.'),
    S('What is the dependent variable in the temperature change practical?', 'temperature change', ['temperature change', 'change in temperature', 'temperature', 'maximum temperature', 'temperature rise'], 'The dependent variable is measured: the temperature change.', [['temperature']]),
    M('Why should the thermometer not rest on the bottom of the cup?', ['It might measure the temperature of the cup/bench rather than the solution', 'It would break the reaction', 'It would make the reaction endothermic', 'It would dissolve'], 0, 'The bulb should be fully in the liquid to measure the solution temperature.'),
    M('Why is the polystyrene cup often placed inside a beaker?', ['To stop it falling over', 'To make the reaction faster', 'To heat the solution', 'To measure the volume'], 0, 'A polystyrene cup is light and can easily tip over, so standing it in a beaker keeps it stable and safe.'),
    M('Which piece of equipment should be used to measure 25 cm³ of acid most accurately for this practical?', ['A measuring cylinder (or pipette)', 'A beaker', 'A conical flask', 'A test tube'], 0, 'Measuring cylinders (or pipettes/burettes) are designed for measuring volumes. Beaker and flask markings are only approximate.'),
    M('A student compares the temperature change for different metals with acid. Which is the independent variable?', ['The type of metal', 'The temperature change', 'The volume of acid', 'The concentration of acid'], 0, 'The independent variable is the one you deliberately change — the type of metal. Temperature change is the dependent variable; the acid volume and concentration are control variables.'),
    N('Start temperature 21.0 °C, lowest temperature 15.5 °C. What is the temperature change? (give a negative value for a fall)', -5.5, 0.01, '°C', ['Temperature change = final − initial', '= 15.5 − 21.0', '= −5.5 °C (a decrease, so endothermic)'], 'A negative temperature change shows that energy was taken in from the solution — the reaction is endothermic.'),
    M('A student draws a graph of maximum temperature against volume of acid added. Two straight lines are drawn and they cross. What does the crossing point show?', ['The volume of acid that exactly neutralises the alkali', 'The point where the reaction starts', 'The boiling point of the solution', 'The point where the thermometer broke'], 0, 'The temperature rises until all the alkali has reacted, then falls as extra cold acid is added. The crossing point estimates the volume needed for complete neutralisation and the maximum temperature.'),
    M('Why should the thermometer be read at eye level?', ['To avoid parallax error', 'To keep it warm', 'To make the reading larger', 'So it does not touch the liquid'], 0, 'Reading from an angle makes the liquid level appear higher or lower than it really is (parallax error).'),
    T('Using a lid on the polystyrene cup reduces energy lost to the surroundings.', true, 'True. A lid reduces heat loss by convection and evaporation from the surface, giving a more accurate temperature change.'),
    T('A larger temperature rise always means a faster reaction.', false, 'False. The temperature change measures how much energy is released, not how fast. Rate is a separate measurement.'),
    T('Repeating the experiment and calculating a mean helps to make the results more reliable (repeatable).', true, 'True. Repeats help identify anomalies and reduce the effect of random errors.'),
    S('What piece of equipment, more precise than a thermometer, can record temperature automatically?', 'temperature probe', ['temperature probe', 'data logger', 'datalogger', 'temperature sensor', 'probe', 'digital thermometer'], 'A temperature probe with a data logger can record temperature at regular intervals and to a higher resolution than a glass thermometer.', [['probe', 'logger', 'sensor', 'digital']]),
    X('Which TWO changes would reduce energy losses in the temperature change practical?', ['Using a lid', 'Using a polystyrene cup instead of a glass beaker', 'Using a metal can', 'Leaving the reaction for 10 minutes before reading', 'Stirring with a metal spoon for several minutes'], [0, 1], 'Polystyrene is a good insulator and a lid reduces heat loss from the top. Metal conducts heat away; waiting a long time lets heat escape.'),
    M('Results: 5 cm³ → 3.0 °C, 10 cm³ → 6.1 °C, 15 cm³ → 4.2 °C, 20 cm³ → 12.0 °C, 25 cm³ → 14.9 °C. Which result is anomalous?', ['15 cm³ → 4.2 °C', '5 cm³ → 3.0 °C', '20 cm³ → 12.0 °C', '25 cm³ → 14.9 °C'], 0, 'The temperature rise increases by about 3 °C for every 5 cm³, so at 15 cm³ you would expect about 9 °C. 4.2 °C does not fit the pattern.'),
    N('Temperature rises from three repeats were 8.4, 8.0 and 8.2 °C. Calculate the mean.', 8.2, 0.01, '°C', ['Add the values: 8.4 + 8.0 + 8.2 = 24.6', 'Divide by the number of values: 24.6 ÷ 3', 'Mean = 8.2 °C'], 'The mean is the sum divided by the number of readings.'),
    M('Why is the same volume of solution used each time when comparing different metals?', ['The temperature change depends on the volume being heated, so it must be controlled', 'So the metals dissolve', 'Because the thermometer only fits one volume', 'So that the reaction is endothermic'], 0, 'The same energy released into a larger volume would cause a smaller temperature rise, so volume must be kept constant for a fair test.'),
    O('Put the steps of the temperature change practical in order.', ['Measure 30 cm³ of acid into a polystyrene cup', 'Record the starting temperature', 'Add the solid or second solution and put on the lid', 'Stir and record the highest (or lowest) temperature'], 'Measure, record initial temperature, add the reactant and cover, stir and record the extreme temperature reached.'),
  ] },
  { name: 'Bond energy calculations (Higher)', intro: 'HT only. Overall energy change = total energy needed to break bonds in reactants − total energy released forming bonds in products.', gen: genBondEnergy },
  { name: 'Chemical cells & fuel cells', intro: 'Chemistry only. Cells use chemical reactions to produce a voltage. Batteries are cells in series. Hydrogen fuel cells react hydrogen with oxygen to make electricity, producing only water.', items: [
    M('What determines the voltage of a simple chemical cell?', ['The type of electrodes and the electrolyte', 'The size of the container', 'The colour of the electrolyte', 'The length of the wires'], 0, 'Voltage depends on the metals used (difference in reactivity) and the electrolyte.'),
    M('Which pair of metals gives the largest voltage in a simple cell?', ['Magnesium and copper', 'Zinc and iron', 'Copper and copper', 'Iron and copper'], 0, 'The bigger the difference in reactivity, the bigger the voltage. Two identical metals give zero.'),
    M('Why do non-rechargeable batteries stop working?', ['A reactant has been used up', 'The electrolyte freezes', 'The electrons run out of the wires', 'The case breaks'], 0, 'When one reactant is used up the reaction stops, so no more voltage.'),
    M('How are rechargeable cells recharged?', ['An external current reverses the chemical reactions', 'Adding more electrolyte', 'Heating them', 'Shaking them'], 0, 'Applying an external electrical current reverses the reactions, regenerating the reactants.'),
    M('What is the only product of a hydrogen fuel cell?', ['Water', 'Carbon dioxide', 'Hydrogen', 'Oxygen'], 0, 'Overall: 2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O.'),
    X('Which TWO are advantages of hydrogen fuel cells over rechargeable batteries?', ['Only waste product is water', 'Do not need long recharging — just refuel', 'Hydrogen is easy to store', 'Hydrogen is a liquid at room temperature', 'They contain toxic metals'], [0, 1], 'Fuel cells produce only water and are refuelled quickly. Disadvantages: hydrogen is a flammable gas, hard to store, often made from fossil fuels.'),
    M('What is a disadvantage of hydrogen fuel cells?', ['Hydrogen is a flammable gas that is difficult to store', 'They produce carbon dioxide', 'They need recharging overnight', 'They contain lead'], 0, 'Hydrogen must be stored under pressure; it is explosive with air.'),
    T('A battery consists of two or more cells connected together in series.', true, 'True. Connecting cells in series adds their voltages.'),
    T('Fuel cells release no pollution at any stage.', false, 'False. The fuel cell only makes water, but producing hydrogen (e.g. from methane or using electricity from fossil fuels) can cause pollution.'),
    M('HT: What is the half equation at the negative electrode of a hydrogen fuel cell (acid electrolyte)?', ['2H<sub>2</sub> → 4H<sup>+</sup> + 4e<sup>−</sup>', 'O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>−</sup> → 2H<sub>2</sub>O', '2H<sub>2</sub>O → O<sub>2</sub> + 4H<sup>+</sup>', 'H<sup>+</sup> + e<sup>−</sup> → H'], 0, 'Hydrogen is oxidised (loses electrons) at the negative electrode; oxygen is reduced at the positive electrode.'),
    S('What gas, besides hydrogen, is needed by a hydrogen fuel cell?', 'oxygen', ['oxygen', 'o2', 'air'], 'Oxygen (from air) combines with hydrogen to form water.'),
    M('Why are alkaline batteries not rechargeable?', ['Their chemical reactions cannot be easily reversed', 'They contain no chemicals', 'They are too small', 'They produce hydrogen'], 0, 'Non-rechargeable cells use reactions that are not reversible by applying a current.'),
    M('A cell made with zinc and copper electrodes gives 1.1 V. What voltage would two such cells in series give?', ['2.2 V', '1.1 V', '0.55 V', '0 V'], 0, 'Voltages of cells in series add.'),
    M('Where are rechargeable cells commonly used?', ['Mobile phones and laptops', 'Hydrogen buses only', 'Light bulbs', 'Kettles'], 0, 'Lithium-ion rechargeable cells power phones, laptops and electric cars.'),
    M('What is used as the electrolyte in a simple lemon cell?', ['The lemon juice (citric acid solution)', 'The copper electrode', 'The zinc electrode', 'The wire'], 0, 'The acidic juice contains ions that allow charge to flow between electrodes.'),
    M('What is needed to make a simple chemical cell?', ['Two different metals in contact with an electrolyte', 'Two identical metals in pure water', 'One metal in air', 'A plastic rod in salt water'], 0, 'A cell needs two different electrodes (usually metals) in an electrolyte. Identical metals give no voltage; pure water is a very poor electrolyte.'),
    M('Which change would increase the voltage of a simple cell using zinc and another metal?', ['Replacing the other metal with one that is much less reactive, such as silver', 'Using a metal closer in reactivity to zinc', 'Using zinc for both electrodes', 'Using distilled water as the electrolyte'], 0, 'The bigger the difference in reactivity between the two metals, the larger the voltage. Identical electrodes give 0 V.'),
    M('In a simple cell, the more reactive metal…', ['Loses electrons and forms ions', 'Gains electrons', 'Does not react', 'Is always copper'], 0, 'The more reactive metal is oxidised — it loses electrons, which flow through the external circuit to the less reactive metal.'),
    M('What is the overall reaction in a hydrogen fuel cell?', ['2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O', 'H<sub>2</sub> + O<sub>2</sub> → H<sub>2</sub>O<sub>2</sub>', '2H<sub>2</sub>O → 2H<sub>2</sub> + O<sub>2</sub>', 'CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O'], 0, 'Hydrogen is oxidised and combines with oxygen to make water. The reverse equation is electrolysis of water.'),
    M('Why is hydrogen difficult to use as a fuel for cars?', ['It is a gas that is hard to store safely in large amounts', 'It produces carbon dioxide', 'It is a solid', 'It cannot react with oxygen'], 0, 'Hydrogen takes up a lot of space unless compressed at high pressure, and it is flammable, so storage and transport are challenging.'),
    M('Most hydrogen today is produced from fossil fuels. Why does this matter?', ['Making the hydrogen can still release carbon dioxide', 'It makes the fuel cell produce carbon monoxide', 'It means the fuel cell needs no oxygen', 'It makes hydrogen non-flammable'], 0, 'Although a fuel cell only emits water, producing the hydrogen (e.g. from methane) can release CO<sub>2</sub>, so it is not automatically pollution-free.'),
    T('In a rechargeable cell, the chemical reactions are reversed by applying an external electric current.', true, 'True. Charging reverses the reactions so the cell can be used again.'),
    T('A fuel cell needs to be recharged from the mains like a phone battery.', false, 'False. A fuel cell keeps producing electricity as long as hydrogen and oxygen are supplied; it is refuelled, not recharged.'),
    T('Cells using two identical metals as electrodes produce no voltage.', true, 'True. There is no difference in reactivity, so there is no tendency for electrons to flow one way.'),
    S('What is the name for the substance that is oxidised in a hydrogen fuel cell?', 'hydrogen', ['hydrogen', 'h2', 'hydrogen gas'], 'Hydrogen is oxidised (loses electrons) at the negative electrode: H<sub>2</sub> → 2H<sup>+</sup> + 2e<sup>−</sup>.'),
    X('Which TWO are disadvantages of rechargeable batteries compared with hydrogen fuel cells?', ['They take a long time to recharge', 'They store less energy for their mass, so vehicles have a shorter range', 'They produce water as the only product', 'They need a hydrogen supply', 'They need oxygen from the air'], [0, 1], 'Batteries are slow to recharge and their limited energy store means shorter range. Water product, hydrogen supply and oxygen use are features of fuel cells.'),
    M('HT: In a hydrogen fuel cell, what is the half equation at the positive electrode (acid electrolyte)?', ['O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>−</sup> → 2H<sub>2</sub>O', 'H<sub>2</sub> → 2H<sup>+</sup> + 2e<sup>−</sup>', '2H<sub>2</sub>O → O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>−</sup>', 'O<sub>2</sub> → 2O<sup>2−</sup>'], 0, 'At the positive electrode oxygen is reduced: it gains electrons and combines with H<sup>+</sup> ions to make water. H<sub>2</sub> → 2H<sup>+</sup> + 2e<sup>−</sup> happens at the negative electrode.'),
    M('Why does a non-rechargeable battery eventually go flat?', ['One of the reactants is used up', 'The electrons run out of the universe', 'The voltage increases until it stops', 'The metal electrodes melt'], 0, 'When a reactant (e.g. the zinc) is used up, the reaction stops and no more electricity is produced.'),
    N('Three cells, each 1.5 V, are connected in series. What is the total voltage?', 4.5, 0.01, 'V', ['Voltages of cells in series add up', '1.5 + 1.5 + 1.5', '= 4.5 V'], 'Connecting cells in series to make a battery adds their voltages.'),
    O('Put these metals in order of the voltage they would give when paired with copper in a simple cell, largest first.', ['Magnesium', 'Zinc', 'Iron', 'Silver'], 'The further the metal is above copper in the reactivity series, the bigger the voltage. Silver is below copper, so the voltage is small (and the polarity reverses).'),
  ] },
], {
  overview: 'Every chemical reaction involves an <b>energy change</b>. Some reactions release energy (<b>exothermic</b>), others absorb it (<b>endothermic</b>). This topic includes the temperature-change required practical, bond energy calculations at Higher tier, and how chemical cells and fuel cells produce electricity.',
  objectives: ['I can classify reactions as exothermic or endothermic and give examples and uses', 'I can draw and interpret reaction profiles, including activation energy', 'I can plan and evaluate the temperature-change required practical', 'HT: I can calculate energy changes from bond energies', 'Chemistry only: I can describe cells, batteries and hydrogen fuel cells'],
  keyWords: [{ term: 'Exothermic', def: 'Transfers energy to the surroundings; temperature rises.' }, { term: 'Endothermic', def: 'Takes in energy from the surroundings; temperature falls.' }, { term: 'Activation energy', def: 'Minimum energy needed for particles to react.' }, { term: 'Reaction profile', def: 'Diagram showing energy of reactants and products during a reaction.' }, { term: 'Bond energy', def: 'Energy needed to break one mole of a particular bond.' }, { term: 'Cell', def: 'Device using a chemical reaction to produce a voltage.' }, { term: 'Fuel cell', def: 'Cell supplied with a fuel and oxygen that produces electricity.' }],
  sections: [
    { title: 'Exothermic and endothermic', html: `<table class="qt"><tr><th>Exothermic</th><th>Endothermic</th></tr><tr><td>Energy out; temperature rises; ΔH negative</td><td>Energy in; temperature falls; ΔH positive</td></tr><tr><td>Combustion, oxidation, neutralisation</td><td>Thermal decomposition, citric acid + NaHCO<sub>3</sub></td></tr><tr><td>Hand warmers, self-heating cans</td><td>Sports cold packs</td></tr></table>` },
    { title: 'Reaction profiles', html: `<svg viewBox="0 0 260 150" width="100%" style="max-width:340px"><line x1="30" y1="10" x2="30" y2="135" stroke="currentColor"/><line x1="30" y1="135" x2="250" y2="135" stroke="currentColor"/><path d="M35 80 L80 80 Q125 0 165 105 L240 105" fill="none" stroke="#3b6cf6" stroke-width="2"/><line x1="70" y1="80" x2="70" y2="32" stroke="currentColor" stroke-dasharray="3"/><text x="74" y="55" font-size="9" fill="currentColor">activation energy</text><line x1="215" y1="80" x2="215" y2="105" stroke="currentColor" stroke-dasharray="3"/><line x1="165" y1="80" x2="240" y2="80" stroke="currentColor" stroke-dasharray="2"/><text x="190" y="96" font-size="8" fill="currentColor">ΔH</text><text x="36" y="74" font-size="9" fill="currentColor">reactants</text><text x="185" y="118" font-size="9" fill="currentColor">products</text><text x="12" y="70" font-size="9" fill="currentColor" transform="rotate(-90 12 70)">energy</text><text x="140" y="147" font-size="9" fill="currentColor" text-anchor="middle">progress of reaction</text></svg><p>Exothermic: products lower than reactants. Endothermic: products higher. The hump is the activation energy.</p>` },
    { title: 'Required practical: temperature changes', html: `<ol><li>Measure 25 cm³ of one solution into a polystyrene cup in a beaker; record temperature.</li><li>Add a measured amount of the other reactant, stir, put on lid, record highest temperature.</li><li>Repeat with different volumes / metals; repeat each to calculate a mean.</li></ol><p>Errors: heat loss to surroundings; reduce with a lid and insulation.</p>` },
    { title: 'Bond energies (Higher)', html: `<div class="rule">energy change = energy to break bonds − energy released making bonds</div><div class="worked"><div class="wq">H<sub>2</sub> + Cl<sub>2</sub> → 2HCl. H–H 436, Cl–Cl 242, H–Cl 431 kJ/mol.</div><ol><li>Broken: 436 + 242 = 678</li><li>Made: 2 × 431 = 862</li><li>678 − 862</li></ol><div class="wa">Answer: −184 kJ/mol (exothermic)</div></div>` },
    { title: 'Cells and fuel cells (chemistry only)', html: `<p>A cell has two different metals in an electrolyte; bigger reactivity difference → bigger voltage. Batteries are cells in series. Non-rechargeable cells stop when a reactant is used up; rechargeable cells are reversed by an external current.</p><p>Hydrogen fuel cell: 2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O. HT half equations: 2H<sub>2</sub> → 4H<sup>+</sup> + 4e<sup>−</sup>; O<sub>2</sub> + 4H<sup>+</sup> + 4e<sup>−</sup> → 2H<sub>2</sub>O.</p>` },
  ],
  mistakes: ['Saying bond breaking releases energy.', 'Getting the sign wrong: exothermic ΔH is negative.', 'Forgetting to count all bonds (e.g. both O–H bonds in each water molecule).', 'Thinking catalysts change the overall energy change.'],
  examTips: ['In bond energy questions, draw displayed formulae and tick off bonds as you count them.', 'Label reaction profiles fully: axes, reactants, products, activation energy, overall energy change with arrows.', 'For evaluation of the practical, the key error is heat loss — suggest insulation/lid.'],
  realLife: 'Self-heating cans of coffee use the exothermic reaction of calcium oxide with water to warm the drink in a few minutes.',
});

// =====================================================================
// YEAR 11 — Rates & equilibrium (AQA 4.6)
// =====================================================================
function genRate(rng) {
  const v = ri(rng, 0, 3);
  if (v === 0) {
    const vol = ri(rng, 12, 96), t = pick(rng, [10, 20, 25, 30, 40, 50, 60, 80, 100, 120]), r = rd(vol / t, 2);
    return { type: 'number', q: `Magnesium reacts with hydrochloric acid. ${vol} cm³ of hydrogen is collected in a gas syringe in ${t} s. Calculate the mean rate of reaction in cm³/s. Give your answer to 2 decimal places.`, value: r, tol: 0.011, unit: 'cm³/s', answer: `${r} cm³/s`,
      steps: ['mean rate = quantity of product formed ÷ time taken', `mean rate = ${vol} ÷ ${t}`, `mean rate = ${r} cm³/s`], explain: 'Mean rate of reaction = amount of product formed (or reactant used) ÷ time. The unit follows: cm³ ÷ s = cm³/s.', hint: 'Divide the volume by the time.' };
  }
  if (v === 1) {
    const m = ri(rng, 5, 60) / 100, t = pick(rng, [20, 30, 40, 50, 60, 100, 120, 150, 200]), r = rd(m / t, 4);
    return { type: 'number', q: `Marble chips react with acid in an open flask on a balance. The mass falls by ${m} g in ${t} s as carbon dioxide escapes. Calculate the mean rate in g/s.`, value: r, tol: Math.max(0.00006, r * 0.01), unit: 'g/s', answer: `${r} g/s`,
      steps: ['mean rate = mass lost ÷ time', `mean rate = ${m} ÷ ${t}`, `mean rate = ${r} g/s`], explain: 'The mass lost equals the mass of CO<sub>2</sub> produced, so mass lost ÷ time gives the mean rate.', hint: 'Mass lost ÷ time.' };
  }
  if (v === 2) {
    const v1 = ri(rng, 5, 30), v2 = v1 + ri(rng, 6, 40), t1 = pick(rng, [10, 20, 30]), t2 = t1 + pick(rng, [10, 20, 30, 40]), r = rd((v2 - v1) / (t2 - t1), 2);
    return { type: 'number', q: `In a reaction, the volume of gas was ${v1} cm³ at ${t1} s and ${v2} cm³ at ${t2} s. Calculate the mean rate between these times (2 d.p.).`, value: r, tol: 0.011, unit: 'cm³/s', answer: `${r} cm³/s`,
      steps: [`gas made = ${v2} − ${v1} = ${v2 - v1} cm³`, `time taken = ${t2} − ${t1} = ${t2 - t1} s`, `mean rate = ${v2 - v1} ÷ ${t2 - t1} = ${r} cm³/s`], explain: 'Use the change in volume over the change in time — not the total volume divided by the final time.', hint: 'Work out the changes first.' };
  }
  const t = ri(rng, 15, 180), r = rd(1000 / t, 2);
  return { type: 'number', q: `In the disappearing-cross experiment (sodium thiosulfate + hydrochloric acid), the cross disappears after ${t} s. Calculate the relative rate, 1000/t, in s<sup>−1</sup> (2 d.p.).`, value: r, tol: 0.011, unit: 's⁻¹', answer: `${r}`,
    steps: ['relative rate = 1000 ÷ time', `= 1000 ÷ ${t}`, `= ${r}`], explain: 'Rate is inversely proportional to the time taken: a shorter time means a faster reaction. 1000/t gives convenient numbers to plot.', hint: 'Rate ∝ 1/time.' };
}

topic({ id: 'chem-y11-rates', strand: 'chem-rates', year: 11, term: 1, tier: 'FH', name: 'Rates of Reaction & Equilibrium',
  summary: 'Measure and calculate rates, explain factors using collision theory, catalysts, and reversible reactions/equilibrium (Le Chatelier HT).', specRef: 'AQA 8462 4.6.1–4.6.2' }, [
  { name: 'Calculating rates', intro: 'Mean rate = quantity of reactant used or product formed ÷ time taken. Units: g/s, cm³/s or (HT) mol/s.', gen: genRate },
  { name: 'Collision theory & factors affecting rate', intro: 'Reactions happen when particles collide with at least the activation energy. Temperature, concentration, pressure, surface area and catalysts change the frequency of successful collisions.', items: [
    M('According to collision theory, what is needed for a reaction?', ['Particles must collide with at least the activation energy', 'Particles must be the same size', 'Particles must be stationary', 'Particles must be in a solid'], 0, 'Only collisions with enough energy (≥ activation energy) are successful.'),
    M('Why does increasing concentration increase the rate?', ['More particles in the same volume, so more frequent collisions', 'Particles move faster', 'Activation energy is lowered', 'Particles have more energy'], 0, 'Concentration affects collision frequency, not particle energy.'),
    M('Why does increasing temperature increase the rate?', ['Particles move faster so collide more often AND more collisions have enough energy', 'Activation energy is lowered', 'There are more particles', 'Surface area increases'], 0, 'Temperature has two effects: more frequent collisions and a greater proportion of collisions with energy ≥ activation energy (the bigger effect).'),
    M('Why does powdered calcium carbonate react faster than lumps?', ['Larger surface area to volume ratio, so more frequent collisions', 'Powder is more concentrated', 'Powder has a lower activation energy', 'Powder is hotter'], 0, 'More exposed particles can be hit by acid particles.'),
    M('Why does increasing the pressure of reacting gases increase the rate?', ['Particles are closer together, so collide more often', 'Particles get bigger', 'Particles get more energy', 'The reaction becomes exothermic'], 0, 'Higher pressure = more gas particles per unit volume = more frequent collisions.'),
    T('Increasing concentration increases the energy of the collisions.', false, 'False. It increases how often particles collide, not how energetic the collisions are.'),
    T('A 10 °C rise in temperature roughly doubles the rate of many reactions.', true, 'True — a useful rule of thumb, because many more collisions exceed the activation energy.'),
    O('Required practical (disappearing cross): put the steps in order.', ['Measure sodium thiosulfate solution into a conical flask on a black cross', 'Add hydrochloric acid and start the timer', 'Swirl and look down through the solution', 'Stop the timer when the cross can no longer be seen'], 'The sulfur precipitate makes the mixture cloudy. Repeat with different concentrations of thiosulfate.'),
    M('In the disappearing-cross practical, what makes the solution go cloudy?', ['A precipitate of sulfur forms', 'Hydrogen gas bubbles', 'The acid evaporates', 'Carbon dioxide forms'], 0, 'Na<sub>2</sub>S<sub>2</sub>O<sub>3</sub> + 2HCl → 2NaCl + H<sub>2</sub>O + SO<sub>2</sub> + S. The solid sulfur blocks the view.'),
    M('What is a weakness of the disappearing-cross method?', ['Judging when the cross disappears is subjective', 'It needs a gas syringe', 'It produces no product', 'It is too fast to measure'], 0, 'Different people judge the end point differently; a light sensor/data logger is more reliable.'),
    X('Which TWO methods can follow the rate of a reaction that produces a gas?', ['Measure gas volume with a gas syringe', 'Measure mass loss on a balance', 'Measure the colour of the gas syringe', 'Count the bubbles of liquid', 'Measure the boiling point'], [0, 1], 'Gas volume collected or mass lost over time both track how fast product forms.'),
    M('On a graph of volume of gas against time, how does the gradient change as the reaction proceeds?', ['It decreases as reactants are used up', 'It increases', 'It stays constant', 'It becomes negative'], 0, 'As reactant concentration falls, collisions become less frequent and the curve levels off.'),
    M('HT: How do you find the rate at a specific time from a curved graph?', ['Draw a tangent and calculate its gradient', 'Read the y-value', 'Divide total y by total x', 'Find the area under the curve'], 0, 'The gradient of the tangent at that point gives the instantaneous rate.'),
    M('Two experiments use the same mass of marble; one uses chips and one powder. Why is the final volume of CO<sub>2</sub> the same?', ['The same amount of reactant is used, so the same amount of product forms', 'Powder reacts slower', 'Chips are more concentrated', 'Some gas is lost'], 0, 'Surface area changes the rate, not the total amount of product.'),
    S('What is the name for the minimum energy that colliding particles need to react?', 'activation energy', ['activation energy'], 'Only collisions with energy greater than or equal to the activation energy lead to a reaction.', [['activation']]),
    M('Rate of reaction can be calculated as…', ['Amount of reactant used (or product formed) ÷ time', 'Time ÷ amount of product', 'Amount of product × time', 'Temperature ÷ time'], 0, 'Mean rate = quantity of reactant used or product formed ÷ time taken, for example in cm³/s or g/s.'),
    M('Why does a reaction slow down as it proceeds?', ['The concentration of reactants falls, so there are fewer collisions per second', 'The particles get tired', 'The temperature always rises', 'The catalyst is used up'], 0, 'As reactants are used up, there are fewer reactant particles in the same volume, so the frequency of successful collisions decreases.'),
    M('Which change would NOT increase the rate of reaction between magnesium ribbon and acid?', ['Using a larger volume of the same acid', 'Using more concentrated acid', 'Warming the acid', 'Cutting the magnesium into small pieces'], 0, 'A larger volume at the same concentration does not change how often particles collide per second. Concentration, temperature and surface area all affect the collision frequency.'),
    M('Which unit could be used for the rate of a reaction measured by loss in mass?', ['g/s', 'cm³', 's', 'g'], 0, 'Rate is an amount per unit time, so loss in mass per second gives g/s. cm³, s and g alone are not rates.'),
    M('Why is the temperature effect on rate larger than the concentration effect for many reactions?', ['Higher temperature increases both collision frequency and the fraction of collisions with enough energy', 'Temperature changes the activation energy', 'Concentration does not affect collisions', 'Temperature makes particles bigger'], 0, 'Heating makes particles move faster (more collisions) AND gives more of them at least the activation energy, so more collisions are successful.'),
    T('A larger surface area to volume ratio increases the frequency of collisions.', true, 'True. Smaller pieces expose more particles at the surface, so more collisions can happen per second.'),
    T('Doubling the concentration of a reactant can increase the rate because there are more particles in the same volume.', true, 'True. More particles per dm³ means more frequent collisions, so the rate increases.'),
    T('Collisions between particles always lead to a reaction.', false, 'False. Only collisions with energy equal to or greater than the activation energy (and the right orientation) are successful.'),
    S('What name is given to a collision that leads to a reaction?', 'successful collision', ['successful collision', 'successful collisions', 'successful', 'effective collision'], 'A successful collision has at least the activation energy, so the particles react.', [['successful', 'effective']]),
    N('A reaction produces 60 cm³ of gas in 30 seconds. Calculate the mean rate in cm³/s.', 2, 0.01, 'cm³/s', ['mean rate = volume of gas ÷ time', '= 60 ÷ 30', '= 2 cm³/s'], 'Divide the amount of product by the time taken.'),
    N('A flask loses 1.2 g in mass over 4 minutes as carbon dioxide escapes. What is the mean rate in g/min?', 0.3, 0.001, 'g/min', ['mean rate = mass lost ÷ time', '= 1.2 ÷ 4', '= 0.3 g/min'], 'The loss in mass is equal to the mass of gas given off.'),
    X('Which TWO changes increase the rate of reaction between marble chips and hydrochloric acid?', ['Using smaller marble chips', 'Increasing the temperature', 'Using more dilute acid', 'Cooling the flask in ice', 'Using larger lumps of marble'], [0, 1], 'Smaller chips (bigger surface area) and higher temperature increase the frequency of successful collisions. More dilute acid, cooling and larger lumps slow it down.'),
    M('A graph of volume of gas against time becomes horizontal. What does this show?', ['The reaction has stopped because a reactant has been used up', 'The reaction is at its fastest', 'The gas has stopped being measured', 'The catalyst has been used up'], 0, 'A flat line means no more gas is being produced — the limiting reactant has run out.'),
    M('In the disappearing-cross practical, a student repeats it at a higher concentration of thiosulfate. What happens to the time taken for the cross to disappear?', ['It decreases', 'It increases', 'It stays the same', 'The cross never disappears'], 0, 'Higher concentration → faster reaction → the sulfur precipitate forms sooner, so the time is shorter. Rate is proportional to 1/time.'),
    O('Put these conditions in order of rate of reaction of magnesium with hydrochloric acid, slowest first.', ['Magnesium ribbon in dilute acid at 20 °C', 'Magnesium ribbon in concentrated acid at 20 °C', 'Magnesium powder in concentrated acid at 20 °C', 'Magnesium powder in concentrated acid at 40 °C'], 'Each change adds a factor that increases the rate: higher concentration, then larger surface area, then higher temperature.'),
  ] },
  { name: 'Catalysts', intro: 'A catalyst speeds up a reaction without being used up, by providing an alternative pathway with a lower activation energy. Enzymes are biological catalysts.', items: [
    M('How does a catalyst increase the rate?', ['It provides a pathway with lower activation energy', 'It increases the temperature', 'It increases the concentration', 'It gives particles more energy'], 0, 'More collisions now exceed the (lower) activation energy.'),
    T('A catalyst is used up in the reaction.', false, 'False. A catalyst is not used up — it can be recovered unchanged in mass and chemical composition at the end.'),
    T('A catalyst does not appear in the overall chemical equation.', true, 'True. It may be written above the arrow, but it is not a reactant or product.'),
    S('What is the name for biological catalysts?', 'enzymes', ['enzymes', 'enzyme'], 'Enzymes are proteins that catalyse reactions in living things, e.g. in fermentation.'),
    M('Which catalyst is used in the Haber process?', ['Iron', 'Platinum', 'Nickel', 'Manganese dioxide'], 0, 'Iron catalyses N<sub>2</sub> + 3H<sub>2</sub> ⇌ 2NH<sub>3</sub>.'),
    M('Manganese(IV) oxide speeds up the decomposition of hydrogen peroxide. Which gas is produced?', ['Oxygen', 'Hydrogen', 'Carbon dioxide', 'Chlorine'], 0, '2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>. Test: relights a glowing splint.'),
    M('How could you show a substance is acting as a catalyst?', ['Show it speeds up the reaction and its mass is unchanged at the end', 'Show it changes colour', 'Show it dissolves', 'Show the mass of product increases'], 0, 'Compare rate with/without it, then filter, dry and weigh it to show it was not used up.'),
    M('Why are catalysts important in industry?', ['They allow reactions at lower temperatures, saving energy and cost', 'They increase the yield at equilibrium', 'They make products purer', 'They make reactions endothermic'], 0, 'Faster reactions at lower temperatures save fuel and money. Catalysts do not change the equilibrium position.'),
    M('On a reaction profile, what does a catalyst change?', ['The height of the activation energy hump', 'The energy of the products', 'The energy of the reactants', 'The overall energy change'], 0, 'Only the activation energy is lowered.'),
    X('Which TWO are true of catalysts?', ['They speed up reactions', 'Different reactions need different catalysts', 'They increase the amount of product', 'They are always metals', 'They raise the activation energy'], [0, 1], 'Catalysts are specific and speed up reactions. They do not increase the total yield, and enzymes are proteins, not metals.'),
    M('Transition metals are often good catalysts. Which is used in catalytic converters?', ['Platinum', 'Sodium', 'Lead', 'Calcium'], 0, 'Platinum/rhodium in converters help convert CO and nitrogen oxides into CO<sub>2</sub> and N<sub>2</sub>.'),
    M('Why are catalysts used as powders or fine meshes?', ['Larger surface area means more sites for reaction', 'They are cheaper', 'They become reactants', 'They react with oxygen'], 0, 'Reactions occur at the catalyst surface, so a large surface area increases rate.'),
    T('Enzymes work fastest at very high temperatures.', false, 'False. Enzymes have an optimum temperature (often around 37 °C); too hot and they denature.'),
    M('Adding a catalyst to a reversible reaction at equilibrium…', ['Does not change the position of equilibrium; equilibrium is reached faster', 'Increases the yield', 'Decreases the yield', 'Stops the reverse reaction'], 0, 'A catalyst speeds up forward and reverse reactions equally.'),
    S('Name the gas made when hydrogen peroxide decomposes.', 'oxygen', ['oxygen', 'o2'], 'Hydrogen peroxide → water + oxygen.'),
    M('What happens to the mass of a catalyst during a reaction?', ['It is the same at the end as at the start', 'It decreases because it is used up', 'It increases', 'It turns into product'], 0, 'A catalyst is not used up, so the same mass can be recovered at the end of the reaction — this can be checked by filtering, drying and weighing.'),
    M('Why are different reactions catalysed by different substances?', ['Each catalyst provides a specific alternative pathway for particular reactions', 'All catalysts work for every reaction', 'Catalysts only work at very high temperature', 'Catalysts change the products'], 0, 'Catalysts are specific: each provides an alternative route with lower activation energy for certain reactions only.'),
    M('What effect does a catalyst have on the amount of product made?', ['None — it only makes the product form faster', 'It increases the amount of product', 'It decreases the amount of product', 'It changes which product is made'], 0, 'A catalyst speeds up the rate but does not change the yield or the final amount of product (nor the position of equilibrium).'),
    M('On a reaction profile, how does a catalysed pathway appear?', ['As a lower hump between the same reactants and products', 'As a higher hump', 'With the products at a lower energy', 'With the reactants at a higher energy'], 0, 'The catalysed curve has a lower peak (lower activation energy). The energies of the reactants and products, and ΔH, do not change.'),
    M('Which enzyme-based use is an example of a biological catalyst?', ['Biological washing powders breaking down stains at low temperatures', 'Iron in the Haber process', 'Platinum in car exhausts', 'Vanadium oxide in making sulfuric acid'], 0, 'Enzymes are biological catalysts, used in washing powders so stains break down at lower temperatures. The others are inorganic (often transition metal) catalysts.'),
    T('A catalyst lowers the activation energy of a reaction.', true, 'True. By providing a different reaction pathway with a lower activation energy, a greater proportion of collisions are successful.'),
    T('A catalyst increases the energy of the reactant particles.', false, 'False. A catalyst does not give the particles more energy; it lowers the energy barrier so more particles already have enough energy to react.'),
    T('Using a catalyst can reduce the energy costs of an industrial process.', true, 'True. With a catalyst, reactions can run fast enough at lower temperatures, which saves energy and money.'),
    S('Name the transition metal oxide used as a catalyst for decomposing hydrogen peroxide.', 'manganese(IV) oxide', ['manganese oxide', 'manganese iv oxide', 'manganese dioxide', 'mno2', 'manganese(iv) oxide'], 'Manganese(IV) oxide (MnO<sub>2</sub>) catalyses 2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>.', [['manganese', 'mno2']]),
    S('What test confirms that the gas from decomposing hydrogen peroxide is oxygen?', 'it relights a glowing splint', ['relights a glowing splint', 'glowing splint', 'glowing splint relights'], 'Oxygen relights a glowing splint. A lit splint with a squeaky pop is the test for hydrogen.', [['glowing'], ['splint']]),
    X('Which TWO pieces of evidence show that copper powder is a catalyst for the reaction of zinc with sulfuric acid?', ['Bubbles form faster when copper is added', 'The same mass of copper is left at the end', 'The copper dissolves completely', 'The solution turns blue with copper sulfate', 'More hydrogen is made in total'], [0, 1], 'A catalyst speeds up the reaction and is not used up. If copper dissolved or extra product formed, it would be reacting, not catalysing.'),
    M('Why might a manufacturer choose a catalyst even though it is expensive?', ['It is not used up, so it can be reused many times, and it saves energy costs', 'It increases the yield of every reaction', 'It is used up and must be replaced each time', 'It makes the product purer by changing what is made'], 0, 'Catalysts are reused, and they let reactions run at lower temperatures, so the savings over time outweigh the initial cost.'),
    M('Why might a catalyst stop working (be "poisoned") over time?', ['Impurities stick to its surface and block it', 'It becomes a reactant', 'It turns into a product', 'Its activation energy increases'], 0, 'Impurities can coat the catalyst surface so reactant particles can no longer reach it, making it less effective.'),
    N('A catalyst reduces the activation energy of a reaction from 180 kJ/mol to 110 kJ/mol. By how much has it been lowered?', 70, 0, 'kJ/mol', ['Decrease = original − new', '= 180 − 110', '= 70 kJ/mol'], 'The catalyst lowers the peak of the reaction profile by 70 kJ/mol; the overall energy change is unchanged.'),
    O('Put these steps in order to show that MnO<sub>2</sub> is a catalyst for decomposing hydrogen peroxide.', ['Weigh a sample of MnO<sub>2</sub>', 'Add it to hydrogen peroxide and observe fast bubbling', 'Filter, wash and dry the MnO<sub>2</sub> after the reaction', 'Reweigh it to show its mass is unchanged'], 'Show it speeds up the reaction, then recover and weigh it to prove it was not used up.'),
  ] },
  { name: 'Reversible reactions & equilibrium', intro: 'Some reactions are reversible (⇌). In a closed system, equilibrium is reached when forward and reverse reactions occur at the same rate. HT: Le Chatelier\'s principle predicts how changing conditions shifts the equilibrium.', items: [
    M('What does the symbol ⇌ show?', ['The reaction is reversible', 'The reaction is fast', 'The reaction is exothermic', 'A catalyst is used'], 0, 'Products can react to re-form the reactants.'),
    M('What is true at dynamic equilibrium?', ['The forward and reverse reactions occur at the same rate', 'Both reactions have stopped', 'Only products are present', 'Concentrations of reactants and products are equal'], 0, 'Both reactions continue at equal rates, so concentrations stay constant (they are not necessarily equal).'),
    M('Equilibrium can only be reached…', ['In a closed system', 'In an open beaker', 'With a catalyst', 'At high temperature'], 0, 'In an open system products (e.g. gases) escape, so the reverse reaction cannot keep pace.'),
    M('Blue hydrated copper sulfate is heated and turns white. Water is added to the white solid. What happens?', ['It turns blue and gets hot', 'It stays white', 'It turns blue and gets cold', 'It turns black'], 0, 'The forward reaction is endothermic, so the reverse is exothermic by the same amount — adding water releases heat.'),
    T('If a reversible reaction is exothermic in one direction, it is endothermic in the other by the same amount.', true, 'True. The same energy is transferred in each direction.'),
    M('HT: N<sub>2</sub> + 3H<sub>2</sub> ⇌ 2NH<sub>3</sub>. What happens to the yield of ammonia if pressure is increased?', ['It increases — equilibrium shifts to fewer gas molecules', 'It decreases', 'No change', 'The reaction stops'], 0, 'Left has 4 gas molecules, right has 2. Higher pressure favours the side with fewer molecules.'),
    M('HT: The forward reaction is exothermic. What happens to the equilibrium yield of product if temperature is increased?', ['It decreases — the endothermic (reverse) direction is favoured', 'It increases', 'No change', 'It doubles'], 0, 'Raising temperature shifts equilibrium in the endothermic direction to absorb the extra energy.'),
    M('HT: What happens to equilibrium if more reactant is added?', ['It shifts to the right, making more product', 'It shifts to the left', 'No change', 'The reaction stops'], 0, 'The system counteracts the change by using up the extra reactant.'),
    M('HT: For H<sub>2</sub> + I<sub>2</sub> ⇌ 2HI (all gases), what is the effect of increasing pressure on equilibrium?', ['No change — equal numbers of gas molecules on each side', 'Shifts right', 'Shifts left', 'Stops the reaction'], 0, '2 molecules on each side, so pressure does not affect the position.'),
    S('HT: Whose principle states that a system at equilibrium will counteract a change in conditions?', 'Le Chatelier', ['le chatelier', 'le chateliers', 'chatelier', 'le chateliers principle'], 'Le Chatelier\'s principle predicts the direction an equilibrium shifts.', [['chatelier']]),
    M('Ammonium chloride is heated: NH<sub>4</sub>Cl ⇌ NH<sub>3</sub> + HCl. What forms at the cool top of the test tube?', ['White solid ammonium chloride re-forms', 'Liquid ammonia', 'Chlorine gas', 'Nothing'], 0, 'The gases recombine in the cooler region — the reverse reaction.'),
    M('Why does the Haber process use 450 °C, though a lower temperature would give a higher yield?', ['Lower temperatures make the rate too slow — 450 °C is a compromise', 'Higher temperature increases yield', 'The catalyst melts below 450 °C', 'Ammonia only forms above 450 °C'], 0, 'The forward reaction is exothermic, so low temperature favours yield but rate would be uneconomically slow.'),
    T('At equilibrium, the concentrations of reactants and products are always equal.', false, 'False. They are constant, but not necessarily equal; the position depends on conditions.'),
    M('HT: Why is very high pressure not used in the Haber process?', ['It is expensive and dangerous to maintain', 'It reduces yield', 'It stops the catalyst working', 'It makes the reaction endothermic'], 0, '200 atm balances good yield against cost and safety of equipment.'),
    X('HT: Which TWO changes would increase the equilibrium yield of NH<sub>3</sub> (forward reaction exothermic)?', ['Increase pressure', 'Decrease temperature', 'Add a catalyst', 'Increase temperature', 'Decrease pressure'], [0, 1], 'Fewer gas molecules on the right → high pressure. Exothermic forward → low temperature. Catalysts do not change yield.'),
    M('What is a closed system?', ['A system where no substances can get in or out', 'A system with no reactions', 'A system where gases can escape', 'A system at room temperature'], 0, 'In a closed system nothing is added or lost, so both forward and reverse reactions can continue and reach equilibrium.'),
    M('White anhydrous copper sulfate turns blue when water is added. What does this reaction show?', ['It can be used to test for water', 'It is a test for carbon dioxide', 'It is an irreversible reaction', 'It produces oxygen'], 0, 'Anhydrous copper sulfate turning blue is a test for water. The reaction is reversible: heating blue copper sulfate turns it white again.'),
    M('Heating blue hydrated copper sulfate is endothermic. What is the energy change when water is added to the white solid?', ['Exothermic — the same amount of energy is given out', 'Endothermic — energy is taken in', 'No energy change', 'Exothermic — twice as much energy is given out'], 0, 'If a reaction is endothermic in one direction, it is exothermic in the reverse direction, transferring the same amount of energy.'),
    M('At dynamic equilibrium, which statement is correct?', ['The forward and reverse reactions continue at equal rates', 'Both reactions have stopped', 'Only the forward reaction occurs', 'All reactants have become products'], 0, '"Dynamic" means both reactions are still happening, but at the same rate, so the amounts of reactants and products stay constant.'),
    M('HT: For 2SO<sub>2</sub> + O<sub>2</sub> ⇌ 2SO<sub>3</sub> (all gases), what happens if pressure is increased?', ['The equilibrium shifts right, towards SO<sub>3</sub>', 'The equilibrium shifts left', 'No change', 'The reaction stops'], 0, 'Left side: 3 molecules of gas; right side: 2. Increasing pressure favours the side with fewer gas molecules, so more SO<sub>3</sub> forms.'),
    M('HT: For N<sub>2</sub>O<sub>4</sub> ⇌ 2NO<sub>2</sub> (forward reaction endothermic), what happens to the equilibrium when temperature increases?', ['It shifts right, producing more NO<sub>2</sub>', 'It shifts left, producing more N<sub>2</sub>O<sub>4</sub>', 'No change', 'Both reactions stop'], 0, 'Raising temperature favours the endothermic direction, which here is the forward reaction, so more NO<sub>2</sub> forms.'),
    M('HT: Product is removed from an equilibrium mixture as it forms. What happens?', ['The equilibrium shifts right to make more product', 'The equilibrium shifts left', 'Nothing changes', 'The reaction becomes irreversible'], 0, 'Removing product lowers its concentration; the system responds by making more product to counteract the change.'),
    T('HT: Adding a catalyst changes the position of equilibrium.', false, 'False. A catalyst speeds up the forward and reverse reactions equally, so equilibrium is reached faster but its position is unchanged.'),
    T('Equilibrium can be approached from either direction — starting from reactants or from products.', true, 'True. In a closed system the same equilibrium mixture is reached whether you start with reactants or products (under the same conditions).'),
    T('HT: If the temperature of a system at equilibrium is decreased, the equilibrium shifts in the exothermic direction.', true, 'True. Lowering the temperature favours the exothermic reaction, which releases energy to counteract the change.'),
    S('What symbol is used in equations to show a reversible reaction?', 'reversible arrow (⇌)', ['reversible arrow', 'double arrow', 'two half arrows', 'equilibrium arrow'], 'The ⇌ symbol (two half-arrows) shows a reaction that can go both forwards and backwards.', [['arrow', 'arrows']]),
    X('HT: For CO + 2H<sub>2</sub> ⇌ CH<sub>3</sub>OH (all gases; forward exothermic), which TWO changes would increase the yield of methanol?', ['Increasing the pressure', 'Decreasing the temperature', 'Increasing the temperature', 'Decreasing the pressure', 'Adding a catalyst'], [0, 1], 'Left side 3 gas molecules, right side 1, so high pressure favours methanol. The forward reaction is exothermic, so lower temperature favours it. A catalyst does not change yield.'),
    M('HT: For H<sub>2</sub> + Cl<sub>2</sub> ⇌ 2HCl (all gases), why does changing pressure have no effect on the yield?', ['There are equal numbers of gas molecules on each side', 'HCl is a liquid', 'The reaction is not reversible', 'Pressure only affects solids'], 0, 'Both sides have 2 molecules of gas, so neither side reduces pressure — the equilibrium position does not change.'),
    M('Ammonium chloride decomposes when heated and reforms on cooling. Which pair of observations shows this?', ['White solid disappears at the hot end and reappears at the cool end', 'Bubbles form and the solid turns blue', 'A brown gas forms and stays', 'The solid melts and stays liquid'], 0, 'NH<sub>4</sub>Cl → NH<sub>3</sub> + HCl when hot; the gases recombine to white NH<sub>4</sub>Cl solid at the cooler part of the tube.'),
    O('HT: Put these in order to describe what happens when the concentration of a reactant at equilibrium is increased.', ['Extra reactant is added', 'The rate of the forward reaction increases', 'More product forms', 'A new equilibrium is reached with more product'], 'Increasing reactant concentration speeds up the forward reaction until the forward and reverse rates become equal again, at a new position with more product.'),
  ] },
], {
  overview: 'Chemists control how fast reactions go and how much product they give. <b>Collision theory</b> explains the effect of temperature, concentration, pressure, surface area and catalysts. Many reactions are <b>reversible</b>, reaching <b>equilibrium</b> in a closed system.',
  objectives: ['I can calculate mean rates (and HT: rates from tangents)', 'I can explain the effect of each factor on rate using collision theory', 'I can describe the rate required practical', 'I can explain how catalysts work', 'I can describe dynamic equilibrium and (HT) predict effects using Le Chatelier\'s principle'],
  keyWords: [{ term: 'Rate of reaction', def: 'How quickly reactants are used up or products formed.' }, { term: 'Collision theory', def: 'Reactions occur when particles collide with sufficient energy.' }, { term: 'Activation energy', def: 'Minimum energy for a collision to result in reaction.' }, { term: 'Catalyst', def: 'Speeds up a reaction without being used up; lowers activation energy.' }, { term: 'Reversible reaction', def: 'A reaction where products can re-form reactants (⇌).' }, { term: 'Dynamic equilibrium', def: 'Forward and reverse rates are equal in a closed system.' }, { term: 'Le Chatelier\'s principle', def: 'A system at equilibrium shifts to oppose a change in conditions.' }],
  sections: [
    { title: 'Measuring and calculating rate', html: `<div class="rule">mean rate = quantity of product formed ÷ time taken</div><p>Methods: gas syringe volume, mass loss on a balance, time for a cross to disappear (precipitate).</p><div class="worked"><div class="wq">48 cm³ of gas is produced in 60 s. Mean rate?</div><ol><li>48 ÷ 60</li></ol><div class="wa">Answer: 0.8 cm³/s</div></div><p>HT: rate at a time = gradient of tangent to the curve.</p>` },
    { title: 'Collision theory and factors', html: `<table class="qt"><tr><th>Factor increased</th><th>Effect</th></tr><tr><td>Concentration / pressure</td><td>More particles per volume → more frequent collisions</td></tr><tr><td>Surface area</td><td>More exposed particles → more frequent collisions</td></tr><tr><td>Temperature</td><td>Faster particles → more frequent collisions AND more with energy ≥ E<sub>a</sub></td></tr><tr><td>Catalyst</td><td>Lower E<sub>a</sub> → more successful collisions</td></tr></table>` },
    { title: 'Required practical: rate and concentration', html: `<p>Sodium thiosulfate + hydrochloric acid gives a sulfur precipitate. Time how long until a cross under the flask disappears, for several concentrations. Alternatively collect gas from magnesium + acid in a gas syringe. Rate ∝ 1/time.</p>` },
    { title: 'Reversible reactions and equilibrium', html: `<p>A ⇌ B. In a closed system, equilibrium is reached when forward and reverse rates are equal. Energy: exothermic one way = endothermic the other (e.g. hydrated copper sulfate ⇌ anhydrous copper sulfate + water).</p><div class="rule">HT Le Chatelier: ↑ concentration of reactant → more product; ↑ temperature → endothermic direction favoured; ↑ pressure → side with fewer gas molecules favoured</div>` },
  ],
  mistakes: ['Saying higher concentration gives particles more energy.', 'Saying catalysts increase yield.', 'Saying reactions stop at equilibrium.', 'Forgetting the energy part of the temperature explanation.'],
  examTips: ['Use the phrase "more frequent successful collisions" — "more collisions" alone may not score.', 'For temperature, give both effects for full marks.', 'In Le Chatelier questions, count gas molecules on each side and state the direction of shift.'],
  realLife: 'Food is kept in fridges because lowering the temperature slows the reactions that make it go off.',
});

// =====================================================================
// YEAR 11 — Organic chemistry (AQA 4.7)
// =====================================================================
topic({ id: 'chem-y11-organic', strand: 'chem-organic', year: 11, term: 1, tier: 'FH', name: 'Organic Chemistry',
  summary: 'Crude oil, alkanes and fractional distillation, cracking and alkenes, and (chemistry only) alcohols, carboxylic acids and polymers.', specRef: 'AQA 8462 4.7.1–4.7.3' }, [
  { name: 'Crude oil, alkanes & fractional distillation', intro: 'Crude oil is a finite mixture of hydrocarbons, mostly alkanes (C<sub>n</sub>H<sub>2n+2</sub>). Fractional distillation separates it into fractions with similar boiling points.', items: [
    M('What is a hydrocarbon?', ['A compound of hydrogen and carbon only', 'A compound containing water and carbon', 'Any compound containing carbon', 'A mixture of hydrogen and carbon'], 0, 'Hydrocarbons contain hydrogen and carbon atoms ONLY. Ethanol (contains O) is not a hydrocarbon.'),
    M('What is the general formula of the alkanes?', ['C<sub>n</sub>H<sub>2n+2</sub>', 'C<sub>n</sub>H<sub>2n</sub>', 'C<sub>n</sub>H<sub>2n−2</sub>', 'C<sub>n</sub>H<sub>n</sub>'], 0, 'Alkanes are saturated: e.g. ethane C<sub>2</sub>H<sub>6</sub> (n = 2, 2n + 2 = 6). C<sub>n</sub>H<sub>2n</sub> is the alkenes.'),
    O('Put the first four alkanes in order of increasing chain length.', ['Methane', 'Ethane', 'Propane', 'Butane'], 'Mnemonic "Monkeys Eat Peanut Butter": 1, 2, 3, 4 carbon atoms.'),
    S('What is the formula of propane?', 'C3H8', ['c3h8'], 'n = 3: C<sub>3</sub>H<sub>2×3+2</sub> = C<sub>3</sub>H<sub>8</sub>.'),
    M('How was crude oil formed?', ['From the remains of ancient biomass (mainly plankton) buried in mud over millions of years', 'From volcanic lava', 'From dinosaurs only', 'From limestone'], 0, 'Plankton remains were buried and changed by heat and pressure — that is why oil is finite.'),
    M('In a fractionating column, where are the fractions with the lowest boiling points collected?', ['At the top', 'At the bottom', 'In the middle', 'They are not collected'], 0, 'The column is hotter at the bottom and cooler at the top; small molecules with low boiling points rise highest before condensing.'),
    M('As alkane chain length increases, what happens to viscosity?', ['It increases', 'It decreases', 'No change', 'It becomes zero'], 0, 'Longer chains → stronger intermolecular forces → thicker (more viscous) liquids.'),
    M('Which property increases as hydrocarbon chain length DECREASES?', ['Flammability', 'Boiling point', 'Viscosity', 'Melting point'], 0, 'Short-chain hydrocarbons are more volatile and flammable — e.g. LPG vs bitumen.'),
    X('Which TWO fractions are used as fuels for vehicles?', ['Petrol', 'Diesel oil', 'Bitumen', 'Lubricating oil', 'Polymers'], [0, 1], 'Petrol and diesel fuel cars; kerosene fuels aircraft. Bitumen surfaces roads.'),
    T('Alkanes are saturated hydrocarbons.', true, 'True. They contain only single C–C bonds.'),
    M('What are the products of complete combustion of propane?', ['Carbon dioxide and water', 'Carbon monoxide and water', 'Carbon and hydrogen', 'Propene and water'], 0, 'C<sub>3</sub>H<sub>8</sub> + 5O<sub>2</sub> → 3CO<sub>2</sub> + 4H<sub>2</sub>O.'),
    M('Which is the balanced equation for the complete combustion of ethane?', ['2C<sub>2</sub>H<sub>6</sub> + 7O<sub>2</sub> → 4CO<sub>2</sub> + 6H<sub>2</sub>O', 'C<sub>2</sub>H<sub>6</sub> + O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O', 'C<sub>2</sub>H<sub>6</sub> + 3O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O', '2C<sub>2</sub>H<sub>6</sub> + 5O<sub>2</sub> → 4CO + 6H<sub>2</sub>O'], 0, 'Products need 4 C (4CO<sub>2</sub>), 12 H (6H<sub>2</sub>O) and 8 + 6 = 14 O, so 7O<sub>2</sub>. Option 3 has only 6 O on the left but 7 on the right; option 4 shows incomplete combustion (CO).'),
    T('Crude oil is a renewable resource.', false, 'False. It takes millions of years to form, so it is finite (non-renewable).'),
    S('What name is given to a group of compounds with the same general formula and similar chemical properties?', 'homologous series', ['homologous series', 'homologous'], 'Alkanes, alkenes, alcohols and carboxylic acids are homologous series.', [['homologous']]),
    M('Why does fractional distillation work for crude oil?', ['The hydrocarbons have different boiling points', 'They have different colours', 'They react with the column', 'They are different densities only'], 0, 'Each fraction condenses at a different height where the temperature is just below its boiling point.'),
    M('What is the formula of butane?', ['C<sub>4</sub>H<sub>10</sub>', 'C<sub>4</sub>H<sub>8</sub>', 'C<sub>4</sub>H<sub>12</sub>', 'C<sub>3</sub>H<sub>8</sub>'], 0, 'Using C<sub>n</sub>H<sub>2n+2</sub> with n = 4 gives C<sub>4</sub>H<sub>10</sub>. C<sub>4</sub>H<sub>8</sub> is butene (an alkene); C<sub>3</sub>H<sub>8</sub> is propane.'),
    M('An alkane has 8 carbon atoms. How many hydrogen atoms does it have?', ['18', '16', '17', '20'], 0, 'C<sub>n</sub>H<sub>2n+2</sub>: 2 × 8 + 2 = 18. This is octane, C<sub>8</sub>H<sub>18</sub>, found in petrol.'),
    M('As alkane chain length increases, what happens to the boiling point?', ['It increases', 'It decreases', 'It stays the same', 'It falls then rises'], 0, 'Longer molecules have stronger intermolecular forces, so more energy is needed to separate them — boiling point rises.'),
    M('As alkane chain length increases, what happens to flammability?', ['It decreases', 'It increases', 'It stays the same', 'Long alkanes cannot burn at all'], 0, 'Short-chain alkanes are very flammable (e.g. methane, petrol). Long-chain ones such as bitumen are hard to ignite, although they can still burn.'),
    M('Which fraction from crude oil is used to surface roads?', ['Bitumen', 'Petrol', 'Kerosene', 'Liquefied petroleum gases'], 0, 'Bitumen has very long chains, a very high boiling point and is thick and sticky — ideal for road surfaces and roofing.'),
    M('Which fraction is used as fuel for aircraft?', ['Kerosene', 'Bitumen', 'Heavy fuel oil', 'Diesel oil'], 0, 'Kerosene (paraffin) is jet fuel. Diesel is used in lorries and some cars; heavy fuel oil in ships.'),
    M('In fractional distillation, what is the temperature gradient in the column?', ['Hot at the bottom, cooler at the top', 'Cool at the bottom, hot at the top', 'The same temperature throughout', 'Hottest in the middle'], 0, 'The column is hottest at the bottom and coolest at the top. Each fraction condenses at the level where the temperature falls below its boiling point.'),
    T('Crude oil is mainly a mixture of compounds made of hydrogen and carbon only.', true, 'True. Crude oil is mainly hydrocarbons, most of which are alkanes.'),
    T('In an alkane, carbon atoms are joined by C=C double bonds.', false, 'False. Alkanes contain only single C–C bonds; they are saturated. Alkenes contain a C=C double bond.'),
    T('Many useful materials, such as solvents, lubricants and polymers, are made from crude oil.', true, 'True. The petrochemical industry uses crude oil fractions as feedstock for many products, not just fuels.'),
    S('What is the name of the alkane with the formula C<sub>2</sub>H<sub>6</sub>?', 'ethane', ['ethane'], 'Meth- (1), eth- (2), prop- (3), but- (4). C<sub>2</sub>H<sub>6</sub> is ethane.'),
    S('What is the name of the process that separates crude oil into fractions?', 'fractional distillation', ['fractional distillation'], 'Crude oil is heated until it vaporises; the vapours rise and condense at different levels according to boiling point.', [['fractional'], ['distillation', 'distilation']]),
    X('Which TWO are properties of short-chain hydrocarbons compared with long-chain ones?', ['Lower boiling point', 'More flammable', 'More viscous', 'Higher boiling point', 'Less volatile'], [0, 1], 'Short-chain hydrocarbons have weaker intermolecular forces, so lower boiling points, and they ignite more easily. They are less viscous and more volatile.'),
    N('How many hydrogen atoms are in an alkane with 12 carbon atoms?', 26, 0, 'atoms', ['General formula C<sub>n</sub>H<sub>2n+2</sub>', '2 × 12 + 2', '= 26 hydrogen atoms'], 'C<sub>12</sub>H<sub>26</sub> is an alkane found in the kerosene/diesel range.'),
    M('Which is the balanced equation for complete combustion of methane?', ['CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O', 'CH<sub>4</sub> + O<sub>2</sub> → CO<sub>2</sub> + H<sub>2</sub>O', 'CH<sub>4</sub> + 2O<sub>2</sub> → CO + 2H<sub>2</sub>O', '2CH<sub>4</sub> + O<sub>2</sub> → 2CO<sub>2</sub> + 4H<sub>2</sub>'], 0, 'Check atoms: C 1 = 1; H 4 = 4; O 4 = 2 + 2. Carbon monoxide would be incomplete combustion.'),
  ] },
  { name: 'Cracking & alkenes', intro: 'Cracking breaks long-chain alkanes into shorter, more useful alkanes and alkenes. Alkenes (C<sub>n</sub>H<sub>2n</sub>) have a C=C double bond and decolourise bromine water.', items: [
    M('What is cracking?', ['Breaking long-chain hydrocarbons into shorter, more useful ones', 'Burning hydrocarbons', 'Joining small molecules into polymers', 'Separating crude oil by boiling point'], 0, 'Cracking is a thermal decomposition reaction. Fractional distillation separates; polymerisation joins.'),
    X('Which TWO are methods of cracking?', ['Catalytic cracking (hot catalyst)', 'Steam cracking (high temperature with steam)', 'Fractional distillation', 'Electrolysis', 'Fermentation'], [0, 1], 'Catalytic cracking passes vapour over a hot catalyst; steam cracking mixes with steam at very high temperature.'),
    M('Why is cracking needed?', ['Demand for short-chain fuels is higher than supply from crude oil', 'Long chains are more flammable', 'To make crude oil', 'To make carbon dioxide'], 0, 'Crude oil contains more long-chain fractions than needed; cracking turns them into petrol and alkenes for polymers.'),
    M('What is the test for an alkene?', ['Bromine water turns from orange to colourless', 'Limewater turns milky', 'Glowing splint relights', 'Universal indicator turns purple'], 0, 'Bromine adds across the C=C bond. Alkanes leave bromine water orange.'),
    M('What is the general formula of alkenes?', ['C<sub>n</sub>H<sub>2n</sub>', 'C<sub>n</sub>H<sub>2n+2</sub>', 'C<sub>n</sub>H<sub>n</sub>', 'C<sub>n</sub>H<sub>2n+1</sub>OH'], 0, 'One C=C means two fewer H than the alkane: ethene C<sub>2</sub>H<sub>4</sub>.'),
    M('Complete: C<sub>10</sub>H<sub>22</sub> → C<sub>8</sub>H<sub>18</sub> + ___', ['C<sub>2</sub>H<sub>4</sub>', 'C<sub>2</sub>H<sub>6</sub>', 'C<sub>2</sub>H<sub>2</sub>', 'CH<sub>4</sub>'], 0, 'Carbon: 10 − 8 = 2; hydrogen: 22 − 18 = 4 → C<sub>2</sub>H<sub>4</sub> (ethene).'),
    S('What word describes alkenes because they contain a C=C double bond?', 'unsaturated', ['unsaturated'], 'Unsaturated = contains a carbon–carbon double bond; can undergo addition reactions.'),
    T('Alkenes are more reactive than alkanes.', true, 'True. The C=C double bond allows addition reactions.'),
    M('Chemistry only: what forms when ethene reacts with hydrogen (nickel catalyst)?', ['Ethane', 'Ethanol', 'Ethanoic acid', 'Poly(ethene)'], 0, 'Hydrogenation: C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub>.'),
    M('Chemistry only: what forms when ethene reacts with steam (catalyst)?', ['Ethanol', 'Ethane', 'Ethanoic acid', 'Ethene oxide'], 0, 'C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O → C<sub>2</sub>H<sub>5</sub>OH, an industrial way to make ethanol.'),
    M('Chemistry only: what forms when ethene reacts with bromine?', ['1,2-dibromoethane', 'Bromoethene', 'Ethane', 'Hydrogen bromide'], 0, 'Bromine adds across the double bond: one Br on each carbon.'),
    M('Why do alkenes burn with smoky flames?', ['They often undergo incomplete combustion', 'They contain oxygen', 'They are saturated', 'They contain nitrogen'], 0, 'Higher carbon-to-hydrogen ratio means more incomplete combustion, giving soot.'),
    M('What is the formula of propene?', ['C<sub>3</sub>H<sub>6</sub>', 'C<sub>3</sub>H<sub>8</sub>', 'C<sub>3</sub>H<sub>4</sub>', 'C<sub>2</sub>H<sub>4</sub>'], 0, 'n = 3: C<sub>3</sub>H<sub>6</sub>.'),
    T('Cracking produces only alkenes.', false, 'False. Cracking produces a shorter alkane AND an alkene (sometimes hydrogen too).'),
    X('Which TWO are uses of the alkenes made by cracking?', ['Making polymers', 'Starting materials for other chemicals', 'Road surfacing', 'Making crude oil', 'Fertiliser'], [0, 1], 'Alkenes are used to make polymers and as feedstock for other chemicals.'),
    M('Why are catalysts used in catalytic cracking?', ['They allow cracking to happen at a lower temperature and faster', 'They increase the size of the molecules', 'They turn alkenes into alkanes', 'They are used up to make the products'], 0, 'A hot powdered catalyst (e.g. zeolite) lets the long molecules break apart quickly at a lower temperature than without it.'),
    M('In steam cracking, what conditions are used?', ['The hydrocarbon vapour is mixed with steam at a very high temperature', 'The hydrocarbon is cooled with ice', 'The hydrocarbon is dissolved in water at room temperature', 'The hydrocarbon is mixed with bromine'], 0, 'Steam cracking mixes the vapour with steam and heats it to a very high temperature, breaking the long chains.'),
    M('What colour change happens when bromine water is added to an alkane?', ['None — it stays orange', 'Orange to colourless', 'Colourless to orange', 'Orange to blue'], 0, 'Alkanes are saturated and do not react with bromine water, so it stays orange. Alkenes decolourise it.'),
    M('Complete the cracking equation: C<sub>12</sub>H<sub>26</sub> → C<sub>8</sub>H<sub>18</sub> + 2___', ['C<sub>2</sub>H<sub>4</sub>', 'C<sub>4</sub>H<sub>8</sub>', 'C<sub>2</sub>H<sub>6</sub>', 'CH<sub>4</sub>'], 0, 'Remaining atoms: C 12 − 8 = 4, H 26 − 18 = 8. Split into 2 molecules: each is C<sub>2</sub>H<sub>4</sub> (ethene).'),
    M('What is the functional group in alkenes?', ['C=C double bond', 'C–C single bond', '–OH', '–COOH'], 0, 'The carbon–carbon double bond is the functional group of alkenes; it makes them more reactive than alkanes.'),
    M('Chemistry only: ethene reacts with hydrogen to form ethane. What is this type of reaction called?', ['Addition (hydrogenation)', 'Substitution', 'Combustion', 'Cracking'], 0, 'Atoms add across the double bond, which becomes a single bond: an addition reaction. With hydrogen it is called hydrogenation.'),
    T('Alkenes are unsaturated because they could have more hydrogen atoms added across the double bond.', true, 'True. The C=C double bond can open up to add atoms, so alkenes are unsaturated.'),
    T('Cracking is an example of thermal decomposition.', true, 'True. Cracking breaks large molecules into smaller ones using heat, so it is a thermal decomposition reaction.'),
    T('Ethene has the formula C<sub>2</sub>H<sub>6</sub>.', false, 'False. Ethene is C<sub>2</sub>H<sub>4</sub> (C<sub>n</sub>H<sub>2n</sub>). C<sub>2</sub>H<sub>6</sub> is ethane, an alkane.'),
    S('Name the alkene with the formula C<sub>2</sub>H<sub>4</sub>.', 'ethene', ['ethene', 'ethylene'], 'C<sub>2</sub>H<sub>4</sub> is ethene, the simplest alkene. It is used to make poly(ethene) and ethanol.'),
    S('Chemistry only: name the product when propene reacts with steam.', 'propanol', ['propanol', 'propan-1-ol', 'propan-2-ol', 'propan 1 ol', 'propan 2 ol'], 'Adding water (steam) across the double bond of an alkene gives an alcohol. Propene + steam → propanol.', [['propanol', 'propan']]),
    X('Chemistry only: which TWO substances can react with alkenes in addition reactions?', ['Hydrogen', 'Bromine', 'Neon', 'Nitrogen', 'Carbon dioxide'], [0, 1], 'Hydrogen, water (steam) and halogens such as bromine add across the C=C bond. Neon, nitrogen and carbon dioxide do not.'),
    M('Chemistry only: what is the product of ethene reacting with chlorine?', ['Dichloroethane', 'Chloroethene', 'Ethane', 'Ethanol'], 0, 'Both chlorine atoms add across the double bond, one to each carbon, giving 1,2-dichloroethane (C<sub>2</sub>H<sub>4</sub>Cl<sub>2</sub>).'),
    N('An alkene has 5 carbon atoms. How many hydrogen atoms does it have?', 10, 0, 'atoms', ['General formula of alkenes: C<sub>n</sub>H<sub>2n</sub>', '2 × 5', '= 10 hydrogen atoms (pentene, C<sub>5</sub>H<sub>10</sub>)'], 'Alkenes have twice as many hydrogen atoms as carbon atoms.'),
    O('Put these steps in order to describe the catalytic cracking of a long-chain alkane.', ['Heat the long-chain alkane to vaporise it', 'Pass the vapour over a hot catalyst', 'Bonds in the long molecules break', 'Shorter alkanes and alkenes are formed'], 'The alkane is vaporised, passed over a hot catalyst, and thermally decomposes into smaller, more useful molecules.'),
  ] },
  { name: 'Alcohols, carboxylic acids & polymers', intro: 'Chemistry only. Alcohols contain –OH; carboxylic acids contain –COOH; they react to form esters. Addition polymers form from alkenes; condensation polymers (HT) from monomers with two functional groups.', items: [
    M('What is the functional group of alcohols?', ['–OH', '–COOH', 'C=C', '–COO–'], 0, 'Alcohols contain the hydroxyl group –OH. –COOH is carboxylic acid; –COO– is ester.'),
    O('Put the first four alcohols in order of chain length.', ['Methanol', 'Ethanol', 'Propanol', 'Butanol'], 'Methanol CH<sub>3</sub>OH, ethanol C<sub>2</sub>H<sub>5</sub>OH, propanol C<sub>3</sub>H<sub>7</sub>OH, butanol C<sub>4</sub>H<sub>9</sub>OH.'),
    M('How is ethanol produced by fermentation?', ['Yeast converts sugar solution to ethanol and CO<sub>2</sub> at about 30 °C, without air', 'Heating ethene with steam', 'Cracking crude oil', 'Electrolysis of water'], 0, 'Anaerobic conditions; warm but not too hot or yeast enzymes denature.'),
    M('What forms when ethanol is oxidised?', ['Ethanoic acid', 'Ethene', 'Ethane', 'Methanol'], 0, 'Oxidising agents (or microbes in air) turn ethanol into ethanoic acid — wine going sour to vinegar.'),
    M('What is produced when sodium reacts with ethanol?', ['Hydrogen', 'Oxygen', 'Carbon dioxide', 'Chlorine'], 0, 'Sodium fizzes gently, releasing hydrogen (less violently than with water).'),
    M('What is the functional group of carboxylic acids?', ['–COOH', '–OH', 'C=C', 'NH<sub>2</sub>'], 0, 'E.g. ethanoic acid CH<sub>3</sub>COOH.'),
    M('What gas is produced when ethanoic acid reacts with sodium carbonate?', ['Carbon dioxide', 'Hydrogen', 'Oxygen', 'Ethene'], 0, 'Carboxylic acids are acids: acid + carbonate → salt + water + CO<sub>2</sub>.'),
    S('What type of compound forms when ethanol reacts with ethanoic acid (acid catalyst)?', 'ester', ['ester', 'an ester', 'ethyl ethanoate'], 'The ester ethyl ethanoate forms, used in perfumes and flavourings.', [['ester', 'ethanoate']]),
    T('Carboxylic acids are weak acids.', true, 'True. They only partially ionise, so they have a higher pH than strong acids of the same concentration.'),
    M('What is the monomer of poly(ethene)?', ['Ethene', 'Ethane', 'Ethanol', 'Propene'], 0, 'Addition polymerisation: many ethene molecules join as the C=C opens.'),
    M('In addition polymerisation, what else forms besides the polymer?', ['Nothing — the polymer is the only product', 'Water', 'Hydrogen chloride', 'Carbon dioxide'], 0, 'All atoms of the monomers end up in the polymer.'),
    M('HT: What is released in condensation polymerisation?', ['A small molecule such as water', 'Nothing', 'Ethene', 'Oxygen'], 0, 'Monomers with two functional groups join, releasing a small molecule (often water) at each link.'),
    M('What type of monomers make proteins?', ['Amino acids', 'Glucose', 'Nucleotides', 'Ethene'], 0, 'Amino acids (with –NH<sub>2</sub> and –COOH) join by condensation polymerisation to make proteins.'),
    X('Which TWO are naturally occurring polymers?', ['DNA', 'Starch', 'Poly(ethene)', 'PVC', 'Ethanol'], [0, 1], 'DNA (nucleotides), starch and cellulose (sugars) and proteins (amino acids) are natural polymers.'),
    M('Why is ethanol used as a fuel?', ['It burns cleanly releasing energy, and can be made from renewable sugar', 'It contains no carbon', 'It is a carboxylic acid', 'It is a solid'], 0, 'Ethanol from fermentation is a biofuel; it still releases CO<sub>2</sub> when burned.'),
    M('What is the formula of ethanol?', ['C<sub>2</sub>H<sub>5</sub>OH', 'CH<sub>3</sub>OH', 'C<sub>2</sub>H<sub>6</sub>', 'CH<sub>3</sub>COOH'], 0, 'Ethanol has 2 carbons and the –OH group: C<sub>2</sub>H<sub>5</sub>OH. CH<sub>3</sub>OH is methanol; CH<sub>3</sub>COOH is ethanoic acid.'),
    M('What is the formula of ethanoic acid?', ['CH<sub>3</sub>COOH', 'C<sub>2</sub>H<sub>5</sub>OH', 'HCOOH', 'C<sub>2</sub>H<sub>4</sub>'], 0, 'Ethanoic acid has 2 carbon atoms including the one in –COOH: CH<sub>3</sub>COOH. HCOOH is methanoic acid.'),
    M('What are the products when ethanol burns completely in air?', ['Carbon dioxide and water', 'Ethanoic acid and water', 'Carbon and hydrogen', 'Ethene and water'], 0, 'Like hydrocarbons, alcohols burn completely to carbon dioxide and water: C<sub>2</sub>H<sub>5</sub>OH + 3O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O.'),
    M('Which conditions are used for fermentation?', ['Yeast, sugar solution, about 30 °C and no air', 'Yeast, sugar solution, 100 °C and plenty of air', 'A nickel catalyst at 60 °C', 'High pressure and an iron catalyst'], 0, 'Yeast enzymes work best at about 30–35 °C; air is kept out so the yeast respires anaerobically. Too hot denatures the enzymes; air would oxidise ethanol to ethanoic acid.'),
    M('What is the name of the ester formed from ethanol and ethanoic acid?', ['Ethyl ethanoate', 'Ethanoic ethanol', 'Ethyl ethanol', 'Methyl ethanoate'], 0, 'Esters are named from the alcohol (ethyl) and the acid (ethanoate): ethyl ethanoate. It is used as a solvent and in flavourings.'),
    M('What is the main property of esters that makes them useful in perfumes and flavourings?', ['They are volatile and have fruity smells', 'They are strong acids', 'They are polymers', 'They have very high boiling points'], 0, 'Esters evaporate easily (volatile) and have distinctive, often fruity smells.'),
    M('What is the repeating unit of poly(propene) formed from?', ['Propene monomers joined by opening the C=C bond', 'Propane monomers', 'Propanol and an acid', 'Amino acids'], 0, 'In addition polymerisation, the C=C bond of each propene opens and the monomers join into a long chain.'),
    T('Alcohols such as methanol and ethanol dissolve in water to form neutral solutions.', true, 'True. Short-chain alcohols are soluble in water and their solutions are neutral (pH 7).'),
    T('HT: DNA is a natural polymer made from four different monomers called nucleotides.', true, 'True. DNA is a large molecule made from four different nucleotide monomers, forming two polymer chains in a double helix.'),
    T('Ethanoic acid reacts with carbonates to produce hydrogen.', false, 'False. Like other acids, ethanoic acid reacts with carbonates to give a salt, water and carbon dioxide (fizzing).'),
    S('What is the functional group in carboxylic acids?', '–COOH', ['cooh', 'carboxyl', 'carboxyl group', 'co2h'], 'Carboxylic acids contain the –COOH group, which can lose an H<sup>+</sup> ion, making them (weak) acids.'),
    S('HT: What is the name for the small molecules that join together to make starch and cellulose?', 'glucose', ['glucose', 'sugars', 'sugar'], 'Starch and cellulose are natural condensation polymers made from glucose monomers.'),
    X('HT: Which TWO statements describe condensation polymerisation?', ['Monomers with two functional groups react together', 'A small molecule such as water is lost for each link formed', 'Monomers must contain a C=C double bond', 'The polymer is the only product', 'Only one type of monomer can ever be used'], [0, 1], 'Condensation polymers form from monomers with two functional groups each, losing a small molecule (often water) at each link. Addition polymers need C=C and give only the polymer.'),
    N('HT: How many molecules of water are released when 50 amino acids join to form a single protein chain?', 49, 0, 'molecules', ['Each peptide link formed releases one water molecule', 'A chain of 50 units has 50 − 1 links', '= 49 water molecules'], 'Joining n monomers in a single chain makes n − 1 links, and each condensation link releases one water molecule.'),
    O('Put these alcohols in order of increasing boiling point.', ['Methanol', 'Ethanol', 'Propanol', 'Butanol'], 'Boiling point rises as the chain gets longer because the intermolecular forces increase: methanol < ethanol < propanol < butanol.'),
  ] },
], {
  overview: 'Organic chemistry is the chemistry of carbon compounds. Crude oil provides <b>alkanes</b> for fuels; <b>cracking</b> makes extra petrol and reactive <b>alkenes</b>, which are used to make polymers. Chemistry students also study <b>alcohols</b>, <b>carboxylic acids</b> and natural and synthetic <b>polymers</b>.',
  objectives: ['I can describe how crude oil is formed and separated', 'I can name and draw the first four alkanes and explain property trends', 'I can describe cracking and the test for alkenes', 'Chemistry only: I can describe reactions of alkenes, alcohols and carboxylic acids', 'Chemistry only: I can describe addition and (HT) condensation polymerisation'],
  keyWords: [{ term: 'Hydrocarbon', def: 'Compound of hydrogen and carbon only.' }, { term: 'Alkane', def: 'Saturated hydrocarbon, CₙH₂ₙ₊₂.' }, { term: 'Alkene', def: 'Unsaturated hydrocarbon with C=C, CₙH₂ₙ.' }, { term: 'Fractional distillation', def: 'Separating crude oil into fractions by boiling point.' }, { term: 'Cracking', def: 'Breaking long hydrocarbons into shorter alkanes and alkenes.' }, { term: 'Functional group', def: 'Group of atoms that determines a compound\'s reactions, e.g. –OH.' }, { term: 'Polymer', def: 'Very long molecule made from many monomers.' }],
  sections: [
    { title: 'Crude oil and alkanes', html: `<p>Crude oil: finite mixture of hydrocarbons from ancient plankton. Alkanes C<sub>n</sub>H<sub>2n+2</sub>: methane CH<sub>4</sub>, ethane C<sub>2</sub>H<sub>6</sub>, propane C<sub>3</sub>H<sub>8</sub>, butane C<sub>4</sub>H<sub>10</sub>.</p><p>Fractional distillation: heat and vaporise; column hot at the bottom, cool at top; fractions condense at their boiling points. Fractions: LPG, petrol, kerosene, diesel, fuel oil, bitumen.</p>` },
    { title: 'Properties and combustion', html: `<p>As chain length increases: boiling point ↑, viscosity ↑, flammability ↓, volatility ↓.</p><div class="rule">Complete combustion: hydrocarbon + oxygen → carbon dioxide + water</div>` },
    { title: 'Cracking and alkenes', html: `<p>Cracking (catalytic or steam) is thermal decomposition: C<sub>10</sub>H<sub>22</sub> → C<sub>8</sub>H<sub>18</sub> + C<sub>2</sub>H<sub>4</sub>.</p><p>Alkenes C<sub>n</sub>H<sub>2n</sub> (ethene, propene, butene, pentene) decolourise orange <b>bromine water</b>. Chemistry only: addition reactions with H<sub>2</sub>, H<sub>2</sub>O and halogens.</p>` },
    { title: 'Alcohols and carboxylic acids (chemistry only)', html: `<p>Alcohols (–OH): dissolve in water (neutral), react with sodium to give hydrogen, burn, oxidise to carboxylic acids. Ethanol by fermentation of sugar with yeast (~30 °C, anaerobic).</p><p>Carboxylic acids (–COOH): weak acids, react with carbonates to give CO<sub>2</sub>, react with alcohols to give esters.</p>` },
    { title: 'Polymers (chemistry only)', html: `<p><b>Addition</b>: alkene monomers join; only one product. <b>Condensation</b> (HT): two functional groups, small molecule (water) lost. Natural polymers: proteins (amino acids), starch/cellulose (sugars), DNA (nucleotides).</p>` },
  ],
  mistakes: ['Mixing up alkane and alkene formulae.', 'Saying bromine water turns "clear" — say colourless.', 'Calling cracking "fractional distillation".', 'Forgetting that cracking gives an alkane AND an alkene.'],
  examTips: ['Use "colourless", not "clear", for the bromine water test.', 'When balancing cracking equations, check C and H totals.', 'For property trends, link chain length to intermolecular forces.'],
  realLife: 'The plastic bottle you drink from was probably made from ethene produced by cracking crude oil.',
});

// =====================================================================
// YEAR 11 — Chemical analysis (AQA 4.8)
// =====================================================================
function genRf(rng) {
  const front = ri(rng, 50, 100) / 10, spot = ri(rng, 5, Math.round(front * 10) - 3) / 10;
  const v = ri(rng, 0, 1);
  if (v === 0) {
    const rf = rd(spot / front, 2);
    return { type: 'number', q: `In a paper chromatogram, the solvent front moved ${front} cm from the start line and a spot moved ${spot} cm. Calculate the R<sub>f</sub> value (2 d.p.).`, value: rf, tol: 0.011, unit: '', answer: `${rf}`,
      steps: ['R<sub>f</sub> = distance moved by substance ÷ distance moved by solvent', `R<sub>f</sub> = ${spot} ÷ ${front}`, `R<sub>f</sub> = ${rf}`], explain: 'R<sub>f</sub> has no units and is always less than 1, because the substance cannot travel further than the solvent. Measure both distances from the start (pencil) line.', hint: 'Spot distance ÷ solvent distance.' };
  }
  const rf = ri(rng, 15, 90) / 100, d = rd(rf * front, 2);
  return { type: 'number', q: `A substance has an R<sub>f</sub> value of ${rf} in a solvent. If the solvent front moves ${front} cm, how far will the substance move (in cm, 2 d.p.)?`, value: d, tol: 0.011, unit: 'cm', answer: `${d} cm`,
    steps: ['distance moved by substance = R<sub>f</sub> × distance moved by solvent', `= ${rf} × ${front}`, `= ${d} cm`], explain: 'Rearrange R<sub>f</sub> = substance distance ÷ solvent distance.', hint: 'Multiply R<sub>f</sub> by the solvent distance.' };
}

topic({ id: 'chem-y11-analysis', strand: 'chem-analysis', year: 11, term: 2, tier: 'FH', name: 'Chemical Analysis',
  summary: 'Purity, formulations, chromatography and R<sub>f</sub> values, gas tests and (chemistry only) tests for ions and instrumental methods.', specRef: 'AQA 8462 4.8.1–4.8.3' }, [
  { name: 'Purity, formulations & chromatography', intro: 'A pure substance is a single element or compound with sharp melting and boiling points. Formulations are designed mixtures. Paper chromatography separates and identifies substances (required practical).', items: [
    M('How can melting point be used to test purity?', ['A pure substance melts at a sharp, fixed temperature; impurities lower it and give a range', 'Pure substances never melt', 'Impure substances melt at a higher sharp point', 'Melting point cannot test purity'], 0, 'Impurities lower the melting point and make the substance melt over a range.'),
    M('What is a formulation?', ['A mixture designed as a useful product with measured amounts of each component', 'A pure compound', 'A chemical formula', 'An impure accidental mixture'], 0, 'Examples: paints, medicines, fuels, cleaning agents, alloys, fertilisers, foods.'),
    X('Which TWO are formulations?', ['Paint', 'Medicine tablets', 'Distilled water', 'Pure gold', 'Oxygen gas'], [0, 1], 'Paints and medicines are carefully designed mixtures. Distilled water, pure gold and oxygen are pure substances.'),
    T('In chemistry, "pure" milk is a pure substance.', false, 'False. Milk is a mixture of water, fats, proteins and sugars; "pure" in advertising means nothing added.'),
    M('Why is the start line on a chromatogram drawn in pencil?', ['Pencil does not dissolve in the solvent and run', 'Pencil is easier to see', 'Ink is too expensive', 'Pencil speeds up the solvent'], 0, 'Ink would dissolve and separate, confusing the results; graphite is insoluble.'),
    M('Why must the start line be above the solvent level?', ['So the spots do not dissolve into the solvent in the beaker', 'So the solvent moves faster', 'So the paper does not tear', 'To keep the paper dry'], 0, 'If below, the samples would wash out into the solvent instead of travelling up the paper.'),
    M('In chromatography, what are the stationary and mobile phases?', ['Paper is stationary; solvent is mobile', 'Solvent is stationary; paper is mobile', 'Both are stationary', 'Ink is the mobile phase'], 0, 'The solvent moves through the paper, carrying substances different distances depending on their attraction to each phase.'),
    M('A pure substance on a chromatogram gives…', ['A single spot in all solvents', 'Several spots', 'No spots', 'A streak'], 0, 'One substance produces one spot. A mixture separates into several spots.'),
    M('An ink gives three spots. Two match known dyes A and B. What can you conclude?', ['The ink contains A, B and at least one other substance', 'The ink is pure', 'The ink contains only A and B', 'A and B are the same'], 0, 'The third spot does not match either known dye, so it is a different substance.'),
    M('Why does a substance with a high R<sub>f</sub> move further?', ['It is more soluble in the solvent / less attracted to the paper', 'It is heavier', 'It is less soluble in the solvent', 'It reacts with the paper'], 0, 'Substances spend more time in the mobile phase if they are more attracted to it.'),
    T('R<sub>f</sub> values can be greater than 1.', false, 'False. The substance can never move further than the solvent front, so R<sub>f</sub> ≤ 1.'),
    O('Put the chromatography required practical steps in order.', ['Draw a pencil start line near the bottom of the paper', 'Put small spots of each sample on the line', 'Stand the paper in solvent below the line, with a lid on', 'Remove when the solvent nears the top and mark the solvent front'], 'Then dry and calculate R<sub>f</sub> values.'),
    M('Why is a lid placed on the beaker during chromatography?', ['To stop the solvent evaporating', 'To keep light out', 'To speed up the solvent', 'To keep the paper flat'], 0, 'Evaporation would change how the solvent moves and could release fumes.'),
    S('What is the name for the line reached by the solvent at the end of the experiment?', 'solvent front', ['solvent front', 'the solvent front'], 'The solvent front must be marked immediately before the solvent evaporates.', [['front']]),
    M('A substance has R<sub>f</sub> 0.45 in water and a known compound has R<sub>f</sub> 0.45 in water. How could you be more certain they are the same?', ['Compare R<sub>f</sub> values in a different solvent too', 'Repeat with ink', 'Use a longer paper', 'Measure with a ruler only once'], 0, 'Different substances can share an R<sub>f</sub> in one solvent; matching in two solvents is stronger evidence.'),
    M('A sample of water boils at 102 °C. What does this suggest?', ['It contains impurities', 'It is pure water', 'The pressure must be zero', 'It is not water at all'], 0, 'Pure water boils at 100 °C (at standard pressure). Dissolved impurities raise the boiling point, so this sample is impure.'),
    M('How does an impurity usually affect the melting point of a solid?', ['It lowers it and makes it melt over a range', 'It raises it to a sharp point', 'It has no effect', 'It stops it melting'], 0, 'Impure solids melt at a lower temperature and over a range rather than at one sharp temperature.'),
    M('Why are formulations carefully designed?', ['Each component is added in a measured quantity to give the product specific properties', 'To make products cheaper by using random amounts', 'Because pure substances cannot be sold', 'To make sure all ingredients react together'], 0, 'Formulations (e.g. paints, medicines, fertilisers) have components in exact proportions so the product works as intended.'),
    M('Calculate the R<sub>f</sub> value: spot moved 3.0 cm; solvent front moved 7.5 cm.', ['0.40', '2.5', '0.75', '4.5'], 0, 'R<sub>f</sub> = distance moved by substance ÷ distance moved by solvent = 3.0 ÷ 7.5 = 0.40. Dividing the other way (2.5) is a common error; R<sub>f</sub> is always less than 1.'),
    M('Why does a substance stay near the start line in chromatography?', ['It is attracted strongly to the paper and is not very soluble in the solvent', 'It is very soluble in the solvent', 'It evaporates', 'It is a pure substance'], 0, 'Separation depends on the balance between attraction to the stationary phase (paper) and solubility in the mobile phase (solvent). Strong attraction to the paper → small R<sub>f</sub>.'),
    M('An ink spot stays on the start line in water but moves with ethanol. What does this show?', ['The ink is insoluble in water but soluble in ethanol', 'The ink is pure', 'Water is the stationary phase', 'Ethanol reacts with the ink'], 0, 'A substance only moves if it dissolves in the mobile phase. Choosing a suitable solvent is important.'),
    T('The R<sub>f</sub> value of a compound depends on the solvent used.', true, 'True. Changing the solvent changes how the substance distributes between the paper and the solvent, so R<sub>f</sub> changes.'),
    T('A single spot on a chromatogram proves that a substance is pure in all solvents.', false, 'False. A single spot suggests purity, but two substances might have the same R<sub>f</sub> in that solvent. Testing in other solvents gives more confidence.'),
    T('In everyday language, "pure" often means natural or with nothing added, which is different from the chemical meaning.', true, 'True. In chemistry a pure substance contains only one element or compound; "pure orange juice" is still a mixture.'),
    S('In paper chromatography, what is the name of the phase that does not move (the paper)?', 'stationary phase', ['stationary phase', 'stationary'], 'The paper is the stationary phase; the solvent moving through it is the mobile phase.', [['stationary']]),
    X('Which TWO are examples of formulations?', ['Fertiliser', 'Medicine tablets', 'Pure sodium chloride', 'Oxygen gas', 'Distilled water'], [0, 1], 'Fertilisers and medicines are designed mixtures of components in measured amounts. The other three are pure substances.'),
    N('A dye has an R<sub>f</sub> value of 0.6. The solvent front moved 8.0 cm. How far did the dye move (in cm)?', 4.8, 0.01, 'cm', ['R<sub>f</sub> = distance moved by dye ÷ distance moved by solvent', 'distance moved by dye = R<sub>f</sub> × solvent distance', '= 0.6 × 8.0 = 4.8 cm'], 'Rearrange the R<sub>f</sub> formula to find the distance moved by the substance.'),
    M('A food colouring gives spots at R<sub>f</sub> 0.3 and 0.7. A banned dye has R<sub>f</sub> 0.5 in the same solvent. What can be concluded?', ['The banned dye is probably not present', 'The banned dye is definitely present', 'The food colouring is pure', 'The R<sub>f</sub> values must be wrong'], 0, 'No spot matches R<sub>f</sub> 0.5, so the banned dye is unlikely to be present in that sample.'),
    M('Why should the solvent front be marked as soon as the paper is removed?', ['The solvent evaporates quickly and the line would become invisible', 'To stop the dyes moving backwards', 'To make the spots darker', 'Because the paper will dissolve'], 0, 'The solvent dries quickly, so its furthest point must be marked immediately to measure R<sub>f</sub> accurately.'),
    O('Put these in order to calculate an R<sub>f</sub> value from a dried chromatogram.', ['Measure from the start line to the solvent front', 'Measure from the start line to the centre of the spot', 'Divide the spot distance by the solvent distance', 'Compare the value with known substances'], 'Both distances are measured from the pencil start line; R<sub>f</sub> = spot distance ÷ solvent distance, then compared with reference values in the same solvent.'),
  ] },
  { name: 'Chromatography R<sub>f</sub> calculations', intro: 'R<sub>f</sub> = distance moved by substance ÷ distance moved by solvent. Values are between 0 and 1 and have no units.', gen: genRf },
  { name: 'Gas tests & ion tests', intro: 'Gas tests identify H<sub>2</sub>, O<sub>2</sub>, CO<sub>2</sub> and Cl<sub>2</sub>. Chemistry only: flame tests, hydroxide precipitates, and tests for carbonate, halide and sulfate ions identify ions (required practical); instrumental methods are faster and more sensitive.', items: [
    M('What is the test for chlorine?', ['Damp litmus paper is bleached white', 'Limewater turns milky', 'Squeaky pop', 'Glowing splint relights'], 0, 'Chlorine bleaches damp litmus (blue litmus may go red first).'),
    M('What is the test for carbon dioxide?', ['Bubble through limewater — it turns milky (cloudy)', 'Squeaky pop with a lighted splint', 'Relights a glowing splint', 'Bleaches damp litmus'], 0, 'CO<sub>2</sub> + calcium hydroxide solution forms insoluble calcium carbonate.'),
    M('Chemistry only: what colour flame does a sodium compound give?', ['Yellow', 'Lilac', 'Crimson', 'Green'], 0, 'Li crimson, Na yellow, K lilac, Ca orange-red, Cu green.'),
    M('Chemistry only: what colour flame does a potassium compound give?', ['Lilac', 'Yellow', 'Orange-red', 'Green'], 0, 'Potassium = lilac.'),
    M('Chemistry only: which flame colour shows lithium ions?', ['Crimson', 'Lilac', 'Yellow', 'Green'], 0, 'Lithium gives a crimson (deep red) flame; calcium gives orange-red.'),
    M('Chemistry only: sodium hydroxide solution is added to a solution and a blue precipitate forms. Which ion is present?', ['Cu<sup>2+</sup>', 'Fe<sup>2+</sup>', 'Fe<sup>3+</sup>', 'Al<sup>3+</sup>'], 0, 'Copper(II) hydroxide is blue. Fe<sup>2+</sup> green, Fe<sup>3+</sup> brown, Al<sup>3+</sup>/Ca<sup>2+</sup>/Mg<sup>2+</sup> white.'),
    M('Chemistry only: a white precipitate with NaOH dissolves in excess NaOH. Which ion is present?', ['Al<sup>3+</sup>', 'Ca<sup>2+</sup>', 'Mg<sup>2+</sup>', 'Cu<sup>2+</sup>'], 0, 'Aluminium hydroxide is amphoteric and dissolves in excess; calcium and magnesium hydroxides do not.'),
    M('Chemistry only: what colour precipitate does Fe<sup>3+</sup> give with sodium hydroxide?', ['Brown', 'Green', 'Blue', 'White'], 0, 'Iron(III) hydroxide is orange-brown. Iron(II) hydroxide is green.'),
    M('Chemistry only: dilute nitric acid and silver nitrate are added to a solution, giving a cream precipitate. Which ion is present?', ['Bromide', 'Chloride', 'Iodide', 'Sulfate'], 0, 'Chloride white, bromide cream, iodide yellow.'),
    M('Chemistry only: what is the test for sulfate ions?', ['Add dilute hydrochloric acid then barium chloride — white precipitate', 'Add silver nitrate — yellow precipitate', 'Add NaOH — blue precipitate', 'Add limewater — milky'], 0, 'Barium sulfate is a white precipitate. The acid removes carbonate ions that would interfere.'),
    M('Chemistry only: how do you test for carbonate ions?', ['Add dilute acid and bubble the gas through limewater', 'Add silver nitrate', 'Do a flame test', 'Add barium chloride'], 0, 'Carbonates fizz with acid, producing CO<sub>2</sub> that turns limewater milky.'),
    T('Chemistry only: a flame test cannot identify all metals in a mixture because some colours mask others.', true, 'True. For example the strong yellow of sodium can hide other colours.'),
    X('Chemistry only: which TWO are advantages of instrumental methods such as flame emission spectroscopy?', ['Accurate', 'Sensitive — work with very small samples', 'Require no equipment', 'Always cheaper', 'Need large samples'], [0, 1], 'Instrumental methods are accurate, sensitive and rapid, but the equipment is expensive.'),
    M('Chemistry only: why is nitric acid (not hydrochloric) added before silver nitrate in the halide test?', ['Hydrochloric acid contains chloride ions which would give a false positive', 'Nitric acid is cheaper', 'Hydrochloric acid reacts with silver to give hydrogen', 'Nitric acid is a halide'], 0, 'Nitric acid removes carbonate ions without adding halide ions.'),
    S('Which gas relights a glowing splint?', 'oxygen', ['oxygen', 'o2'], 'Oxygen supports combustion, so a glowing splint bursts into flame.'),
    M('What is the test for hydrogen?', ['A lit splint gives a squeaky pop', 'A glowing splint relights', 'Limewater turns milky', 'Damp litmus is bleached'], 0, 'Hydrogen burns with a squeaky pop when a lit splint is held at the mouth of the tube. The other tests are for oxygen, carbon dioxide and chlorine.'),
    M('Chemistry only: what colour flame does a calcium compound give?', ['Orange-red', 'Crimson', 'Lilac', 'Green'], 0, 'Calcium ions give an orange-red flame. Lithium is crimson, potassium lilac and copper green.'),
    M('Chemistry only: what colour flame does a copper compound give?', ['Green', 'Yellow', 'Lilac', 'Crimson'], 0, 'Copper ions give a green flame. Sodium is yellow, potassium lilac and lithium crimson.'),
    M('Chemistry only: what colour precipitate forms when NaOH is added to a solution containing Fe<sup>2+</sup> ions?', ['Green', 'Brown', 'Blue', 'White'], 0, 'Iron(II) hydroxide is a green precipitate. Iron(III) gives brown; copper(II) gives blue.'),
    M('Chemistry only: a solution gives a white precipitate with NaOH that does NOT dissolve in excess. Which ion could it contain?', ['Mg<sup>2+</sup> or Ca<sup>2+</sup>', 'Al<sup>3+</sup>', 'Cu<sup>2+</sup>', 'Fe<sup>3+</sup>'], 0, 'Calcium and magnesium give white precipitates that stay in excess NaOH. Aluminium hydroxide redissolves; copper and iron give coloured precipitates.'),
    M('Chemistry only: what colour precipitate forms when silver nitrate (with nitric acid) is added to a chloride solution?', ['White', 'Cream', 'Yellow', 'Blue'], 0, 'Chloride gives a white precipitate of AgCl, bromide gives cream AgBr and iodide gives yellow AgI.'),
    M('Chemistry only: dilute HCl and barium chloride are added to a solution. A white precipitate forms. Which ion is present?', ['Sulfate (SO<sub>4</sub><sup>2−</sup>)', 'Chloride (Cl<sup>−</sup>)', 'Carbonate (CO<sub>3</sub><sup>2−</sup>)', 'Iodide (I<sup>−</sup>)'], 0, 'Barium sulfate is an insoluble white precipitate. The acid is added first to remove carbonate ions, which would also form a white precipitate.'),
    T('Chemistry only: a yellow precipitate with acidified silver nitrate shows iodide ions.', true, 'True. Silver iodide is yellow. Silver chloride is white and silver bromide is cream.'),
    T('Carbon dioxide puts out a lit splint, and this is the standard test for carbon dioxide.', false, 'False. Several gases put out a lit splint. The standard test is bubbling the gas through limewater, which turns milky (cloudy).'),
    T('Chemistry only: instrumental methods can detect very small amounts of a substance.', true, 'True. Instrumental methods are sensitive, accurate and rapid, so they can detect tiny quantities.'),
    S('Chemistry only: what flame colour does a lithium compound give?', 'crimson', ['crimson', 'red', 'crimson red'], 'Lithium ions give a crimson (deep red) flame. Calcium gives orange-red, which is a common mix-up.'),
    S('What gas bleaches damp litmus paper?', 'chlorine', ['chlorine', 'cl2', 'chlorine gas'], 'Chlorine bleaches damp litmus paper white (blue litmus may turn red briefly first).'),
    X('Chemistry only: which TWO tests would identify the ions in iron(III) sulfate?', ['Add NaOH: brown precipitate', 'Add HCl then BaCl<sub>2</sub>: white precipitate', 'Flame test: lilac', 'Add HNO<sub>3</sub> then AgNO<sub>3</sub>: yellow precipitate', 'Add acid: fizzing that turns limewater milky'], [0, 1], 'Fe<sup>3+</sup> gives a brown hydroxide precipitate; sulfate gives white BaSO<sub>4</sub> with acidified barium chloride. Lilac is potassium; yellow AgI shows iodide; fizzing shows carbonate.'),
    M('Chemistry only: what is flame emission spectroscopy used for?', ['Identifying metal ions and measuring their concentrations from the light they emit', 'Measuring the pH of a solution', 'Separating dyes', 'Testing for gases'], 0, 'A sample is put into a flame; the light given out is passed through a spectroscope. The spectrum identifies the metal ions, and its intensity shows their concentration.'),
    O('Chemistry only: put the steps of a flame test in order.', ['Clean a nichrome wire loop by dipping in acid and heating', 'Dip the loop into the solid sample', 'Hold the loop in a blue Bunsen flame', 'Observe and record the flame colour'], 'The wire must be cleaned first so no other ions contaminate the result; a blue (non-luminous) flame is used so the colour is clearly seen.'),
  ] },
], {
  overview: 'Analytical chemists find out what substances are and whether they are pure. This topic covers <b>purity</b> and <b>formulations</b>, <b>paper chromatography</b> (a required practical), tests for common gases and, in GCSE Chemistry, tests for <b>ions</b> and <b>instrumental</b> analysis.',
  objectives: ['I can use melting/boiling point data to judge purity', 'I can identify formulations', 'I can carry out and interpret paper chromatography and calculate R<sub>f</sub>', 'I can describe the tests for H<sub>2</sub>, O<sub>2</sub>, CO<sub>2</sub> and Cl<sub>2</sub>', 'Chemistry only: I can identify metal ions, carbonates, halides and sulfates', 'Chemistry only: I can explain the advantages of instrumental methods'],
  keyWords: [{ term: 'Pure substance', def: 'A single element or compound, not mixed with anything.' }, { term: 'Formulation', def: 'A mixture designed as a useful product.' }, { term: 'Chromatography', def: 'Separation using a stationary and a mobile phase.' }, { term: 'Rf value', def: 'Distance moved by substance ÷ distance moved by solvent.' }, { term: 'Precipitate', def: 'An insoluble solid formed in a solution.' }, { term: 'Flame emission spectroscopy', def: 'Instrumental method identifying metal ions from the light they emit.' }],
  sections: [
    { title: 'Purity and formulations', html: `<p>Pure substances have sharp melting/boiling points; impure substances melt over a range and usually lower. Formulations (paints, medicines, alloys, fertilisers) have precise amounts of each component.</p>` },
    { title: 'Chromatography', html: `<div class="rule">R<sub>f</sub> = distance moved by substance ÷ distance moved by solvent</div><div class="worked"><div class="wq">Solvent front 8.0 cm, spot 3.2 cm. R<sub>f</sub>?</div><ol><li>3.2 ÷ 8.0</li></ol><div class="wa">Answer: 0.40</div></div><p>Pencil start line above the solvent; lid on; pure substances give one spot.</p>` },
    { title: 'Gas tests', html: `<table class="qt"><tr><th>Gas</th><th>Test</th><th>Result</th></tr><tr><td>Hydrogen</td><td>Lighted splint</td><td>Squeaky pop</td></tr><tr><td>Oxygen</td><td>Glowing splint</td><td>Relights</td></tr><tr><td>Carbon dioxide</td><td>Limewater</td><td>Turns milky</td></tr><tr><td>Chlorine</td><td>Damp litmus</td><td>Bleached white</td></tr></table>` },
    { title: 'Tests for ions (chemistry only)', html: `<p>Flame tests: Li<sup>+</sup> crimson, Na<sup>+</sup> yellow, K<sup>+</sup> lilac, Ca<sup>2+</sup> orange-red, Cu<sup>2+</sup> green.</p><p>NaOH: Al<sup>3+</sup>, Ca<sup>2+</sup>, Mg<sup>2+</sup> white (Al dissolves in excess); Cu<sup>2+</sup> blue; Fe<sup>2+</sup> green; Fe<sup>3+</sup> brown.</p><p>Carbonate: acid → CO<sub>2</sub>. Halides: HNO<sub>3</sub> + AgNO<sub>3</sub> → Cl<sup>−</sup> white, Br<sup>−</sup> cream, I<sup>−</sup> yellow. Sulfate: HCl + BaCl<sub>2</sub> → white.</p>` },
    { title: 'Instrumental methods (chemistry only)', html: `<p>Flame emission spectroscopy: sample in flame, light passed through a spectroscope; the line spectrum identifies ions and intensity gives concentration. Instrumental methods are accurate, sensitive and rapid.</p>` },
  ],
  mistakes: ['Drawing the start line in pen.', 'Measuring R<sub>f</sub> distances from the bottom of the paper instead of the start line.', 'Saying limewater turns "cloudy white" for oxygen.', 'Using HCl before silver nitrate in the halide test.'],
  examTips: ['Gas tests need both the test AND the result for marks.', 'R<sub>f</sub> answers have no units and should be less than 1.', 'In ion test questions, state the reagent, the observation and the conclusion.'],
  realLife: 'Forensic scientists use chromatography to match inks on forged documents and to detect drugs in blood samples.',
});

// =====================================================================
// YEAR 11 — Chemistry of the atmosphere (AQA 4.9)
// =====================================================================
topic({ id: 'chem-y11-atmosphere', strand: 'chem-atmos', year: 11, term: 2, tier: 'FH', name: 'Chemistry of the Atmosphere',
  summary: 'How Earth\'s atmosphere evolved, greenhouse gases and climate change, and common atmospheric pollutants.', specRef: 'AQA 8462 4.9.1–4.9.3' }, [
  { name: 'Evolution of the atmosphere', intro: 'Earth\'s early atmosphere was probably mainly carbon dioxide from volcanoes, with little or no oxygen. Oceans, carbonate rocks, fossil fuels and photosynthesis changed it to today\'s ~80% nitrogen, ~20% oxygen.', items: [
    M('What was the main gas in Earth\'s early atmosphere (according to one theory)?', ['Carbon dioxide', 'Oxygen', 'Nitrogen', 'Argon'], 0, 'Intense volcanic activity released mainly CO<sub>2</sub>, like the atmospheres of Mars and Venus today.'),
    M('Where did the water in the oceans come from?', ['Water vapour from volcanoes condensed as Earth cooled', 'Photosynthesis', 'Melting of carbon dioxide', 'Comets only, recently'], 0, 'Volcanoes released water vapour that condensed to form the oceans.'),
    M('How did carbon dioxide levels decrease?', ['It dissolved in oceans and formed carbonate rocks; plants/algae used it in photosynthesis', 'It escaped to space', 'It turned into nitrogen', 'Volcanoes absorbed it'], 0, 'Dissolving, precipitation of carbonates, photosynthesis and locking into fossil fuels and sedimentary rocks all removed CO<sub>2</sub>.'),
    M('What produced the oxygen in the atmosphere?', ['Photosynthesis by algae and plants', 'Volcanoes', 'Respiration', 'Combustion'], 0, 'Algae began photosynthesising about 2.7 billion years ago, gradually increasing oxygen.'),
    M('About how long ago did algae start producing oxygen?', ['2.7 billion years ago', '2.7 million years ago', '4.6 billion years ago', '200 years ago'], 0, '2.7 billion years ago; oxygen reached levels allowing animals to evolve over the following billion years or so.'),
    M('What are the proportions of gases in today\'s dry air?', ['About 4/5 nitrogen, 1/5 oxygen, small amounts of others', 'About 1/5 nitrogen, 4/5 oxygen', 'Half nitrogen, half oxygen', 'Mostly carbon dioxide'], 0, '~78% N<sub>2</sub>, ~21% O<sub>2</sub>, ~1% other gases including argon and CO<sub>2</sub>.'),
    T('Evidence about the early atmosphere is limited because it was billions of years ago.', true, 'True. Theories are based on evidence such as rocks and other planets, so there are different theories.'),
    S('Name one type of rock that contains carbon locked from the early atmosphere.', 'limestone', ['limestone', 'chalk', 'carbonate rock', 'sedimentary rock'], 'Limestone (calcium carbonate) formed from shells and skeletons of marine organisms.', [['limestone', 'chalk', 'carbonate', 'sedimentary']]),
    M('Write the word equation for photosynthesis.', ['carbon dioxide + water → glucose + oxygen', 'glucose + oxygen → carbon dioxide + water', 'carbon + oxygen → carbon dioxide', 'nitrogen + oxygen → nitrogen oxide'], 0, '6CO<sub>2</sub> + 6H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub>.'),
    O('Put these atmospheric changes in time order.', ['Volcanoes release CO<sub>2</sub> and water vapour', 'Water vapour condenses to form oceans', 'CO<sub>2</sub> dissolves and forms carbonate rocks', 'Algae photosynthesise, increasing oxygen'], 'The broad sequence is volcanic outgassing → oceans → CO<sub>2</sub> removal → oxygen build-up.'),
    T('Nitrogen in the early atmosphere may have come from volcanoes.', true, 'True. Volcanoes probably released nitrogen, which built up because it is unreactive.'),
    M('Which planets have atmospheres similar to Earth\'s early atmosphere?', ['Mars and Venus', 'Jupiter and Saturn', 'Mercury only', 'The Moon'], 0, 'Mars and Venus have atmospheres mostly of CO<sub>2</sub>.'),
    M('Why did oxygen levels increase only slowly at first?', ['Oxygen reacted with other substances (e.g. iron in rocks) before building up', 'Algae did not photosynthesise', 'Oxygen escaped into space', 'Volcanoes used it'], 0, 'Early oxygen reacted to form oxides; only later did free oxygen accumulate.'),
    X('Which TWO processes locked carbon dioxide away in rocks or fuels?', ['Formation of sedimentary carbonate rocks', 'Formation of coal, crude oil and natural gas', 'Volcanic eruptions', 'Respiration', 'Combustion'], [0, 1], 'Carbonates and fossil fuels store carbon. Volcanoes, respiration and combustion release it.'),
    M('Which gas makes up most of the atmosphere today?', ['Nitrogen', 'Oxygen', 'Carbon dioxide', 'Argon'], 0, 'About 78% (four-fifths) nitrogen.'),
    M('How did the oceans form in the early Earth?', ['Water vapour from volcanoes condensed as the Earth cooled', 'Photosynthesis produced liquid water', 'Ice from the core melted', 'Nitrogen reacted to form water'], 0, 'Volcanoes released water vapour. As the Earth cooled, the water vapour condensed to form the oceans.'),
    M('How did forming the oceans reduce the amount of carbon dioxide in the atmosphere?', ['Carbon dioxide dissolved in the oceans', 'Carbon dioxide froze in the oceans', 'The oceans produced oxygen directly', 'Water reacted with nitrogen'], 0, 'Some CO<sub>2</sub> dissolved in the water; later, carbonates precipitated and formed sediments, locking carbon away.'),
    M('Which gases may also have been present in small amounts in the early atmosphere?', ['Methane and ammonia', 'Argon and neon only', 'Chlorine and fluorine', 'Oxygen and ozone in large amounts'], 0, 'Volcanic gases may have included small amounts of methane and ammonia, as well as nitrogen. There was little or no oxygen.'),
    M('Approximately how long ago did the Earth form?', ['About 4.6 billion years ago', 'About 6000 years ago', 'About 65 million years ago', 'About 1 million years ago'], 0, 'Evidence such as radioactive dating of rocks and meteorites suggests the Earth formed about 4.6 billion years ago.'),
    M('How was crude oil formed from the early atmosphere\'s carbon?', ['From the remains of plankton buried in mud and compressed over millions of years', 'From volcanic lava', 'From limestone dissolving', 'From nitrogen in the air'], 0, 'Carbon taken in by tiny sea organisms (plankton) was buried in mud and, under heat and pressure over millions of years, became crude oil and natural gas.'),
    M('Coal is a sedimentary rock formed from…', ['Thick plant deposits', 'Shells of sea animals', 'Volcanic ash', 'Dissolved salts'], 0, 'Coal formed from the remains of plants that were buried and compressed. Limestone formed mainly from shells and skeletons of marine organisms.'),
    T('The early atmosphere is thought to have been like the atmospheres of Mars and Venus today, which are mainly carbon dioxide.', true, 'True. Mars and Venus have atmospheres that are mostly carbon dioxide, which supports the theory about Earth\'s early atmosphere.'),
    T('The oxygen in today\'s atmosphere came mainly from volcanoes.', false, 'False. Oxygen was produced by photosynthesis, first by algae and later by plants. Volcanoes released mainly carbon dioxide, water vapour and nitrogen.'),
    T('As oxygen levels increased, more complex life forms could evolve.', true, 'True. The build-up of oxygen allowed animals, which need oxygen for respiration, to evolve.'),
    S('What is the main gas released by volcanic activity in the early atmosphere theory?', 'carbon dioxide', ['carbon dioxide', 'co2'], 'Intense volcanic activity released mainly carbon dioxide, along with water vapour and nitrogen.'),
    S('What process allowed algae and plants to add oxygen to the atmosphere?', 'photosynthesis', ['photosynthesis'], 'Photosynthesis takes in carbon dioxide and water and releases oxygen.'),
    X('Which TWO statements about the composition of today\'s dry air are correct?', ['About four-fifths is nitrogen', 'About one-fifth is oxygen', 'About half is carbon dioxide', 'Argon is the second most abundant gas', 'There is no carbon dioxide'], [0, 1], 'Nitrogen is about 80% (four-fifths) and oxygen about 20% (one-fifth). CO<sub>2</sub> is only about 0.04%, and argon (≈0.9%) is third.'),
    M('Which statement explains why scientists are not certain about the early atmosphere?', ['There is little direct evidence because it was about 4.6 billion years ago', 'No one has studied it', 'The atmosphere has never changed', 'It is impossible to study gases'], 0, 'With so little evidence surviving from billions of years ago, scientists propose theories and test them against the limited evidence available.'),
    M('What is the balanced symbol equation for photosynthesis?', ['6CO<sub>2</sub> + 6H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub>', 'CO<sub>2</sub> + H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + O<sub>2</sub>', 'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub> → 6CO<sub>2</sub> + 6H<sub>2</sub>O', '6CO<sub>2</sub> + 6O<sub>2</sub> → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6H<sub>2</sub>O'], 0, 'Carbon dioxide and water react using light to make glucose and oxygen. The third equation is respiration (the reverse).'),
    O('Put these in the order they happened in the history of the atmosphere.', ['Volcanoes release CO<sub>2</sub>, water vapour and nitrogen', 'Water vapour condenses to form oceans', 'Algae begin photosynthesis', 'Oxygen builds up to about 20%'], 'Volcanic gases first, then oceans formed as Earth cooled, then algae evolved and slowly raised oxygen levels to today\'s value.'),
  ] },
  { name: 'Greenhouse gases & climate change', intro: 'Water vapour, carbon dioxide and methane are greenhouse gases. Human activities increase CO<sub>2</sub> and methane, which most scientists agree is causing global climate change.', items: [
    M('How do greenhouse gases warm the Earth?', ['They absorb infrared radiation emitted by Earth and re-radiate it', 'They reflect sunlight away', 'They create heat by reacting', 'They block ultraviolet light'], 0, 'Short-wavelength radiation from the Sun passes through; Earth emits longer-wavelength infrared, which greenhouse gases absorb.'),
    X('Which TWO human activities increase methane?', ['Cattle farming', 'Decomposition in landfill', 'Planting trees', 'Using wind turbines', 'Recycling'], [0, 1], 'Livestock digestion, rice paddies and landfill release methane.'),
    M('Which activity increases carbon dioxide levels?', ['Burning fossil fuels', 'Photosynthesis', 'Reforestation', 'Using solar power'], 0, 'Combustion of fossil fuels and deforestation are the main sources.'),
    X('Which TWO are potential effects of global climate change?', ['Sea level rise causing flooding', 'More frequent severe weather', 'More stable ice caps', 'Fewer droughts everywhere', 'Lower ocean temperatures'], [0, 1], 'Also changes in rainfall and food production, and species distribution.'),
    M('What is a carbon footprint?', ['Total greenhouse gases emitted over the full life cycle of a product, service or event', 'Mass of carbon in a fuel', 'Carbon released by one car journey only', 'Amount of coal used'], 0, 'It includes manufacture, use and disposal.'),
    M('Which is a way to reduce a carbon footprint?', ['Using renewable energy and increasing energy efficiency', 'Burning more coal', 'Cutting down forests', 'Sending more waste to landfill'], 0, 'Also carbon capture and storage, carbon taxes and carbon offsetting (e.g. tree planting).'),
    M('Why might people not reduce their carbon footprint?', ['Lack of public understanding, cost, and economic reasons', 'It is illegal', 'It is easy', 'It increases fuel use'], 0, 'Barriers include cost, lifestyle changes, lack of agreement and economic development needs.'),
    T('Scientists agree that peer-reviewed evidence shows human activities are likely to cause increased average global temperatures.', true, 'True. Peer review checks the evidence; climate models are complex so simplified versions are often presented in the media.'),
    S('Name the gas, besides carbon dioxide and methane, that is a natural greenhouse gas.', 'water vapour', ['water vapour', 'water', 'h2o', 'steam'], 'Water vapour is the most abundant greenhouse gas.', [['water', 'steam']]),
    M('What is carbon capture and storage?', ['Trapping CO<sub>2</sub> from power stations and storing it underground', 'Burning more carbon', 'Planting carbon fibres', 'Making charcoal'], 0, 'CO<sub>2</sub> is captured and stored in old oil/gas fields or rocks.'),
    T('Without the greenhouse effect, Earth would be too cold to support life as we know it.', true, 'True. The problem is the enhanced greenhouse effect from extra gases.'),
    M('Why is it hard to model climate change?', ['The climate system is complex with many factors interacting', 'There is no data', 'Temperature cannot be measured', 'Greenhouse gases do not change'], 0, 'Simplified models give ranges; uncertainty does not mean there is no effect.'),
    M('What is carbon offsetting?', ['Balancing emissions by actions that remove CO<sub>2</sub>, such as tree planting', 'Emitting more CO<sub>2</sub>', 'Taxing all fuels', 'Recycling metals'], 0, 'Planting trees absorbs CO<sub>2</sub> to compensate for emissions elsewhere.'),
    M('Which gas has increased most in concentration due to human activity since the industrial revolution?', ['Carbon dioxide', 'Nitrogen', 'Argon', 'Oxygen'], 0, 'CO<sub>2</sub> has risen from about 280 ppm to over 400 ppm.'),
    M('Why does deforestation increase CO<sub>2</sub> in the atmosphere?', ['Fewer trees remove CO<sub>2</sub>, and burning trees releases it', 'Trees produce CO<sub>2</sub> by photosynthesis', 'Trees absorb oxygen', 'Soil releases nitrogen'], 0, 'Two effects: less photosynthesis and CO<sub>2</sub> released if the wood is burned or decays.'),
    M('Which type of radiation from the Earth\'s surface do greenhouse gases absorb?', ['Infrared (long wavelength) radiation', 'Ultraviolet radiation only', 'Visible light only', 'Gamma radiation'], 0, 'Short-wavelength radiation from the Sun passes through the atmosphere, warms the Earth, and the Earth emits longer-wavelength infrared radiation, which greenhouse gases absorb.'),
    M('Which of these is a source of methane linked to human activity?', ['Decomposition of waste in landfill sites', 'Photosynthesis', 'Wind turbines', 'Electrolysis of water'], 0, 'Landfill sites, cattle farming and rice paddy fields all release methane.'),
    M('Why could rising sea levels be a problem?', ['Flooding of low-lying land and coastal erosion', 'More fresh water for drinking', 'Colder winters everywhere', 'Fewer storms'], 0, 'Rising sea levels (from melting land ice and thermal expansion) can flood coastal communities and increase erosion.'),
    M('Climate change could change where species can live. Why?', ['Temperature and rainfall patterns change, so habitats shift', 'Animals no longer need food', 'Plants stop photosynthesising', 'All habitats become identical'], 0, 'As climates change, some areas become unsuitable and species must move or adapt; distribution of wildlife changes.'),
    M('Why is a carbon footprint difficult to measure accurately?', ['Many different sources of emissions must be included across the whole life cycle', 'Carbon dioxide cannot be measured', 'Only methane counts', 'It only includes electricity use'], 0, 'A carbon footprint includes all greenhouse gas emissions over a product\'s life cycle, which involves many stages and estimates.'),
    M('Which action would reduce emissions of greenhouse gases from electricity generation?', ['Using more renewable sources such as wind and solar', 'Burning more coal', 'Cutting down forests', 'Using more natural gas boilers'], 0, 'Renewable sources do not release CO<sub>2</sub> when generating electricity. Burning fossil fuels and deforestation increase greenhouse gases.'),
    T('Water vapour is a greenhouse gas.', true, 'True. Water vapour, carbon dioxide and methane are all greenhouse gases.'),
    T('Simplified models of climate can cause uncertainty, and the media may present only parts of the evidence.', true, 'True. Climate is very complex, so models are simplified; speculation and selective reporting can make the public uncertain.'),
    T('The greenhouse effect is entirely caused by human activity.', false, 'False. The greenhouse effect is natural and keeps Earth warm enough for life. Human activity is enhancing it, which causes additional warming.'),
    S('What name is given to the long-term change in global weather patterns linked to rising temperatures?', 'climate change', ['climate change', 'global climate change', 'global warming'], 'Climate change describes long-term changes in temperature, rainfall and weather patterns across the globe.', [['climate', 'warming']]),
    S('Which greenhouse gas, released from cattle and rice fields, has the formula CH<sub>4</sub>?', 'methane', ['methane'], 'Methane (CH<sub>4</sub>) is a powerful greenhouse gas released by cattle, rice paddies and landfill.'),
    X('Which TWO actions reduce a person\'s carbon footprint?', ['Using public transport instead of a car', 'Insulating their home', 'Taking more flights', 'Leaving lights on', 'Buying more single-use plastic'], [0, 1], 'Public transport and better insulation reduce energy use and emissions. Flights, wasted electricity and single-use plastics increase the footprint.'),
    M('Why might governments find it hard to agree on reducing carbon emissions?', ['Reducing emissions can be costly and affect economic growth', 'Carbon dioxide is not a greenhouse gas', 'There is no evidence of warming', 'All countries already emit the same amount'], 0, 'Changing energy systems costs money and may slow development, so countries disagree about who should do what. International agreement is needed.'),
    M('Which statement about the evidence for human-caused climate change is correct?', ['It is based on peer-reviewed evidence collected by many scientists', 'It comes from a single unchecked experiment', 'It relies only on newspaper reports', 'It has never been tested'], 0, 'Scientific consensus comes from large amounts of peer-reviewed data and models produced and checked by many independent scientists.'),
    O('Put these steps in order to explain the greenhouse effect.', ['Short-wavelength radiation from the Sun reaches the Earth', 'The Earth\'s surface warms and emits infrared radiation', 'Greenhouse gases absorb some infrared radiation', 'Energy is re-emitted in all directions, warming the lower atmosphere'], 'Sunlight in, infrared out from the surface, absorbed by greenhouse gases and re-radiated — keeping the atmosphere warmer.'),
  ] },
  { name: 'Atmospheric pollutants', intro: 'Burning fuels releases carbon dioxide, water vapour, carbon monoxide, soot (particulates), sulfur dioxide and oxides of nitrogen, which harm health and the environment.', items: [
    M('Why is carbon monoxide dangerous?', ['It is toxic, colourless and odourless — it stops blood carrying oxygen', 'It causes acid rain', 'It is a greenhouse gas only', 'It causes global dimming'], 0, 'CO binds to haemoglobin in red blood cells, reducing oxygen transport.'),
    M('How is carbon monoxide produced?', ['Incomplete combustion of fuels', 'Complete combustion', 'Burning sulfur', 'Reaction of nitrogen and oxygen'], 0, 'With limited oxygen, carbon forms CO (and soot) instead of CO<sub>2</sub>.'),
    M('Where does sulfur dioxide pollution come from?', ['Sulfur impurities in fossil fuels being burned', 'Nitrogen in the air', 'Incomplete combustion', 'Photosynthesis'], 0, 'Coal and some oils contain sulfur, which burns to SO<sub>2</sub>.'),
    M('How are oxides of nitrogen formed in car engines?', ['Nitrogen and oxygen from the air react at high temperatures', 'Nitrogen in the fuel burns', 'Incomplete combustion', 'Sulfur reacts with air'], 0, 'The high temperature of the engine makes N<sub>2</sub> and O<sub>2</sub> react.'),
    X('Which TWO pollutants cause acid rain?', ['Sulfur dioxide', 'Oxides of nitrogen', 'Carbon monoxide', 'Particulates', 'Water vapour'], [0, 1], 'SO<sub>2</sub> and NO<sub>x</sub> dissolve in rain to form acids, and cause respiratory problems.'),
    M('What are particulates?', ['Tiny solid particles such as soot (carbon)', 'Gases from volcanoes', 'Drops of acid rain', 'Molecules of CO<sub>2</sub>'], 0, 'Soot and unburned hydrocarbons from incomplete combustion.'),
    M('What problems do particulates cause?', ['Global dimming and lung damage', 'Acid rain', 'Toxic binding to haemoglobin', 'Ozone formation'], 0, 'They reflect sunlight (global dimming) and damage lungs when breathed in.'),
    T('Removing sulfur from fuels before burning reduces acid rain.', true, 'True. Desulfurised fuels and flue-gas scrubbers reduce SO<sub>2</sub> emissions.'),
    M('What effect does acid rain have?', ['Damages buildings, statues and trees and acidifies lakes', 'Increases crop yields', 'Reduces global warming', 'Removes CO<sub>2</sub>'], 0, 'Acid reacts with limestone and metal, harms plants and aquatic life.'),
    S('Which toxic gas binds to haemoglobin in blood?', 'carbon monoxide', ['carbon monoxide', 'co'], 'CO reduces the blood\'s capacity to carry oxygen.', [['monoxide']]),
    M('What does a catalytic converter do?', ['Converts CO and nitrogen oxides into CO<sub>2</sub> and N<sub>2</sub>', 'Removes all CO<sub>2</sub>', 'Removes sulfur from fuel', 'Makes petrol'], 0, 'Platinum/rhodium catalysts convert harmful gases to less harmful ones.'),
    T('Carbon monoxide can be detected by its smell.', false, 'False. It is colourless and odourless — that is why CO alarms are needed in homes.'),
    M('Why does burning coal produce more particulates than burning natural gas?', ['Coal burns less completely and contains impurities', 'Natural gas contains more carbon', 'Coal has no carbon', 'Gas produces soot'], 0, 'Solid fuels burn less cleanly, releasing soot and ash.'),
    M('What is "global dimming"?', ['Reduced sunlight reaching Earth\'s surface due to particulates', 'The Sun getting smaller', 'Thinning of the ozone layer', 'Fewer street lights'], 0, 'Particulates in the air reflect sunlight back into space.'),
    X('Which TWO products of burning fuel are greenhouse gases?', ['Carbon dioxide', 'Water vapour', 'Sulfur dioxide', 'Particulates', 'Carbon monoxide'], [0, 1], 'CO<sub>2</sub> and water vapour are greenhouse gases.'),
    M('A poorly maintained gas boiler burns with a yellow flame instead of a blue one. Which pollutant is most likely to be produced?', ['Carbon monoxide', 'Sulfur dioxide', 'Ozone', 'Argon'], 0, 'A yellow flame shows incomplete combustion caused by too little oxygen, which produces carbon monoxide and soot. Sulfur dioxide comes from sulfur impurities, not from a lack of oxygen.'),
    M('Why is carbon monoxide described as a "silent killer"?', ['It is colourless and odourless, so it cannot be detected by our senses', 'It makes a loud noise when it forms', 'It is bright red', 'It only affects plants'], 0, 'CO has no colour or smell, so people may not notice it. Carbon monoxide alarms are used in homes.'),
    M('How does sulfur dioxide cause acid rain?', ['It dissolves in water in clouds to form acidic solutions', 'It reacts with nitrogen to form ammonia', 'It absorbs infrared radiation', 'It blocks sunlight'], 0, 'SO<sub>2</sub> dissolves in rainwater, forming acidic solutions (eventually sulfuric acid), which fall as acid rain.'),
    M('Why are oxides of nitrogen produced in car engines even though petrol contains no nitrogen?', ['The high temperature makes nitrogen and oxygen from the air react', 'Petrol is made of nitrogen compounds', 'Catalytic converters produce them', 'Water vapour reacts with carbon'], 0, 'Air contains nitrogen and oxygen; at the very high temperatures in an engine they react to form oxides of nitrogen (NO<sub>x</sub>).'),
    M('Which health problem can be made worse by sulfur dioxide and oxides of nitrogen?', ['Breathing problems such as asthma', 'Broken bones', 'Short-sightedness', 'Tooth decay'], 0, 'SO<sub>2</sub> and NO<sub>x</sub> irritate the lungs and can make breathing problems worse.'),
    M('Which fuel produces the least sulfur dioxide when burned?', ['Hydrogen', 'Coal', 'Diesel', 'Heavy fuel oil'], 0, 'Hydrogen contains no sulfur, so it produces no SO<sub>2</sub> — only water. Coal and heavy oils often contain sulfur impurities.'),
    T('Particulates can travel deep into the lungs and cause health problems.', true, 'True. Tiny solid particles such as soot can be breathed in and damage the lungs.'),
    T('Catalytic converters change carbon monoxide into carbon dioxide.', true, 'True. Catalytic converters oxidise CO to CO<sub>2</sub> and help convert oxides of nitrogen into nitrogen.'),
    T('Acid rain is caused mainly by carbon dioxide.', false, 'False. Carbon dioxide makes rain only slightly acidic. Acid rain is mainly caused by sulfur dioxide and oxides of nitrogen.'),
    S('What is the name for solid particles of carbon produced by incomplete combustion?', 'soot', ['soot', 'carbon particulates', 'particulates', 'carbon'], 'Soot is solid carbon from incomplete combustion; it is one type of particulate.', [['soot', 'particulate']]),
    S('What general name is given to the pollutants NO and NO<sub>2</sub>?', 'oxides of nitrogen', ['oxides of nitrogen', 'nitrogen oxides', 'nox'], 'NO and NO<sub>2</sub> are oxides of nitrogen, often written NO<sub>x</sub>.', [['nitrogen', 'nox'], ['oxide', 'oxides', 'nox']]),
    X('Which TWO products are formed from the complete combustion of a hydrocarbon fuel?', ['Carbon dioxide', 'Water vapour', 'Carbon monoxide', 'Soot', 'Sulfur dioxide'], [0, 1], 'Complete combustion of a hydrocarbon gives only CO<sub>2</sub> and H<sub>2</sub>O. CO and soot are from incomplete combustion; SO<sub>2</sub> comes from sulfur impurities.'),
    M('How do power stations reduce sulfur dioxide emissions?', ['Removing sulfur dioxide from waste gases (flue gas desulfurisation)', 'Adding more sulfur to the coal', 'Burning the coal at a lower temperature only', 'Releasing the gases at night'], 0, 'Waste gases can be treated (e.g. reacted with calcium carbonate or calcium oxide) to remove SO<sub>2</sub>, or low-sulfur fuel can be used.'),
    M('Global dimming is caused by particulates. What is its effect?', ['Less sunlight reaches the Earth\'s surface', 'More ultraviolet reaches the surface', 'The ozone layer gets thicker', 'The oceans become alkaline'], 0, 'Particulates in the atmosphere reflect sunlight back into space, so less sunlight reaches the ground.'),
    O('Put these steps in order to describe how acid rain forms from coal burning.', ['Coal containing sulfur is burned', 'Sulfur dioxide is released into the air', 'Sulfur dioxide dissolves in water droplets in clouds', 'Acid rain falls, damaging buildings and plants'], 'Sulfur impurities burn to form SO<sub>2</sub>, which dissolves in cloud water to make acidic rain.'),
  ] },
], {
  overview: 'Earth\'s atmosphere has changed hugely over 4.6 billion years. Today, human activities are changing it again by adding <b>greenhouse gases</b> and <b>pollutants</b>. This topic links chemistry to climate change and air quality.',
  objectives: ['I can describe the composition of today\'s atmosphere', 'I can explain how the early atmosphere evolved', 'I can explain the greenhouse effect and name greenhouse gases', 'I can evaluate ways to reduce carbon footprints', 'I can describe sources and effects of CO, SO₂, NOₓ and particulates'],
  keyWords: [{ term: 'Greenhouse effect', def: 'Greenhouse gases absorb infrared radiation, keeping Earth warm.' }, { term: 'Carbon footprint', def: 'Total greenhouse gas emissions over a product\'s life.' }, { term: 'Photosynthesis', def: 'Plants use CO₂ and water to make glucose and oxygen.' }, { term: 'Acid rain', def: 'Rain made acidic by dissolved SO₂ and NOₓ.' }, { term: 'Particulates', def: 'Tiny solid particles (e.g. soot) in the air.' }, { term: 'Global dimming', def: 'Reduction in sunlight reaching the surface caused by particulates.' }],
  sections: [
    { title: 'Today\'s atmosphere', html: `<div class="rule">About 80% nitrogen, 20% oxygen, small amounts of CO<sub>2</sub>, water vapour and noble gases</div>` },
    { title: 'How the atmosphere evolved', html: `<ol><li>First billion years: volcanoes → mainly CO<sub>2</sub>, little/no O<sub>2</sub>, water vapour, some nitrogen, maybe methane and ammonia.</li><li>Water vapour condensed → oceans; CO<sub>2</sub> dissolved → carbonate precipitates.</li><li>Algae (2.7 billion years ago) and plants photosynthesised → O<sub>2</sub> increased, CO<sub>2</sub> decreased.</li><li>Carbon locked in sedimentary rocks and fossil fuels.</li></ol>` },
    { title: 'Greenhouse gases and climate change', html: `<p>Greenhouse gases: water vapour, CO<sub>2</sub>, methane. Human sources: combustion, deforestation (CO<sub>2</sub>); livestock, landfill (CH<sub>4</sub>).</p><p>Effects: rising sea levels, extreme weather, changes to rainfall, food production and habitats. Reduce by renewables, efficiency, carbon capture, carbon taxes, offsetting.</p>` },
    { title: 'Atmospheric pollutants', html: `<table class="qt"><tr><th>Pollutant</th><th>Source</th><th>Effect</th></tr><tr><td>Carbon monoxide</td><td>Incomplete combustion</td><td>Toxic, reduces oxygen in blood</td></tr><tr><td>Soot (particulates)</td><td>Incomplete combustion</td><td>Global dimming, lung damage</td></tr><tr><td>Sulfur dioxide</td><td>Sulfur in fuels</td><td>Acid rain, respiratory problems</td></tr><tr><td>Oxides of nitrogen</td><td>N<sub>2</sub> + O<sub>2</sub> in hot engines</td><td>Acid rain, respiratory problems</td></tr></table>` },
  ],
  mistakes: ['Confusing the greenhouse effect with ozone depletion.', 'Saying nitrogen oxides come from nitrogen in fuel — they come from air.', 'Saying CO causes acid rain.', 'Saying oxygen came from volcanoes.'],
  examTips: ['Link each pollutant to its source AND effect.', 'In "evaluate" questions about climate action, give advantages and disadvantages and a conclusion.', 'Use approximate fractions (4/5, 1/5) for air composition.'],
  realLife: 'Carbon monoxide alarms save lives in homes with gas boilers, because the gas cannot be seen or smelled.',
});

// =====================================================================
// YEAR 11 — Using resources (AQA 4.10) + yield & atom economy (4.3.3)
// =====================================================================
function genYield(rng) {
  const v = ri(rng, 0, 2);
  const prod = pick(rng, ['copper sulfate', 'magnesium oxide', 'ammonia', 'aspirin', 'ethanol', 'calcium oxide', 'zinc chloride', 'iron']);
  if (v === 0) {
    const theo = ri(rng, 20, 200) / 10, act = rd(theo * ri(rng, 40, 95) / 100, 2), y = rd(act / theo * 100, 1);
    return { type: 'number', q: `The theoretical maximum mass of ${prod} in a reaction is ${theo} g. ${act} g is actually obtained. Calculate the percentage yield (1 d.p.).`, value: y, tol: 0.11, unit: '%', answer: `${y}%`,
      steps: ['% yield = (mass of product actually made ÷ maximum theoretical mass) × 100', `% yield = (${act} ÷ ${theo}) × 100`, `% yield = ${y}%`], explain: 'Yield is below 100% because the reaction may not go to completion, some product is lost when separated, or other reactions occur.', hint: 'Actual ÷ theoretical × 100.' };
  }
  if (v === 1) {
    const theo = ri(rng, 20, 300) / 10, p = ri(rng, 30, 95), act = rd(theo * p / 100, 2);
    return { type: 'number', q: `A reaction has a percentage yield of ${p}%. The theoretical yield of ${prod} is ${theo} g. What mass is actually obtained?`, value: act, tol: Math.max(0.01, act * 0.005), unit: 'g', answer: `${act} g`,
      steps: ['actual mass = % yield × theoretical mass ÷ 100', `= ${p} × ${theo} ÷ 100`, `= ${act} g`], explain: 'Rearranging the percentage yield equation.', hint: 'Find that percentage of the theoretical mass.' };
  }
  const nR = ri(rng, 2, 30) / 10, mR = rd(nR * 24, 2), theo = rd(nR * 40, 2), act = rd(theo * ri(rng, 50, 95) / 100, 2), y = rd(act / theo * 100, 1);
  return { type: 'number', q: `HT: ${mR} g of magnesium is burned (2Mg + O<sub>2</sub> → 2MgO; M<sub>r</sub>: Mg 24, MgO 40). ${act} g of magnesium oxide is collected. Calculate the percentage yield (1 d.p.).`, value: y, tol: 0.11, unit: '%', answer: `${y}%`,
    steps: [`moles Mg = ${mR} ÷ 24 = ${nR} mol`, `Ratio Mg : MgO = 1 : 1, so ${nR} mol MgO`, `theoretical mass MgO = ${nR} × 40 = ${theo} g`, `% yield = ${act} ÷ ${theo} × 100 = ${y}%`], explain: 'First find the theoretical yield from reacting masses, then compare the actual mass with it.', hint: 'Find the maximum mass first.' };
}
const AE_RX = [
  ['CaCO<sub>3</sub> → CaO + CO<sub>2</sub>', 'calcium oxide', 56, 100],
  ['C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O → C<sub>2</sub>H<sub>5</sub>OH', 'ethanol', 46, 46],
  ['C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> → 2C<sub>2</sub>H<sub>5</sub>OH + 2CO<sub>2</sub>', 'ethanol', 92, 180],
  ['Fe<sub>2</sub>O<sub>3</sub> + 3CO → 2Fe + 3CO<sub>2</sub>', 'iron', 112, 244],
  ['N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>', 'ammonia', 34, 34],
  ['Zn + 2HCl → ZnCl<sub>2</sub> + H<sub>2</sub>', 'hydrogen', 2, 138],
  ['Zn + 2HCl → ZnCl<sub>2</sub> + H<sub>2</sub>', 'zinc chloride', 136, 138],
  ['CuO + H<sub>2</sub>SO<sub>4</sub> → CuSO<sub>4</sub> + H<sub>2</sub>O', 'copper sulfate', 159.5, 177.5],
  ['2NaCl + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub> + Cl<sub>2</sub>', 'sodium hydroxide', 80, 153],
  ['CH<sub>4</sub> + H<sub>2</sub>O → CO + 3H<sub>2</sub>', 'hydrogen', 6, 34],
];
function genAtomEconomy(rng) {
  if (rng() < 0.4) {
    const [eq, prod, mp, mr] = pick(rng, AE_RX), ae = rd(mp / mr * 100, 1);
    return { type: 'number', q: `${eq}<br>Calculate the atom economy for making ${prod}. (Total M<sub>r</sub> of reactants = ${mr}; M<sub>r</sub> of desired product as shown in the equation = ${mp}.) Give your answer to 1 d.p.`, value: ae, tol: 0.11, unit: '%', answer: `${ae}%`,
      steps: ['atom economy = (M<sub>r</sub> of desired product ÷ sum of M<sub>r</sub> of all reactants) × 100', `= (${mp} ÷ ${mr}) × 100`, `= ${ae}%`], explain: 'Atom economy measures the proportion of reactant atoms that end up in the useful product. Reactions with only one product have 100% atom economy.', hint: 'Useful product ÷ total reactants × 100.' };
  }
  const tot = ri(rng, 60, 400), mp = ri(rng, 10, tot - 5), ae = rd(mp / tot * 100, 1);
  return { type: 'number', q: `In a reaction the total relative formula mass of the reactants (using the balanced equation) is ${tot}. The desired product has a total M<sub>r</sub> of ${mp}. Calculate the percentage atom economy (1 d.p.).`, value: ae, tol: 0.11, unit: '%', answer: `${ae}%`,
    steps: ['atom economy = (M<sub>r</sub> of desired product ÷ total M<sub>r</sub> of reactants) × 100', `= (${mp} ÷ ${tot}) × 100`, `= ${ae}%`], explain: 'A high atom economy means less waste, which is better for sustainability and profit. Remember to use the balancing numbers when finding the total M<sub>r</sub>.', hint: 'Desired ÷ total × 100.' };
}

topic({ id: 'chem-y11-resources', strand: 'chem-resources', year: 11, term: 3, tier: 'FH', name: 'Using Resources, Yield & Atom Economy',
  summary: 'Potable and waste water, life cycle assessment, recycling, metal extraction alternatives, materials and the Haber process, with yield and atom economy.', specRef: 'AQA 8462 4.10.1–4.10.4, 4.3.3' }, [
  { name: 'Water, sustainability & extraction', intro: 'Potable water is safe to drink. It is produced by filtering and sterilising fresh water, or by desalinating sea water. Waste water is treated before release. HT: phytomining and bioleaching extract copper from low-grade ores.', items: [
    M('What is potable water?', ['Water that is safe to drink', 'Pure water (H<sub>2</sub>O only)', 'Sea water', 'Distilled water only'], 0, 'Potable water contains low levels of dissolved salts and microbes — it is not chemically pure.'),
    O('Put the steps to produce potable water from fresh water in order.', ['Choose a suitable source of fresh water', 'Pass the water through filter beds', 'Sterilise the water', 'Supply the water'], 'Filtering removes solids; sterilising (chlorine, ozone or UV) kills microbes.'),
    X('Which TWO are used to sterilise drinking water?', ['Chlorine', 'Ultraviolet light', 'Sodium chloride', 'Carbon dioxide', 'Sand'], [0, 1], 'Chlorine, ozone and UV light kill microbes.'),
    M('Which methods can desalinate sea water?', ['Distillation or reverse osmosis', 'Filtration', 'Chlorination', 'Chromatography'], 0, 'Both need large amounts of energy, so are used where fresh water is scarce.'),
    O('Put the stages of sewage (waste water) treatment in order.', ['Screening and grit removal', 'Sedimentation into sludge and effluent', 'Anaerobic digestion of sludge', 'Aerobic biological treatment of effluent'], 'Screening removes large solids; sludge is digested anaerobically (producing biogas); effluent is treated aerobically.'),
    M('Required practical: how can you find the mass of dissolved solids in a water sample?', ['Evaporate a measured volume to dryness and weigh the residue', 'Filter it', 'Measure its pH', 'Add chlorine'], 0, 'The residue left after evaporation is the dissolved solid.'),
    M('What are the four main stages of a life cycle assessment (LCA)?', ['Extracting raw materials, manufacturing, use, disposal', 'Design, advertising, selling, buying', 'Mining, smelting, recycling, burning', 'Planting, growing, harvesting, eating'], 0, 'LCAs assess environmental impact at each stage, including transport and energy.'),
    T('Life cycle assessments are completely objective.', false, 'False. Values for pollutant effects can involve judgements, so LCAs can be biased or selectively used.'),
    M('HT: What is phytomining?', ['Growing plants on low-grade ore so they absorb metal compounds, then burning them to get ash', 'Using bacteria to extract metals', 'Electrolysis of plants', 'Smelting ore with carbon'], 0, 'The ash contains metal compounds from which copper can be extracted.'),
    M('HT: What is bioleaching?', ['Using bacteria to produce leachate solutions containing metal compounds', 'Using plants to absorb metals', 'Burning ores', 'Distilling metals'], 0, 'Bacteria produce solutions from which copper is obtained by displacement (with scrap iron) or electrolysis.'),
    M('HT: Why are phytomining and bioleaching important?', ['High-grade copper ores are running out', 'They are faster than smelting', 'They produce pure copper directly', 'Copper is very reactive'], 0, 'They make low-grade ores and waste economic to process, and avoid digging, moving and disposing of large amounts of rock.'),
    M('Which plastic bag versus paper bag factor might an LCA show?', ['Paper bags may use more energy and water to make, though they are biodegradable', 'Plastic bags are always better', 'Paper bags use no resources', 'LCAs never compare products'], 0, 'LCAs consider all stages; neither option is best at every stage.'),
    S('What word describes development that meets current needs without compromising future generations?', 'sustainable', ['sustainable', 'sustainable development', 'sustainability'], 'Sustainable development is a key aim of modern chemistry.', [['sustainab']]),
    M('Why is recycling glass by crushing and melting better than making new glass?', ['It uses less energy and fewer raw materials', 'It makes stronger glass', 'It uses more limestone', 'It produces more CO<sub>2</sub>'], 0, 'Recycling reduces mining, energy use and waste.'),
    M('Why is the sludge from waste water treatment digested anaerobically?', ['Bacteria break it down producing methane (biogas) and fertiliser', 'To add oxygen', 'To make drinking water directly', 'To remove salt'], 0, 'Anaerobic digestion produces biogas for energy and digested material for fertiliser.'),
    M('Why is fresh water in the UK usually treated rather than desalinated?', ['Fresh water is plentiful and treating it uses much less energy than desalination', 'Sea water cannot be made potable', 'Desalination makes water radioactive', 'Fresh water has no microbes'], 0, 'The UK has enough rainfall for fresh water sources. Desalination requires large amounts of energy, so it is used where fresh water is scarce.'),
    M('What is the purpose of passing water through filter beds?', ['To remove solid particles', 'To kill microbes', 'To remove dissolved salts', 'To add fluoride'], 0, 'Filter beds (e.g. sand and gravel) remove solids. Sterilising kills microbes; dissolved salts are removed only by desalination.'),
    M('Which statement about potable water is correct?', ['It is safe to drink but may contain low levels of dissolved substances', 'It is pure water with nothing dissolved', 'It is always sea water', 'It has a pH of 1'], 0, 'Potable water is not chemically pure — it contains dissolved substances, but at safe levels, and has low levels of microbes.'),
    M('What is reverse osmosis used for?', ['Desalinating sea water using membranes', 'Sterilising water with chlorine', 'Separating crude oil', 'Making fertilisers'], 0, 'In reverse osmosis, pressure forces water through a membrane that holds back the salts, producing fresh water.'),
    M('In sewage treatment, what is the purpose of aerobic biological treatment of the effluent?', ['Bacteria break down organic matter using oxygen', 'To remove grit', 'To add salt', 'To produce methane for fuel'], 0, 'Air is bubbled through the effluent so aerobic bacteria break down remaining organic matter. Anaerobic digestion of sludge produces methane.'),
    M('HT: How is copper obtained from the leachate produced in bioleaching?', ['By displacement with scrap iron or by electrolysis', 'By heating with carbon only', 'By fractional distillation', 'By filtration only'], 0, 'Copper ions in solution can be displaced by a more reactive metal (scrap iron) or reduced at the cathode during electrolysis.'),
    T('Sterilising water kills microbes but does not remove dissolved salts.', true, 'True. Chlorine, ozone or UV light kill microbes; salts must be removed by desalination if needed.'),
    T('Life cycle assessments consider the environmental impact of a product only while it is being used.', false, 'False. An LCA considers all stages: extracting raw materials, manufacturing and packaging, use, and disposal at end of life.'),
    T('HT: Phytomining involves growing plants on soil that contains metal compounds.', true, 'True. The plants absorb metal compounds; they are harvested and burned, and the ash contains the metal compounds.'),
    S('What is the name for water that is safe to drink?', 'potable water', ['potable', 'potable water'], 'Potable water is safe to drink. It has low levels of dissolved salts and microbes.', [['potable']]),
    S('Name one gas used to sterilise drinking water.', 'chlorine', ['chlorine', 'ozone', 'cl2', 'o3'], 'Chlorine or ozone are used to sterilise water; ultraviolet light is another method.'),
    X('Which TWO are reasons why desalination is not widely used in the UK?', ['It requires large amounts of energy', 'It is expensive', 'It produces radioactive waste', 'It adds microbes to the water', 'Sea water has no salt'], [0, 1], 'Distillation and reverse osmosis require lots of energy, which makes desalination expensive. It does not produce radioactive waste or add microbes.'),
    M('Required practical: a 50 cm³ water sample is evaporated to dryness in a weighed basin. The basin gains 0.10 g. What is the mass of dissolved solids per dm³?', ['2.0 g/dm³', '0.10 g/dm³', '5.0 g/dm³', '0.002 g/dm³'], 0, '50 cm³ = 0.050 dm³. Mass per dm³ = 0.10 ÷ 0.050 = 2.0 g/dm³.'),
    M('HT: Why are phytomining and bioleaching useful even though they are slow?', ['They can extract metals from low-grade ores and waste, and avoid digging and moving large amounts of rock', 'They are faster than smelting', 'They produce pure metal directly', 'They need no further processing'], 0, 'Copper-rich ores are running out. These methods extract metal from low-grade ores and mine waste with less environmental damage, though further processing is needed.'),
    O('Put the life cycle assessment stages in order.', ['Extracting and processing raw materials', 'Manufacturing and packaging', 'Use and operation during its lifetime', 'Disposal at the end of its useful life'], 'An LCA follows a product from cradle to grave: raw materials → manufacture → use → disposal (including transport at each stage).'),
  ] },
  { name: 'Percentage yield', intro: 'Chemistry only. Percentage yield = mass of product actually made ÷ maximum theoretical mass × 100.', gen: genYield },
  { name: 'Atom economy', intro: 'Chemistry only. Atom economy = M<sub>r</sub> of desired product ÷ sum of M<sub>r</sub> of all reactants × 100. High atom economy means less waste.', gen: genAtomEconomy },
  { name: 'Materials, corrosion & the Haber process', intro: 'Chemistry only. Corrosion and its prevention; alloys, glass, ceramics, polymers and composites; the Haber process and NPK fertilisers.', items: [
    M('What two substances are needed for iron to rust?', ['Water and oxygen', 'Oxygen and nitrogen', 'Water and carbon dioxide', 'Salt and oxygen'], 0, 'Rusting needs both water and oxygen; salt speeds it up but is not essential.'),
    M('How does galvanising protect iron?', ['A zinc coating acts as a barrier and sacrificial protection', 'It makes iron more reactive', 'It removes oxygen from iron', 'It turns iron into steel'], 0, 'Zinc is more reactive than iron, so it corrodes instead even if scratched.'),
    M('What is sacrificial protection?', ['Attaching a more reactive metal that corrodes instead', 'Painting the metal', 'Oiling the metal', 'Using a less reactive coating'], 0, 'Magnesium blocks on ship hulls corrode instead of the steel.'),
    M('Bronze is an alloy of copper and…', ['Tin', 'Zinc', 'Iron', 'Aluminium'], 0, 'Bronze = copper + tin. Brass = copper + zinc.'),
    M('What does 18 carat gold mean?', ['75% gold', '18% gold', '100% gold', '50% gold'], 0, '24 carat is pure; 18/24 = 75%.'),
    M('Which steel is hard but brittle?', ['High carbon steel', 'Low carbon steel', 'Stainless steel', 'Pure iron'], 0, 'High carbon steel is strong but brittle; low carbon steel is softer and easily shaped; stainless steel (Cr, Ni) resists corrosion.'),
    M('How is soda-lime glass made?', ['Heating sand, sodium carbonate and limestone', 'Heating clay', 'Heating sand and boron trioxide only', 'Polymerising ethene'], 0, 'Borosilicate glass uses sand and boron trioxide and melts at a higher temperature.'),
    M('What is a composite?', ['A material of a reinforcement embedded in a matrix (binder)', 'A pure metal', 'An alloy', 'A polymer only'], 0, 'Examples: fibreglass, carbon fibre, concrete, wood.'),
    M('Why do thermosetting polymers not melt when heated?', ['They have cross-links between polymer chains', 'They have weak intermolecular forces', 'They are metals', 'They contain water'], 0, 'Thermosoftening polymers have no cross-links and melt; thermosets have covalent cross-links.'),
    M('What are the conditions of the Haber process?', ['About 450 °C, 200 atmospheres, iron catalyst', '25 °C, 1 atm, no catalyst', '1000 °C, 1000 atm, platinum', '450 °C, 1 atm, nickel'], 0, 'A compromise between rate, yield and cost.'),
    M('Where do the raw materials for the Haber process come from?', ['Nitrogen from air; hydrogen from natural gas', 'Both from water', 'Nitrogen from sea water; hydrogen from coal', 'Both from crude oil'], 0, 'Nitrogen is extracted from air; hydrogen is made from methane (natural gas).'),
    M('What happens to unreacted nitrogen and hydrogen in the Haber process?', ['They are recycled back into the reactor', 'They are released to the air', 'They are burned', 'They are converted to fertiliser directly'], 0, 'Ammonia is removed by cooling (it liquefies); unreacted gases are recycled.'),
    X('Which TWO elements are in NPK fertilisers besides potassium?', ['Nitrogen', 'Phosphorus', 'Sodium', 'Carbon', 'Sulfur'], [0, 1], 'NPK = nitrogen, phosphorus, potassium — needed for plant growth.'),
    M('Which compound is made from ammonia and nitric acid for fertiliser?', ['Ammonium nitrate', 'Ammonium sulfate', 'Potassium chloride', 'Calcium phosphate'], 0, 'NH<sub>3</sub> + HNO<sub>3</sub> → NH<sub>4</sub>NO<sub>3</sub>.'),
    T('Low density poly(ethene) and high density poly(ethene) are made from the same monomer under different conditions.', true, 'True. Different catalysts and reaction conditions give polymers with different properties.'),
    M('What is brass an alloy of?', ['Copper and zinc', 'Copper and tin', 'Iron and carbon', 'Aluminium and magnesium'], 0, 'Brass is copper + zinc and is used in fittings and instruments. Bronze is copper + tin; steel is iron + carbon.'),
    M('What does 24 carat gold mean?', ['100% pure gold', '24% gold', 'Gold mixed with 24 other metals', '50% gold'], 0, '24 carat is pure gold. 18 carat is 18/24 = 75% gold, mixed with other metals to make it harder.'),
    M('Which property makes low-carbon steel useful for car bodies?', ['It is soft and easily shaped', 'It is very brittle', 'It resists corrosion completely', 'It has a very low density'], 0, 'Low-carbon (mild) steel is soft and easily shaped (malleable). High-carbon steel is strong but brittle.'),
    M('What metals are added to iron to make stainless steel?', ['Chromium and nickel', 'Copper and zinc', 'Tin and lead', 'Gold and silver'], 0, 'Stainless steels contain chromium and nickel, which make them hard and resistant to corrosion.'),
    M('How is borosilicate glass different from soda-lime glass?', ['It is made from sand and boron trioxide and melts at a higher temperature', 'It is made from clay', 'It has a lower melting point', 'It is a polymer'], 0, 'Borosilicate glass (sand + boron trioxide) has a higher melting point than soda-lime glass, so it is used for ovenware and lab glassware.'),
    M('How are clay ceramics such as pottery and bricks made?', ['By shaping wet clay and heating it in a furnace', 'By melting sand with sodium carbonate', 'By polymerising alkenes', 'By electrolysis of clay'], 0, 'Clay is shaped while wet, then heated (fired) in a furnace to harden it.'),
    T('Aluminium does not corrode much because a layer of aluminium oxide forms on its surface and protects it.', true, 'True. The thin oxide layer stops air and water reaching the metal underneath.'),
    T('Thermosoftening polymers have cross-links between their chains.', false, 'False. Thermosoftening polymers have separate chains held by intermolecular forces, so they soften when heated. Thermosetting polymers have cross-links and do not melt.'),
    T('Painting, oiling and greasing prevent rusting by forming a barrier that keeps out air and water.', true, 'True. Barrier methods stop oxygen and water reaching the iron.'),
    S('What is the name of the reversible process used to manufacture ammonia?', 'Haber process', ['haber', 'haber process', 'the haber process'], 'The Haber process makes ammonia from nitrogen and hydrogen: N<sub>2</sub> + 3H<sub>2</sub> ⇌ 2NH<sub>3</sub>.', [['haber']]),
    S('Which metal is used as the catalyst in the Haber process?', 'iron', ['iron', 'fe'], 'An iron catalyst speeds up the reaction so equilibrium is reached faster at a practical temperature.'),
    X('Which TWO statements explain why galvanised iron is still protected when its zinc coating is scratched?', ['Zinc is more reactive than iron', 'Zinc corrodes in preference to the iron (sacrificial protection)', 'Zinc is less reactive than iron', 'The scratch makes the iron unreactive', 'Iron is a noble metal'], [0, 1], 'Zinc is more reactive, so it is oxidised instead of iron even where the iron is exposed. This is sacrificial protection.'),
    M('Chemistry only: what is produced when phosphate rock is treated with nitric acid?', ['Phosphoric acid and calcium nitrate', 'Ammonium sulfate', 'Potassium chloride', 'Sodium chloride'], 0, 'Phosphate rock + nitric acid → phosphoric acid and calcium nitrate. Phosphoric acid can then be neutralised with ammonia to give ammonium phosphate.'),
    M('In the Haber process, why is the gas mixture cooled after leaving the reactor?', ['To liquefy the ammonia so it can be removed', 'To freeze the nitrogen', 'To stop the iron catalyst melting', 'To make the reaction go faster'], 0, 'Ammonia has a much higher boiling point than nitrogen and hydrogen, so it condenses and is removed as a liquid; unreacted gases are recycled.'),
    O('Put these steps of the Haber process in order.', ['Nitrogen and hydrogen are purified and mixed', 'The gases are compressed to about 200 atmospheres', 'The gases pass over an iron catalyst at about 450 °C', 'The mixture is cooled; ammonia liquefies and unreacted gases are recycled'], 'Prepare and compress the gases, react them over the iron catalyst, then cool to remove liquid ammonia and recycle the rest.'),
  ] },
], {
  overview: 'Chemists use Earth\'s resources to provide food, water, warmth and materials, and aim to do so <b>sustainably</b>. This topic covers producing safe water, life cycle assessments, recycling and new ways to extract metals, and — in GCSE Chemistry — <b>percentage yield</b>, <b>atom economy</b>, corrosion, materials and the <b>Haber process</b>.',
  objectives: ['I can describe how potable water is produced and waste water is treated', 'I can carry out and evaluate an LCA', 'HT: I can describe phytomining and bioleaching', 'Chemistry only: I can calculate percentage yield and atom economy', 'Chemistry only: I can describe corrosion prevention, alloys, glass, ceramics, polymers and composites', 'Chemistry only: I can describe the Haber process and NPK fertilisers'],
  keyWords: [{ term: 'Potable water', def: 'Water safe to drink.' }, { term: 'Desalination', def: 'Removing salts from sea water.' }, { term: 'Life cycle assessment', def: 'Assessment of environmental impact over a product\'s life.' }, { term: 'Percentage yield', def: 'Actual mass ÷ theoretical mass × 100.' }, { term: 'Atom economy', def: 'Mr of desired product ÷ total Mr of reactants × 100.' }, { term: 'Corrosion', def: 'Destruction of materials by chemical reactions with substances in the environment.' }, { term: 'Composite', def: 'Reinforcement embedded in a matrix.' }, { term: 'Haber process', def: 'Industrial production of ammonia from nitrogen and hydrogen.' }],
  sections: [
    { title: 'Water', html: `<p>Potable water: filter then sterilise (chlorine, ozone, UV). Desalination: distillation or reverse osmosis (energy-intensive). Waste water: screening → sedimentation → anaerobic digestion of sludge → aerobic treatment of effluent.</p><p>Required practical: test pH, evaporate to find dissolved solids, distil to purify.</p>` },
    { title: 'LCA, recycling and extraction', html: `<p>LCA stages: raw materials, manufacture, use, disposal. Recycling saves energy and resources. HT: phytomining (plants → ash) and bioleaching (bacteria → leachate) extract copper from low-grade ores; copper is then obtained by displacement or electrolysis.</p>` },
    { title: 'Percentage yield and atom economy (chemistry only)', html: `<div class="rule">% yield = actual mass ÷ theoretical mass × 100<br>atom economy = M<sub>r</sub> desired product ÷ total M<sub>r</sub> reactants × 100</div><div class="worked"><div class="wq">CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. Atom economy for CaO?</div><ol><li>M<sub>r</sub>: CaCO<sub>3</sub> = 100, CaO = 56</li><li>56 ÷ 100 × 100</li></ol><div class="wa">Answer: 56%</div></div><p>Yields are below 100% because of incomplete reactions, losses and side reactions.</p>` },
    { title: 'Materials (chemistry only)', html: `<ul><li>Rusting needs water + oxygen; prevent by barriers (paint, oil, plating) or sacrificial protection (zinc, magnesium).</li><li>Alloys: bronze (Cu + Sn), brass (Cu + Zn), gold carats, steels, aluminium alloys.</li><li>Glass (soda-lime, borosilicate), clay ceramics, polymers (LDPE, HDPE, thermosoftening vs thermosetting), composites.</li></ul>` },
    { title: 'Haber process and fertilisers (chemistry only)', html: `<div class="rule">N<sub>2</sub> + 3H<sub>2</sub> ⇌ 2NH<sub>3</sub> — 450 °C, 200 atm, iron catalyst</div><p>Ammonia is cooled and liquefied; unreacted gases are recycled. NPK fertilisers supply nitrogen, phosphorus and potassium; ammonia makes ammonium salts and nitric acid.</p>` },
  ],
  mistakes: ['Saying potable water is pure water.', 'Using the mass of only one reactant in atom economy instead of all reactants.', 'Confusing percentage yield with atom economy.', 'Saying galvanising works only as a barrier — it is also sacrificial.'],
  examTips: ['In "explain the Haber conditions" questions, discuss rate, yield and cost for temperature and pressure.', 'Use balancing numbers when totalling Mr for atom economy.', 'For LCA questions, refer to data in the table for each stage.'],
  realLife: 'About half the world\'s food is grown using fertilisers made from ammonia produced by the Haber process.',
});
